def selection_sort(arr):
    for i in range(len(arr)):  
        least_index = i
        for j in range(i+1, len(arr)):
            if arr[j] < arr[least_index]:
                least_index = j 
        arr[i], arr[least_index] = arr[least_index], arr[i]
    return arr

