def subsets(list_):
    if len(list_) == 0:
        return [[]]
    elif len(list_) == 1:
        return [[], list_]

    # get the subset without the last element
    pre_subs = subsets(list_[:-1])

    # add the last element to the current subsets
    cur_subs = []
    for pre in pre_subs:
        cur_subs.append(pre + [list_[-1]])

    # combine the two subsets
    return pre_subs + cur_subs

