public static int Fibonacci(int number)
{
     if (number < 0)
     {
         throw new ArgumentException("Input must be greater than or equal to 0.");
     }
     if (number == 0) return 0;
     if (number == 1) return 1;

     return Fibonacci(number - 1) + Fibonacci(number - 2);
}

