def getMinSteps(source, destination, instructions): 
    x_source, y_source = source 
    x_dest, y_dest = destination 
    minSteps = 0
    x, y = x_source, y_source 

    for inst in instructions: 
        if inst == "right": 
            x += 1
        if inst == "down": 
            y += 1

        if x == x_dest and y == y_dest: 
            break 
        minSteps += 1

    return minSteps

