CREATE FUNCTION AverageStringLength(tableName VARCHAR(100))
RETURNS DECIMAL
BEGIN
 DECLARE average DECIMAL;
 DECLARE length DECIMAL;
 DECLARE rowCount INT;

 SELECT AVG(LENGTH(string_column)) INTO average
 FROM tableName;

 SELECT COUNT(*) INTO rowCount FROM tableName;

 IF rowCount = 0 THEN
 SET length = 0;
 ELSE
 SET length = average;
 END IF;

RETURN length;
END

