		return; 
	} 

	if ($n == 0) 
		return; 

	if ($arr[$n-1] > $sum) 
	{
		printSubsetsSum ($arr, $n-1, $sum); 
		return;
	} 

	printSubsetsSum ($arr, $n-1, $sum); 

