def find_most_requested_categories(category_data):
    # Create an empty dictionary
    counts = {}

    # Iterate over the list
    for category in category_data:
        # Create an entry in the dictionary with the count of each category
        if category not in counts:
            counts[category] = 1 
        # Increment the count of existing categories
        else:
            counts[category] += 1

    # Find the most requested categories
    most_requested = None
    max = 0 
    for category, count in counts.items():
        if count > max:
            most_requested = category
            max = count

    # Return the most requested categories
