def maximize_sum(arr):
    length = len(arr)
    dp = [[0 for _ in range(length)] for _ in range(length)]
    for i in range(length):
        for j in range(i+1,length):
            if i == 0:
                dp[i][j] = max(arr[i],arr[j])
            else:
                dp[i][j] = max(dp[i-1][j], arr[i]+dp[i-1][i-1])
