import java.util.*;

public class Sudoku {

  // Size of the Sudoku grid
  static int N = 10;

  // Function to generate random puzzle
  static void generateSudoku(int[][] grid, int N) {

        // Choose random numbers from 1 to N
        // for each row
        for (int row = 0; row < N; row++) {
            grid[row][0] = (int)(Math.random() * N + 1);

            // Choose random numbers from the
            // remaining numbers
            for (int col = 1; col < N; col++) {
                int num;

                // Randomly generate a number
                // from the remaining numbers
                // (column)
                do {
                    num = (int)(Math.random() * N + 1);
                } while (isPresentInRow(grid, row, num));

                grid[row][col] = num;
            }
        }
    }

    // Function to check if num is present in row
    static boolean isPresentInRow(int[][] grid, int row, int num) {
        for (int col = 0; col < N; col++) {
            if (grid[row][col] == num)
                return true;
        }
        return false;
    }

    // Function to print the puzzle
    static void printGrid(int[][] grid) {
        for (int row = 0; row < N; row++) {
            for (int col = 0; col < N; col++)
                System.out.print(grid[row][col] + " ");
            System.out.println();
        }
    }

    public static void main(String[] args) {
        // create a 9x9 grid
        int N = 10;
        int[][] grid = new int[N][N];

        generateSudoku(grid, N);

        printGrid(grid);
    }
}

