public class NearestDeliveryService {
 public static int closestService(int x, int y, int[][] locations) {
  int minDistance = Integer.MAX_VALUE;
  int closestIndex = 0;
  // Loop through all delivery services
  for (int i=0; i<locations.length; i++) {
    int deliveryX = locations[i][0];
    int deliveryY = locations[i][1];
    // Calculate distance between the user and the delivery service
    int distance = (deliveryX - x)*(deliveryX - x) + (deliveryY - y)*(deliveryY - y);
    if (distance < minDistance) {
      minDistance = distance;
      closestIndex = i;
    }
  }
  return closestIndex;
 }
}

