def optimize_portfolio(portfolio, prices):
    total_value = 0
    for item in portfolio:
        for key, value in item.items():
            total_value += value

    optimal_portfolio = [0] * len(portfolio)
    min_loss = float("inf")

    for i in range(len(portfolio)):
        prev_total = total_value
        for j in range(len(prices)):
            total_value = prev_total - portfolio[i][list(portfolio[i].keys())[0]] * prices[j]
            loss = (prev_total - total_value) / prev_total
            if loss < min_loss:
                min_loss = loss
                optimal_portfolio[i] = j

    return optimal_portfolio

