def generate_completeness_order(dependency_list): 
    # dictionary to store the ordered list 
    order = {} 

    # populate the order dictionary 
    for (before, after) in dependency_list: 
        order[before] = after 

    # Store the sources in the dependency list 
    sources = [] 
    for node in order.keys():
        if node not in order.values(): 
            sources.append(node) 

    # Create an empty list to store the order 
    order_list = [] 

    # Create a copy of the sources list 
    sources_copy = sources[:] 

    # Iterate over the source list to generate an ordered list 
    while sources: 
        i = 0
        n = len(sources)
        while i < n:
            source = sources[i] 
            order_list.append(source)
            if source in order.keys(): 
                del order[source] 
            sources.remove(source) 
