"""Design a multi-threaded Java program to calculate Fibonacci numbers using the recursive approach."""

import java.util.concurrent.Callable;

public class MultiThreadedFibonacci {

    public static long calculateFibonacciNumber(int n) throws Exception {
        if (n == 0 || n == 1) {
            return n;
        }

        // Create two threads
        Callable<Long> thread1 = new FibonacciThread(n - 1);
        Callable<Long> thread2 = new FibonacciThread(n - 2);

        // Execute the two threads
        long result1 = thread1.call();
        long result2 = thread2.call();

        // Return the sum of the two results
        return result1 + result2;
    }

    private static class FibonacciThread implements Callable<Long> {
        private int n;

        public FibonacciThread(int n) {
            this.n = n;
        }

        public Long call() throws Exception {
            return calculateFibonacciNumber(n);
        }
    }
}

