class TrieNode: 
    # Initialize the data structure
    def __init__(self):
        self.children = dict()
        self.isEndWord = False

class Trie:
    def __init__(self):
        self.root = TrieNode()

    # Inserts a word into the trie
    def insert(self,word):
        crawler = self.root
        for char in word:
            if char not in crawler.children:
                crawler.children[char] = TrieNode()
            crawler = crawler.children[char]
        crawler.isEndWord = True

    # Search a word in the trie
    def search(self,word):
        crawler = self.root
        for char in word:
            if char not in crawler.children:
                return False
            crawler = crawler.children[char]
        return crawler.isEndWord

