        }
        max = Math.max(max, seq[i]);
    }  

    let currentNum = arr[arr.length - 1];
    let longestSubsequence = [currentNum];
    for (let i = arr.length - 1; i >= 0; i--) {
        if(arr[i] < currentNum && seq[i] === max) {
            longestSubsequence.unshift(arr[i]);
            currentNum = arr[i];
            max--;
        }
    }
    return longestSubsequence;
}

