void delete_element(struct Node* node, int key)  
{  
    struct Node * temp, * prev;   
    temp = node;  

    while (temp != NULL && temp->key != key)  
    {  
        prev = temp;  
        temp = temp->next;  
    }  

    if (temp != NULL)  
    {  
        prev->next = temp->next;  
        free(temp);  
    }  

}

