public class blockIPFilter implements Filter {

private String blockedIP;

@Override
public void init(FilterConfig filterConfig) throws ServletException {

    blockedIP = filterConfig.getInitParameter("blockedIP");
}

@Override
public void doFilter(ServletRequest request, ServletResponse response, FilterChain chain)
        throws IOException, ServletException {

    if (blockedIP.equals(((HttpServletRequest) request).getRemoteAddr())) {
        throw new IOException("Request blocked from IP address: " + blockedIP);
    }
    chain.doFilter(request, response);
}

