template<typename K, typename V>
int BinarySearch(K key, std::vector<V>& sortedVector, int low, int high) 
{
 while (low <= high) 
 {
  /* Calculate the middle element */
  int mid = (low + ((high - low) >> 1));

  /* Check if key is present in the middle element */
  if (sortedVector[mid] == key)
  {
   return mid;
  }
  else if (sortedVector[mid] > key)
  {
   /* Key is present in left sub array */
   return BinarySearch(key, sortedVector, low, mid - 1);
  } 
  else 
  {
   /* Key is present in right sub array */
   return BinarySearch(key, sortedVector, mid + 1, high);
  }
 }

 /* Key is not present in the array */
 return -1;
}

