function search(set, num) { 
    var i = 0; 

    // Iterate over the set
    while (i < set.length) { 
        // Return true if match found 
        if (set[i] === num) { 
            return true; 
        }       
        i++; 
    }  

    // Return false if match not found 
    return false; 
} 

