import React, { useState } from 'react';

function App() {
  const [grades, setGrades] = useState([]);
  const [name, setName] = useState('');
  const [gradePoint, setGradePoint] = useState('');

  const handleAddGrade = () => {
    setGrades([...grades, { name, gradePoint }]);
    setName('');
    setGradePoint('');
  };

  const calculateGPA = () => {
    if (grades.length === 0) {
      alert('No grades added yet!');
      return;
    }

    const totalGrades = grades.reduce((acc, cur) => acc + parseInt(cur.gradePoint), 0);

    const averageGPA = totalGrades / grades.length;

    alert(`The student's average GPA is ${averageGPA.toFixed(2)}`);
  };

  return (
    <div>
      <h1>Calculate GPA</h1>
      <div>
        <input
          type='text'
          value={name}
          onChange={e => setName(e.target.value)}
        />
        <input
          type='number'
          value={gradePoint}
          onChange={e => setGradePoint(e.target.value)}
        />
        <button onClick={handleAddGrade}>Add Grade</button>
      </div>

      <div>
        {grades.map(grade => (
          <div key={grade.name}>
            {grade.name} - {grade.gradePoint}
          </div>
        ))}
      </div>

      <button onClick={calculateGPA}>Calculate GPA</button>
    </div>
  );
}

