public class FindSubstring {

    public static int findSubstring(String string, String substring) {
        int checkIndex = 0;
        boolean check = true;
        for (int i = 0; i < string.length() && check; i++) {
            for (int j = 0; j < substring.length() && check; j++) {
                char stringChar = string.charAt(i + j);
                char substringChar = substring.charAt(j);
                if (!(stringChar == substringChar)) {
                    check = false;
                    break;
                }
            }
            if (check) {
                checkIndex = i;
                break;
            }
        }
        return checkIndex;
    }

    public static void main(String[] args) {
        String string = "Hello World";
        String substring = "World";
        int index = findSubstring(string, substring);
        System.out.println("Index : " + index);
