def heapsort(my_list):
  # create the parents
  parents = [int(item/2) for item in my_list[1:]]
  parents.insert(0, -1)

  # build the maxheap
  length = len(my_list)
  for idx in range(1, length):
    index = idx
    while my_list[index] > my_list[parents[index]]:
      my_list[index], my_list[parents[index]] = my_list[parents[index]], my_list[index]
      index = parents[index]
      parents[index] = check_parent(parents, index)

  # build the sorted list
  while length > 0:
    my_list[0], my_list[length - 1] = my_list[length - 1], my_list[0]
    parents[0] = 0
    length -= 1
    index = 0
    if length > 0: 
      while my_list[index] < my_list[2*index+1] or my_list[index] < my_list[2*index+2]:
        if my_list[2*index+1] > my_list[2*index+2] and length > 2*index+2: 
          my_list[index], my_list[2*index+1] = my_list[2*index+1], my_list[index]
          index = 2*index + 1
          parents[index] = check_parent(parents, index)
        else:
          my_list[index], my_list[2*index+2] = my_list[2*index+2], my_list[index]
          index = 2*index +2
          parents[index] = check_parent(parents, index)
  return my_list

def check_parent(parents, index):
    if index > 0 and index < len(parents):
      return int((index - 1)/2)
    else:
      return index

