int numIslands(vector<vector<int>>& grid) {
    if (grid.empty() || grid.front().empty())
        return 0;
    int num = 0;

    int row = grid.size();
    int col = grid[0].size();

    for (int r = 0; r < row; r++) {
        for (int c = 0; c < col; c++) {
            if (grid[r][c] == 1) {
                num++;
                dfs(grid, r, c);
            }
        }
    }
    return num;
}

void dfs(vector<vector<int>>& grid, int r, int c) {
    int row = grid.size();
    int col = grid[0].size();
    if (r < 0 || c < 0 || r >= row || c >= col || 
        grid[r][c] == 0) 
        return;

    grid[r][c] = 0;
    dfs(grid, r - 1, c);
    dfs(grid, r + 1, c);
    dfs(grid, r, c - 1);
    dfs(grid, r, c + 1);
}

function knapsack(items, maxWeight) {
    let selectedItems = [];
    let totalWeight = 0;

    // Sort items in descending order of their value
    items.sort((a, b) => {
        return b.value - a.value;
    });

    // Add items to knapsack so long as the total weight is less than the maximum weight
    for (let i = 0; i < items.length; i++) {
        let item = items[i];
        let weight = item.weight;

        if (totalWeight + weight <= maxWeight) {
            totalWeight += weight;
            selectedItems.push(item);
        }
    }

    // Return the items selected
    return selectedItems;
}

def delete_node(head, delete_num):

    if head is None:
        return

    curr = head
    prev = None

    while curr and curr.data != delete_num:
        prev = curr
        curr = curr.next

    if prev == None:
        return head.next

    prev.next = curr.next
    return head

