def sort(arr):
    if len(arr) == 0:
        return arr
    left, right = [], []
    pivot = arr[0]
    for i in range(1, len(arr)):
        if arr[i] < pivot:
            left.append(arr[i])
        else:
            right.append(arr[i])
    left = sort(left)
    right = sort(right)
    return left + [pivot] + right

