// Function to print prime numbers between 
// 2 to n 
void printPrime(int n) 
{ 
    // Create a boolean array and init 
    // all elements to true. A value in 
    // prime[i] will finally be false 
    // if i is Not a prime, else true 
    // bool prime[n+1]; 
    int prime[n+1]; 
    memset(prime, 1, sizeof(prime)); 

    for (int p=2; p*p<=n; p++) 
    { 
        // If prime[p] is not changed, then 
        // it is a prime 
        if (prime[p] == 1) 
        { 
            // Update all multiples of p 
            for (int i=p*2; i<=n; i += p) 
                prime[i] = 0; 
        } 
    } 

    // Print all prime numbers 
    for (int p=2; p<=n; p++) 
       if (prime[p]) 
          printf("%d ",p); 
} 

