public class Sudoku {
 public static void main(String[] args) { 
  int[][] board = new int[9][9];

  // Populate board with input 
  int k = 0;
  for (int i = 0; i < 9; i++) {
   for (int j = 0; j < 9; j++) {
    board[i][j] = args[k];
    k++;
   }
  }

  solveSudoku(board); 

  // Print solved board 
  System.out.println("Solved Sudoku:"); 
  for (int i = 0; i < 9; i++) {
   for (int j = 0; j < 9; j++) {
    System.out.print(board[i][j] + " "); 
   }
   System.out.println(); 
  }
 } 

 // Backtracking Algorithm 
 static boolean solveSudoku(int[][] board) { 
  int row, col; 

  // Check for an empty cell 
  boolean isEmpty = true; 
  for (row = 0; row < 9; row++) { 
   for (col = 0; col < 9; col++) { 
    if (board[row][col] == 0) { 
     isEmpty = false; 
     break; 
    } 
   } 
   if (!isEmpty) 
    break; 
  } 

  // No empty cell is found, puzzle is solved 
  if (isEmpty) 
   return true; 

  // Assume numbers from 1 - 9 
  for (int num = 1; num <= 9; num++) { 
   // Check if num is valid for the cell 
   if (isSafe(board, row, col, num)) { 
    board[row][col] = num; 
    // Solve the problem recursively 
    if (solveSudoku(board)) 
     return true; 
    // Reset the cell, if the solution doesn't satisfy 
    else
     board[row][col] = 0; 
   } 
  } 
  return false; 
 } 

 // Check whether a number can be put in the cell 
 static boolean isSafe(int[][] board,  
                       int row, int col, int num)  
 { 
  // Check all rows in column 
  for (int r = 0; r < 9; r++) { 
   // Check whether the number is present 
   if (board[r][col] == num) 
    return false; 
  } 

  // Check all columns in row 
  for (int c = 0; c < 9; c++) { 
   // Check whether the number is present 
   if (board[row][c] == num) 
    return false; 
  } 

  // Check all 3*3 parts in board 
  int startRow = 3 * (row / 3); 
  int startCol = 3 * (col / 3); 

  // Check whether the number is present 
  for (int r = startRow; r < startRow + 3; r++) { 
   for (int c = startCol; c < startCol + 3; c++) { 
    if (board[r][c] == num) 
     return false; 
   } 
  } 

  // Number can be put in the cell  
  return true; 
 } 
}

