    def backtrack(curr, rest):
        if not rest:
            result.append(''.join(curr))
        else:
            for i in range(len(rest)):
                curr.append(rest[i])
                rest_copy = list(rest)
                rest_copy.pop(i)
                backtrack(curr, rest_copy)
                curr.pop(-1)
    backtrack([], chars)
