import numpy as np

class Tic_Tac_Toe_Env():
    def __init__(self):
        self.state = np.zeros((3,3))
        self.player_1 = 1
        self.player_2 = -1
        self.winner = None
        self.ended = False
        self.num_states = 3**(3*3)

    def is_empty(self,i,j):
        return self.state[i,j] == 0

    def reward(self, sym):
        """ Sym = 1 if player 1 has won,
            Sym = -1 if player 2 has won.
        """
        if self.has_won(sym):
            return 1
        else:
            return 0

    def get_state(self):
        k = 0
        h = 0
        for i in range(3):
            for j in range(3):
                if self.state[i,j] == 0:
                    v = 0
                elif self.state[i,j] == self.player_1:
                    v = 1
                elif self.state[i,j] == self.player_2:
                    v = 2
                h += (3**k) * v
                k += 1
        return h

    def game_over(self, force_recalculate=False):
        if not force_recalculate and self.ended:
            return self.ended

        for i in range(3):
            for player in (self.player_1, self.player_2):
                if self.state[i].sum() == player*3:
                    self.winner = player
                    self.ended = True
                    return True

        for j in range(3):
            for player in (self.player_1, self.player_2):
                if self.state[:,j].sum() == player*3:
                    self.winner = player
                    self.ended = True
                    return True

        for player in (self.player_1, self.player_2):
            if (self.state.trace() == player*3):
                self.winner = player
                self.ended = True
                return True

        if np.all((self.state == 0) == False):
            self.winner = None
            self.ended = True
            return True

        self.winner = None
        self.ended = False
        return False

    def has_won(self, sym):
        return self.ended and self.winner == sym

    def draw_board(self):
