# Playing tic-tac-toe
def tic_tac_toe(env,sym):
    # Define parameters for Q-learning
    learning_rate = 0.2
    discount_rate = 0.9
    epsilon = 0.1 # Exploration
    num_episodes = 5000

    # Initialize Q-table with all zeros
    Q = np.zeros((env.num_states, 9))

    # Loop over episodes
    for episode in range(num_episodes):
        # Reset the environment
        env.reset()

        # Set epsilon to decrease over the epocss
        epsilon = 1.0 / episode

        # Get current state
        cur_state = env.get_state()

        # Set your own reward
        reward = 0

        # The Q-Table learning algorithm
        while True:
            # Choose an action by greedily (with noise) picking from Q table
            if np.random.rand()<epsilon:
                action = np.random.choice([0,1,2,3,4,5,6,7,8])
            else:
                action = np.argmax(Q[cur_state,:])

            # Take action and get feedback
            (new_state, reward, done) = env.act(action, sym)

            # Update Q-Table with new knowledge
            Q[cur_state,action] = Q[cur_state,action] + learning_rate*(reward + discout_rate*(np.max(Q[new_state,:]) - Q[cur_state,action]))

            cur_state = new_state

            if done:
                break

    print("Q-Table:\n",Q)

