public class PermutationGenerator
{
    public static List<List<int>> Generate(List<int> list)
    {
        List<List<int>> permutations = new List<List<int>>();
        if (list.Count == 1)
        {
            permutations.Add(list);
            return permutations;
        }

        foreach (var item in list)
        {
            List<int> listClone = list.FindAll(x => x != item);
            List<List<int>> subPermutations = Generate(listClone);
            foreach (List<int> subPermutation in subPermutations)
            {
                subPermutation.Add(item);
                permutations.Add(subPermutation);
            }
        }
        return permutations;
    }
}

