def edit_distance(word1, word2):
    m = len(word1)
    n = len(word2)

    # create a 2d matrix
    mem = [[0 for x in range(n + 1)] for x in range(m + 1)]

    for i in range(m + 1):
        for j in range(n + 1):
            # check if the one of the string is empty
            if i == 0:
                mem[i][j] = j 
            elif j == 0:
                mem[i][j] = i 
            # if the last character matches, ignore it
            elif word1[i - 1] == word2[j - 1]: 
                mem[i][j] = mem[i - 1][j - 1] 
            # insert, remove or substitute
            else: 
                mem[i][j] = 1 + min(mem[i - 1][j], 
                                   mem[i][j - 1], 
                                   mem[i - 1][j - 1]) 

    return mem[m][n]

