def encryptMatrixTranspose(string):
    matrix = [list(string[i:i+6]) for i in range(0, len(string), 6)]
    for row in matrix:
        if(len(row) != 6):
            for i in range(len(row), 6):
                row.append("_")

    new_matrix = []
    for i in range(6):
        new_row = []
        for row in matrix:
            new_row.append(row[i])
        new_matrix.append(new_row)
    return ''.join([''.join(row) for row in new_matrix])

