public static void quickSort(String[] myArray, int left, int right) {

int index = partition(myArray, left, right);
if (left < index - 1) {
 quickSort(myArray, left, index - 1);
}
if (index < right) {
 quickSort(myArray, index, right);
}
}

public static int partition(String[] myArray, int left, int right) {
int pivot = myArray[(left + right) / 2];

while (left <= right) {
 while (myArray[left].compareTo(pivot) < 0) {
 left++;
 }
 while (myArray[right].compareTo(pivot) > 0) {
 right--;
 }
 if (left <= right) {
String temp = myArray[left];
myArray[left] = myArray[right];
myArray[right] = temp;

 left++;
 right--;
 }
}
return left;
}

