{ 
    int N = x.length; 

    Complex[] X = new Complex[N]; 
    for (int k = 0; k < N; k++) 
    { 
        X[k] = new Complex(0, 0); 
        for (int n = 0; n < N; n++) 
        { 
            double angle = 2 * Math.PI * k * n / N; 
            Complex e = Complex.fromPolar(1.0, -angle); 
