using namespace std;

// Function to calculate error rate
double calculateErrorRate(vector<double> v1, vector<double> v2)
{
    int size = v1.size();
    double error = 0;
    for (int i = 0; i < size; i++)
    {
        error += (v1[i] - v2[i]) * (v1[i] - v2[i]);
    }
    return sqrt(error);
}

// Function to minimize error rate
void optimizeErrorRate(vector<double> &v1, vector<double> &v2, double error)
{
    int size = v1.size();
    for (int i = 0; i < size; i++)
    {
        // Finding local minima by perturbing vector v2
        vector<double> x(size);
        fill(x.begin(), x.end(), 0.15);

        vector<double> new_v2(size);
        for (int i = 0; i < size; i++)
            new_v2[i] = v2[i] + x[i];

        double new_error = calculateErrorRate(v1, new_v2);

        // Updating vector v2 with new values
        if (new_error < error)
            for (int i = 0; i < size; i++)
                v2[i] += x[i];

        // Calculating new error rate
        error = calculateErrorRate(v1, v2);
    }

    cout << "Optimized Error Rate: " << error << endl;
}

// Driver program
int main()
{
    vector<double> v1 = {10, 20, 30};
    vector<double> v2 = {30, 20, 10};

    double error = calculateErrorRate(v1, v2);
    cout << "Error Rate: " << error << endl;

    optimizeErrorRate(v1, v2, error);
    return 0;
}

