# Define a function that tokenizes reviews
def tokenize_review(review):
    tokens = tokenizer.tokenize(review)
    input_ids = tokenizer.convert_tokens_to_ids(tokens)
    return torch.tensor(input_ids).unsqueeze(0)

# Define a function to predict the sentiment of a review
def predict_review(review):
    # Tokenize the review
    input_ids = tokenize_review(review)

    # Generate predictions from the model
    output = model(input_ids)[0][0]
    sentiment = output.argmax().item()
    probabilities = torch.nn.functional.softmax(output, dim=0)

    if sentiment == 1:
        return 'positive', probabilities[1].item()
    else:
        return 'negative', probabilities[0].item()

def sort_list_ascending(input_list):
    # Iterate through input list
    for x in range(len(input_list)-1):
        # Set min value for x
        min_val = x
        # Iterate through subsequent values
        for y in range(x+1, len(input_list)):
            # Find smallest element after x
            if input_list[min_val] > input_list[y]:
                min_val = y
        # Switch smallest value with value at x
        input_list[x], input_list[min_val] = input_list[min_val], input_list[x]

    return input_list

