def constructBST(arr):
    if len(arr) == 0:
        return None
    mid_idx = len(arr) // 2
    root = BinaryTree(arr[mid_idx])

    root.left = constructBST(arr[:mid_idx])
    root.right = constructBST(arr[mid_idx + 1:])

    return root

