    result = ""
    prev_c = None
    count = 1
    for c in s:
        if prev_c == c:
            count += 1
        else:
            if count > 2:
                result += str(count) + prev_c
            elif count == 2:
                result += prev_c * 2
            else:
                result += prev_c
            count = 1
            prev_c = c
