// discounting factor for q learning
const double gamma = 0.5;
// state reward matrix
const vector<vector<double>> R = {{2, 0, 0, 0}, 
                                 {-1, 0, -2, 0}, 
                                 {-1, 0, 0, 0},
                                 {-1, -2, 0, 0}};

// utility functions declaration
unsigned int max_index(const vector<double> &);

int main()
{
    // Q-table initialization
    vector<vector<double>> Q(R.size(), vector<double>(R[0].size(), 0));

    // q learning algorithm
    int iterations = 1000;
    for (int k = 0; k < iterations; k++)
    {
        for ( unsigned int a = 0; a < R.size(); a++ )
        {
            for ( unsigned int b = 0; b < R[a].size(); b++ )
            {
                // Find the action with maximum Q-Value
                unsigned int c = max_index(Q[a]);
                // Update Q-Value
                Q[a][b] = R[a][b] + gamma * Q[a][c];
            }
        }
    }

    // printing final Q-table
    for (unsigned int a = 0; a < Q.size(); a++ )
    { 
        for ( unsigned int b = 0; b < Q[a].size(); b++ )
        {
            cout << "Action at state " << a << " = " << Q[a][b] << endl;
        }
    }

    return 0;
}

// returns index of maximum element 
unsigned int max_index(const vector<double> &x)
{
    unsigned int result_index = 0;
    double max = numeric_limits<double>::lowest();

    for (unsigned int a = 0; a < x.size(); a++ )
    {
        if ( max < x[a] )
        {
            max = x[a];
            result_index = a;
        }
    }
    return result_index;
}

