def solve_linear_system(matrix, solution):
    # Create a new matrix
    matrix_len = len(matrix)
    matrix_result = [[0] * matrix_len for _i in range(matrix_len)]

    # Fill the new matrix with the coefficients
    for i in range(matrix_len):
        for j in range(matrix_len):
            matrix_result[i][j] = matrix[i][j]

    # Update the new matrix with the solution
    for i in range(matrix_len):
        matrix_result[i].append(solution[i])   

    # Solve the system of linear equations
    for i in range(matrix_len):
        for j in range(i+1, matrix_len):
            coefficient = -1 * (matrix_result[j][i] / matrix_result[i][i])
            for k in range(i, matrix_len+1):
                matrix_result[j][k] += coefficient * matrix_result[i][k]

    # Compute the solution
    solution = [0] * matrix_len
    for i in range(matrix_len-1, -1,-1):
        solution[i] = matrix_result[i][matrix_len] / matrix_result[i][i]

    return solution

