def calculate_levenshtein_distance(str1, str2):
    """
    This function takes two strings as inputs and calculates the Levenshtein Distance
    between them.
    """
    # Initialize the cost matrix
    len_str1 = len(str1)+1
    len_str2 = len(str2)+1
    cost = [[0 for x in range(len_str2)] for x in range (len_str1)] 
    # Fill in the cost matrix
    for i in range(1, len_str1):
        cost[i][0] = i
    for j in range(1, len_str2):
        cost[0][j] = j
    for i in range(1, len_str1):
        for j in range(1, len_str2):
            if str1[i-1] == str2[j-1]:
                cost[i][j] = cost[i-1][j-1]
            else:
                cost[i][j] = min(cost[i-1][j], cost[i][j-1], cost[i-1][j-1]) + 1
    return cost[-1][-1]

