pair<int, int> maxSubarraywithSum(int arr[], int size, int target) {
 pair<int, int> result;
 int windowStart = 0, sum = 0;

 for (int i = 0; i < size; i++) {
 // Increment current sum with current element
 sum += arr[i];

 // If the sum is greater than target, remove
 // elements from start of the window
 while (sum > target) {
 sum -= arr[windowStart];
 windowStart++;
 }

 // Update the max size window if needed
 if (i - windowStart > result.second - result.first) {
 result = { windowStart, i };
 }
 }

 return result;
}

