class TicTacToe {

    // Define the variables
    private var board: Array<CharArray>    // 2D array to store the board 
    private var currentPlayer: Char        // Current player (X or O)

    // Initialize the game
    init {
        board = Array(3) { CharArray(3) }
        restartGame()   
    }

    // Restart the game
    private fun restartGame() {
        // Reset the board
        for (row in 0..2) {
            for (col in 0..2) {
                board[row][col] = '-'
            }
        }
        // Set the first player
        this.currentPlayer = 'X'
    }

    // Make a move
    fun makeMove(row: Int, col: Int) {
        // Check for a valid move
        if (!isValidMove(row, col)) 
             throw InvalidMoveException()

        // Make the move
        board[row][col] = currentPlayer

        // Change the player
        currentPlayer = if (currentPlayer == 'X') 'O' else 'X'
    }

    // Check for a valid move
    private fun isValidMove(row: Int, col: Int): Boolean {
        if (row < 0 || row > 2 || col < 0 || col > 2)
            return false

        // Check if the cell is empty
        return board[row][col] == '-'
    }

    //Check for a winner
    fun checkForWinner(): Char? {

        // Check the rows
        for (row in 0..2) {
            if (board[row][0] == board[row][1]
             && board[row][1] == board[row][2]
             && board[row][0] != '-')
            return board[row][0]
        }

        // Check the columns
        for (col in 0..2) {
            if (board[0][col] == board[1][col] 
             && board[1][col] == board[2][col]
             && board[0][col] !=  '-')
            return board[0][col]
        }

        // Check the diagonals
        if (board[0][0] == board[1][1] 
         && board[1][1] == board[2][2] 
         && board[0][0] != '-')
            return board[0][0]

        if (board[0][2] == board[1][1]
         && board[1][1] == board[2][0]
         && board[0][2] != '-')
            return board[0][2]

        // Game in progress
        return null
    }
}

