void generatePermutations(vector<int> arr, int index) 
{  
    // Base case 
    if (index >= arr.size()) { 
        for (int i = 0; i < arr.size(); i++) 
            cout << arr[i] << " "; 
        cout << endl; 
        return; 
    } 

    // Recursive case 
    for (int i = index; i < arr.size(); i++) 
    { 
        // Swapping branch 
        swap(arr[index], arr[i]); 

        // Recursive call 
        generatePermutations(arr, index + 1); 

        // Backtracking (Swapping back) 
        swap(arr[index], arr[i]); 
    } 
} 

