def merge(head1, head2): 
    # Base cases 
    if head1 is None: 
        return head2  
    if head2 is None: 
        return head1 

    mergedHead = None
    if head1.data <= head2.data: 
        mergedHead = head1 
        mergedHead.next = merge(head1.next, head2) 
