// Global object created to store and track users
let users = {};

// Middleware function to track the page visits
app.use((req, res, next) => {
 // Retrieve user from global users object
 let user = users[req.sessionID];
 // If user does not exist, create a new user and store in global object
 if (!user) {
 user = {
 pageVisits: {},
 totalTimeSpent: 0
 };
 users[req.sessionID] = user;
 }
 // Retrieve the page url
 let page = req.url;
 // If the page has not been visited before, store its initial visit time 
 if (!user.pageVisits[page]) {
 user.pageVisits[page] = {
 startTime: new Date(),
 totalTime: 0
 };
 }
 // Calculate the total page time
 let pageVisitTime = new Date() - user.pageVisits[page].startTime; 
 user.totalTimeSpent += pageVisitTime;
 // Store the total page time
 user.pageVisits[page].totalTime += pageVisitTime;
 // Reset the start time for visited page
 user.pageVisits[page].startTime = new Date();
 // Pass control to next middleware
 next();
});

// Endpoint to serve total time spent page visits
app.get('/time_spent', (req, res) => {
 // Retrieve user from global users object
 let user = users[req.sessionID];
 // If user does not exist, return zero
 if (!user) {
 return res.send({ totalTimeSpent: 0 });
 }
 // Return the user's total time spent
 return res.send({ totalTimeSpent: user.totalTimeSpent });
});

