    # create a dictionary to hold the count of each element
    count = {}

    # loop through the first list
    for elem in lst1:
        if elem in count:
            count[elem] += 1
        else:
            count[elem] = 1

    # count the number of elements in the second list
    # that are also present in the first list
    num_common = 0
    for elem in lst2:
        if elem in count and count[elem] > 0:
            num_common += 1
            count[elem] -= 1

