#include <stdio.h> 
#include <limits.h> 

#define MAX_PRIO_NUM 10

// A heap has current size and array of elements
struct MinHeap { 
    int size; 
    int* array; 
}; 

// A scheduling system has the number of tasks and the min heap
struct SchedulingSystem {
    int num_tasks;
    struct MinHeap min_heap;
};

// The structure to represent a task
struct Task { 
    int prio; 
    int period; 
    int exec_time; 
    int deadline; 
};

// Utility function to create a min heap of given capacity 
struct MinHeap* createMinHeap(int cap) { 
    struct MinHeap* min_heap = (struct MinHeap*) malloc(sizeof(struct MinHeap)); 
    min_heap->size = 0;  
    min_heap->array = 
        (int*) malloc(cap * sizeof(int)); 
    return min_heap; 
} 

// Utility function inserts a task into the heap
void insertTask(struct MinHeap* min_heap, int task) { 
    if (min_heap->size == MAX_PRIO_NUM) 
        return; 

    int i = ++min_heap->size; 
    while (i && min_heap->array[i/2] > task) { 
        min_heap->array[i] = min_heap->array[i/2]; 
        i /= 2; 
    } 
    min_heap->array[i] = task; 
}

// Utility function to delete a task from min heap 
int deleteTask(struct MinHeap* min_heap) { 
    if (min_heap->size == 0) 
        return INT_MAX; 

    int root = min_heap->array[0]; 

    min_heap->array[0] = min_heap->array[min_heap->size-1]; 
    --min_heap->size; 
    min_heapify(min_heap, 0); 

    return root; 
} 

// Utility function heapify 
void min_heapify(struct MinHeap* min_heap, int idx) { 
    int smallest = idx; 
    int l = 2 * idx + 1; 
    int r = 2 * idx + 2; 

    if (l < min_heap->size && 
        min_heap->array[l] < min_heap->array[smallest]) 
        smallest = l; 

    if (r < min_heap->size && 
        min_heap->array[r] < min_heap->array[smallest]) 
        smallest = r; 

    if (smallest != idx) { 
        swap(min_heap->array[smallest],min_heap->array[idx]); 
        min_heapify(min_heap, smallest); 
    } 
} 

// The driver program to add and delete tasks from the heap
int main() 
{
    int num_tasks;
    printf("Enter the number of tasks: \n");
    scanf("%d", &num_tasks);

    struct MinHeap* min_heap = createMinHeap(num_tasks); 
    struct SchedulingSystem* scheduling_sys = (struct SchedulingSystem*) malloc(sizeof(struct SchedulingSystem)); 
    scheduling_sys->min_heap = *min_heap;
    scheduling_sys->num_tasks = num_tasks;

    // insert tasks 
    int task_counter = 0;
    while (task_counter < num_tasks) { 
        insertTask(min_heap, task_counter);
        task_counter += 1;
    }

    // delete tasks 
    while (min_heap->size) { 
        printf("%d ", deleteTask(min_heap));
        task_counter -= 1; 
    } 

    deleteTask(min_heap); 
    return 0; 
}

