s App extends React.Component {
  state = {
    loggedIn: false,
    message: '',
    messages: [],
    username: '',
    photoURL: '',
  }

  componentDidMount() {
    // Initialize Firebase
    const firebaseConfig = {
      // Your firebase configuration values go here
    };
    firebase.initializeApp(firebaseConfig);

    // Handle authentication state changes
    this.authUnsubscribe = firebase.auth().onAuthStateChanged((user) => {
      if (user) {
        const { uid, photoURL } = user;
        this.setState({ loggedIn: true, username: uid, photoURL });
        this.dbUnsubscribe = firebase.database().ref('/messages').on('value', (snapshot) => {
          const messages = Object.values(snapshot.val()) || [];
          this.setState({ messages });
        });
      } else {
        // User is signed out
        this.authUnsubscribe && this.authUnsubscribe();
        this.dbUnsubscribe && this.dbUnsubscribe();
        this.setState({ loggedIn: false, message: '', messages: [], username: '', photoURL: '' });
      }
    });
  }

  // Generate a unique key for the message
  generateKey = (pre) => {
    return `${pre}_${new Date().getTime()}`;
  };

  // Read message from the text input
  onChangeText = (message) => this.setState({ message });

  // Handle sending button press
  onSend = () => {
    if (this.state.message.length > 0) {
      // Generate a key and add the message to the database
      const key = this.generateKey('message');
      firebase.database().ref('/messages').child(key).set({
        text: this.state.message,
        createdAt: new Date().getTime(),
        user: {
          id: this.state.username,
          photoURL: this.state.photoURL,
        },
      });
      this.setState({ message: '' });
    }
  };

  // Render the chat messages and the text input field
  render() {
    const { messages, message, loggedIn } = this.state;
    return (
      <View style={styles.container}>
        <Text>Logged in: {loggedIn ? 'Yes' : 'No'}</Text>
        {messages.map((m) => (
          <View key={m.createdAt} style={styles.messageContainer}>
            <Image
              style={{ width: 30, height: 30, borderRadius: 15 }}
              source={{ uri: m.user.photoURL }}
            />
            <Text style={styles.messageText}>{m.text}</Text>
          </View>
        ))}
        {loggedIn && (
          <View style={styles.inputContainer}>
            <TextInput 
              style={styles.input} 
              value={message} 
              onChangeText={this.onChangeText} 
            />
            <TouchableOpacity onPress={this.onSend}>
              <Text style={styles.send}>Send</Text>
            </TouchableOpacity>
           </View>
        )}
      </View>
    );
  }
}

