# Hashes a block
def hash_block(block):
    # Create a SHA256 hash
    sha = hashlib.sha256()
    # Encode the data to the hash - 
    # for consistency between different systems
    sha.update(json.dumps(block).encode())
    # Return the encoded block
    return sha.hexdigest()

