import itertools

def find_all_permutations(string):
    permutations = itertools.permutations(string)
    subsequences = set()
    for permutation in permutations:
        subsequences.add(''.join(permutation))
        for i in range(1, len(permutation)+1):
            for subset in itertools.combinations(permutation, i):
                subsequences.add(''.join(subset))
                #print(''.join(subset))
    return subsequences

