// Function to determine the longest increasing sub sequence
int longestIncSubseq(int arr[], int size) 
{ 
   int max = 0; 
   int min = 0; 
   int dp[size]; 

   // Initializing each elements of dp with 1 
   for (int i = 0; i < size; i++) 
      dp[i] = 1; 

   // Loop for deciding individual element as per LIS 
   for (int i = 1; i < size; i++) { 
      for (int j = 0; j < i; j++) { 
         if (arr[i] > arr[j] && dp[i] < dp[j] + 1) 
            dp[i] = dp[j] + 1; 
      } 
   } 

   // Loop for determining maximum of all dp[i] 
   for (int i = 0; i < size; i++) { 
      if (max < dp[i]) { 
         max = dp[i]; 
      }
   } 
   return max; 
}

void rotateAroundOrigin(float angle) 
{ 
    // Create an identity matrix
    mat4 identityMatrix = mat4(1.0f); 

    // Create a translation matrix to move the origin to the centre of the polygon 
    mat4 translationMatrix = translate(identityMatrix, vec3(-0.5f, -0.5f, 0.0f)); 

    // Create a rotation matrix around the Z axis by the given angle
    mat4 rotationMatrix = rotate(identityMatrix, radians(angle), vec3(0.0f, 0.0f, 1.0f)); 

    // Multiply the matrices to obtain the transformation matrix
    mat4 transformationMatrix = translationMatrix * rotationMatrix; 

    // Pass the transformation matrix to the vertex shader
    glUniformMatrix4fv(transformLoc, 1, GL_FALSE, value_ptr(transformationMatrix)); 

    // Draw the polygon
    glDrawElements(GL_TRIANGLES, 6, GL_UNSIGNED_INT, 0); 
}

