// Java program to join two arrays 
// into one 
public class JoinArrays {  
    public static void main(String[] args) {  
        // First array  
        int[] array1 = {2, 4, 5};  

        // Second array  
        int[] array2 = {3, 6, 8};  

        int l1 = array1.length;  
        int l2 = array2.length;  

        int[] merge = new int[l1 + l2];  

        // Copying elements of first array into 
        // merge array  
        int i;  
        for (i = 0; i < l1; i++) {  
            merge[i] = array1[i];  
        }  

        // Copying elements of second array into  
        // merge array  
        for (i = l1; i < l2 + l1; i++) {  
            merge[i] = array2[i - l1];  
        }  

        // Printing elements of merged array  
        for (i = 0; i < l2 + l1; i++)  
            System.out.print(merge[i] + " ");  
    }  
}

