def max_sum(nums):
    # Initialize max_sum to first number in array
    max_sum = nums[0]

    # Iterate through array
    for i in range(1, len(nums)):
        # If sum of current number and the next number is greater than current max_sum
        if nums[i] + nums[i-1] > max_sum:
            max_sum = nums[i] + nums[i-1]
    return max_sum

