function float_bin(number) { 
    let bin = number.toString(2);
    const sign = bin < 0 ? "-" : "";

    if(bin.indexOf(".") == -1) {
        return sign + "0"+"."+"0".repeat(32-bin.length)+Math.abs(bin);
    }
    const [a,b] = bin.split(".");
    if(b.length < 32) {
        return sign + a + "." + b + "0".repeat(32 - b.length);
    }
    return sign + a + "." + b.slice(0,32); 
}

