def generate_fibonacci_numbers(n):
    # Starting numbers
    a = 0
    b = 1

    # Check that n is a valid number
    if n < 0:
        print("Error: Cannot generate Fibonacci sequence of length less than 0.")
    elif n == 0:
        return []
    elif n == 1:
        return [a]
    elif n == 2:
        return [a, b]
    else:
        # Generate list of Fibonacci numbers
        fib_nums = [a, b]
        for _ in range(2, n):
            c = a + b
