function binarySearch(arr, x) {
  let start = 0;
  let end = arr.length - 1;

  while (start <= end) {
    const mid = Math.floor((start + end) / 2);

    if (arr[mid] === x) {
      return mid;
    }

    if (arr[mid] < x){
      start = mid + 1;
    } else {
      end = mid - 1;
    }
  }

  return -1;
}

