def infixToPostfix(infixExpression):
    precedence = {
        '+': 1,
        '-': 1,
        '*': 2,
        '/': 2,
        '^': 3
    }

    output = ""
    stack = []

    for ch in infixExpression:
        if ch == '(':
            stack.append(ch)
        elif ch == ')':
            while len(stack) != 0 and stack[-1] != '(':
                item = stack.pop()
                output += item
            if len(stack) != 0 and stack[-1] != '(':
                return -1
            else:
                stack.pop()
        elif ch in precedence:
            while len(stack) != 0 and precedence[ch] < precedence[stack[-1]]:
                item = stack.pop()
                output += item
            stack.append(ch)
        else:
            output += ch

    while len(stack) != 0:
        item = stack.pop()
        output += item

    return output

