// Function to calculate the Euclidean distance between two points
double distance(Point p1, Point p2) {
 double d  = sqrt(pow(p2.x - p1.x, 2) + pow(p2.y - p1.y, 2) + pow(p2.z - p1.z, 2));
 return d;
}

// Function to calculate the closest pair in a vector of points
pair<Point, Point> closest_pair(vector<Point> points) {
 double min_distance = __DBL_MAX__;
 pair<Point, Point> min_pair;

 for (int i = 0; i < points.size(); i++) {
 for (int j = 0; j < points.size() - i - 1; j++) {
 double d = distance(points[i], points[i + j + 1]);
 if (d < min_distance) {
 min_distance = d;
 min_pair = {points[i], points[i + j + 1]};
 }
 }
 }

 return min_pair;
}

