class ContactsViewController: UIViewController {

    @IBOutlet weak var tableView: UITableView!
    @IBOutlet weak var searchTextField: UITextField!

    let store = CNContactStore()

    var contacts = [CNContact]()

    override func viewDidLoad() {
        super.viewDidLoad()

        authorize()
    }

    func authorize() {
        store.requestAccess(for: .contacts) { granted, error in
            guard granted else { return }
            self.retrieveContacts()
        }
    }

    func retrieveContacts() {
        contacts = store.unifiedContacts(matching: CNContact.predicateForContacts(), keysToFetch: [
            CNContactFamilyNameKey as CNKeyDescriptor,
            CNContactGivenNameKey as CNKeyDescriptor
        ]).map { $0.mutableCopy() as! CNMutableContact }
        tableView.reloadData()
    }

    @IBAction func search(_ sender: UITextField) {
        if let query = sender.text,
            !query.isEmpty {
            contacts = store.unifiedContacts(matching: CNContact.predicateForContacts(matchingName: query),
                                             keysToFetch: [
                CNContactGivenNameKey as CNKeyDescriptor,
                CNContactFamilyNameKey as CNKeyDescriptor
            ]).map { $0.mutableCopy() as! CNMutableContact }
        } else {
            retrieveContacts()
        }

        tableView.reloadData()
    }
}

