public class FindFirstMissingPositive {
    public static int findFirstMissingPositive(int[] arr) {
        int n = arr.length;

        int missing_positive = 1;
        int i = 0; 
        while (i < n) { 
            if (arr[i] <= 0 || arr[i] >= n) 
                i++ ; 
            else { 
                int index = arr[i] - 1; 
                if (arr[index] != arr[i]) 
                    swap(arr, i, index);
                else
                    i++ ; 
            } 
        } 

        for (i = 0; i < n; i++) { 
            if (arr[i] != i + 1) { 
                missing_positive = i + 1; 
                break; 
            } 
        } 

        return missing_positive; 
    } 

    static void swap(int[] arr, int i, int j) { 
        int temp = arr[i]; 
        arr[i] = arr[j]; 
        arr[j] = temp; 
    } 

    public static void main(String[] args) {
        int[] arr = {-7, -5, -2, 0, 4};
        int res = FindFirstMissingPositive.findFirstMissingPositive(arr);
        System.out.println("The first missing positive number is " + res);
    }
}

