  let output = [];
  const recursiveParse = (input, path = []) => {
    if (typeof input === 'object' && !Array.isArray(input)) {
      Object.keys(input).forEach(key => {
        const newPath = [...path, key];
        recursiveParse(input[key], newPath);
      });
    } else {
      output.push([path.join('.'), input]);
    }
  };
  recursiveParse(jsonObj);
  return output;
};

