bool is_substring(string string1, string string2) {
    int lenString1 = string1.length();
    int lenString2 = string2.length();

    // Check if string2 is longer than string1
    if (lenString2 > lenString1)
    {
        return false;
    }

    // compare the two strings character by character
    for (int i = 0; i <= lenString1 - lenString2; i++)
    {
        int j;
        for (j = 0; j < lenString2; j++)
        {
            if (string1[i + j] != string2[j])
            {
                break;
            }
        }

        // if we reached end of 'string2', it is a sub-string
        if (j == lenString2)
        {
            return true;
        }
    }
    return false;
}

