class EnglishRepresentation:
    ones = ["", "one", "two", "three", "four",  "five", "six", "seven", "eight", "nine", "ten",
            "eleven", "twelve", "thirteen", "fourteen", "fifteen","sixteen", "seventeen", "eighteen", "nineteen"]

    tens = ["", "ten", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"]

    scales = ["", "thousand", "million", "billion", "trillion"]

    def english_number(self, number):
        if number < 0:
            return "negative " + self.english_number(-number)

        if number < 20:
            return self.ones[number]

        if number < 100:
            return self.tens[number//10] + ( "" if number % 10 == 0 else " " + self.ones[number % 10] )

        if number < 1000:
            return self.ones[number//100] + " hundred" + ( "" if number % 100 == 0 else " " + self.english_number(number % 100) )

        scale_number = 0
        number = number // 1000
        english = ""

        while number > 0:
            number, rem = divmod(number, 1000)
            if rem > 0:
                english = self.english_number(rem).strip() + " " + self.scales[scale_number] + ", " + english
            scale_number += 1

        return english.strip()

