class Node { 
    constructor(data) 
    { 
        this.data = data; 
        this.left = null; 
        this.right = null; 
    } 
} 

// Function to build binary tree from given array 
function constructTree(nums) { 
    let n = nums.length; 
    if (n == 0) 
        return null; 

    let root = new Node(nums[0]); 

    let lp = []; 
    let rp = []; 

    lp.push(root); 

    // start from first element 
    let i = 1; 

    while (i < n) { 
        let par = lp.shift(); 
        let lc = new Node(nums[i]); 
        par.left = lc; 
        lp.push(lc); 

        if (i + 1 < n) { 
            let rc = new Node(nums[i + 1]); 
            par.right = rc; 
            rp.push(rc); 
            i += 2; 
        } 
    } 
    i = 0; 
    while (i < rp.length) { 
        lp.push(rp[i++]); 
    } 
    return root; 
}

