fn generate_permutations(s: String, result: &mut Vec<String>) {
    let n = s.len();
    if n == 0 { return; }
    if n == 1 { result.push(s); return; }

    let mut chars: Vec<char> = s.chars().collect();
    permutations(&mut chars[..], 0, result);
}

fn permutations(arr: &mut [char], index: usize, result: &mut Vec<String>) {
    if index >= arr.len() {
        result.push(arr.iter().collect());
        return;
    }

    for i in index..arr.len() {
        arr.swap(index, i);
        permutations(arr, index + 1, result);
        arr.swap(index, i);
    }
}

