def get_closest(word, lines):
    min_dist = float('inf')
    closest_match = ""

    for line in lines:
        dist = edit_dist(word, line)
        if dist < min_dist:
            min_dist = dist
            closest_match = line

    return closest_match

# Calculate the Levenshtein Distance
def edit_dist(str1, str2): 
    m=len(str1)+1
    n=len(str2)+1

    tbl = {}
    for i in range(m): 
        tbl[i,0]=i
    for j in range(n): 
        tbl[0,j]=j
    for i in range(1, m): 
        for j in range(1, n):
            cost = 0 if str1[i-1] == str2[j-1] else 1
            tbl[i,j] = min(tbl[i, j-1]+1, tbl[i-1, j]+1, tbl[i-1, j-1]+cost)

    return tbl[i,j]

