function levenshteinDistance(str1, str2) {
  // base case
  if (str1 === str2) {
    return 0;
  }
  // if either strings are empty, return length of the other one
  if (str1.length === 0) {
    return str2.length; 
  }
  if (str2.length === 0) {
    return str1.length; 
  }
  // if last characters are the same, calculate edit distance of the shortened strings
  const lastChar = str1[str1.length - 1];
  if (lastChar === str2[str2.length - 1]) {
    const shorterStr1 = str1.slice(0, -1);
    const shorterStr2 = str2.slice(0, -1);
    return levenshteinDistance(shorterStr1, shorterStr2);
  } else {
    // edit distance of shorter strings
    const shorterStr1 = str1.slice(0, -1);
    const shorterStr2 = str2.slice(0, -1);
    const distanceShort = levenshteinDistance(shorterStr1, shorterStr2);

    // edit distance of the same string without the last char
    const distanceDel = levenshteinDistance(str1, shorterStr2);

    // edit distance of the same string with an additional last char
    const distanceIns = levenshteinDistance(shorterStr1, str2);

    // return the min of all options
    return 1 + Math.min(distanceShort, distanceDel, distanceIns);
  }
}

