def distinct_subsequences(s):
    n = len(s)
    dp = [[0 for i in range(n+1)] for i in range(n+1)]
    for i in range(n+1):
     dp[i][0] = 1

    for i in range(1, n+1):
        for j in range(1, n+1):
            if s[i-1] == s[j-1] and i != j:
                dp[i][j] = dp[i-1][j-1] + dp[i-1][j]
            else:
                dp[i][j] = dp[i-1][j]
    return dp[n][n]

