std::vector<int> intersection(std::vector<int>& set1, std::vector<int>& set2) 
{
    std::vector<int> res; 
    int i = 0, j = 0; 
    while (i < set1.size() && j < set2.size()) 
    { 
        if (set1[i] < set2[j]) 
            i++; 

        else if (set2[j] < set1[i]) 
            j++; 

        else 
        { 
