function countingSort(arr) {
    let counts = [];
    for(let i = 0; i < arr.length; i++) {
        counts[arr[i]] = (counts[arr[i]] || 0) + 1;
    }

    let sortedArr = [];
    let idx = 0;
    for(let i = 0; i < counts.length; i++) {
        while(counts[i] > 0) {
            sortedArr[idx++] = i;
            counts[i]--;
        }
    }

    return sortedArr;
}

public class TwoDimensionalArraySort {

    // function to sort the 2D array according to the sum of elements in row wise 
    static void rowWiseSorting(int m[][]) 
    { 
        // get the length of number of columns of 2D array 
        int cols = m[0].length; 

        for (int i = 0. i < m.length; i++) { 

            // For every row, sort the elements using a temporary row 
            int[] temp = new int[m[i].length]; 
            System.arraycopy(m[i], 0, temp, 0, m[i].length); 

            // This will sort the ith row of 2D array 
            Arrays.sort(temp); 

            // Overwrite the sorted values in the original array
            for (int j = 0; j < cols; j++) { 
                m[i][j] = temp[j]; 
            } 
        } 
    } 

    // Driver code 
    public static void main(String[] args) 
    { 
        int m[][] = { { 3, 5, 4 }, { 2, 5, 1 }, { 9, 7, 3 }, { 11, 9, 5 } }; 

        rowWiseSorting(m); 

        System.out.println("Sorted 2D Array :"); 
        for (int i = 0; i < m.length; i++) { 
            for (int j = 0; j < m[0].length; j++) { 
                System.out.print(m[i][j] + " "); 
            } 
            System.out.println(); 
        } 
    } 
}

