func longestCommonSubsequence(_ s1: String, _ s2: String) -> Int {
    var lcsLength = 0 
    var s1 = Array(s1) 
    var s2 = Array(s2) 

    let m = s1.count 
    let n = s2.count 

    var L = Array(repeating: Array(repeating: 0, count: n + 1), count: m + 1) 

    for i in 0...m { 
        for j in 0...n { 
            if s1[i] == s2[j] { 
                L[i][j] = L[i-1][j-1] + 1 
            } else { 
                L[i][j] = max(L[i-1][j], L[i][j-1]) 
            } 
            lcsLength = max(lcsLength, L[i][j]) 
        } 
    } 
    return lcsLength
}

