public static String toBinary(int n){ 
    if(n == 0){ 
        return "0"; 
    } 

    String binary = "";  
    while(n > 0) { 
        int rem = n % 2; 
        binary = rem + binary; 
        n = n / 2; 
    }  
    return binary; 
}

