    result = "" 

    for i in range(len(plain_str)): 
        char = plain_str[i] 

        # Encrypt uppercase characters
        if (char.isupper()): 
            result += chr((ord(char) + key-65) % 26 + 65) 

        # Encrypt lowercase characters    
        else: 
            result += chr((ord(char) + key - 97) % 26 + 97) 

    return result

