    let output = [];
    let i = 0;
    let j = 0;

    while(i < input1.length && j < input2.length) {
        if (input1[i] <= input2[j]) {
            output.push(input1[i]);
            i++;
        } else {
            output.push(input2[j]);
            j++;
        }
    }

    while (i < input1.length) {
        output.push(input1[i]);
        i++;
    }

    while (j < input2.length) {
        output.push(input2[j]);
        j++;
    }
    return output;
}

