def compare_address(address1, address2):
    ''' This function takes two address objects and compare them. Returns 1 if
    address1 is greater than address2, -1 if address1 is lesser than address2, 0 if
    they are equal.
    '''
    # First compare house number
    if address1.house_number > address2.house_number:
        return 1
    elif address1.house_number < address2.house_number:
        return -1
    # Then compare street name
    if address1.street_name > address2.street_name:
        return 1
    elif address1.street_name < address2.street_name:
        return -1
    # Finally compare zip code
    if address1.zip_code > address2.zip_code:
        return 1
    elif address1.zip_code < address2.zip_code:
        return -1
    # If all fields are equal, address are equal.
    return 0

