CREATE PROCEDURE ReverseString(IN inputString VARCHAR(255))
BEGIN
  DECLARE outputString VARCHAR(255);
  DECLARE counter INT DEFAULT LENGTH(inputString);
  WHILE counter > 0 DO
    SET outputString = CONCAT(outputString, SUBSTRING(inputString, counter, 1));
    SET counter = counter - 1;
  END WHILE;
  SELECT outputString;
END

