// Function to print all possible combinations of a given set
// of numbers
void findCombinations(vector<int> arr, vector<vector<int>> &result,
                      vector<int> temp, int i) 
{ 
    // Print current subset 
    if (temp.size() > 0) 
        result.push_back(temp); 

    // Recur for remaining elements with remaining elements 
    for (int j = i; j < arr.size(); j++) { 

        // add current element arr[j] to 
        // the subset 
        temp.push_back(arr[j]); 

        // Move onto the next element 
        findCombinations(arr, result, 
                         temp, j + 1); 

        // Backtrack - Remove current element
        // from subset 
        temp.pop_back(); 
    } 
} 

