import "fmt"

func lcs(s1, s2 string) int {
  m := len(s1)
  n := len(s2)

  dp := make([][]int, m+1)
  for i := range dp {
    dp[i] = make([]int, n+1)
  }

  for i := 1; i < m+1; i++ {
    for j := 1; j < n+1; j++ {
      if s1[i-1] == s2[j-1] {
        dp[i][j] = 1 + dp[i-1][j-1]
      } else {
        dp[i][j] = max(dp[i-1][j], dp[i][j-1]);
      }
    }
  }

  return dp[m][n]
}

