#include <iostream>
#include <unordered_map>
using namespace std;

int mostCommonElement(int arr[], int n){
  // Create a map to store elements and frequencies
  unordered_map<int, int> count;

  // Traverse through the array
  for (int i=0; i<n; i++)
    count[arr[i]]++;

  // Find the greatest frequency
  int max_count = 0;
  int most_frequent_element = -1;

  for (unordered_map<int, int>::iterator it=count.begin(); it!=count.end(); it++){
    // Update max_count if it is less than the frequency
    if (max_count < it->second){
      max_count = it->second;
      most_frequent_element = it->first;
    }
  }

  return most_frequent_element;
}

int main(){
  int arr[] = {3, 5, 2, 6, 3, 1, 3};
  int n = sizeof(arr)/sizeof(arr[0]);

  // Find most frequent element
