// Function to generate prime numbers
bool isPrime(int n)
{
    // Corner case
    if (n <= 1)  return false;

    // Iterate from 2 to n/2
    for (int i = 2; i < n / 2; i++)
        if (n % i == 0)  return false;

    return true;
}

// Function to generate all the prime numbers
int primeNumbers(int n)
{
    int primeArr[n];
    int k = 0;
    for (int i = 2; k < n; i++)
    {
        if (isPrime(i)) {
            primeArr[k] = i;
            k++;
        }
    }

    // Print all the numbers
    for (auto i : primeArr)
        std::cout << i << " ";
    std::cout << endl;
    return 0;
}

