// Function to sort array using insertion sort 
void insertionSort(int list[], int n) 
{ 
   int i, key, j; 
   for (i = 1; i < n; i++) 
   { 
       key = list[i]; 
       j = i-1; 

       while (j >= 0 && list[j] > key) 
       { 
           list[j+1] = list[j]; 
           j = j-1; 
       } 
       list[j+1] = key; 
   } 
} 

