 int time;

 public Order(int w, int t) {
 weight = w;
 time = t;
 }
}

public class DeliveryRouteOptimizer {
 // Function to optimize the delivery routes
 public void optimize(Vehicle[] vehicles, Order[] orders) {
 // Variables to store the current capacity and time
 int currCap = 0;
 int currTime = 0;

 // Iterate through all orders
 for (int i = 0; i < orders.length; i++) {
 // Current order
 Order currOrder = orders[i];

 // Check if current capacity is enough for the order
 if (currCap + currOrder.weight <= vehicles[0].capacity) {
 // Add the order to current route
 currCap += currOrder.weight;
 currTime += currOrder.time;
 }
 else {
 // Reset the capacity and time
 currCap = currOrder.weight;
 currTime = currOrder.time;

 // Assign different vehicle
 vehicles[1].capacity = currCap;
 vehicles[1].time = currTime;
 }
 }
 }
}

