import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.TimeZone;

public class TimeZoneExample {
    public static void main(String[] args) {
        try {
            // Given Time in UTC
            String givenUTC = "2020-05-18T09:15:00Z";

            // Format of the given time
            DateFormat utcFormat = new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss'Z'");
            utcFormat.setTimeZone(TimeZone.getTimeZone("UTC"));

            // Parse the time and convert it to Date object
            Date date = utcFormat.parse(givenUTC);

            // Get the current system default time zone
            String currentSystemTimeZone = TimeZone.getDefault().getID();

            // Create a new DateFormat and set the current system time zone
            DateFormat currentFormat = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
            currentFormat.setTimeZone(TimeZone.getTimeZone(currentSystemTimeZone));

            // Format the given date object to the new time zone
            String newTime = currentFormat.format(date);
            System.out.println(newTime);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}

