import numpy as np

class ConnectFourGame():
    def __init__(self, player="X", size=6):
        self.turn = player
        self.board = np.zeros((size, size), dtype=str)
        self.columns = []

    def play(self, col):
        if not 0 <= col < 7 or col in self.columns:
            return

        if self.turn == "X":
            self.board[:, col][self.board[:, col] == 0] = "X"
            self.turn = "O"
            self.columns.append(col)
        else:
            self.board[:, col][self.board[:, col] == 0] = "O"
            self.turn = "X"
            self.columns.append(col)

    def check_win(self):
        last_player = ""
        if self.turn == "X":
            last_player = "O"
        else:
            last_player = "X"

        # vertical check
        for i in range(7):
            for j in range(3):
                if np.all(self.board[j:j+4, i] == last_player):
                    return True

        # horizontal check
        for i in range(6):
            for j in range(4):
                if np.all(self.board[i, j:j+4] == last_player):
                    return True

        # diagonal check
        for i in range(3):
            for j in range(4):
                if (np.all(self.board[i:i+4, j:j+4].diagonal() == last_player) or
                        np.all(np.fliplr(self.board[i:i+4, j:j+4]).diagonal() == last_player)):
                    return True
        return False

