// Recursive function to calculate longest increasing subsequence 
int LIS(vector<int> &arr, int n) 
{ 
    // If only single item is present
    if (n == 1) 
        return 1; 

    // Initialize result 
    int max_ending_here = 1; 

    // Calculate LIS for each subseq of length n
    for (int i=1; i<n; i++) 
    { 
        int res = LIS(arr, i); 
        if (arr[i-1] < arr[n-1] && res + 1 > max_ending_here) 
            max_ending_here = res + 1; 
    } 

    return max_ending_here; 
} 

int main()
{
    vector<int> arr = { 3, 4, 2, 1, 5 }; 

    int n = arr.size(); 
    cout << "Length of LIS: "
         << LIS(arr, n) << endl;

    return 0;
}

def mode(nums):
    num_count = {}
    # Count the occurences of each number
    for num in nums:
        if num in num_count:
            num_count[num] += 1
        else:
            num_count[num] = 1
    # Return the mode if there is one
    max_count = 0
    mode = -1
    for num in num_count:
        if num_count[num] > max_count:
            max_count = num_count[num]
            mode = num
    return mode

