def merge_sorted_lists(list1, list2): 
    merged_list = [] 

    # While there are elements in both lists 
    while len(list1) > 0 and len(list2) > 0: 
        if list1[0] < list2[0]: 
            merged_list.append(list1[0]) 
            list1.pop(0) 
        else: 
            merged_list.append(list2[0]) 
            list2.pop(0) 

    # If the second list is empty 
    if len(list1) > 0: 
        merged_list.extend(list1) 
    # If the first list is empty 
    elif len(list2) > 0: 
        merged_list.extend(list2) 
    return merged_list

def check_same_list(list1, list2):
    current_node1 = list1.head
    current_node2 = list2.head
    while current_node1 is not None and current_node2 is not None:
        if current_node1.data != current_node2.data:
            return False
        current_node1 = current_node1.next_node
        current_node2 = current_node2.next_node

    if current_node1 is not None or current_node2 is not None:
        return False

    return True

