public class PerformanceComparison { 
    public static void main(String args[]) 
    { 
        int array[] = {64, 25, 12, 22, 11}; 

        // Bubble Sort 
        long bubbleStartTime = System.nanoTime(); 
        bubbleSort(array); 
        long bubbleEndTime = System.nanoTime(); 
        long bubbleTimeTaken = bubbleEndTime - bubbleStartTime; 

        // Insertion Sort 
        long insertionStartTime = System.nanoTime(); 
        insertionSort(array); 
        long insertionEndTime = System.nanoTime(); 
        long insertionTimeTaken = insertionEndTime - insertionStartTime; 

        System.out.println("Time Taken by Bubble Sort: " + bubbleTimeTaken); 
        System.out.println("Time Taken by Insertion Sort: " + insertionTimeTaken); 
    } 

    // Bubble Sort Code 
    static void bubbleSort(int[] array) 
    { 
        int n = array.length; 
        int temp = 0; 
        for(int i = 0; i < n; i++) 
        { 
            for(int j = 1; j < (n-i); j++) 
            { 
                if(array[j-1] > array[j]) 
                {  
                    temp = array[j-1]; 
                    array[j-1] = array[j]; 
                    array[j] = temp; 
                }                     
            } 
        } 
    } 

    // Insertion Sort Code 
    static void insertionSort(int array[]) 
    { 
        int n = array.length; 
        for (int i = 1; i < n; ++i) { 
            int key = array[i]; 
            int j = i - 1; 
            while (j >= 0 && array[j] > key) { 
                array[j + 1] = array[j]; 
                j = j - 1; 
            } 
            array[j + 1] = key; 
        } 
    } 
}

