bool areAnagram(string& s1, string& s2) 
{ 
    if (s1.length() != s2.length()) 
        return false; 

    int frequency[256] = { 0 }; 

    // Increment the frequency of characters present in the first string 
    for (int i = 0; i < s1.length(); i++) 
        frequency[s1[i]]++; 

    // Decrement frequency of characters present in the second string 
    for (int i = 0; i < s2.length(); i++) 
        frequency[s2[i]]--; 

    // If all frequencies become 0, then both strings will be anagrams 
    for (int i = 0; i < 256; i++) 
        if (frequency[i] != 0) 
            return false; 

    return true; 
}

