class Queue {

  Stack<Integer> s1;
  Stack<Integer> s2;

  public Queue() {
    s1 = new Stack<Integer>();
    s2 = new Stack<Integer>();
  }

  void enqueue(int item) {
    s1.push(item);
  }

  int dequeue() {
    if (s2.isEmpty()) {
      while (!s1.isEmpty()) {
        s2.push(s1.pop());
      }
    }
    return s2.pop();
  }
}

