class ViewController: UIViewController {

    let apiURL = "https://www.example.com/timetable" //change this to the API URL

    @IBOutlet weak var timetableTableView: UITableView!

    // array to store the transit timetables
    var transitTimetableArray = [TransitTimetable]()

    override func viewDidLoad() {
        super.viewDidLoad()

        // To use the Table View Data Source protocol
        timetableTableView.delegate = self
        timetableTableView.dataSource = self

        // Call the API
        fetchTransitTimetable()
    }

    // Fetch transit timetable from a server
    func fetchTransitTimetable() {
        guard let url = URL(string: apiURL) else {
            return
        }

        URLSession.shared.dataTask(with: url) { (data, response, error) in
            if error != nil {
                print(error!.localizedDescription)
            }

            guard let data = data else { return }

            do {
                // Fetch the data
                let transitData = try JSONDecoder().decode([TransitTimetable].self, from: data)

                // Set the data to transitTimetableArray
                self.transitTimetableArray = transitData

                DispatchQueue.main.async {
                    // Reload table view to show the fetched data
                    self.timetableTableView.reloadData()
                }
            } catch let jsonError {
                print(jsonError)
            }
        }.resume()
    }
}

