int numberOfUniqueSubstring(string s)
{
    int n = s.length();

    // To store the number of unique
    // substrings
    int result = 0;

    // Pick starting point of substring
    for (int i=0; i<n; i++)
    {
        // Pick ending point of substring
        for (int j=i+1; j<=n; j++)
        {
            // Result stores the valid substring
            if (findUnique(s.substr(i, j)) == true)
                result++;
        }
