class Tree {
  constructor() {
    this.root = null;
    this.count = 0;
  }

  addNode(data) {
    let node = {
      data: data,
      children: [], // Child nodes
      parent: null
    };

    // Root
    if (this.count === 0) {
      this.root = node;
      this.count += 1;
      return;
    }

    // Find the parent of the node
    let currentParent = this.root;

    while (true) {
      // Found the parent
      if (currentParent.data === data.parent) {
        currentParent.children.push(node);
        break;
      }
      // Didn't find the parent, keep looking
      else {
        let notFound = true;
        for (let i = 0; i < currentParent.children.length; i++) {
          let child = currentParent.children[i];
          if (child.data.parent === data.parent) {
            currentParent = child;
            notFound = false;
            break;
          }
        }
        if (notFound) {
          console.log('Parent not found!');
          return;
        }
      }
    }
    this.count += 1;
  }
}

