void findMinimalRequests(vector<Page> pageList) {
 // set of strings used to maintain a list of already encountered assets
 unordered_set<string> globalResources;
 // map of pageName and its minimal requests
 unordered_map<string, int> pageResources;

 // iterate over all the pages
 for (auto page : pageList) {
  // unique page name
  string pageName = page.pageName;
  // list of assests of a page
  auto assets = page.assets;

  // set of strings used to maintain a list of page's assets
  unordered_set<string> pageAssetsList;
  // counter to keep track of minimal requests
  int minimalRequests = 0;

  // loop over all the assets of a page
  for (auto asset: assets) {
   // if global asset set does not contain the asset, 
   // increment minimal requests and add the asset to global list
   if (globalResources.find(asset) == globalResources.end()) {
    minimalRequests++;
    globalResources.insert(asset);
   }

   // add the asset to pages asset list
   pageAssetsList.insert(asset);

  }
  // insert pageName and its minimalRequests in the pageResources map
  pageResources.insert(make_pair(pageName, minimalRequests)); 
 }

 // printing of page name and its minimal requests
 for (auto page : pageResources) {
  cout << page.first << " : " << page.second << endl; 
 }

}

// main function
int main() {
 // List of pages
 vector<Page> pageList{{ "P1", {"A1", "A2", "A3", "A4"}},
                       {"P2", {"A4", "A5"}},
	               {"P3", {"A1", "A3", "A5", "A7"}}};

 // function to find minimal requests to load all assets of a page 		       
 findMinimalRequests(pageList);

 return 0;
}

