fun fibonacciUpTo(limit : Int) {
    var cur = 1
    var prev = 0
    print("$prev\t$cur\t")
    while (cur + prev <= limit) {
        var temp = cur
        cur += prev
        prev = temp
        print("$cur\t")
    }
    println()
}

