def most_frequent_char(data):
    # Create a dictionary of characters frequency
    data_dict = {}
    for char in data:
        if char not in data_dict:
            data_dict[char] = 0
        data_dict[char] += 1

    # Find the character with highest frequency
    max_freq = 0
    max_freq_char = None
    for char, freq in data_dict.items():
        if freq > max_freq:
            max_freq = freq
            max_freq_char = char

    return max_freq_char

