public boolean compareTrees(Node root1, Node root2) {
 if (root1 == null && root2 == null) {
  return true;
 }
 if (root1 != null && root2 != null) {
  return (root1.data == root2.data
   && compareTrees(root1.left, root2.left)
   && compareTrees(root1.right, root2.right));
 }
 return false;
}

