class LinkedList { 
 constructor() { 
  this.head = null; 
 } 

 insertAtBeginning(data) { 
  this.head = new Node(data, this.head); 
 } 

 reverse() { 
  let current = this.head; 
  let prevNode = null; 
  let nextNode = null; 

  while (current) { 
   // Store the next node. 
   nextNode = current.next; 
   // Change the pointer direction 
   current.next = prevNode; 
   // Move prevNode and currentNode by 1 node 
   prevNode = current; 
   current = nextNode; 
  } 

  this.head = prevNode; 
 } 

}

