Node* addLL(Node *list1, Node *list2){
    Node *head = new Node(); 
    Node *curr = head;
    Node *curr1 = list1;
    Node *curr2 = list2;
    int carry = 0;
    while (curr1 != NULL || curr2 != NULL){
        int n1 = curr1 != NULL ? curr1->val : 0;
        int n2 =  curr2 != NULL ? curr2->val : 0;
        int sum = n1 + n2 + carry;
        curr->val = sum % 10;
        carry = sum/10;
        if (curr1 != NULL){
            curr1 = curr1->next;
        }
        if (curr2 != NULL){
            curr2 = curr2->next;
        }
        if (curr1 != NULL || curr2 != NULL){
            curr->next = new Node();
            curr = curr->next;
        }
    }
    if (carry != 0){
        curr->next = new Node(carry);
    }
    return head;
}

