public class LongestSubsequence {

    public static int longestIncreasingSubsequence(int[] arr) { 
        int longestSubsequence = 0;
        int[] lis = new int[arr.length]; 

        for(int i=0;i<arr.length;i++) 
            lis[i] = 1; 

        for(int i=1;i<arr.length;i++) 
            for(int j=0; j<i; j++) 
                if(arr[i] > arr[j] && lis[i] < lis[j] + 1) 
                    lis[i] = lis[j] + 1; 

        for(int i=0;i<arr.length;i++) 
            if(longestSubsequence < lis[i]) 
                longestSubsequence = lis[i]; 

        return longestSubsequence;
    } 

    public static void main (String[] args) 
    {
        int[] arr = {2,4,3,5};
        System.out.println("The length of the longest increasing subsequence is: "+longestIncreasingSubsequence(arr));

    }
}

public static int[] OptimizeArray(int[] arr) 
{ 
    // Count of non-zero elements 
    int count = 0; 

    // Count of zeroes 
    int n = arr.Length; 

    //traversing the given array 
    for (int i = 0; i < n; i++) { 
        // If current element is non-zero 
        if (arr[i] != 0) { 
            // Add to the count of non-zero elements 
            arr[count++] = arr[i]; 
        } 
    } 

    // Make all elements 0 from count to end 
    while (count < n) 
        arr[count++] = 0; 

    return arr; 
}

