def transform(d):
    transformed = {'all': {}}
    for key, val in d.items():
        if isinstance(val, dict):
            transformed['all'].update(transform(val))
        elif isinstance(val, list):
            for i, el in enumerate(val):
                if isinstance(el, dict):
                    transformed['all'].update(transform(el))
                else:
                    transformed['all'][key + '_' + str(i)] = el
        else:
            transformed['all'][key] = val
    return transformed

