function editDistance(string1, string2) {
 let m = string1.length;
 let n = string2.length;
 let dp = Array.from(Array(m + 1), () => new Array(n + 1).fill(0));

 // Base cases
 for (let i = 0; i <= m; i++) {
 dp[i][0] = i;
 }
 for (let j = 0; j <= n; j++) {
 dp[0][j] = j;
 }

 // Fill the dp table
 for (let i = 1; i <= m; i++) {
 for (let j = 1; j <= n; j++) {
 if (string1[i - 1] === string2[j - 1]) {
 dp[i][j] = dp[i - 1][j - 1];
 } else {
 dp[i][j] = 1 + Math.min(dp[i - 1][j - 1],
 dp[i - 1][j],
 dp[i][j - 1]);
 }
 }
 }

 return dp[m][n];
}

