def find_shortest_path(start, end):
    queue = collections.deque([[start]])
    visited = set([start])
    while queue:
        path = queue.popleft()
        x, y = path[-1]
        if (x, y) == end:
            return len(path) - 1
        for x2, y2 in ((x+1, y), (x-1, y), (x, y+1), (x, y-1)):
            if (x2, y2) not in visited:
                queue.append(path + [(x2, y2)])
                visited.add((x2, y2))
    return -1

