public class LongestSubstringWithoutRepeating {
 public static void main(String[] args) {
 String inputString = "abcabcbb";
 int lengthOfLongestSubstring = longestSubstring(inputString);
 System.out.println("Length of the longest substring without repeating characters: " + lengthOfLongestSubstring);
 }

 public static int longestSubstring(String str) {
 int n = str.length();

 int[] lastIndex = new int[256];

 for (int i = 0; i < 256; i++) {
 lastIndex[i] = -1;
 }

 int maxLen = 0;
 int startIndex = 0;

 for (int i = 0; i < n; i++) {
 int currChar = str.charAt(i);

 if (lastIndex[currChar] >= startIndex) {
 startIndex = lastIndex[currChar] + 1;
 }

 lastIndex[currChar] = i;
 maxLen = Math.max(maxLen, i - startIndex + 1);
 }

 return maxLen;
 }
}

