def arbitrarily_large(array): 
    size_arr = len(array) 

    if size_arr == 0: 
        return [] 

    if size_arr == 1: 
        return [array[0]] 

    L = arbitrarily_large(array[:size_arr//2]) 
    R = arbitrarily_large(array[size_arr//2:]) 

    return L + R

