        String million = "";
        if(numString.contains("thousand")) {
            thousand = numString.substring(0, numString.indexOf("thousand"));
            numString = numString.substring(numString.indexOf("thousand") + 8);
            if(numString.contains("million")) {
                million = numString.substring(0, numString.indexOf("million"));
            }
        }
        int decMillion = numToDec(million);
        int decThousand = numToDec(thousand);
        int decNum = decMillion * 1000000 + decThousand * 1000;
        return decNum;
    }

    private static int numToDec(String numString) {
        String[] digits = numString.split(" ");
        int decNum = 0;
        for(int i = digits.length - 1; i >= 0; i--) {
            decNum += convertDigit(digits[i], i);
        }
        return decNum;
    }

    private static int convertDigit(String digit, int pos) {
        int decNum = 0;
        switch(digit) {
            case "one":
                decNum = Math.pow(10, pos);
                break;
            case "two":
                decNum = 2 * Math.pow(10, pos);
                break;
            case "three":
                decNum = 3 * Math.pow(10, pos);
                break;
            case "four":
                decNum = 4 * Math.pow(10, pos);
                break;
            case "five":
                decNum = 5 * Math.pow(10, pos);
                break;
            case "six":
                decNum = 6 * Math.pow(10, pos);
                break;
            case "seven":
                decNum = 7 * Math.pow(10, pos);
                break;
            case "eight":
                decNum = 8 * Math.pow(10, pos);
                break;
            case "nine":
                decNum = 9 * Math.pow(10, pos);
                break;
            default:
                break;
        }
        return decNum;
    }

}

