float fromBinary(string binary) {
    int i = 0;
    float num = 0; 

    int length = binary.length();
    int flag = 0;
    if (binary[0] == '1')
        flag = 1;

    // Interchange the 0's with 1's 
    // and vice versa
    if (flag == 1) {
        for (i = 0; i < length; i++) {
            if (binary[i] == '0')
                binary[i] = '1';
            else
                binary[i] = '0';
        }
    }

    // Calculate the decimal value
    // of the binary number
    for (i = length - 1; i >= 0; i--) {
        if (binary[i] == '1')
        {
            num += pow(2, length - i - 1);
        }
    }

    // If MSB is 1, then multiply the
    // number with -1
    if (flag == 1) 
        num = -num;

    return num;
}

