  <th key={column} onClick={() => setSorter(column)}>
  {column}
  </th>
 ));

 const tableRows = pageData.map((row, i) => (
 <tr key={`${row.name}-${i}`}>
  {props.config.columns.map(column => (
   <td key={row[column]}>{row[column]}</td>
  ))}
  </tr>
 ));

 return (
  <>
  <table>
   <thead>
    <tr>{columnNames}</tr>
   </thead>
   <tbody>{tableRows}</tbody>
  </table>
  <p>Page {page} of {data.length / props.config.rowsPerPage}</p>
  <button onClick={() => setPage(page - 1)} disabled={page < 2}>Previous</button>
  <button onClick={() => setPage(page + 1)} disabled={page >= data.length / props.config.rowsPerPage}>Next</button>
  </>
 );
};

