public class UniqueSevenDigitNumberGenerator {
	public static void main(String[] args) {
		int[] numbers = {4357, 1397, 2875, 5565};
		int number = generateUniqueSevenDigitNumber(numbers);
		System.out.println("Generated unique seven digit number: " + number);
	}

	public static int generateUniqueSevenDigitNumber(int[] numbers) {
		Set<Integer> uniqueNumbers = new HashSet<>();

		// Add all elements of the array to the Set
		for(int i = 0; i < numbers.length; i++) {
			uniqueNumbers.add(numbers[i]);
		}

		// Generate a random seven digit number
		int number = (int)(Math.random() * (9999999 - 1000000)) + 1000000;
		while(uniqueNumbers.contains(number)) {
			number = (int)(Math.random() * (9999999 - 1000000)) + 1000000;
		}

		return number;
	}

}

