"""
Implement a Stack data structure in Python
"""

class Stack:
    def __init__(self):
        self.stack = []

    def push(self, data):
        self.stack.append(data)

    def pop(self):
        if len(self.stack) == 0:
            return None
        return self.stack.pop(-1)

    def peek(self):
        if len(self.stack) == 0:
            return None
        return self.stack[-1]

if __name__ == "__main__":
    stack = Stack()
    stack.push(1)
    stack.push(2)
    stack.push(3)
    stack.push(4)
    print("Peek:", stack.peek())
    print("Pop:", stack.pop())

