string infixToPostfix(string s) {
    string postfix;
    stack <char> st;
    st.push('N');
    int l = s.length();
    for(int i = 0; i < l; i++) {
        if((s[i] >= 'A' && s[i] <= 'Z') || (s[i] >= 'a' && s[i] <= 'z')) 
            postfix+=s[i];
        else if(s[i] == '(') 
            st.push('(');
        else if(s[i] == ')') {
            while(st.top() != 'N' && st.top() != '(') {
                char c = st.top(); 
                st.pop();
                postfix += c;
            }
            if(st.top() == '(') { 
                char c = st.top(); 
                st.pop();
            }
        } else { 
            while(st.top() != 'N' && prec(s[i]) <= prec(st.top())) { 
                char c = st.top(); 
                st.pop(); 
                postfix += c; 
            } 
            st.push(s[i]); 
        } 

    }

    while(st.top() != 'N') { 
        char c = st.top(); 
        st.pop(); 
        postfix += c; 
    } 
    return postfix; 
} 

int main() { 
    string exp = "(A+B*C^D-E)"; 
    cout << "Postfix : " << infixToPostfix(exp); 
    return 0; 
}

