def quick_sort(arr):
    if len(arr) <= 1:
        return arr

    pivot = arr[len(arr)//2]
    left, right = [], []
    for elem in arr:
        if elem < pivot:
            left.append(elem)
        else:
            right.append(elem)

    left = quick_sort(left)
    right = quick_sort(right)

    return left + [pivot] + right

