pub struct Vector3 {
  pub x : f32,
  pub y : f32,
  pub z : f32
}

impl Vector3 {
  pub fn new(x: f32, y: f32, z: f32) -> Vector3 {
    Vector3 { x, y, z }
  }

  pub fn magnitude(&self) -> f32 {
    let mag_sq = self.x * self.x + self.y * self.y + self.z * self.z;
    mag_sq.sqrt()
  }

  pub fn normalized(&self) -> Vector3 {
    let mag = self.magnitude();
    Vector3 {
      x : self.x / mag,
      y : self.y / mag,
      z : self.z / mag
    }
  }
}

