class QueueUsingStacks:
    def __init__(self):
        self.enqueue_stack = []
        self.dequeue_stack = []

    def enqueue(self, x):
        self.enqueue_stack.append(x)

    def dequeue(self):
        if not self.dequeue_stack:
            while self.enqueue_stack:
                x = self.enqueue_stack.pop()
                self.dequeue_stack.append(x)
        return self.dequeue_stack.pop()

