public class AnagramChecker {
    public static boolean isAnagram(String str1, String str2) {

        // Check if the length of both strings is same
        if (str1.length() != str2.length()) {
            return false;
        }

        int[] char1 = new int[256];
        int[] char2 = new int[256];

        // Store the count of each character in the strings in respective arrays
        for(int i = 0; i < str1.length(); i++){
            char1[str1.charAt(i)]++;
            char2[str2.charAt(i)]++;
        }

        /* Compare the respective arrays of characters
        to check if both strings are anagrams of each other */
        for(int i = 0; i < 256; i++){
            if(char1[i] != char2[i]) {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        String str1 = "cinema";
        String str2 = "iceman";

        if (isAnagram(str1, str2)) {
            System.out.println("Yes, both strings are anagrams of each other.");
        }
        else {
            System.out.println("No, both strings are not anagrams of each other.");
        }
    }
}

