def longest_subarray_sum_to_zero(arr):
    maxlen = 0 # maxlen of the subarray whose sum equals 0
    sums = 0   # current sum
    sum_dict = {0: -1} # used to store previous sums

    for i in range(len(arr)):
        sums += arr[i] 
        if sums in sum_dict:
            maxlen = max(maxlen, i - sum_dict[sums])
        else:
            sum_dict[sums] = i

    return maxlen

