def findMaxMin(array):
    maxValue = array[0]
    minValue = array[0]
    for i in range(1, len(array)):
        if array[i] > maxValue:
            maxValue = array[i]
        if array[i] < minValue:
            minValue = array[i]
    return (maxValue, minValue)

