// Binary search 
// arr[]  ---> Array to be searched 
// target ---> Element to be searched 
// Returns index of key element if it is present in the array, else returns -1 
public static int binarySearch(int[] arr, int target) 
{ 
    int left = 0; 
    int right = arr.length - 1; 

    while (left <= right) 
    { 
        int mid = (left) + (right - left) / 2;  

        // Check if key element is present at mid 
        if (arr[mid] == target) 
            return mid; 

        // If key element is smaller than mid element, 
        // It lies in the left subarray 
        if (arr[mid] > target) 
            right = mid - 1; 

        // Else it lies in the right subarray 
        else
            left = mid + 1; 
    } 

    // if the element is not present in the array 
    return -1; 
}

