def find_most_frequent_number(nums):
    # Create a dictionary to store each number's frequency
    count_dict = {}
    for num in nums:
        # If number is already in the dictionary, increment its frequency
        if num in count_dict:
            count_dict[num] += 1
        # Otherwise, add the number to the dictionary with a frequency of 1
        else:
            count_dict[num] = 1

    # Find the number with the highest frequency
    max_num = None
    max_count = 0
    for num, count in count_dict.items():
        if count > max_count:
            max_num = num
            max_count = count

    # Return the number with the highest frequency
    return max_num

