class Calculator extends React.Component {
 constructor(props) {
  super(props);
  this.state = {
   num1: 0,
   num2: 0,
   operator: '+',
   result: 0
  }
  this.handleChange = this.handleChange.bind(this);
  this.handleSubmit = this.handleSubmit.bind(this);
 }

 handleChange(e) {
  this.setState({[e.target.name]: e.target.value});
 }

 handleSubmit(e) {
  e.preventDefault();
  let num1 = this.state.num1;
  let num2 = this.state.num2;
  let op = this.state.operator;
  let result = 0;

  switch (op) {
   case '+': 
    result = parseInt(num1, 10) + parseInt(num2, 10);
    break;
   case '-':
    result = parseInt(num1, 10) - parseInt(num2, 10);
    break;
   case 'x':
    result = parseInt(num1, 10) * parseInt(num2, 10);
    break;
   case '/':
    result = parseInt(num1, 10) / parseInt(num2, 10);
    break;
   default:
    break;
  }

  this.setState({ result });
 }

 render() {
  return(
   <div>
    <form onSubmit={this.handleSubmit}>
     <input type="number" name="num1" value={this.state.num1} onChange={this.handleChange} />
     <input type="text" name="operator" value={this.state.operator} onChange={this.handleChange} />
