int findLongestCommonSubstring(string s1, string s2){
    int m = s1.length(), n = s2.length();
    int maxlen = 0;
    int table[m+1][n+1];
    memset(table, 0, sizeof(table));
    for (int i = 1; i <= m; i++) {
        for (int j = 1; j <= n; j++) {
            if (s1[i-1] == s2[j-1]) {
                table[i][j] = table[i-1][j-1] + 1;
                maxlen = max(maxlen, table[i][j]);
            }
        }
    }
    return maxlen;
}

