import random

def checkWin(board):
    # check rows and columns
    for row in range(len(board)):
        for col in range(len(board[row])):
            if (board[row][col] == board[row][col+1] == board[row][col+2] == board[row][col+3]):
                return board[row][col]
            if (board[row][col] == board[row+1][col] == board[row+2][col] == board[row+3][col]):
                return board[row][col]

    # check diagonals
    for row in range(len(board)):
        for col in range(len(board[row])):
            if (board[row][col] == board[row+1][col+1] == board[row+2][col+2] == board[row+3][col+3]):
                return board[row][col]
            if (board[row][col+3] == board[row+1][col+2] == board[row+2][col+1] == board[row+3][col]):
                return board[row][col+3]
    return False

def randomMove(board):
    validMoves = []
    for row in range(len(board)):
        for col in range(len(board[row])):
            if board[row][col] == 0:
                validMoves.append([row, col])

    if len(validMoves) > 0:
        move = validMoves[random.randint(0, len(validMoves)-1)]
        board[move[0]][move[1]] = 1
        return board
    else:
        return False

def ticTacToeAI(board):
    # check if there are any winning moves
    if checkWin(board) == 1 or checkWin(board) == -1:
        return board
    if checkWin(board) == False:
        # make a random move
        newBoard = randomMove(board)
        if newBoard != False:
            return newBoard
        else:
            return board

    return board

