def summarize_text(text):

# Tokenize the text
sents = sent_tokenize(text)

# Create our word-frequency dictionary
word_counts = {}
for sent in sents:
 for word in nltk.word_tokenize(sent):
 if word not in word_counts.keys():
 word_counts[word] = 1
 else:
 word_counts[word] += 1

# Create our sentence-score dictionary
sent_scores = {}
for sent in sents:
 score = 0
 for word in nltk.word_tokenize(sent.lower()):
 if word in word_counts.keys():
 score += word_counts[word]
 sent_scores[sent] = score

# Get the most important sentence
summary_sentences = sorted(sent_scores.items(), key=lambda x: x[1], reverse=True)[:3]
