 {
 	 int rA = A.length;
 	 int cA = A[0].length;
 	 int rB = B.length;
 	 int cB = B[0].length;

 	if (cA != rB )
 	return null; 
 	int[][] C = new int[rA][cB];

	for(int i = 0; i < rA; i++)
 	{
 		for (int j = 0; j < cB; j++) 
 		{
 			C[i][j] = 0;
 			for (int k = 0; k < cA; k++) 
