public static void insertionSort(string[] arr) 
 { 
     // Elements within the sorted part
     // are in ascending order
     int sorted = 1; 
     while (sorted < arr.Length) 
     { 
        string temp = arr[sorted]; 

        int j = sorted - 1; 
        while (j >= 0 && arr[j].CompareTo(temp) >= 0) 
        { 
            arr[j + 1] = arr[j];  
            j--; 
        } 

        arr[j + 1] = temp;  
        sorted++; 
     } 
 } 

