#include <vector>
#include <algorithm>

class MergeSort
{
public:
    void sort(std::vector<int>& v)
    {
        if (v.size() <= 1)
            return;

        std::vector<int> left(v.begin(), v.begin() + v.size() / 2);
        std::vector<int> right(v.begin() + v.size() / 2, v.end());

        sort(left);
        sort(right);

        merge(v, left, right);
    }

private:
    void merge(std::vector<int>& v, std::vector<int>& left, std::vector<int>& right)
    {
        int i = 0, j = 0, k = 0;

        while (i < left.size() && j < right.size())
        {
            if (left[i] <= right[j])
            {
                v[k++] = left[i++];
            }
            else
            {
                v[k++] = right[j++];
            }
        }

        while (i < left.size())
            v[k++] = left[i++];

