def find_path(maze):
    start = (0, 0)
    end = (len(maze) - 1, len(maze[0]) - 1)
    visited = [[False for y in range(len(maze[0]))] for x in range(len(maze))]

    path = []
    queue = deque([[start]])
    visited[start[0]][start[1]] = True

    while queue:
        path = queue.popleft()
        node = path[-1]

        if node == end:
            return path

        for dir in [[1, 0], [-1, 0], [0, 1], [0, -1]]:
            new_x, new_y = node[0] + dir[0], node[1] + dir[1]
            if 0 <= new_x < len(maze) and 0 <= new_y < len(maze[0]) and not visited[new_x][new_y] and maze[new_x][new_y] == 0:
                queue.append(path +[[new_x, new_y]])
                visited[new_x][new_y] = True

    return None

