public class Fibonacci {
    // Method to return nth Fibonacci number
    public static int getNthFibNumber(int n) {
        // If n is 0 or 1, return the respective value
        if(n == 0 || n == 1)
            return n;
        int first = 0, second = 1;
        // loop from 2 to N
        for(int i = 2; i <= n; ++i) {
            int temp = first + second;
            first = second;
            second = temp;
        }
        return second;
    }
    public static void main(String[] args) {
        // Get the Nth Fib number
        int N = Integer.parseInt(args[0]);
        int nthFibNum = getNthFibNumber(N);
        System.out.println(nthFibNum);
    }
}

