function breadthFirstSearch(graph, root) {
  let node = {};
  root.marked = true;
  // Queue of (node, depth) pairs
  let queue = [{node: root, depth: 0}];
  while (queue.length > 0) {
    let current = queue.shift();
    node = current.node;
    let depth = current.depth;
    graph.forEach((n) => {
      if (n.marked === false) {
        queue.push({node: n, depth: depth + 1});
      }
    });
  }
  return node;
}

