class Node:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None

def build_bst(lst):
    root = Node(lst[0])

    for num in lst[1:]:
        cur = root
        while cur:
            if num < cur.val:
                if cur.left:
                    cur = cur.left
                else:
                    cur.left = Node(num)
                    break
            else:
                if cur.right:
                    cur = cur.right
                else:
                    cur.right = Node(num)
                    break
    return root

