def subset_sum(items, weights, n): 
    # Set all elements to False
    visited = [False] * len(items) 

    # Store all possible combination of item and its weight 
    combination = []
    for i in range(len(items)):
        combination.append((items[i], weights[i]))

    # Traverse combination array and mark all visited elements 
    for i in range(len(combination)): 
        w = combination[i][1]
        if w <= n:
            visited[i] = True
            for j in range(i + 1, len(combination)): 
                w += combination[j][1]
                if w <= n and visited[j] == False:
                    visited[j] = True
                elif w > n: 
                    break

    # Check if all elements are marked 
    for i in range(len(visited)): 
        if visited[i] == False: 
            return False

    return True

