public class EditDistance {

    public static int editDistance(String str1, String str2) {

        // Create an edit distance matrix for str1 and str2
        int[][] distMatrix = new int[str1.length()+1][str2.length()+1];

        // Initialize the distance matrix
        // Populate the first row and column
        for (int i = 0; i <= str1.length(); i++) {
            distMatrix[i][0] = i;
        }
        for (int j = 0; j <= str2.length(); j++) {
            distMatrix[0][j] = j;
        }

        // Iterate through each character in both strings
        // Populate the distance matrix
        for (int i = 1; i <= str1.length(); i++) {
            for (int j = 1; j <= str2.length(); j++) {
                int cost = (str1.charAt(i-1) == str2.charAt(j-1)) ? 0 : 1;
                int min = Math.min(distMatrix[i-1][j] + 1,distMatrix[i][j-1] + 1);
                distMatrix[i][j] = Math.min(min, distMatrix[i-1][j-1] + cost);
            }
        }

        // Return the last element in the matrix
        return distMatrix[str1.length()][str2.length()];
    }

    public static void main(String[] args) {
        String str1 = "cat";
        String str2 = "cut";
        System.out.println(editDistance(str1, str2));
    }
}

