using namespace std; 

#define R 3 
#define C 6 

void spiralPrint(int m, int n, int arr[R][C]) 
{ 
    int i, k = 0, l = 0; 

    /* k - starting row index 
        m - ending row index 
        l - starting column index 
        n - ending column index 
        i - iterator 
    */

    while (k < m && l < n) { 
        /* Print the first row from 
               the remaining rows */
        for (i = l; i < n; ++i) { 
            cout << arr[k][i] << " "; 
        } 
        k++; 

        /* Print the last column 
         from the remaining columns */
        for (i = k; i < m; ++i) { 
            cout << arr[i][n - 1] << " "; 
        } 
        n--; 

        /* Print the last row from 
                the remaining rows */
        if (k < m) { 
            for (i = n - 1; i >= l; --i) { 
                cout << arr[m - 1][i] << " "; 
            } 
            m--; 
        } 

        /* Print the first column from 
                   the remaining columns */
        if (l < n) { 
            for (i = m - 1; i >= k; --i) { 
                cout << arr[i][l] << " "; 
            } 
            l++; 
        } 
    } 
} 

