def find_longest_palindrome(input_string):
	#start and end indices
    start = 0 
    end = len(input_string)

	#store the longest palindrome
    longest_palindrome = ""

    for k in range(end, 0, -1):
        for i in range(start, k):
            if input_string[i] == input_string[k-1]: # check if palindrome
                if input_string[i:k] == input_string[i:k][::-1]: 
                    if len(input_string[i:k]) > len(longest_palindrome): #update longest palindrome 
                        longest_palindrome = input_string[i:k] 
                        break

    return longest_palindrome

