import React, {Component} from 'react';
import {BrowserRouter as Router, Link, Route,} from 'react-router-dom';

class UserComponent extends Component {
 state = {
 users: []
 };

 addUser = (user) => {
 this.setState((prevState)=> ({
  users: [...prevState.users, user]
 }))
 }

 updateUser = (userId, updates) => {
 this.setState((prevState)=> ({
  users: prevState.users.map((user)=> {
   if (user.id === userId) {
    return {...user, ...updates};
   }
   return user;
  })
 }))
 }

 deleteUser = (userId) => {
 this.setState((prevState)=> ({
  users: prevState.users.filter(user => user.id !== userId)
 }))
}

render() {
 const { users } = this.state;

 return (
  <Router>
   <div>
    {users.map((user)=> (
     <Link key={user.id} to={`/user/${user.id}`}>
      {user.name}
     </Link>
    ))}

    <Route path="/user/add" render={props => (
     <UserForm {...props} onSubmit={this.addUser} />
    )} />

    <Route path="/user/:userId/update" render={props => {
     const user = users.find((user)=> user.id === +props.match.params.userId);
     return (
      <UserForm {...props} user={user} onSubmit={(updates) => this.updateUser(+props.match.params.userId, updates)} />
     );
    }} />

    <Route path="/user/:userId/delete" render={props => {
     return (
      <DeleteUser
       onSubmit={() => this.deleteUser(+props.match.params.userId)}
      />
     );
    }} />
   </div>
  </Router>
 );
}
}

