def longestSubsequence(array):
    longest_start = 0
    longest_length = 0
    start = 0
    current_length = 0
    for i in range(len(array) - 1):
        if array[i] == array[i + 1]:
            current_length += 1
        else:
            current_length = 0
            start = i+1
        if current_length > longest_length:
            longest_length = current_length
            longest_start = start
    return array[longest_start : longest_start + longest_length + 1]

