const typeDefs = gql`
 type Post {
  id: ID!
  title: String!
  content: String!
  comments: [Comment]!
 }

 type Comment {
  id: ID!
  post_id: ID!
  author: String!
  content: String!
 }

 type Query {
  posts: [Post]
  post(id: ID!): Post
  comment(id: ID!): Comment
 }

 type Mutation {
  addPost(title: String!, content: String!): Post
  addComment(post_id: ID!, author: String!, content: String!): Comment
 }
`;


const resolvers = {
 Query: {
  posts: () => posts,
  post: (_, { id }) => posts.find(post => post.id === id),
  comment: (_, { id }) => comments.find(comment => comment.id === id)
 },
 Mutation: {
  addPost: (_, { title, content }) => {
   const post = {
    id: posts.length + 1,
    title,
    content
   };

   posts = posts.concat(post);
   return post;
  },
  addComment: (_, { post_id, author, content }) => {
   const comment = {
    id: comments.length + 1,
    post_id,
    author,
    content
   };

   comments = comments.concat(comment);
   pubsub.publish('commentAdded', { commentAdded: comment });
   return comment;
  }
 }
}

