    public static void main(String[] args) {
        int[] arr = {1, 2, 3, 4, 5, 6};

        int min = arr[0];
        int max = arr[0];
        int sum = 0;

        for (int i = 0; i < arr.length; i++) {
            if (arr[i] < min)
                min = arr[i];
            else if (arr[i] > max)
                max = arr[i];
            sum += arr[i];
        }

