class Agent:
 def __init__(self, epsilon=0.1, alpha=0.5):
 self.epsilon = epsilon
 self.alpha = alpha
 self.verbose = False
 self.state_history = []
 self.V = {}

 def setV(self, V):
 self.V = V

 def set_symbol(self, symbol):
 self.symbol = symbol

 def set_verbose(self, v):
 self.verbose = v

 def reset_history(self):
 self.state_history = []

 def take_action(self, env):
 best_state = None
 if random.uniform(0, 1) < self.epsilon:
 if self.verbose:
 print("Taking a random action")
 possible_moves = []
 for i in range(NUM_COLS):
 if env.is_valid_location(i):
 possible_moves.append(i)
 move = random.choice(possible_moves)

 else:
 if self.verbose:
 print("Taking a greedy action")
 # We use the make_all_states list to get the valid moves
 moves = env.make_all_states()
 best_value = -99999
 for move, state in moves.items():
 if self.V.get(state) is None:
 # If we have not seen this state, then evaluate and assign
 # This state will not be seen again
 self.V[state] = 0
 v = self.V[state]
 if v > best_value:
 best_value = v
 best_state = state
 move = move
 if self.verbose:
 print("Best move: {}".format(move))
 env.make_move(move, self.symbol)
 self.state_history.append(best_state)

 def update_state_history(self, s):
 self.state_history.append(s)

 def update(self, env):
 reward = env.reward(self.symbol)
 target = reward
 for prev in reversed(self.state_history):
 value = self.V[prev] + self.alpha*(target - self.V[prev])
 self.V[prev] = value
 target = value
 self.reset_history()

