def travelling_salesman(n, graph):
   # Create a matrix to store results
   cost= [[0 for x in range(n)] for x in range(1<<n)]

   # Set the base cases
   for i in range(1<<n):
       cost[i][0]=0

   # Iterate through all sets(masks)
   for mask in range(1<<n):
       for i in range(n):
           # Check if i is part of the set
           if(mask & (1<<i)):
               start=i
               if(i!=0):
                   # Now find the minimum travelling cost
                   min_cost=float('inf')
                   for j in range(n):
                       if(mask & (1<<j) and i!=j):
                           min_cost=min(min_cost,graph[start][j]+cost[mask - (1<<start)][j])
                       cost[mask][start]=min_cost
   return cost[(1<<n) - 1][0]

