def min_swap(arr, x, y):
    x_pos = arr.index(x)
    y_pos = arr.index(y)

    steps = 0

    for i in range(min(x_pos, y_pos), max(x_pos, y_pos)):
        if i == x_pos:
            arr[i], arr[i+1] = arr[i+1], arr[i]
        else:
            arr[i], arr[i-1] = arr[i-1], arr[i]
        steps += 1

    return steps

