// This function takes a number and returns its prime factors
function getPrimeFactors(num) {
    // Create an empty list that will store the prime factors
    let primeFactors = []; 

    // Loop over the divisors
    while (num % 2 == 0) { 
        primeFactors.push(2); 
        num = num / 2; 
    } 

    // Loop over odd numbers
    for (let i = 3; i <= Math.sqrt(num); i+= 2) { 
        while (num % i == 0) { 
            primeFactors.push(i); 
            num = num / i; 
        } 
    } 

    // if num is greater than 2, then it must be a prime number
    if (num > 2)
        primeFactors.push(num);

    return primeFactors; 
}

