// Java program to implement a Binary Search Tree  
public class Tree {  

    // Root of BST  
    public Node root;  

    // Constructor  
    public Tree() {
        root = null;  
    }  

    // Inserts node into a tree 
    public void insertNode(int data)    
    {
        root = insertNodeRecursive(root, data);  
    }  

    // Recursively inserts node into a tree 
    public Node insertNodeRecursive(Node currentNode, int data) 
    {   
        // Base case: empty tree
        if (currentNode == null)    
        {
            return new Node(data);  
        }

        // Compare value to current node
        if (data < currentNode.data) 
        {
            currentNode.left = insertNodeRecursive(
                currentNode.left, data); 
        } 
        else if (data > currentNode.data) 
        {
            currentNode.right = insertNodeRecursive(
                currentNode.right, data);  
        } 
        else 
        {
            return currentNode; // value exists
        }

        return currentNode;  
    }  

    // Class that represents nodes in a tree
    public class Node {  
        public int data; 
        public Node left; 
        public Node right; 

        public Node(int data) 
        { 
            this.data = data; 
            left = null; 
            right = null; 
        } 
    } 
}

