public int convert(int base8)
{
    int result = 0;
    int multiplier = 1;

    while (base8 > 0)
    {
        int digit = base8 % 10;
        result = result + (digit * multiplier);
        multiplier = multiplier * 8;
        base8 = base8 / 10;
    }

    return result;
}

