function closestPoints(point, n) {
  let distances = {};

  for(let [x, y, z] of points) {
    let distance = Math.sqrt(Math.pow(point[0] - x, 2) + Math.pow(point[1] - y, 2) + Math.pow(point[2] - z, 2));
    distances[distance] = {x: x, y: y, z: z};  
  }

  // Sort distances in ascending order
  let sortedDistances = Object.keys(distances).sort((a,b) => a-b);
  let closestPoints = [];

  for (let i = 0; i < n; i++) {
    closestPoints.push(distances[sortedDistances[i]]); 
  }

  return closestPoints;  
}

