class LinkedList:
    def __init__(self):
        self.head = None

    def is_empty(self):
        return self.head == None

    def add(self, data):
        node = Node(data)
        node.next = self.head
        self.head = node

    def remove(self):
        if self.is_empty():
            return None
        data = self.head.data
        self.head = self.head.next
        return data

def lcs(string1, string2): 
    m = len(string1) 
    n = len(string2) 

    L = [[0 for x in range(n+1)] for x in range(m+1)] 

    for i in range(m+1): 
        for j in range(n+1): 
            if i == 0 or j == 0: 
                L[i][j] = 0
            elif string1[i-1] == string2[j-1]: 
                L[i][j] = L[i-1][j-1] + 1
            else: 
                L[i][j] = max(L[i-1][j], L[i][j-1]) 

    index = L[m][n] 

    lcs = [""] * (index+1) 
    lcs[index] = "" 

    i = m 
    j = n 
    while i > 0 and j > 0: 

        if string1[i-1] == string2[j-1]: 
            lcs[index-1] = string1[i-1] 
            i-=1
            j-=1
            index-=1

        elif L[i-1][j] > L[i][j-1]: 
            i-=1
        else: 
            j-=1

    return "".join(lcs)

