  if len(array) == 0:
    return True

  num_rows = len(array)
  num_cols = len(array[0])

  # check if num_cols are symmetrical
  for row in array:
    if len(row) != num_cols:
      return False

  # check each row is symmetrical
  for row_a, row_b in zip(array, reversed(array)):
    if row_a != row_b:
