def numWays(m, n): 
    # Create a 2D table to store  
    # results of subproblems 
    count = [[0 for x in range(m)] for x in range(n)] 

    # Count of paths to reach any  
    # cell in first column is 1 
    for i in range(m): 
        count[i][0] = 1; 

    # Count of paths to reach any  
    # cell in first row is 1 
    for j in range(n): 
        count[0][j] = 1; 

    # Calculate count of paths  
    # for other cells in bottom-up  
    # manner using the recursive solution 
    for i in range(1, m): 
        for j in range(1, n): 
            count[i][j] = count[i-1][j] + count[i][j-1] 

    return count[m-1][n-1]

def largest_sum(nums):
    largest = max(nums[0], nums[1])
    second_largest = min(nums[0], nums[1])
    for elem in nums[2:]:
        if elem > largest:
            second_largest = largest
            largest = elem 
        elif elem > second_largest:
            second_largest = elem
    return largest + second_largest

