def groupStrings(strings):
    # Initialize a dictionary
    dict = {}

    # Iterate over the list
    for string in strings:
        # Get the first character
        first_char = string[0]

        # Check if the first character is in the dictionary
        if first_char in dict:
            # Append the string to the existing list
            dict[first_char].append(string)
        else:
            # Create a list with the string
            dict[first_char] = [string]

