def LCSlength(X, Y):  
    m = len(X)
    n = len(Y)
    table = [[0 for j in range(n+1)] for i in range(m+1)]
    for i in range(m+1): 
        for j in range(n+1): 
            if i == 0 or j == 0: 
                table[i][j] = 0
            elif X[i-1] == Y[j-1]: 
                table[i][j] = table[i-1][j-1] + 1
            else: 
                table[i][j] = max(table[i-1][j], table[i][j-1]) 
    return table[m][n]

