def binary_search(arr, key): 
    low = 0
    high = len(arr) - 1
    while low <= high: 
        mid = (low + high)//2
        if arr[mid] < key: 
            low = mid + 1
        elif arr[mid] > key: 
            high = mid - 1
        else: 
            return mid 
    return -1 

