def find_permutations(my_string):
  if len(my_string) == 0:
    return []
  if len(my_string) == 1:
    return [my_string]
  permutations = []
  for i in range(len(my_string)):
    current_letter = my_string[i] 
    remaining_letters = my_string[:i] + my_string[i+1:]
    for p in find_permutations(remaining_letters):
      permutations.append(current_letter + p)
  return permutations

