def max_sum(nums):
    max_sum_so_far = nums[0]
    for i in range(1, len(nums)):
        nums[i] = max(nums[i], nums[i] + nums[i-1])
        max_sum_so_far = max(max_sum_so_far, nums[i])
    return max_sum_so_far

