def shortest_path(grid, start, end):
    # start and end points should be tuples of (x, y) coordinates
    x0, y0 = start
    x1, y1 = end 

    # find the shortest path using breadth-first search
    queue = Deque([[(x0, y0)]])
    seen = {(x0, y0)}
    while queue:
        path = queue.popleft()
        x, y = path[-1]
        if (x, y) == end:
            return path
        for x2, y2 in ((x+1, y), (x-1, y), (x, y+1), (x, y-1)):
            if (x2, y2) not in seen and grid[x2][y2] != 'X':
                queue.append(path + [(x2, y2)])
                seen.add((x2, y2))
    return 'No path found.'

