function isAnagram(str1, str2) {
    if (str1.length !== str2.length) {
        return false;
    }

    let frequencyCounterStr1 = {};
    let frequencyCounterStr2 = {};

    for (let char of str1) {
        frequencyCounterStr1[char] ? frequencyCounterStr1[char]++ : frequencyCounterStr1[char] = 1;
    }

    for (let char of str2) {
        frequencyCounterStr2[char] ? frequencyCounterStr2[char]++ : frequencyCounterStr2[char] = 1;
