def count_binary_trees(nodes):
    if nodes <= 1:
        return 1
    else:
        num_trees = 0
        for i in range(nodes):
            left_subtrees = count_binary_trees(i)
            right_subtrees = count_binary_trees(nodes - 1 - i)
            num_trees += left_subtrees*right_subtrees
        return num_trees

