fun insertionSort(list: MutableList<Int>) {
 for (i in 1 until list.size) {
  val currentEl = list[i]
  var j = i
  while (j > 0 && currentEl < list[j - 1]) {
   list[j] = list[j - 1]
   j--
  }
  list[j] = currentEl
 }
}

