public class URLParser {
  public static void main(String[] args) {
    // parseURL takes in a String URL and parses it into the protocol, domain name, and path
    String[] parseURL(String url){
      // declares protocol, domain name, and path
      String protocol = "", domainName = "", path = "";
      // splits the string by slashes
      String[] urlSplit = url.split("/");
      // declare index for looping
      int i = 0;
      // loops through urlSplit until a period is detected
      while(!urlSplit[i].contains(".")){
        domainName += urlSplit[i] + ".";
        i++;
      }
      // if a period is detected, take the protocol and domain name
      protocol = urlSplit[0];
      domainName = urlSplit[i].replace(".","");
      // loop through urlSplit and add the path string
      for(int j=i+1; j<urlSplit.length; j++)
        path+= urlSplit[j] + "/";
      // removes the last slash of the path string
      path = path.substring(0,path.length() - 1);
      // returns protocol, domain name, and path 
      return new String[]{protocol, domainName, path};
    }
  }
}

