});

app.post('/leave', (req, res) => {
 let {name, chatroom} = req.body;
 let chatroomInfo = chatrooms.find(c => c.name === chatroom);
 if (!chatroomInfo) {
  res.send({message: 'Chatroom not found'});
 }else {
   let index = chatroomInfo.users.indexOf(name);
   chatroomInfo.users.splice(index, 1);
   res.send({message: 'User left'});
 }
});

