"""
Write a class to store RGB color information and include an iterator function to iterate through generated colors
"""

class Color:
    def __init__(self, r, g, b):
        self.r = r
        self.g = g
        self.b = b

    def __iter__(self):
        return self

    def __next__(self):
        if self.r <= 255 and self.g <= 255 and self.b <= 255:
            color = (self.r, self.g, self.b)
            self.r += 1
            self.g += 1
            self.b += 1
            return color
        else:
            raise StopIteration

