function isAnagram(string1, string2) {
 // remove any whitespace
 string1 = string1.replace(/\s/g, '');
 string2 = string2.replace(/\s/g, '');

 // check if lengths are different
 if (string1.length !== string2.length) {
 return false;
 }

 // create object with character counts
 const tally = {};

 for (let i = 0; i < string1.length; i++) {
 const letter = string1[i];

 // if character is new, add to tally with a count of 1
 if (!tally[letter]) {
 tally[letter] = 1;
 } else {
 // if character has been seen, increment count
 tally[letter]++;
 }
 }

 // check if the tally object has the same
 // character counts for string2
 for (let i = 0; i < string2.length; i++) {
 const letter = string2[i];

 // if character is not found in tally,
 // strings are not anagrams
 if (!tally[letter]) {
 return false;
 } else {
 // if character is found, decrement count
 tally[letter]--;
 }
 }

 return true;
}

