def longest_common_prefix(arr):
    n = len(arr)
    if n < 1:
        return ""
    # Find the string with the minimum length
    min_length = len(arr[0])
    min_str = arr[0]
    for s in arr:
        if len(s) < min_length:
            min_length = len(s)
            min_str = s

    # Iterate over the string to find the longest common prefix
    prefix = ""
    for i in range(min_length):
        c = min_str[i]
        all_match = True
        for s in arr:
            if s[i] != c:
                all_match = False
                break
        if all_match:
            prefix += c
        else:
            break
    return prefix

// Function to find the maximum sum of two non-overlapping subarrays
function findMaxSum(array, subarray_len) {

 // Initialize max sum to 0
 let max_sum = 0;

 // Iterate over first subarray
 for (let i = 0, j = subarray_len; i < subarray_len; i++, j++) {

  // Calculate sum of first subarray
  let sub1_sum = 0;
  for (let m = i; m < j; m++) sub1_sum += array[m];

  // Iterate over second subarray
  for (let k = i+subarray_len, l = j+subarray_len; k < l; k++) {

   // Calculate sum of second subarray
   let sub2_sum = 0;
   for (let n = k; n < l; n++) sub2_sum += array[n];

   // Compare sum of both subarrays with max sum
   if (sub1_sum + sub2_sum > max_sum) max_sum = sub1_sum + sub2_sum;
  }
 }

 return max_sum;
}

