// Write a Java program to get the most frequent item in an array

public class MostFrequentItem {

 public static int getMostFrequentItem(int[] arr) {

 // create a map to store the count of each item
 Map<Integer, Integer> itemTrack = new HashMap<>();

 // traverse through the input array
 for (int n : arr) {
  // check if the map already contains the item
  if (!itemTrack.containsKey(n)) {
   // if not, add the item with count 1
   itemTrack.put(n, 1);
  }
  // if yes, increment the count
  else {
   itemTrack.put(n, itemTrack.get(n) + 1);
  }
 }

 // traverse through the map
 int mostFrequent = -1;
 int maxCount = 0;
 for (int key : itemTrack.keySet()) {
  // update the mostFrequent and maxCount if a higher count is found
  if (maxCount < itemTrack.get(key)) {
   mostFrequent = key;
   maxCount = itemTrack.get(key);
  }
 }

 return mostFrequent;
 }
 public static void main(String[] args) {

 int[] arr = {2, 5, 3, 5, 6, 2, 7, 3, 2, 6, 2};
 int mostFrequent = getMostFrequentItem(arr);
 System.out.println("The most frequent number is: " + mostFrequent);
 }
}

