"""
Design an algorithm to generate all permutations of a given string
"""

# Function to generate permutations of the given string
def generate_permutations(s):
    if len(s) == 0:
        return []
    elif len(s) == 1:
        return [s]
    else:
        # Find all permutations for the substring s[1:]
        permutations_substring = generate_permutations(s[1:])

        # Insert the first character into all possible positions 
        # of the substrings
        permutations = set()
        for permutation in permutations_substring:
            for i in range(len(permutation)+1):
                permutation_inserted = permutation[:i] + s[0] + permutation[i:]
                permutations.add(permutation_inserted)

        return list(permutations)

