function isAnagram(str1, str2) {
  // Check if the two strings have the same number of characters
  if (str1.length != str2.length) {
    return false;
  }

  // Create and populate a character Counter object
  let str1Counter = {};
  for (let char of str1) {
    str1Counter[char] = (str1Counter[char] || 0) + 1;
  }

  // Loop through each character of the second string
  for (let char of str2) {
    // Check if the character exists in str1Counter
    if (!str1Counter[char]) {
      return false;
    }
    // Decrement the count for the character
    // If the count is 0, remove the character from the object
    str1Counter[char] -= 1;
    if (str1Counter[char] == 0) {
      delete str1Counter[char];
    }
  }
  // If there are any characters left in str1Counter, the two strings are not anagrams
  if (Object.keys(str1Counter).length != 0) {
    return false;
  }
  // All characters matched
  return true;
}

