public class Stack {

 private int[] data;
 private int top = -1;

 public Stack(int size) {
 data = new int[size];
 }

 public int pop() {
 if (top == -1) {
 throw new EmptyStackException();
 }
 return data[top--];
 }

 public void push(int element) {
 if (top == data.length - 1) {
 throw new FullStackException();
 }
 data[++top] = element;
 }

 public int peek() {
 if (top == -1) {
 throw new EmptyStackException();
 }
 return data[top];
 }
}

