def level_order_traversal(root):
    result = []
    q = []
    q.append(root)

    while len(q) > 0:
        current = q.pop(0)
        result.append(current.val)

        if current.left:
            q.append(current.left)
        if current.right:
            q.append(current.right)

    return result

