public static void edit(String str) {
    // Create an array to keep track of the visited substrings
    boolean[] visited = new boolean[str.length()];

    // Iterate through each character in the str
    for (char c : str.toCharArray()) {
        // If the current character has already been visited,
        // replace it with an empty character
        if (visited[c - 'a']) {
            str = str.replace(c, ' ');
        }
        // Otherwise, mark it visited
        else {
            visited[c - 'a'] = true;
        }
    }

    // Return the modified string
    return str;
}

