            permutations.append([i]+permutation)

    return permutations

def count_primes(lower, upper):
    count = 0
    for num in range(lower, upper + 1):
        factors = 0
        for i in range(2, num):
            if num % i == 0:
                factors += 1
        if not factors:
            count += 1
    return count

