class ContactList extends React.Component {
  constructor( props ) {
    super( props );

    this.handleAddContact = this.handleAddContact.bind(this);
    this.handleSearchChange = this.handleSearchChange.bind(this);

    this.state = {
      contacts: contactData,
      searchKey: ""
    };
  }

  handleDeleteContact(contactId) {
    this.setState({
      contacts: this.state.contacts.filter(contact => contact.id !== contactId)
    });
  }

  handleAddContact(contact) {
    contact.id = Date.now();

    this.setState({
      contacts: this.state.contacts.concat([ contact ])
    });
  }

  handleSearchChange(event) {
    this.setState({
      searchKey: event.target.value
    });
  }

  render() {
    let contacts = this.state.contacts;

    const searchKey = this.state.searchKey;
    if (searchKey) {
        contacts = contacts.filter(contact => contact.name.includes(searchKey));
    }

    return (
      <div className="contact-list">
        <Search value={ searchKey } onChange={ this.handleSearchChange } />
        <ContactForm onFormSubmit={ this.handleAddContact } />
        <ContactListing
          contacts={ contacts }
          onDeleteContact={ this.handleDeleteContact.bind(this) }
        />
      </div>
    );
  }
}

