using namespace std;

//function to find the most efficient tour
vector<int> findsol(vector<vector<int>> graph)
{
    int n = graph.size();
    vector<int> tour;
    vector<bool> visited(n, false);

    // Start from the first node
    tour.push_back(0);
    visited[0] = true;

    // Find the shortest possible tour
    int current = 0;
    while (tour.size() < n)
    {
        int minimum_cost = INT_MAX;
        int minimum_index = 0;

        // Consider all unvisited nodes
        for(int i=1; i<n; i++)
        {
            if(visited[i]==false)
            {
                // Calculate the distance between two nodes
                int dist = int(graph[current][i]);

                // If the distance is smaller than the current minimum, update it
                if(dist < minimum_cost)
                {
                    minimum_cost = dist;
                    minimum_index = i;
                }
            }
        }

        // Add the smallest distance node to the tour
        tour.push_back(minimum_index);
        visited[minimum_index] = true;

        // Set the current node to the found node
        current = minimum_index;
    }

    return tour;
}

