        return True
    root = array[0]
    left_subtree = [elem for elem in array if elem < root]
    right_subtree = [elem for elem in array if elem > root]
    return ( is_bst(left_subtree) and is_bst(right_subtree) 
            and all(elem < root for elem in left_subtree) 
            and all(elem > root for elem in right_subtree) )

