        freq[ch] += 1
    huffman_heap = []
    for key in freq: 
        huffman_heap.append({'data': key, 'freq': freq[key]}) 
    while(len(huffman_heap)>1): 
        h1 = huffman_heap[0] 
        h2 = huffman_heap[1] 
        for i in range(2,len(huffman_heap)): 
            if huffman_heap[i]['freq'] < h1['freq']: 
                h1 = huffman_heap[i] 
            elif huffman_heap[i]['freq'] < h2['freq']: 
                h2 = huffman_heap[i] 
        new_node = {'data': h1['data']+h2['data'], 'freq': h1['freq']+h2['freq']} 
        huffman_heap.append(new_node) 
        huffman_heap.remove(h1) 
        huffman_heap.remove(h2) 

    codes = {} 
    def assign_codes(node, pat=''): 
        if len(node['data'])==1: 
            codes[node['data']] = pat 
        else: 
            assign_codes(node['left'], pat+'0') 
            assign_codes(node['right'], pat+'1') 
