function insertionSort(arr) {
  // Loop through the array
  for (let i = 1; i < arr.length; i++) {
    let current = arr[i];
    let j = i - 1;

    while (j > -1 && arr[j] > current) {
      arr[j + 1] = arr[j];
      j--;
    }
    // Insert the current element in its place
    arr[j + 1] = current;
  }
  return arr;
}

