function binarySearch(arr, x) { 
    let start = 0, end = arr.length - 1; 

    while (start <= end) { 
        let mid = Math.floor(start + (end - start) / 2); 

        if (arr[mid] === x) { 
            return mid; 
        } 
        else if (arr[mid] < x) { 
            start = mid + 1; 
        } 
        else { 
            end = mid - 1; 
        } 
    } 

    return -1; 
};

