def evaluateInfix(exp):
    operandsStack = []
    operatorsStack = []

    for i in exp:

        # check if character is an operator 
        if i in '+-*/':
            operatorsStack.append(i)

        # check if character is an operand
        elif i.isnumeric():
            operandsStack.append(i)

        # check if character is a closing bracket
        elif i == ')': 
            operator = operatorsStack.pop(-1)

            if operator == '+':
                operandsStack[-2] = int(operandsStack[-2]) + int(operandsStack[-1])
            elif operator == '-':
                operandsStack[-2] = int(operandsStack[-2]) - int(operandsStack[-1])
            elif operator == '*':
                operandsStack[-2] = int(operandsStack[-2]) * int(operandsStack[-1])
            elif operator == '/':
                operandsStack[-2] = int(operandsStack[-2]) // int(operandsStack[-1])

            operandsStack.pop()

    return operandsStack.pop()

