def optimize_prob_space(space):
    best_solution = [float("inf")] * len(space)
    while True:
        new_solution = get_random_solution(space)
        if is_more_desirable(new_solution, best_solution):
            best_solution = new_solution
        if is_optimal(new_solution, space):
            break
    return best_solution

def get_random_solution(space):
    # Generate a random solution in the given space 
    solution = [random.uniform(space[i][0], space[i][1]) for i in range(len(space))] 
    return solution

def is_more_desirable(new_solution, best_solution):
    # Check if the new solution is more desirable than the current best solution 
    for i in range(len(new_solution)): 
        if new_solution[i] > best_solution[i]: 
            return False
    return True

def is_optimal(new_solution, space):
    # Check if the new solution is an optimal solution in the given space 
    for i in range(len(new_solution)): 
        if new_solution[i] > space[i][1]:
            return False

    return True

