// Minimax algorithm
function minimax(gameboard, depth, maxPlayer) {
 if (maxPlayer) {
 let maxEval = -Infinity;

 for (let i = 0; i < 7; i++) {
 let result = minimax(gameboard, depth + 1, false);
 maxEval = Math.max(result.evaluation, maxEval);
 }

 return { evaluation: maxEval }
 } else {
 let minEval = Infinity;

 for (let i = 0; i < 7; i++) {
 let result = minimax(gameboard, depth + 1, true);
 minEval = Math.min(result.evaluation, minEval);
 }

 return { evaluation: minEval };
 }
}

// Agent's turn
function agentMove(gameboard) { 
 let maxEval = -Infinity;
 let bestMove;

 for (let i = 0; i < 7; i++) {
 let evaluation = minimax(gameboard, 0, false).evaluation;

 if (evaluation > maxEval) {
 maxEval = evaluation;
 bestMove = i;
 }
 }

 return bestMove;
}

