def is_anagram(str1, str2):
    # convert both strings to lowercase
    str1 = str1.lower()
    str2 = str2.lower()

    # remove whitespaces
    str1 = str1.replace(" ", "")
    str2 = str2.replace(" ", "")

    # if the length of both strings is not the same, they can't be anagrams
    if len(str1) != len(str2):
        return False

    # create an empty dictionary
    dict1 = {}

    # create a dictionary with the letters of the first string
    for letter in str1:
        if letter in dict1:
            dict1[letter] += 1
        else:
            dict1[letter] = 1

    # check if the letters of the second string also exist in the first string
    for letter in str2:
        if letter in dict1:
            dict1[letter] -= 1
        else:
            return False

    # if the dictionary is empty, it means that the two strings are anagrams
    if all(value == 0 for value in dict1.values()):
        return True

    return False

