// Java program to check if a string is a palindrome
public class PalindromeTest { 

    // Function to check whether a string is palindrome or not
    public static boolean isPalindrome(String str) {  
        // Pointers pointing to the beginning and the end of the string 
        int i = 0, j = str.length() - 1; 

        // While there are characters to compare 
        while (i < j) { 
            // If there is a mismatch 
            if (str.charAt(i) != str.charAt(j)) 
                return false; 

            // Increment first pointer and decrement the other 
            i++; 
            j--; 
        } 

        // Given string is a palindrome 
        return true; 
    } 

    // Driver code 
    public static void main(String[] args) 
    { 
        // Test 1
        String str1 = "Hello"; 

        if (isPalindrome(str1)) 
            System.out.println("String is palindrome"); 
        else
            System.out.println("String is not palindrome"); 
    } 
}

