def sortDictByValues(d):
  # create a list of tuples where each tuple contains 
  #(key,value) pair from the dictionary
  list_of_tuples = []
  for key, value in d.items(): 
    list_of_tuples.append((key, value)) 

  # sort the list in reverse order by values 
  sorted_list = sorted(list_of_tuples, key=lambda x: x[1], reverse = True) 

  # return the sorted dictionary
  sorted_dict = {} 
  for tup in sorted_list: 
    sorted_dict[tup[0]] = tup[1] 

