function animateObject(canvas, x_position, y_position, speed) { 
    // variable to store the x and y position 
    let x = x_position; 
    let y = y_position; 

    // set the speed of the animation 
    let ms = speed; 

    // draw the object 
    let ctx = canvas.getContext("2d"); 
    ctx.fillStyle = "red"; 
    ctx.fillRect(x, y, 10, 10); 

    // animate the object 
    var animate = setInterval(animateObj, ms); 

    function animateObj() { 
        if (x > canvas.width) { 
            clearInterval(animate); 
        } 
        else { 
            x += 10; 
            ctx.clearRect(0, 0, canvas.width, canvas.height); 
            ctx.fillRect(x, y, 10, 10); 
        } 
    } 
}

