struct Node {
    int data;
    Node *left;
    Node *right;
    Node *next;
};

Node *binary_tree_to_ll(Node *root) {
    Node *head = nullptr;
    Node *tail = nullptr;

    if (root == nullptr)
        return nullptr;

    queue<Node*> q;
    q.push(root);

    while (!q.empty()) {
        Node *current = q.front();
        q.pop();

        if (current->left != nullptr) 
            q.push(current->left);

        if (current->right != nullptr) 
            q.push(current->right);

        if (head == nullptr) {
            head = tail = current;
        } else {
            tail->next = current;
            tail = current;
        } 
    }
    return head;
}

