/* Function to find the minimum spanning tree of a graph
*   using Kruskal's algorithm
*/
vector<pair<int, pair<int, int>>> kruskal(int V, vector<pair<int, pair<int, int>>> edges)
{
    // Sort edges by weight 
    sort(edges.begin(), edges.end());

    // Create a vector to store the minimum spanning tree
    vector<pair<int, pair<int, int>>> mst; 

    // Set to store the subset elements
    vector<int> subset(V + 1); 

    // Initialize the subsets
    for (int i = 1; i <= V; i++) 
        subset[i] = i; 

    int i = 0;
    int e = 0;

    // Iterate until the number of edges in the MST is V-1
    while (e < V-1) 
    { 
        // Pick the smallest-weighted edge
        pair<int, pair<int, int>> next_edge = edges[i++];

        int x = next_edge.second.first; 
        int y = next_edge.second.second; 

        // Check if the picked edge creates a cycle by finding 
        // the root of the nodes connected by the edge.
        int x_set = subset[x];
        int y_set = subset[y];

        // If it does not form a cycle, add to MST
        if (x_set != y_set) 
        { 
            // Add to MST
            mst.push_back(next_edge);
            e++; 

            // Union the subset of x and y 
            for (int k = 1; k <= V; k++) 
                if (subset[k] == x_set) 
                    subset[k] = y_set; 
        } 
    } 

    return mst; 
}

