# KNN Classifier

import numpy as np

class KNNClassifier:
    def __init__(self, k):
        self.k = k

    def fit(self, X, y):
        self.X_train = X
        self.y_train = y

    def predict(self, X):
        y_pred = np.zeros(X.shape[0])
        for i, x in enumerate(X):
            distances = np.sum((self.X_train-x)**2, axis=1)
            nearest_neigbors = np.argsort(distances)[:self.k]
            y_pred[i] = self.y_train[nearest_neigbors].mean()
        return y_pred

