// function to check if a given number is a prime number or not
bool isPrime(int n) {
        if (n <= 1)  return false;
        if (n == 2)  return true;
        if (n % 2 == 0) return false;

        for (int i=3; i<n; i+=2) {
            if (n % i == 0)
                return false;
        }
        return true;
}

// function to reduce a given number to sum of its prime factors
int reduceNumToSumOfItsPrimeFactors(int n) {
    // if n is prime
    if (isPrime(n))  return n;

    // start reduction form 2
    int result = 0;
    for (int i=2; i<=n; i++) {
        // check if i is prime
        if (isPrime(i)) {
            // check if i divides n
            while (n % i == 0) {
                n /= i;
                result += i;
            }
        }
    }
    return result;
}

