function getThreeMostCommonWords(text) {
  let wordCounts = {};
  const words = text.replace(/[.,\/#!$%\^&\*;:{}=\-_`~()]/g,"").split(" ");

  words.forEach(word => {
    word = word.toLowerCase();
    if (word in wordCounts) {
      wordCounts[word] += 1;
    } else {
      wordCounts[word] = 1;
    }
  });

  let sortedWordCounts = Object.entries(wordCounts).sort((a, b) => b[1] - a[1]);

  let threeMostCommon = [];
  for (let i = 0; i < 3; i++) {
    if (i < sortedWordCounts.length) {
      threeMostCommon.push(sortedWordCounts[i]);
    }
  }
  return threeMostCommon;
}

