rev_comp <- function(dna_seq) { 
    # Reverse sequence
    rev_seq <- strrev(dna_seq)

    # Match complementary base pairs
    rev_comp_strand <- ""
    for (element in rev_seq) {
        if (element == "A") rev_comp_strand <- paste0(rev_comp_strand, "T") 
        if (element == "T") rev_comp_strand <- paste0(rev_comp_strand, "A")
        if (element == "G") rev_comp_strand <- paste0(rev_comp_strand, "C")
        if (element == "C") rev_comp_strand <- paste0(rev_comp_strand, "G")
    }

    return (rev_comp_strand) 
}

def generate_primes(n):
  primes = []
  for number in range(2, n+1):
    is_prime = True
    for divisor in range(2, number):
      if number % divisor == 0: 
        is_prime = False
        break
    if is_prime:
      primes.append(number)
  return primes

