    This function takes a number as an argument
    and generates the Fibonacci series up to its value.
    """
    if num <= 0:
        print("Incorrect input")
    elif num == 1:
        return 0
    elif num == 2:
        return [0, 1]
    else:
        fibonacci_arr = [0 ,1]
