def deleteNode(root, key):
    if root is None:
        return root

    if root.value > key:
        root.left = deleteNode(root.left, key)
    elif root.value < key:
        root.right = deleteNode(root.right, key)
    else:
        if root.left is None:
            no_child = root.right
            root = None
            return no_child

        if root.right is None:
            no_child = root.left
            root = None
            return no_child

        temp_node = findMinNode(root.right)
        root.value = temp_node.value
        root.right = deleteNode(root.right, temp_node.value)

    return root

