const areAnagrams = (str1, str2) => {
  // First, split the two strings into arrays of characters
  const first = str1.split('');
  const second = str2.split('');

  // Return false if the length of the strings don't match
  if (first.length !== second.length) return false;

  // Create an object to store the character counts
  let counts = {};

  // Loop over the first string and add the character count to the object
  first.forEach(char => {
    counts[char] ? counts[char]++ : counts[char] = 1;
  });

  // Loop over the second string, if the character exists in the object, decrement it, or return false
  second.forEach(char => {
    if (counts[char]) {
      counts[char]--;
    } else {
      return false;
    }
  });

  // Return true if all the counts are 0
  for (let char in counts) {
    if (counts[char] !== 0) return false;
  }
  return true;
}

