public class DeleteDuplicates {

    public static int[] deleteDuplicates(int array[])
    {

        int n = array.length;

        // Pick all elements one by one
        for (int i = 0; i < n; i++)
        {
            // Compare the picked element 
            // with rest of the elements
            for (int j = i + 1; j < n; j++)
            {
                // If any two elements are found 
                // equal
                if (array[i] == array[j])
                {
                    // Move all the elements 
                    // after the index j
                    for (int k = j; k < n - 1; k++)
                    {
                        array[k] = array[k + 1];
                    }

                    // Decrement size of array
                    n--;

                    // Reduce the index value
                    // of 'i' as one element is deleted
                    j--;
                }
            }
        }

        // Copy array into another array with
        // exact size
        int[] temp = new int[n];
        for (int i = 0; i < n; i++)
            temp[i] = array[i];

        // Modify original array 
        array = temp;

        return array;
    }

    public static void main(String[] args)
    {
        int array[] = { 1, 1, 2, 2, 3, 3 };
        int size = array.length;

        array = deleteDuplicates(array);

        System.out.println("Array elements after deleting duplicates : ");
