def max_z(x, y):
    if x + y > 10: 
        return 0 

    z = 2*x + y
    step_size = 0.01

    while True: 
        if x + y > 10: 
            break
        dx = step_size
        dy = step_size
        new_z = 2*(x+dx) + (y+dy)
        if new_z > z: 
            x += dx
            y += dy
            z = new_z
        else: 
            break
