// A class to represent a game of chess
class ChessGame {
    protected Piece[][] board; // The board of the game
    protected int turn; // Whose turn white or black
    protected boolean gameOver; // Is the game over

    public ChessGame() {
        this.board = new Piece[8][8];
        this.turn = 0; // White's turn
        this.gameOver = false;
    }

    // Moves a piece if the move is valid and switches turn
    public void move(int fromX, int fromY, int toX, int toY) {
        // Check if the move is valid
        if (this.board[fromX][fromY] == null ||
            this.board[fromX][fromY].isWhite() != (turn == 0) ||
            !this.board[fromX][fromY].Moves().contains(new int[] {toX, toY})) {
            return;
        }

        // Move the piece
        this.board[toX][toY] = this.board[fromX][fromY];
        this.board[fromX][fromY] = null;

        // Switch turn
        this.turn = 1 - this.turn;
    }
}

