public static void MergeSort(int[] input)
{
    if (input.Length < 2)
        return;

    int middle = input.Length / 2;
    int[] leftArray = new int[middle];
    int[] rightArray = new int[input.Length - middle];

    for (int i = 0; i < middle; i++)
    {
        leftArray[i] = input[i];
    }

    for (int i = middle; i < input.Length; i++)
    {
        rightArray[i - middle] = input[i];
    }

    MergeSort(leftArray);
    MergeSort(rightArray);
    Merge(input, leftArray, rightArray);
}

public static void Merge(int[] input, int[] left, int[] right)
{
    int leftIndex = 0;
    int rightIndex = 0;
    int targetIndex = 0;

    int remaining = left.Length + right.Length;

    while(remaining > 0)
    {
        if(leftIndex >= left.Length)
        {
            input[targetIndex] = right[rightIndex++];
        }
        else if(rightIndex >= right.Length)
        {
            input[targetIndex] = left[leftIndex++];
        }
        else if(left[leftIndex] <= right[rightIndex])
        {
            input[targetIndex] = left[leftIndex++];
        }
        else
        {
            input[targetIndex] = right[rightIndex++];
        }
        targetIndex++;
        remaining--;
    }
}

