      rear.setNextNode(node);
    }
    rear = node;
    size++;
  }

  public T dequeue() {
    if (isEmpty()) {
      return null;
    }
    T data = front.getData();
    front = front.getNextNode();
    if (isEmpty()) {
      rear = null;
    }
    size--;
    return data;
  }

  public int getSize() {
    return size;
  }

  public T getFront() {
    if (isEmpty()) {
      return null;
    }
    return front.getData();
  }

  public boolean isEmpty() {
    return size == 0;
  }
}

