public static List<Integer> findMaxSubarray(int[] nums, int target){
    List<Integer> result = new ArrayList<>();
    int startPos = 0;
    int endPos = 0;
    int sum = 0;
    int maxLength = 0;

    for(int i = 0; i < nums.length; i++){
        int currentSum = 0;
        for(int j = i; j < nums.length; j++){
            currentSum += nums[j];
            if(currentSum > target){
                break;
            }
            if(currentSum > sum){
                sum = currentSum;
                startPos = i;
                endPos = j;
                maxLength = endPos - startPos + 1;
            } else if(currentSum == sum){
                int currentLength = j - i + 1;
                if(currentLength > maxLength){
                    startPos = i;
                    endPos = j;
                    maxLength = currentLength;
                }
            }
        }
    }

    // Add the max subarray elements to the list
    for(int i = startPos; i <= endPos; i++){
        result.add(nums[i]);
    }
    return result;
}

