// Function to check if array is sorted or not 
bool isSorted(int arr[], int n) 
{ 
    // Start from 0th element and 
    // compare with all other elements 
    for (int i = 0; i < n - 1; ++i) 
        if (arr[i] > arr[i + 1]) 
            return false; 

    // Return true if all elements were compared 
    return true; 
} 

