public static int FindSmallestDivisibleNumber(int n)
{ 
 int number = 1;

 // Compute the lcm of all numbers from 1 to n
 for(int i = 2; i <= n; i++)
 {
  number = FindLCM(number, i);
 }  

 return number;
}

public static int FindLCM(int a, int b)
{
// Find the GCD
int t;
 while(b != 0)
 {
  t = b;
  b = a % b;
  a = t; 
 }

 return (a * b) / a;
}

