    static int printWords(String sentence) 
    { 
        // variable to store the count 
        int count = 0; 

        // take the sentence as a string array 
        String[] string_array = sentence.split(" "); 

        // increment the count if size is 3 
        for (int i = 0; i < string_array.length; i++)  
