def permute(s):
    out = []

    # Base Case
    if len(s) == 1:
        out = [s]

    else:
        # For every letter in string
        for i, let in enumerate(s):

            # For every permutation resulting from Step 2 and 3 described above
            for perm in permute(s[:i] + s[i+1:]):

                # Add it to output
                out += [let + perm]

    return out

# Function to return most frequent 
# element in a list 
def most_frequent_item(list): 
	# return None if list is empty 
	if len(list) == 0: 
		return None
	# Dictionary to store element 
	# and its frequency 
	dict = {} 
	for element in list: 
		if element in dict: 
			dict[element] += 1
		else: 
			dict[element] = 1

	# Find maximum frequency 
	max_frequency = 0
	for element in dict: 
		if (dict[element] > max_frequency): 
			max_frequency = dict[element] 
			max_element = element

	return max_element 

