    # Split string into list of words
    words = input_string.split()

    # Create an empty dictionary
    freq = {}

    # Loop through the list of words and populate the dictionary
    for word in words:
        if word in freq:
            freq[word] += 1
        else:
            freq[word] = 1

    # Get the most frequently occurring word
    max_freq = 0
    for key, value in freq.items():
        if value > max_freq:
            max_freq = value 
            max_word = key

