def triplet_sum(nums, target):
    result = 0
    for i in range(len(nums)-2):
        for j in range(i+1, len(nums)-1):
            for k in range(j+1, len(nums)):
                if (nums[i] + nums[j] + nums[k] == target):
                    result+=1

    return result

