public class LongestCommonSubstring {
 public static String lcs(String s1, String s2) {
  int maxlen = 0;
  int lastSubsBegin = 0;
  String lcs = "";
  int[] prev = new int[s2.length()];

  for (int i = 0; i < s1.length(); i++) {
   for (int j = 0; j < s2.length(); j++) {
    if (s1.charAt(i) == s2.charAt(j)) {
     if ((i == 0) || (j == 0)) {
      prev[j] = 1;
     } else {
      prev[j] = prev[j - 1] + 1;
     }

     if (prev[j] > maxlen) {
      maxlen = prev[j];
      // generate substring from str              
      int thisSubsBegin = i - prev[j] + 1;
      if (lastSubsBegin == thisSubsBegin) {
       lcs += s1.charAt(i);
      } else {
       lastSubsBegin = thisSubsBegin;
       lcs = "";
       lcs += s1.substring(lastSubsBegin, i + 1);
      }
     }
    } else {
     prev[j] = 0;
    }
   } 
  }
  return lcs;
 }

 public static void main(String[] args) {
  String s1 = "abcdefgh";
  String s2 = "xyzabc";
  System.out.println("LCS of " + s1 + " and " + s2 + " is " + lcs(s1, s2));
 }
}

