 private static int getWordCount(String s) {
 String[] words = s.split("\\s+");
 return words.length;
 }

 private static String getLongestWord(String s) {
 String[] words = s.split("\\s+");
 int longestLen = 0;
 String longestWord = "";
 for (String word : words) {
 int len = word.length();
 if (len > longestLen) {
 longestLen = len;
 longestWord = word;
 }
 }
 return longestWord;
 }

 private static int getNonAlphabeticCount(String s) {
 int count = 0;
 for (char c : s.toCharArray()) {
 if (!Character.isAlphabetic(c)) {
 count++;
 }
 }
 return count;
 }

}

def search_sorted_matrix(matrix, target):
    row = 0
    col = len(matrix[0]) - 1
    while row < len(matrix) and col >= 0:
        if matrix[row][col] == target:
            return (row, col)
        if matrix[row][col] > target:
            col -= 1
        else:
            row += 1
    return (-1, -1)

class DoublyLinkedList { 

    // Doubly Linked List node 
    public static class Node { 
        public int data; 
        public Node next; 
        public Node prev; 

        public Node(int data) { 
            this.data = data; 
        } 
    } 

    public Node head; 
    public Node tail; 

    // Function to initialize the linkedlist 
    public void initialize() 
    { 
        head = new Node(0); 
        tail = new Node(0); 

        head.next = tail; 
        tail.prev = head; 
    } 

    // Function to append values at the end of Linked List 
    public void append(int data) 
    { 
        Node no = new Node(data); 

        Node tempTail = tail; 
        tail.data = data; 
        tail.next = no; 
        tail.prev = tempTail; 
        tail = no; 
    } 

    // Function to prepend values at the beginning of Linked List 
    public void prepend(int data) 
    { 
        Node no = new Node(data); 

        Node tempHead = head; 
        head.data = data; 
        head.prev = no; 
        head.next = tempHead; 
        head = no; 
    } 

    // Function to delete a node 
    public void delete(Node node) 
    { 
        node.prev.next = node.next; 
        node.next.prev = node.prev; 
    } 

    // Function to delete a node at the given position 
    public void deleteAtPosition(int pos) 
    { 
        // code to delete the node at the given position 
    } 

    public void display() 
    { 
        Node current = head; 
        while (current != tail) { 
            System.out.print(current.data + " "); 
            current = current.next; 
        } 
        System.out.println(); 
    } 
}

