vector<string> splitString(string str, char delimiter){
    vector<string> subStrings;
    string currentString = "";

    for(int i = 0; i < str.size(); i++){
        if(str[i] == delimiter){
            subStrings.push_back(currentString);
            currentString = "";
        }
        else {
            currentString += str[i];
        }
    }

    subStrings.push_back(currentString);
    return subStrings;
}

