import React, { Component } from 'react';
import { Text, View, TouchableOpacity, StyleSheet } from 'react-native';

export default class App extends Component {
  constructor(props) {
    super(props);
    this.state = { 
      // 0 = empty, 1 = circle, 2 = cross
      gameState: [0, 0, 0, 0, 0, 0, 0, 0, 0],
      currentPlayer: 1,
    }
  }

  componentDidMount() {
    this.initializeGame();
  }

  initializeGame = () => {
    this.setState({ gameState: [0, 0, 0, 0, 0, 0, 0, 0, 0] });
  }

  drawItem = (itemNumber) => {
    switch (this.state.gameState[itemNumber]) {
      case 1: return <View style={[styles.item, { backgroundColor: 'red' }]} />;
      case 2: return <View style={[styles.item, { backgroundColor: 'green' }]} />;
      default: return <View style={styles.item} />;
    }
  }

  onItemSelect = (itemNumber) => {
    // Don't allow if the game is over
    if (this.gameOver()) return;

    // Don't allow if the spot is taken
    if (this.state.gameState[itemNumber] !== 0) return;

    this.state.gameState[itemNumber] = this.state.currentPlayer;

    this.setState({ gameState: this.state.gameState, currentPlayer: this.state.currentPlayer === 1 ? 2 : 1 });

    if (this.gameOver()) {
      if (this.state.gameState[itemNumber] === 1) alert('You lost');
      else alert('You won');
      this.initializeGame();
    }
  }

  gameOver = () => {
    const winningResult = [
      [0, 1, 2],
      [3, 4, 5],
      [6, 7, 8],
      [0, 3, 6],
      [1, 4, 7],
      [2, 5, 8],
      [0, 4, 8],
      [2, 4, 6]
    ];

    for (let i = 0; i < winningResult.length; i += 1) {
      const [a, b, c] = winningResult[i];
      if (
        this.state.gameState[a] === this.state.gameState[b] &&
        this.state.gameState[b] === this.state.gameState[c] &&
        this.state.gameState[a] !== 0
      ) {
        return true;
      }
    }
    return false;
  }

  render() {
    return (
      <View style={styles.container}>
        <View>
          <Text style={{ fontSize: 25 }}>Tic Tac Toe</Text>
          <Text style={{ fontSize: 20 }}>Current Player: {this.state.currentPlayer === 1 ? 'Circle' : 'Cross'} </Text>
        </View>
        <View style={styles.gameBoard}>
          <View style={styles.row} >
            <TouchableOpacity onPress={() => this.onItemSelect(0)} style={styles.item}>
              {this.drawItem(0)}
            </TouchableOpacity>
            <TouchableOpacity onPress={() => this.onItemSelect(1)} style={styles.item}>
              {this.drawItem(1)}
            </TouchableOpacity>
            <TouchableOpacity onPress={() => this.onItemSelect(2)} style={styles.item}>
              {this.drawItem(2)}
            </TouchableOpacity>
          </View>
          <View style={styles.row} >
            <TouchableOpacity onPress={() => this.onItemSelect(3)} style={styles.item}>
              {this.drawItem(3)}
            </TouchableOpacity>
            <TouchableOpacity onPress={() => this.onItemSelect(4)} style={styles.item}>
              {this.drawItem(4)}
            </TouchableOpacity>
            <TouchableOpacity onPress={() => this.onItemSelect(5)} style={styles.item}>
              {this.drawItem(5)}
            </TouchableOpacity>
          </View>
          <View style={styles.row} >
            <TouchableOpacity onPress={() => this.onItemSelect(6)} style={styles.item}>
              {this.drawItem(6)}
            </TouchableOpacity>
            <TouchableOpacity onPress={() => this.onItemSelect(7)} style={styles.item}>
              {this.drawItem(7)}
            </TouchableOpacity>
            <TouchableOpacity onPress={() => this.onItemSelect(8)} style={styles.item}>
              {this.drawItem(8)}
            </TouchableOpacity>
          </View>
        </View>
        <View>
          <TouchableOpacity onPress={() => this.initializeGame()}>
            <Text style={{ fontSize: 25 }}>Restart</Text>
          </TouchableOpacity>
        </View>
      </View>
    );
  }
};

