public static int lcs(String s1, String s2) { 
    int l1 = s1.length(); 
    int l2 = s2.length(); 

    int[][] LCS = new int[l1 + 1][l2 + 1]; 

    for (int i = 0; i <= l1; i++) { 
        for (int j = 0; j <= l2; j++) { 
            if (i == 0 || j == 0) 
                LCS[i][j] = 0; 
            else if (s1.charAt(i - 1) == s2.charAt(j - 1)) 
                LCS[i][j] = LCS[i - 1][j - 1] + 1; 
            else
                LCS[i][j] = Math.max(LCS[i - 1][j], LCS[i][j - 1]); 
        } 
    } 

    return LCS[l1][l2]; 
}

