def compute_levenshtein_distance(a, b): 
    n = len(a)
    m = len(b)
    d = [[0 for i in range(m + 1)] for j in range(n + 1)] 

    for i in range(n + 1): 
        for j in range(m + 1): 
            if i == 0:
                d[i][j] = j
            elif j == 0:
                d[i][j] = i
            elif a[i-1] == b[j-1]: 
                d[i][j] = d[i-1][j-1]
            else: 
                d[i][j] = min(d[i-1][j], d[i][j-1], d[i-1][j-1]) + 1   
    return d[n][m]

