# Function to find the MST using Prim's algorithm 
def prims(graph, start): 
    visited = [] # list to keep track of visited nodes
    total_cost = 0 # variable for total cost of MST 
    visited.append(start) # append the starting node to the visited list 

    # loop until all nodes are visited
    while len(visited) != len(graph): 
        min_edge = None
        for node in visited: 
            for (neighbor, cost) in graph[node]: 
                if neighbor not in visited and (min_edge == None or cost<min_edge[2]): 
                    min_edge = (node, neighbor, cost) 
        visited.append(min_edge[1])
        total_cost += min_edge[2] 

    return total_cost

