public class BST {

  static class Node {
   int data;
   Node left, right;

   Node(int data) {
    this.data = data;
    this.left = null;
    this.right = null;
   }
  }

  Node root;

  // Insert an item in its correct position in BST
  public void insert(int data) {
   root = insertRec(root, data);
  }

  // A utility function to insert a new node with given data 
  private Node insertRec(Node node, int data) {
   // if the tree is empty, return a new node
   if (node == null) {
    node = new Node(data);
    return node;
   }

   // otherwise, recur down the tree
   if (data < node.data)
    node.left = insertRec(node.left, data);
   else if (data > node.data)
    node.right = insertRec(node.right, data);

   // return the unchanged node pointer
   return node;
  }
}

public static List<String> three_most_used_words(String sentence) {
    List<String> words = new ArrayList<>();
    String[] split_words = sentence.split(" ");
    for (String word : split_words) {
        words.add(word);
    }
    Map<String, Integer> word_counter = new HashMap<>();
    for (String word : words) {
        if (word_counter.containsKey(word)) {
            word_counter.put(word, word_counter.get(word) + 1);
        } else {
            word_counter.put(word, 1);
        }
    }
    List<String> most_used_words = new ArrayList<>();
    Map<String, Integer> sorted_word_counter = word_counter
    .entrySet()
    .stream()
    .sorted(Map.Entry.comparingByValue())
    .collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue, (e1, e2) -> e2, LinkedHashMap::new));
    int count = 0;
    for (Map.Entry<String, Integer> entry : sorted_word_counter.entrySet()) {
        if (count == 3) {
            break;
        }
        most_used_words.add(entry.getKey());
        count++;
    }
    return most_used_words;
}

