"""
Generate a solution that resolves a deadlock problem between two threads
"""

import threading

def lock_resources(lock1, lock2):
    success = False
    while not success:
        result_lock1 = lock1.acquire(blocking=False)
        result_lock2 = lock2.acquire(blocking=False)
        if result_lock1 and result_lock2:
            success = True 
        else:
            if result_lock1:
                lock1.release()
            if result_lock2:
                lock2.release()
            time.sleep(0.1) 

if __name__ == '__main__':
    lock1 = threading.Lock()
    lock2 = threading.Lock()

    lock_resources(lock1, lock2)

