 public static int generateRandomPrime() { 
  //use a cryptographically secure random number generator 
  SecureRandom random = new SecureRandom(); 
  int n = random.nextInt(1000000000); 

  //continue generating a random number until a prime is found 
  while (!isPrime(n)) { 
   n = random.nextInt(1000000000); 
  } 

  return n; 
 } 

 //determine if a number is prime 
 private static boolean isPrime(int n) { 
  //check for divisors from 2 to the square root of n 
  for (int i = 2; i < Math.sqrt(n); i++) { 
   if (n % i == 0) { 
    return false; 
   } 
  } 

  return true; 
 } 

