        String str = "Hello World";

        // Create the tokenizer
        StringTokenizer st = new StringTokenizer(str);

        // Create the array
        String[] arr = new String[st.countTokens()];

        // Parse the input string into tokens
        for(int i = 0; i < st.countTokens(); i++){
