class PriorityQueue<T> {
 private data: {priority: number, value: T}[] = [];

public enqueue(value: T, priority: number) {
 this.data.push({priority, value});
 this.data.sort((a, b) => b.priority - a.priority);
}

public dequeue(): T | undefined {
 return this.data.pop()?.value;
}

public peek(): T | undefined {
 return this.data[this.data.length - 1]?.value;
}

public getLength(): number {
 return this.data.length;
 }
}

