// Function to sort the array in non-descending order
void sortArray(int arr[], int n)
{
  // outer loop iterates through the array
  for (int i = 0; i < n; i++) 
  {
    // inner loop iterates through the remaining elements
    for (int j = i + 1; j < n; j++)
    {
      // if the current element is greater than the next element, swap them
      if (arr[i] > arr[j])
      {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
      }
    }
  }

  // Print the sorted array
  cout << "\nSorted array is: ";
  for (int i = 0; i < n; i++)
    cout << arr[i] << " ";
}

