def shortest_path(maze, start, end):
 queue = [[start]]
 visited = set()
 while queue:
 path = queue.pop(0)
 vertex = path[-1]
 if vertex == end:
 return path
 if vertex not in visited:
 for neighbor in maze.get(vertex, []):
 new_path = list(path)
 new_path.append(neighbor)
 queue.append(new_path)
 visited.add(vertex)

