bool naiveStringSearch(string s, string pat) {
 int sLen = s.length();
 int patLen = pat.length();

 // Iterate through string
 for (int i = 0; i < sLen - patLen + 1; i++) {
 int j = 0;

 // Iterate through pattern
 for (j = 0; j < patLen; j++) 
 if (s[i + j] != pat[j]) 
 break;

 // Pattern found
 if (j == patLen) 
 return true;
 }
 return false;
}

