function mergeSort(arr) {
 // If array has at least 2 elements
 if (arr.length >= 2) {
 // Helper functions
 // Divide array into halves
 let mid = Math.floor(arr.length / 2);
 let left = arr.slice(0, mid);
 let right = arr.slice(mid);
 // Merge halves
 return merge(mergeSort(left), mergeSort(right));
 } else {
 return arr;
 }
}

// Helper function for mergeSort
function merge(left, right) {
 let result = [];
 let lInd = 0;
 let rInd = 0;

 while (lInd < left.length && rInd < right.length) {
 if (left[lInd] < right[rInd]) {
 result.push(left[lInd]);
 lInd++;
 } else {
 result.push(right[rInd]);
 rInd++;
 }
 }
 // Empty any remaining elements from left or right arrays
 return result.concat(left.slice(lInd), right.slice(rInd));
}

