int countPrimes(int limit)  
{  
    int count = 0; 
    // loop to check whether each number is a prime or not 
    for(int i = 2; i < limit; i++) 
    { 
        // variable to check whether number is prime or not 
        bool check = true; 

        // loop to check whether the number is prime or not 
        for(int j = 2; j <= i/2; j++) 
        { 
            if (i % j == 0) 
            { 
            	check = false; 
                break; 
            } 
        } 

        // if number is prime, then increase the count 
        if (check) 
            count++; 
    } 
    return count; 
}

