#include <string>
using namespace std;

string encryptCaesarCipher(string str, int shift)
{
 string result = "";
 for (int i = 0; i < str.length(); ++i)
 {
 char ch = str[i];
 if (std::isalpha(ch))
 {
 ch = (toupper(ch) + shift - 65) % 26 + 65;
 }
 result += ch;
 }
 return result;
}

string decryptCaesarCipher(string str, int shift)
{
 string result = "";
 for (int i = 0; i < str.length(); ++i)
 {
 char ch = str[i];
 if (std::isalpha(ch))
 {
 ch = (toupper(ch) - shift - 65) % 26 + 65;
 }
 result += ch;
 }
 return result;
}

int main()
{
 string str = "Hello, my name is John.";
 int shift = 4;

 string encrypted_str = encryptCaesarCipher(str, shift);
 cout << encrypted_str << "\n"; // Output: "Lipps, qa pqeb nb Mtiw."
 string decrypted_str = decryptCaesarCipher(encrypted_str, shift);
 cout << decrypted_str << "\n"; // Output: "Hello, my name is John."

