public class WatermarkPhotoActivity extends Activity {

 private static final int CAPTURE_IMAGE_ACTIVITY_REQUEST_CODE = 100;
 private Uri imageUri;

 public void takePicture(View v) {
 // Create an intent for taking a photo
 Intent intent = new Intent(MediaStore.ACTION_IMAGE_CAPTURE);

 // Save the photo to the specified URI
 ContentValues values = new ContentValues();
 values.put(MediaStore.Images.Media.TITLE, "MyPicture");
 values.put(MediaStore.Images.Media.DESCRIPTION,
              "Photo taken on " + System.currentTimeMillis());
 imageUri = getContentResolver().insert(
 MediaStore.Images.Media.EXTERNAL_CONTENT_URI, values);
 intent.putExtra(MediaStore.EXTRA_OUTPUT, imageUri);

 // Launch the camera
 startActivityForResult(intent, CAPTURE_IMAGE_ACTIVITY_REQUEST_CODE);
 }

 @Override
 protected void onActivityResult(int requestCode, int resultCode, Intent data) {
 if (requestCode == CAPTURE_IMAGE_ACTIVITY_REQUEST_CODE) {
 if (resultCode == RESULT_OK) {
 // Add watermark to the photo
 Bitmap bitmap = null;
 try {
 bitmap = MediaStore.Images.Media.getBitmap(this.getContentResolver(), imageUri);
 } catch (Exception e) {
 e.printStackTrace();
 }
 Bitmap watermarked = addWatermark(bitmap, this);

 String imagePath = Environment.getExternalStorageDirectory().getAbsolutePath()
 + "/watermarkPhoto.jpg";
 saveAsJPEG(watermarked, imagePath);
 Toast.makeText(this,
 "The watermarked image is saved to: " + imagePath,
 Toast.LENGTH_LONG).show();
 } else if (resultCode == RESULT_CANCELED) {
 Toast.makeText(this, "Take picture cancelled",
 Toast.LENGTH_LONG).show();
 } else {
 Toast.makeText(this, "Take picture failed",
 Toast.LENGTH_LONG).show();
 }
 }
 }

 public Bitmap addWatermark(Bitmap original, Context context) {
 Bitmap result = Bitmap.createBitmap(original.getWidth(),
            original.getHeight(), Bitmap.Config.ARGB_8888);
 Canvas canvas = new Canvas(result);
 Paint paint = new Paint();
 paint.setStyle(Paint.Style.FILL);
 paint.setAntiAlias(true);
 paint.setColor(Color.BLACK);
 paint.setTextSize(20);
 paint.setTypeface(Typeface.create(Typeface.DEFAULT, Typeface.BOLD));

 String text = "Timestamp: " + System.currentTimeMillis();
 canvas.drawText(text, 10, result.getHeight() - 10, paint);
 canvas.drawBitmap(original, 0, 0, paint);

 return result;
 }

 public void saveAsJPEG(Bitmap bitmap, String path) {
 FileOutputStream out = null;
 try {
 out = new FileOutputStream(path);
 bitmap.compress(Bitmap.CompressFormat.JPEG, 90, out);
 } catch (Exception e) {
 e.printStackTrace();
 } finally {
 try {
 if (out != null) {
 out.close();
 }
 } catch (IOException e) {
 e.printStackTrace();
 }
 }
 }
}

