public class FilterPrime {
 public static List<Integer> filter(List<Integer> numbers) {
  List<Integer> primes = new ArrayList<>();
  for (int n : numbers) {
   if (isPrime(n)) {
    primes.add(n);
   }
  }
  return primes;
 }

 private static boolean isPrime(int number) {
  if (number <= 1) {
   return false;
  }
  for (int i = 2; i < number; i++) {
   if (number % i == 0) {
    return false;
   }
  }
  return true;
 }
}

