class RangeMaximumQuery
{
    private int[] array;
    private int[] segmentTree;

    public RangeMaximumQuery(int[] array)
    {
        this.array = array;
        this.segmentTree = new int[this.array.length * 4];
        constructSegmentTree(0, array.length - 1, 0);
    }

    private int constructSegmentTree(int low, int high, int pos)
    {
        if (low == high)
        {
            segmentTree[pos] = array[low];
            return segmentTree[pos];
        }
        int mid = (low + high) / 2;
        segmentTree[pos] = Math.max(constructSegmentTree(low, mid, 2 * pos + 1),
                constructSegmentTree(mid + 1, high, 2 * pos + 2));
        return segmentTree[pos];
    }

    public int rangeMaximumQuery(int qLow, int qHigh)
    {
        return rangeMaximumQuery(0, array.length - 1, qLow, qHigh, 0);
    }

    private int rangeMaximumQuery(int low, int high, int qLow, int qHigh, int pos)
    {
        if (qLow <= low && qHigh >= high)
        {
            return segmentTree[pos];
        }
        if (qLow > high || qHigh < low)
        {
            return Integer.MIN_VALUE;
        }
        int mid = (low + high) / 2;
        return Math.max(rangeMaximumQuery(low, mid, qLow, qHigh, 2 * pos + 1),
                rangeMaximumQuery(mid + 1, high, qLow, qHigh, 2 * pos + 2));
    }
}

// Function to find the solution
function solveLinearEquations(A, b) {
 let x = [];
 let n = A.length;

 // Create Matrix A-1
 let AInverse = inverseMatrix(A);

 // Compute x = A-1b
 for (let i = 0; i < n; i++) {
  let result = 0;
  for (let j = 0; j < n; j++) {
   result += AInverse[i][j] * b[j];
  }
  x.push(result);
 }
 return x;
}

// Function to calculate the inverse of a matrix
function inverseMatrix(A) {
 // calculate the determinant
 let determinant = determinant(A);

 // Special case for 2x2 matrix:
 if (A.length === 2) {
  let a = A[0][0];
  let b = A[0][1];
  let c = A[1][0];
  let d = A[1][1];

  return [[d/determinant, -b/determinant],
         [-c/determinant, a/determinant]];
 }

// Find matrix of cofactors
 let cofactors = [];
 for (let i = 0; i < A.length; i++) {
  let row = [];
  for (let j = 0; j < A[i].length; j++) {
   let minor = minor(A, i, j);
   row.push(((i + j) % 2 === 0 ? 1 : -1) * determinant(minor) / determinant);
  }
  cofactors.push(row);
 }

// Return the transpose of cofactor to get inverse
 return transpose(cofactors);
}

