      num = num + temp
      temp = 0
    elif (inputString[i] == "-"):
      num = num - temp
      temp = 0
    elif (inputString[i] == "*"):
      num = num * int(inputString[i+1])
      i+=1
    elif (inputString[i] == "/"):
      num = num / int(inputString[i+1])
      i+=1
    else:
      temp = int(inputString[i])

  num = num + temp

