class SearchEngine:
 def __init__(self):
 self.documents = []
 self.index = defaultdict(list)

 # Add a new document to the search engine
 def add_document(self, document):
 # Add the new document to the list of documents
 self.documents.append(document)

 # Split the document text into words
 words = document.text.split()
 # Add a record for each word
 for word in words:
 self.index[word].append(document.id)

 # Search for documents containing a given keyword
 def search(self, keyword):
  if keyword in self.index:
   # Return the list of documents which contain the keyword
   return [self.documents[doc_id] for doc_id in self.index[keyword]]
  else:
   # Return an empty list if the keyword is not found
   return []

