void executeProgram(std::string input)
{
    // Create an input string stream from our input string
    std::istringstream ss(input);

    // Variables to store the results of each execution
    std::string result, line;

    // Read each line of the program
    while (std::getline(ss, line))
    {
        // Create a stringstream to read the line
        std::istringstream line_ss(line);

        // Attempt to compile and execute the line
        try 
        {
            result += "Line " + line + ": " + std::to_string(true) + "\n";
        }
        catch (std::exception& e)
        {
            result += "Line " + line + ": " + std::to_string(false) + "\n";
        }
    }

    // Print the results
    std::cout << result;
}

