import java.util.HashSet;
import java.util.Set;

public class SmallestNewInteger {
    public static int findSmallestNewInt(int[] arr) {
        // create a HashSet to store existing elements
        Set<Integer> set = new HashSet<>();
        for (int num : arr) {
            set.add(num);
        }

        // start from 1 and incrementally search for the smallest new integer
        int smallestNewInteger = 1;
        while (set.contains(smallestNewInteger)) {
            smallestNewInteger++;
        }

        return smallestNewInteger;
    }

    public static void main(String[] args) {
        int[] arr = {1,2,3,4,5};
        int res = findSmallestNewInt(arr);
        System.out.println(res);
    }
}

