// Simple Sieve of Eratosthenes
function sieve(n) { 
  let primes = []; 
  for (let i = 0; i <= n; i++) 
    primes[i] = true; 

  for (let p = 2; p*p <= n; p++) { 
    if (primes[p]) { 
      for (let i = p*2; i <= n; i += p) 
        primes[i] = false; 
    } 
  } 

  // Print all prime numbers 
  for (let p = 2; p <= n; p++) 
    if (primes[p]) 
      console.log(p); 
}

