        setContentView(R.layout.activity_main);

        // Get Views
        searchButton = (Button) findViewById(R.id.searchButton);
        searchEditText = (EditText) findViewById(R.id.searchEditText);
        searchResultsListView = (ListView) findViewById(R.id.searchResultsListView);

        // Initialize movieList
        movieList = new ArrayList<Movie>();

        // Set onClickListener for searchButton
        searchButton.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View view) {
                // Get query from searchEditText
                String query = searchEditText.getText().toString();

                // Call searchTMDB() with query
                searchTMDB(query);
            }
        });
    }

    // searchTMDB()
    private void searchTMDB(String query){
        // Create API url with query
        String API_URL = "https://api.themoviedb.org/3/search/movie?api_key=API_KEY&query="+query;

        // Make API call
        StringRequest request = new StringRequest(Request.Method.GET, API_URL, new Response.Listener<String>(){
            @Override
            public void onResponse(String response) {
                try {
                    // Convert response to JSONObject
                    JSONObject jsonObject = new JSONObject(response);
                    // Get JSONArray of results
                    JSONArray jsonArray = jsonObject.getJSONArray("results");
                    // Get JSONObject from JSONArray
                    for (int i = 0; i < jsonArray.length(); i++) {
                        JSONObject movieJSON = jsonArray.getJSONObject(i);
                        // Create Movie object from JSON
                        Movie movie = new Movie();
                        movie.setId(movieJSON.getInt("id"));
                        movie.setTitle(movieJSON.getString("title"));
                        movie.setOverview(movieJSON.getString("overview"));
                        movie.setPoster_path(movieJSON.getString("poster_path"));
                        movieList.add(movie);
                    }
                    // Initialize MovieAdapter and set it to the searchResultsListView
                    MovieAdapter adapter = new MovieAdapter(MainActivity.this, movieList);
                    searchResultsListView.setAdapter(adapter);
                } catch (JSONException e) {
                    e.printStackTrace();
                }
            }
        }, new Response.ErrorListener() {
            @Override
            public void onErrorResponse(VolleyError error) {
                error.printStackTrace();
            }
        });
        // Add request to requestQueue
        RequestQueue queue = Volley.newRequestQueue(getApplicationContext());
        queue.add(request);
    }
}

