public class BalancedParentheses {

    public static boolean isBalanced(String input) {
        char[] stack = new char[input.length()];
        int top = -1;

        for (int i=0; i < input.length(); i++) {
            char ch = input.charAt(i);
            if (ch == '(' || ch == '{' || ch == '[') {
                // push the opening parentheses onto the stack
                stack[++top] = ch;
            }
            else if (ch == ')' || ch == '}' || ch == ']') {
                // if the stack is empty, return false
                if (top == -1) {
                    return false;
                }
                // otherwise, pop the top element in the stack and check if it 
                // matches the corresponding closing parentheses
                char topChar = stack[top--];
                if ((ch == '(' && topChar != ')') || (ch == '{' && topChar != '}') || (ch == '[' && topChar != ']')) {
                    return false;
                }
            }
        }
        // if there are any remaining parentheses in the stack, the expression is unbalanced
        if (top != -1) {
            return false;
        }
        return true;
    }

    public static void main(String[] args) {
        String expr1 = "((A+B))";
        String expr2 = "(A+[B*C]";

        if (isBalanced(expr1)) 
            System.out.println("The expression " + expr1 + " is balanced."); 
        else
            System.out.println("The expression " + expr1 + " is not balanced."); 

        if (isBalanced(expr2)) 
            System.out.println("The expression " + expr2 + " is balanced."); 
        else
            System.out.println("The expression " + expr2 + " is not balanced.");    
    }
}

