def caesar_cipher(string, shift):
  encrypted_string = ""
  for char in string:
    if char.isalpha():
      char_code = ord(char)
      char_code += shift
      if char.isupper():
        if char_code > ord('Z'):
          char_code -= 26
        elif char_code < ord('A'):
          char_code += 26
      elif char.islower():
        if char_code > ord('z'):
          char_code -= 26
        elif char_code < ord('a'):
          char_code += 26
      encrypted_string += chr(char_code)
    else:
      encrypted_string += char
  return encrypted_string

