// A recursive function that returns the maximum value 
// which can be put in a knapsack of capacity W
int knapsack(int W, int wt[], int val[], int n) 
{ 
   // Base Case: The capacity is 0 or there are no items
   if (W == 0 || n == 0) 
       return 0; 

   // recursive Cases
   // If weight of nth item is greater than capacity W, 
   // then this item cannot be included in the optimal solution 
   if (wt[n-1] > W) 
       return knapsack(W, wt, val, n-1); 

   // Return the maximum of two cases: 
   // (1) nth item included 
   // (2) not included 
   else return max( val[n-1] + knapsack(W-wt[n-1], wt, val, n-1), 
                     knapsack(W, wt, val, n-1) ); 
}

// Return the optimal value 
int knapsackSolution(int W, int wt[], int val[], int n) 
{
    int weights[] = {2, 3, 4};
    int values[] = {60, 100, 120};
    return knapsack(6, weights, values, 3);   
}

