def compare_dictionaries(dic1, dic2):
    # Check if both dictionaries have the same number of keys
    if len(dic1) != len(dic2):
        return False

    # Iterate through the keys of the two dictionaries
    for key in dic1:
        # Check if the corresponding value in the second dictionary is the same as the first
        if dic1[key] != dic2[key]:
            return False
    # If the keys and values have all been the same, return True
    return True

