const findTotalCostPerDate = (events) => {
  let totalCosts = {};
  events.forEach(event => {
    // For each event, check if the date has already been added to the totalCosts object
    if (totalCosts[event.date]) {
      // If the date is already in the object, add the event cost to the existing cost
      totalCosts[event.date] += event.cost;
    } else {
      // If the date is not in the object, add it and set the cost to the event cost
      totalCosts[event.date] = event.cost;
    }
  });
  return totalCosts;
}

