class InstallCommand(CommandProcessor):

    from .base import coroutine
    package = ''
    adapter = ''

    def wiring(self):
        self.out = self.write()
        self.ticker.routine(self.progress(None))
        return self.each(self.spacing(self.call(self.res())))

    def seen(self, command, adapter, package, result=False):
        self.package = package
        self.adapter = adapter
        return result

    @coroutine
    def res(self):
        while True:
            res = (yield)
            if res[1] == 0:
                print 'Successfully installed package: {} with {}'.format(self.package, self.adapter)
            else:
                print 'Aborted: Error while installing package: {} {} returned exit code {}'.format(
                    self.package, self.adapter, res[1]
                )

    @coroutine
    def write(self):
        import sys
        out = sys.stdout
        while True:
            text = (yield)
            out.write(text)

    @coroutine
    def spacing(self, target):
        while True:
            payload = (yield)
            print u'\n'
            target.send(payload)

    @coroutine
    def progress(self, responder):
        while True: (yield)

def longest_common_substring(str1, str2):
 m = [[0] * (1 + len(str2)) for i in range(1 + len(str1))]
 longest, x_longest = 0, 0
 for x in range(1, 1 + len(str1)):
  for y in range(1, 1 + len(str2)):
   if str1[x - 1] == str2[y - 1]:
    m[x][y] = m[x - 1][y - 1] + 1
    if m[x][y] > longest:
     longest = m[x][y]
     x_longest = x
  else:
   m[x][y] = 0
 return str1[x_longest - longest: x_longest]

