def get_all_permutations(arr): 
    if len(arr) == 0: 
        return [] 

    if len(arr) == 1: 
        return [arr]

    l = [] # empty list 
    for i in range(len(arr)): 
       m = arr[i] 

       remaining_elements = arr[:i] + arr[i+1:] 
       for p in get_all_permutations(remaining_elements): 
           l.append([m] + p) 
    return l 

