def knapsack(limit, items):
    """Solves the knapsack problem.""" 
    n = len(items)

    # create a matrix to store the index and maximum value
    matrix = [[-1 for x in range(limit + 1)] for y in range(n + 1)] 

    for i in range(n + 1):
        for w in range(limit + 1):
            if i == 0 or w == 0:
                matrix[i][w] = 0
            elif items[i-1][1] <= w:
                matrix[i][w] = max(items[i-1][0] + matrix[i-1][w-items[i-1][1]], matrix[i-1][w] )
            else:
                matrix[i][w] = matrix[i-1][w]

    # return the maximum value
    return matrix[n][limit]

