public class SumOfTwo {
    public static int addTwoNumbers(int x, int y) {
        // Iterate till there is no carry  
        while (y != 0) { 
            int carry = x & y; 
            x = x ^ y; 
            y = carry << 1; 
        } 
        return x; 
    } 

