// Function to find the mid-point of the list 
public Node FindMiddle(Node head) 
{ 
    // Edge cases 
    if (head == null || head.next == null) 
        return head; 

    Node slow = head; 
    Node fast = head; 

    // Move fast by two nodes, and slow by one node 
    while (fast != null && fast.next != null) { 
        slow = slow.next; 
        fast = fast.next.next; 
    } 

    // Return the middle node 
    return slow; 
}

