def fibonacci(n):
    fibonacci_sequence = [0]

    # Handle the base case
    if n == 1:
        return fibonacci_sequence

    else:
        # Initialize the first two elements of the sequence
        fibonacci_sequence.append(1)

        # Generate the sequence up to the nth number
        for i in range(2,n):
            next_element = fibonacci_sequence[i-2] + fibonacci_sequence[i-1]
            fibonacci_sequence.append(next_element)

