class Stack{
    private:
        int capacity;
        int *arr; 
        int top; 
    public:
        Stack(int arrSize){
            capacity = arrSize;
            arr = new int[arrSize];
            top = -1;
        } 
        void push(int); 
        int pop(); 
        bool isEmpty(); 
        int peek(); 
}; 

void Stack::push(int value){
    if (top == (capacity - 1)) { 
        cout << "Stack Overflow"; 
    } 
    else { 
        arr[++top] = value; 
        cout << value << " pushed into stack\n"; 
    } 
} 

int Stack::pop() { 
    if (top == -1) { 
        cout << "Stack Underflow"; 
        return 0; 
    } 
    else { 
        int x = arr[top--]; 
        return x; 
    } 
}

bool Stack::isEmpty(){
    return top == -1;
} 

int Stack::peek(){
    if(top == -1){
        cout << "Stack Overflow"; 
    }else{
        return arr[top];
    }
}

