def validate_bst(tree):
    valid = True
    queue = [tree]

    while queue:
        current_node = queue.pop(0)
        left = tree.get(current_node[0], None)
        right = tree.get(current_node[1], None)

        if left is not None and current_node[0] > current_node[1]:
            valid = False
            break
        elif right is not None and current_node[1] < current_node[0]:
            valid = False
            break

        if left is not None:
            queue.append(left)
        if right is not None:
            queue.append(right)

