def is_prime(number): 
    if number <= 1: 
        return False 

    for i in range(2, number): 
        if number % i == 0: 
            return False 

    return True

def nth_prime(n): 
    prime_numbers = []
    num = 2
    while len(prime_numbers) < n:
        isPrime = True
        for i in range(2, num):
            if (num % i == 0):
                isPrime = False
        if isPrime:
            prime_numbers.append(num)
        num += 1
    return prime_numbers[-1]

