// JavaScript function to check if two strings are an anagram
function isAnagram(str_1, str_2) {
	// Anagrams have the same length
	if (str_1.length != str_2.length) {
        return false;
	}

	// Convert the strings to lowercase
	let str1 = str_1.toLowerCase();
	let str2 = str_2.toLowerCase();

	// Convert the strings to character array
	let char1 = str1.split("");
	let char2 = str2.split("");

	// Sort the character arrays
	char1.sort();
	char2.sort();

	// Join back the character arrays and check if they are the same
	let res1 = char1.join("");
	let res2 = char2.join("");

    return (res1 === res2);
}

