def find_minimum_coins(denominations, amount):
    # Base case
    if amount == 0:
        return 0

    # Initialize the minimum number of coins needed to infinity
    res = float("Inf")

    for i in range(len(denominations)):
        # If the denomination is less than the amount
        if denominations[i] <= amount:
            # Recursively call the function to see how many coins would be needed
            num_coins = find_minimum_coins(denominations, amount - denominations[i])
            # Check if this solution is better than the current solution
            if num_coins + 1 < res:
                res = num_coins + 1
    # Return the best solution
    return res

