public int maxProfit(int[] prices) { 
    int n = prices.length; 

    int profit = 0; 

    // Find the local minima and store it 
    for (int i = 0; i < n - 1; i++) { 

        // Look for lower minima 
        if (prices[i + 1] < prices[i]) { 
            profit -= prices[i]; 
        } 

        // Look for higher maxima 
        if (prices[i + 1] > prices[i]) { 
            profit += prices[i + 1]; 
        } 
    } 
    return profit; 
}

