public static int[][] solveSudoku(int[][] board) {
 //Check if the board is valid
 if (!boardIsValid(board)) {
 throw new IllegalArgumentException("Invalid Board");
 }

 while (!sudokuSolved(board)) {
 for (int row = 0; row < 9; row++) {
 for (int col = 0; col < 9; col++) {
 if (board[row][col] == 0) {
 List<Integer> possible = findPossibleNums(board, row, col);

 //If there is only one possible number, set the cell
 if (possible.size() == 1) {
 board[row][col] = possible.get(0);
 }
 }
 }
 }
 }
 return board;
}

