sub minmax {
    my $arr_ref = shift;
    my @array   = @$arr_ref;

    my ( $min, $max ) = ( $array[0], $array[0] );
    for ( my $i = 1; $i < scalar @array; ++$i ) {
        if ( $array[$i] > $max ) {
            $max = $array[$i];
        }
        elsif ( $array[$i] < $min ) {
            $min = $array[$i];
        }
    }
    return ( $min, $max );
}

