def sort_numbers_ascending(nums):
    # Bubble sort algorithm
    for i in range(len(nums)):
        for j in range(len(nums)-1-i):
            if nums[j] > nums[j+1]:
                nums[j+1], nums[j] = nums[j], nums[j+1]
    return  nums

# Nanoflow algorithm
def nanoflow(start, end, size):
    random_nums = generate_random_numbers(start, end, size)
    return sort_numbers_ascending(random_nums)

