#include<iostream>

class Node 
{  
    public: 
    int data;  
    Node* next;  
}; 

class LinkedList 
{  
    public: 
    Node* head;  

    // Constructor to initializationg the head of linked list  
    LinkedList() 
    {  
        head = NULL;  
    }  

    void add(int data) 
    {  
        // Create a new node  
        Node* new_node = new Node();  

        // Put data in new node  
        new_node->data = data;  

        // Make linked list is empty  
        if(head == NULL) 
        {  
            head = new_node;  
        } 
        else 
        {  
            // Create a pointer to traverse linked list  
            Node* ptr = head;  

            // Traverse until reach to the last node  
            while(ptr->next != NULL) 
            {  
                ptr = ptr->next;  
            }  

            // Link the last node of linked list with new node  
            ptr->next = new_node;  
        }  
    }  

    void remove(int data) 
    {  
        // Create a pointer to traverse linked list  
        Node* ptr = head;  
        Node* previous = NULL;  

        // Traverse until found the given node  
        while(ptr != NULL && ptr->data != data) 
        {  
            previous = ptr;  
            ptr = ptr->next;  
        }  

        // If given node found then delete the node  
        if(ptr != NULL) 
        {  
            // Found the given node at the head of the linked list  
            if(previous == NULL) 
            {  
                head = ptr->next;  
                delete ptr;  
            }  
            else 
            {  
                // Found the given node at the non-head of the linked list  
                previous->next = ptr->next;  
                delete ptr;  
            }  
        }  
    }  

    // Function to get the data of given node  
    int get(int data) 
    {  
        // Create a pointer to traverse linked list  
        Node* ptr = head;  

        // Traverse until reach to the given node  
        while(ptr != NULL && ptr->data != data) 
        {  
            ptr = ptr->next;  
        }  

        if(ptr != NULL) 
        {  
            // If node found then return the data  
            return ptr->data;  
        }  
    }  
}; 

