def eval_expr(expr):
    stack = []

    for char in expr: 
        if char == "(": 
            stack.append(char) 
        elif char == ")": 
            top_item = stack.pop() 
            while top_item != "(": 
                stack.append(top_item) 
                top_item = stack.pop() 
        else:
            stack.append(char) 
    ans = "".join(stack) 

    return eval(ans)

