def parseToTitleCase(string):
    # create a list for words
    words = []

    # loop over each letter
    for i in range(len(string)):
        # check if the letter is uppercase
        if string[i].isupper():
            # if so, convert it to lowercase and store as a new word
            if i != 0:
                words.append(string[i].lower())
            else:
                words.append(string[i])
        # if not, add it to the last word
        else:
            words[-1] += string[i]

    # construct the sentence using title case
    sentence = ""
    for word in words:
        sentence += word.title()

    return sentence

