    arr.sort()
    final_sum = None
    closest_sum = None
    prev_diff = float("inf")
    for i in range(len(arr)):
        for j in range(i+1, len(arr)):
            for k in range(j+1, len(arr)):
                sum = arr[i] + arr[j] + arr[k]
                diff = abs(num - sum)
                if diff < prev_diff:
