public int optimizeGreedyScheduling(int[] startTime, int[] endTime){
    // Sort activities according to their finish times
    sort(endTime);
    int prev = 0;
    int maxTime = 0;

    // Select all tasks from the sorted array that
    // do not overlap with the previously considered activity.
    for (int i = 0; i < endTime.length; i++) 
    { 
        if (startTime[i] >= endTime[prev]) 
        { 
            maxTime += endTime[i] - startTime[i]; 
            prev = i;
            } 
    } 
    return maxTime;
}

