using namespace std; 

#define MAX_CHAR 256 

string decrypt(string cipher) 
{ 
    int count[MAX_CHAR] = { 0 }; 
    int len = cipher.length();  

    int prev[len + 1];   
    prev[0] = 0;  
    for (int i = 1; i <= len; i++) 
    { 
        count[cipher[i - 1]]++;  
        prev[i] = count[cipher[i - 1]];  
    } 

    string decrypt; 
    for (int i = 0; i < len; i++)  
    { 
        int c = prev[i]; 
        decrypt.push_back(c + 'a' - 1); 
        prev[i] = --count[cipher[i]]; 
    }  
    return decrypt; 
} 

