        if len(string) < len(word):
            short_str = string
            long_str = word
        else:
            short_str = word
            long_str = string
        for i in range(len(short_str)):
            for j in range(len(long_str)):
                if short_str[i] == long_str[j]:
                    sub = short_str[i]
                    i_index = i + 1
                    j_index = j + 1
                    while (i_index < len(short_str) and j_index < len(long_str) and short_str[i_index] == long_str[j_index]):
                        sub += short_str[i_index]
                        i_index += 1
                        j_index += 1
                    if len(substring) < len(sub):
                        substring = sub

    return substring

