// C++ Code

vector<int> removeDuplicates(vector<int>& arr) {
    unordered_set<int> set;
    vector<int> result;
    for(int x : arr) {
        if(set.find(x) == set.end()) {
            set.insert(x);
            result.push_back(x);
        }
    }
    return result;
}

