using namespace std;

// structure of node
struct Node
{
    int data;
    struct Node* next;
};

// function to create and return a node 
struct Node* getNode(int data)
{
    // allocating memory to the node
    struct Node* temp = new Node;

    // assigning data to the node
    temp->data = data; 

    // assigning NULL to the next node
    temp->next = NULL; 

    // return the node
    return temp;
}

// function to insert a node at the beginning of the list 
struct Node* insertAtBeginning(struct Node* head, int data)
{
    // if linked list is empty
    if(head == NULL)
    {
        head = getNode(data);
        return head;
    }

    // create a node
    Node* newNode = getNode(data);

    // link the address of node to the starting node of the list 
    newNode->next = head;

    // set the address of new node as the head of the list  
    head = newNode;

    return head;
}

// function to print the list
void printList(struct Node *head)
{
    while(head != NULL)
    {
        cout << head->data << " ";
        head = head->next;
    }
}

int main()
{
    struct Node* head = NULL;

    // call the insertAtBeginning() to add elements to the list
    head = insertAtBeginning(head, 5);
    head = insertAtBeginning(head, 8);
    head = insertAtBeginning(head, 10);

    // print the list
    printList(head);

    return 0;
}

