// Structure for a single ray
struct Ray {
    Vector origin;
    Vector direction;

    Ray(Vector o, Vector d) : origin(o), direction(d) { }
};

// Structure for a single point in 3D space
struct Vector {
    float x, y, z;

    Vector(float x, float y, float z) : x(x), y(y), z(z) { }
};

// Function to find the closest object a ray intersects
float closestIntersection(std::vector<Object*> objects, Ray ray) {
    float minDist = INFINITY;
    for (auto object : objects) {
        float dist = object->intersect(ray);
        if (dist < minDist) {
            minDist = dist;
        }
    }
    return minDist;
}

// Main raytracing function
void rayTrace(std::vector<Object*> objects, Ray ray, Vector light, int iterations) {
    // Initialize variables
    Vector color(0.5, 0.5, 0.5);
    float dist = closestIntersection(objects, ray);

    // Recursively trace the ray
    if (dist < INFINITY && iterations > 0) {

        // Find the point where the ray and object intersect
        Vector point = ray.origin + (ray.direction * dist);

        // Find the normal vector of the object at the intersection
        Vector normal = object->getNormal(point);

        // Move the point slightly along the normal to avoid shadow acne
        point = point + (normal * 0.1f);

        // Calculate the diffuse lighting
        float diffuse = std::max(0.f, Vector::dot(light - point, normal));

        // Calculate the intensity of the light
        float intensity = 1.f - ((light - point).magnitude() / light.magnitude());

        // Add the diffuse component to the color
        color = color + (diffuse * intensity);

        // Trace another ray in a random direction
        Vector direction = (ray.direction + Vector(rand(), 0, rand())).normalized();
        rayTrace(objects, Ray(point, direction), light, iterations - 1);
    }

    // Set the pixel color
    setPixel(ray.origin.x, ray.origin.y, color);
}

