    // Add objects to the scene
    for (int i = 0; i < 10; i++) {
        objects.push_back(new Sphere(Vector(i, i, 0), 1, Color(1, 0, 0)));
    }

    // Render the scene with raytracing
    rayTrace(objects, ray, light, iterations)
}

