function findDeepestNode(node) {
    let deepestNode = node;
    let maxDepth = 0;

    const traverse = (node, depth) => {
        if (!node.children || node.children.length === 0) {
            if (depth > maxDepth) {
                maxDepth = depth;
                deepestNode = node;
            }

            return;
        }

        for (let child of node.children) {
            traverse(child, depth + 1);
        }
    }

    traverse(node, 0);
    return deepestNode;
}

