def longest_sequence(input_string):
    """Returns the length of the longest continuous sequence of the same character in a string """
    current_length = 0
    longest_length = 0
    prev_char = ""

    for char in input_string:
        if char == prev_char:
            current_length += 1
            if current_length > longest_length:
                longest_length = current_length
        else:
            current_length = 1
        prev_char = char
    return longest_length


