public static double[][] kMeans(double[][] data, int clusters) {
    int numAttributes = data[0].length;
    int numDataPoints = data.length;

    double[][] clusters = new double[clusters][numAttributes];

    // Randomly select two cluster centroids
    for (int i = 0; i < clusters; i++) {
        int randomDataPointIndex = (int) (Math.random() * numDataPoints);
        clusters[i] = data[randomDataPointIndex];
    }

    double[][] distances = new double[numDataPoints][clusters];

    // Calculate the distance of each data point to the centroids and assign the closest centroid to the data point
    while (true) {
        // Calculate distances of all data points to all centroids
        for (int i = 0; i < numDataPoints; i++) {
            for (int j = 0; j < clusters; j++) {
                distances[i][j] = calculateDistance(data[i], clusters[j]);
            }
        }

        // Assign each data point to the closest centroid
        int[] clusterIndices = new int[numDataPoints];
        for (int i = 0; i < numDataPoints; i++) {
            double minDistance = Double.MAX_VALUE;
            int index = -1;
            for (int j = 0; j < clusters; j++) {
                if (distances[i][j] < minDistance) {
                    minDistance = distances[i][j];
                    index = j;
                }
            }
            clusterIndices[i] = index;
        }

        // Create a new centroid for each cluster by taking the mean of all data points assigned to that cluster
        double[][] newClusters = new double[clusters][numAttributes];
        for (int i = 0; i < clusters; i++) {
            int c = 0;
            for (int j = 0; j < numDataPoints; j++) {
                if (clusterIndices[j] != i) {
                    continue;
                }
                for (int k = 0; k < numAttributes; k++) {
                    newClusters[i][k] += data[j][k];
                }
                c++;
            }
            if (c == 0) {
                continue;
            }
            for (int j = 0; j < numAttributes; j++) {
                newClusters[i][j] /= c;
            }
        }

        // Check if the new centroids are equal to the previous centroids and if so, break the loop
        boolean sameCentroids = true;
        for (int i = 0; i < clusters; i++) {
            for (int j = 0; j < numAttributes; j++) {
                if (clusters[i][j] != newClusters[i][j]) {
                    sameCentroids = false;
                    break;
                }
            }
            if (!sameCentroids) {
                break;
            }
        }

        if (sameCentroids) {
            break;
        }

        clusters = newClusters;
    }

    return clusters;
}

