    // find the lowest of both numbers
    int lowest = Math.min(number1, number2);
    int gcd = 1;
    //create a loop that iterates over all numbers until the
    // lowest number
    for (int i = 1; i <= lowest; i++) {
        //check if both numbers are divisible by i
