public static boolean isAnagram(String s1, String s2) {
 // Check for invalid inputs
 if (s1 == null || s2 == null) {
 return false;
 }

 // Convert strings to lowercase
 s1 = s1.toLowerCase();
 s2 = s2.toLowerCase();

 // Create two dictionaries for the strings
 Map<Character, Integer> dict1 = new HashMap<>();
 Map<Character, Integer> dict2 = new HashMap<>();

 // Populate dictionaries
 for (Character c : s1.toCharArray()) {
 dict1.put(c, dict1.getOrDefault(c, 0) + 1);
 }

 for (Character c : s2.toCharArray()) {
 dict2.put(c, dict2.getOrDefault(c, 0) + 1);
 }

 // If the counts of the character are not the same, then the two strings are not anagrams
 if (dict1.size() != dict2.size()) {
 return false;
 }

 // If the counts of the characters are the same, then it is an anagram
 for (Character c : dict1.keySet()) {
 if (!dict2.containsKey(c) || !dict1.get(c).equals(dict2.get(c))) {
 return false;
 }
 }

 return true;
}

