def evaluate(exp):
    """Evaluates a postfix expression containing single digit numbers and basic arithmetic operators"""
    stack = []
    for char in exp:
        if char.isdigit():
            stack.append(int(char))
        else:
            operand2 = stack.pop()
            operand1 = stack.pop()
            result = operate(operand1, operand2, char)
            stack.append(result)
