import java.util.Arrays;

public class MaximumOverlappingIntervals {
    public static int maxOverlappingIntervals(int[][] intervals) {
        // Sort the array using Java's built-in sorting mechanism
        Arrays.sort(intervals, (a, b) -> a[0] - b[0]);

        // Initialize variables to track 
        // no. of overlapping intervals and current end time
        int count = 0, endTime = 0;

        // Iterate through each interval
        for (int[] interval : intervals) {
            // if current start time <= curr end time,
            // it means there is overlap. So increase
            // endTime and, count 
            if (interval[0] <= endTime) {
                endTime = Math.max(endTime, interval[1]);
                count++;
            } 
            // else, interval do not overlap and we 
            // must update endTime to current interval's endTime
            else {
                endTime = interval[1];
            }
        }
        return count;
    }
}

