function isPalindromeSubstrings(str){
  let palindromeLength = 0;
  // Iterate over each character
  for(let i=0;i<str.length;i++){
      // Get the current character
      let char = str[i];
      // Create a lookback window of length 2
      for(let j=i-2;j>=0;j--){
          // Get the previous character
          if(char == str[j]){
              // Check if the substring between i and j is a palindrome
              let substr = str.substring(j,i+1);
              if(isPalindrome(substr)){
                  // Update the maximum palindrome length
                  palindromeLength = Math.max(palindromeLength, substr.length);
              }
          }
      }

  }
  return palindromeLength;
}

