def findAuthor(text):

    # Create a dictionary mapping words to authors
    wordDict = {}

    # Split the text into a list of words
    words = text.split()

    # Create a set of authors
    authors = set([author for author in wordDict.values()])

    # Count the number of times each author's words appear
    counts = {author:0 for author in authors}
    for word in words:
        if word in wordDict:
            counts[wordDict[word]] += 1

    # Find the most frequently occuring author's words
    max_author = None
    max_count = 0
    for author, count in counts.items():
        if count > max_count:
            max_author = author
            max_count = count

    return max_author

