import React, { useState, useEffect } from "react";

const boardSize = 3; // 3 x 3 board

const App = () => {
  const [board, setBoard] = useState(Array(boardSize).fill(Array(boardSize).fill(null)));
  const [currentPlayer, setCurrentPlayer] = useState("x");
  const [winner, setWinner] = useState(null);

  // Use to check if there is a winner
  useEffect(() => {
    const winCombos = [
      // Horizontal wins
      [0, 1, 2],
      [3, 4, 5],
      [6, 7, 8],
      // Vertical wins
      [0, 3, 6],
      [1, 4, 7],
      [2, 5, 8],
      // Diagonal wins
      [0, 4, 8],
      [2, 4, 6],
    ];

    for (let i = 0; i < winCombos.length; i++) {
      const [a, b, c] = winCombos[i];
      const value = board[a] && board[a] === board[b] && board[b] === board[c];
      if (value) {
        setWinner(value);
        break;
      }
    }
  },[board]);

// Create each tic-tac-toe cell
const renderCell = () => {
    let cellResults = [];

    for (let rowIndex = 0; rowIndex < boardSize; rowIndex++) {
      for (let colIndex = 0; colIndex < boardSize; colIndex++) {
        const cellId = `${rowIndex}-${colIndex}`;

        cellResults.push(
          <button
            key={cellId}
            onClick={() => handleCellClick(cellId, rowIndex, colIndex)}
            className="cell"
          >
            {board[rowIndex][colIndex]}
          </button>
        );
      }
    }

    return cellResults;
};

  // Reset the board and clear the winner
  const handleReset = () => {
    setBoard(Array(boardSize).fill(Array(boardSize).fill(null)));
    setWinner(null);
  };

  // When a cell is clicked
  const handleCellClick = (cellId, rowIndex, colIndex) => {
    if (!winner) {
      const updatedBoard = board;
      updatedBoard[rowIndex][colIndex] = currentPlayer;

      setBoard(updatedBoard);

      // Toggle currentPlayer
      if (currentPlayer === "x") {
        setCurrentPlayer("o");
      } else {
        setCurrentPlayer("x");
      }
    }
  };

  return (
    <div className="App">
      <h1>Tic Tac Toe</h1>
      <div className="board">{renderCell()}</div>
      {winner && <h4>Winner is {winner.toUpperCase()}</h4>}
      <button onClick={handleReset}>Reset</button>
    </div>
  );
};

