def nth_prime_number(n):
    prime_numbers = [2]
    i = 3
    while len(prime_numbers) < n:
        if all(i % prime != 0 for prime in prime_numbers):
            prime_numbers.append(i)
        i+= 1
    return prime_numbers[-1]

