 public static int EvaluateExpression(string expression)
 {
  int result = 0;
  int currentNumber = 0;
  char operation = '+';

  foreach (char c in expression)
  {
   if (char.IsDigit(c))
   {
    currentNumber = currentNumber * 10 + (c - '0');
    continue;
   }

   switch (operation)
   {
    case '+':
     result += currentNumber;
     break;
    case '-':
     result -= currentNumber;
     break;
    case '*':
     result *= currentNumber;
     break;
    case '/':
     result /= currentNumber;
     break;
   }

   currentNumber = 0;
   operation = c;
  }

  return result + currentNumber;
 }
}

bool isPrime(int number){
    // Basic edge cases
    if (number <= 1) return false;
    if (number <= 3) return true;

    // this check is done if number is not divisible by 2 and 3
    if (number % 2 == 0 || number % 3 == 0) return false;

    // This loop iterates through all possible factors
    // of the number i.e. odd numbers upto the square 
    // root of the number
    for (int i = 5; i * i <= number; i = i + 6){
        if (number % i == 0 || number % (i + 2) == 0) return false;
    }
    return true;
}

