// Input: a sorted array A and a search key k
// Output: The position of k in A if exists, else -1 

BINARY-SEARCH(A,k)

// Start looking at the middle of A
Set start = 0
Set end = size of A
Set mid = (start + end)/2

// If k is equal to mid then return mid
If A[mid] = k then
    return mid

// If k is greater than mid then look in the right subarray
ElseIf k > A[mid] then
    Set start = mid+1

// If k is lesser than mid then look in the left subarray
Else
    Set end = mid-1

// If start is greater or equal to end then k does not exist in A
If start >= end then
    return -1 
Else
    return BINARY-SEARCH (A, k)

END BINARY-SEARCH()

def binomialCoefficient(n, k):
    """
    This function calculates the binomial coefficient of n and k. 
    """
    if k > n-k:
        k = n-k
    res = 1
    for i in range(k):
        res *= (n-i)
        res /= (i+1)
    return int(res)

