public class Library {

    public static int[] insertionSort(int[] array) {
        if (array == null) {
            return array;
        }
        int len = array.length;
        for (int i = 0; i < len; i++) {
            int temp = array[i];
            int j = i - 1;
            while (j >= 0 && array[j] > temp) {
                array[j + 1] = array[j];
                j--;
            }
            array[j + 1] = temp;
        }
        return array;
    }

