// optimizing linear equations
function optimizeLinearEquations(x, y, z) {
  // define coefficient values
  var ax = -3, ay = 4, az = 3;
  var bx = 2, by = 3, bz = -1;
  var cx = 4, cy = 2, cz = 2;

  // calculate inverse matrix
  var idet = (ax*by*cz + bx*cy*az + cx*ay*bz - az*by*cx - bz*cy*ax - cz*ay*bx);
  var m11 = (by*cz - bz*cy) / idet;
  var m12 = (bz*cx - bx*cz) / idet;
  var m13 = (bx*cy - by*cx) / idet;
  var m21 = (cy*az - cz*ay) / idet;
  var m22 = (cz*ax - cx*az) / idet;
  var m23 = (cx*ay - cy*ax) / idet;
  var m31 = (ay*bz - az*by) / idet;
  var m32 = (az*bx - ax*bz) / idet;
  var m33 = (ax*by - ay*bx) / idet;

  // compute optimized variables
  x = m11*25 + m12*19 + m13*23;
  y = m21*25 + m22*19 + m23*23;
  z = m31*25 + m32*19 + m33*23;

  return [x, y, z];
}

