function countMostOccuringLetter(str) {
	const charCounter = new Map(); // Map to hold character frequency

	for (let char of str) {
		if (charCounter.has(char)) {
			let count = charCounter.get(char);
			charCounter.set(char, ++count);
		} else {
			charCounter.set(char, 1);
		}
	}

	let max = 0, maxChar = '';

	for (const [key, value] of charCounter) {
		if (value > max) {
			max = value;
			maxChar= key;
		}
	}

	return maxChar;
}

