// Binary search (with recursion):

function binarySearch(arr, x, low, high) {
    if (low > high) {
        return -1;
    }

    let mid = Math.floor((low + high) / 2);

    if (arr[mid] === x) {
        return mid;
    } else if (arr[mid] > x) {
        return binarySearch(arr, x, low, mid - 1);
    } else {
        return binarySearch(arr, x, mid + 1, high);
    }
}

