def valid_parentheses_combinations(s): 
    # Base Case 
    if len(s) == 0: 
        return 1 

    # Initialize count 
    count = 0

    # Check for each opening bracket 
    for i in range(len(s)):
        if s[i] == '(':
            # Count the number of closing brackets  
            # with same opening bracket 
            count += ending_brackets(s[i+1:])

    return count

