public ListNode convertToLinkedList(TreeNode root) { 

    // Base case 
    if (root == null) 
        return null; 

    // Initialize result List 
    ListNode result = null; 

    // The main function that flattens a BST into a list 
    flatten(root, result); 

    // returns the root of the 
    //  flattened linked list 
    return result; 
} 

private ListNode flatten(TreeNode root, ListNode list) { 

    // Base cases 
    if (root == null) { 
        return list; 
    } 

    // Step 1. Connect the left and right subtrees 
    list = flatten(root.right, list); 

    // Step 2. Flatten the left subtree 
    list = flatten(root.left, list); 

    // Step 3. Connect sibilings  
    root.right = list; 
    root.left = null; 
    list = root; 

    // return tail of the list 
    return list; 
}

function longestSubstring(str) {
    let maxLength = 0;
    let subStr = '';

    for (let i = 0; i < str.length; i++) {
        let char = str[i];
        let currentLength = 0;
        let seenChars = new Set();

        for (let j = i; j < str.length; j++) {
            currentLength++;
            char = str[j];

            if (seenChars.has(char)) {
                break;
            }

            seenChars.add(char);
        }
        if (currentLength > maxLength) {
            subStr = str.substring(i, i + currentLength);
            maxLength = currentLength;
        }
    }
    return subStr;
}

