    let array = Array(str)
    var maxLen = 0
    var currLen = 0
    var characters = [Character]()

    for char in array {
        if characters.contains(char) {
            if currLen > maxLen {
                maxLen = currLen
            }
            currLen = 0
            characters = [Character]()
        }
        characters.append(char)
