std::string generateRandomKey() {
 std::random_device seed;
 std::mt19937 randomGenerator (seed());
 std::string key (16, '\0');
 for (int i = 0; i < 16; ++i) 
 key[i] = randomGenerator() % 128; 
 return key;
}

std::string encryptXor(std::string plaintext, std::string key) {
 std::string ciphertext (plaintext.length(), '\0');
 for (size_t i = 0; i < plaintext.length(); ++i) 
 ciphertext[i] = plaintext[i] ^ key[i % key.length()];
 return ciphertext;
}

std::string decryptXor(std::string ciphertext, std::string key) {
 std::string plaintext (ciphertext.length(), '\0');
 for (size_t i = 0; i < ciphertext.length(); ++i) 
 plaintext[i] = ciphertext[i] ^ key[i % key.length()];
 return plaintext;
}

int main() {
 std::string plaintext = "this is a secret";

 std::string key = generateRandomKey();
 std::cout << "Key: " << key << std::endl;

 std::string ciphertext = encryptXor(plaintext, key);
 std::cout << "Ciphertext: " << ciphertext << std::endl;

 std::string decryptedPlaintext = decryptXor(ciphertext, key);
 std::cout << "Decrypted plaintext: " << decryptedPlaintext << std::endl;

 return 0;
}

