def merge(left, right):
    l, r = 0, 0
    combined = []
    while l < len(left) and r < len(right):
        if left[l] <= right[r]:
            combined.append(left[l])
            l += 1
        else:
            combined.append(right[r])
            r += 1
    combined += left[l:]
    combined += right[r:]
    return combined

def merge_sort(unsorted):
    if len(unsorted) <= 1:
        return unsorted
    mid = len(unsorted) // 2
    left = unsorted[:mid]
    right = unsorted[mid:]
    left = merge_sort(left)
    right = merge_sort(right)
    return merge(left, right)

