def generate_sql_insert(tablename, schema):
    sql = "INSERT INTO `{}` (".format(tablename)
    for i, field in enumerate(schema):
        sql += field[0]
        if i != len(schema) - 1:
            sql += ', '
    sql += ") VALUES ("
    for i, field in enumerate(schema):
        sql += "?"
        if i != len(schema) - 1:
            sql += ', '
    sql += ");"
