using namespace std; 

// Function to search an item in a sorted array 
int binarySearch(int arr[], int n, int item) 
{ 
    int left = 0; 
    int right = n - 1; 

    while (left <= right) { 
        int mid = left + (right - left) / 2; 
        if (arr[mid] == item) 
            return mid; 
        if (arr[mid] < item) 
            left = mid + 1; 
        else
            right = mid - 1; 
    } 
    return -1; 
} 

// main function 
int main() 
{ 
    int arr[7] = {1, 3, 4, 5, 6, 8, 9}; 
    int item = 5; 

    int index = binarySearch(arr, 7, item); 

    if (index != -1) 
        cout << "Item found at index " << index; 
    else
        cout << "Item not found"; 

    return 0; 
}

