class Node:

    # Constructor to create a new node
    def __init__(self, data):
        self.data = data  
        self.left = None
        self.right = None   

class BST:
    def __init__(self):
        self.root = None

    # A utility function to insert a new node with the given data
    def insert(self, root, data):
        if root is None:
            return Node(data)
        else:
            if data <= root.data:
                new_node = self.insert(root.left, data)
                root.left = new_node
            else:
                new_node = self.insert(root.right, data)
