import "fmt"

func quickSort(arr []int) []int {
	if len(arr) < 2 {
		return arr
	}

	pivot := arr[0]
	left := []int{}
	right := []int{}

	for _, v := range arr[1:] {
		if v <= pivot {
			left = append(left, v)
		} else {
			right = append(right, v)
		}
	}

	left = quickSort(left)
	right = quickSort(right)

	left = append(left, pivot)
	return append(left, right...)
}

func main() {
	arr := []int{5, 8, 7, 10, 2, 1}
	fmt.Println(quickSort(arr)) // [1, 2, 5, 7, 8, 10]
}

