// Function to check if binary tree is binary search tree or not.
const isBST = node => {
    // Empty tree is a BST
    if (node === null) {
        return true;
    }
    // False if this node is less than any of its left sub-trees
    if (node.left !== null && node.value < node.left.value) {
        return false;
    }
    // False if this node is greater than any of its right sub-trees
    if (node.right !== null && node.value > node.right.value) {
        return false;
    }
    // All subtrees must also be BSTs
    if (!isBST(node.left) || !isBST(node.right)) {
        return false;
    }
    // If all the above cases are false, then tree is binary search tree
    return true;
};

