import java.util.HashMap;
import java.util.Map;
import java.util.PriorityQueue;

public class HuffmanTree {

    private class Node implements Comparable<Node> {
        char ch;
        int freq;
        Node left;
        Node right;

        public Node(char ch, int freq, Node left, Node right) {
            this.ch = ch;
            this.freq = freq;
            this.left = left;
            this.right = right;
        }

        // other methods 
    }

    public Map<Character, String> encode(String s) {
        // build frequency map
        Map<Character, Integer> freqMap = new HashMap<>();
        for (char ch : s.toCharArray()) {
            freqMap.put(ch, freqMap.getOrDefault(ch, 0) + 1);
        }

        // build Huffman Tree
        PriorityQueue<Node> priorityQueue = new PriorityQueue<>();
        for (Map.Entry<Character, Integer> entry : freqMap.entrySet()) {
            priorityQueue.add(new Node(entry.getKey(), entry.getValue(), null, null));
        }

        while (priorityQueue.size() != 1) {
            Node left = priorityQueue.poll();
            Node right = priorityQueue.poll();
            int sum = left.freq + right.freq;
            priorityQueue.add(new Node('\0', sum, left, right));
        }

        // build code table
        Map<Character, String> codeTable = new HashMap<>();
        buildCodeTable(priorityQueue.peek(), "", codeTable);

        return codeTable;
    }

    private void buildCodeTable(Node node, String s, Map<Character, String> codeTable) {
        if (node.left == null && node.right == null) {
            codeTable.put(node.ch, s);
            return;
        }

        buildCodeTable(node.left, s + "0", codeTable);
        buildCodeTable(node.right, s + "1", codeTable);
    }    
}

