public class NotificationListener extends BroadcastReceiver {

 private static int mNotificationCount = 0;

 @Override
 public void onReceive(final Context context, Intent intent) {
        String action = intent.getAction();
        if (action != null && action.equals("android.intent.action.BOOT_COMPLETED")) {
            // Read saved notification count when device restarts
            mNotificationCount = context.getSharedPreferences("notification_count", Context.MODE_PRIVATE)
                    .getInt("notification_count", 0);
        }
        if (action != null && action.equals("android.intent.action.ACTION_NOTIFICATION_LISTENER_SERVICE_EXAMPLE")) {
            // Get message from received notification
            String message = intent.getStringExtra("message");
            // Read existing notification count
            int notificationCount = context.getSharedPreferences("notification_count", Context.MODE_PRIVATE)
                    .getInt("notification_count", 0);
            // Increase notification count
            if (message != null) {
                mNotificationCount++;
            }
            // Save notification count
            SharedPreferences.Editor editor = context.getSharedPreferences("notification_count", Context.MODE_PRIVATE).edit();
            editor.putInt("notification_count", mNotificationCount);
            editor.apply();
        }
    }
}

