def bubblesort(arr):  
    # Traverse through the list 
    for i in range(len(arr)): 
        for j in range(len(arr)-i-1):   
            # Swap the elements if the current element 
            # is greater than the next  
            if arr[j] > arr[j+1] : 
                arr[j], arr[j+1] = arr[j+1], arr[j]
    return arr

