def binary_search(array, search_term): 

    low = 0
    high = len(array) - 1

    while low <= high: 

        mid = (low + high) // 2

        if array[mid] < search_term: 
            low = mid + 1

        elif array[mid] > search_term: 
            high = mid - 1

        else: 
            return mid 

    return -1

