def permutations(nums):
    if not nums:
        return [[]]
    else:
        # Saving the first element of the list
        first_el = nums[0]
        # Recursively computing the permutations of the rest of the 
        perms = permutations(nums[1:])
        total_permutations = []
        # Inserting the first element in all the possible positions
        for perm in perms:
            for i in range(len(perm)+1):
                total_permutations.append(perm[:i] + [first_el] + perm[i:])
        return total_permutations

