public class CoinChange {
    public static void main(String[] args) {
        int[] denominations = new int[]{25, 10, 5, 1};
        int amount = 37;
        int[] result = getMinCoins(amount, denominations);
        for(int i = 0; i < result.length; i++) {
            System.out.println(denominations[i] +  " coins: " + result[i]);
        }
    }

    public static int[] getMinCoins(int amount, int[] denominations) {
        int[] result = new int[denominations.length];
        int remaining = amount;
        int index = 0;
        while(remaining > 0 && index < denominations.length) {
            int numCoins = remaining/denominations[index];
            result[index] = numCoins;
            remaining -= numCoins*denominations[index];
            index++;
        }
        return result;
    }

}

