def row_maximum(arr):
    rows = len(arr)
    cols = len(arr[0])

    for row in range(rows):
        row_max = 0

        for col in range(cols):
            row_max = max(row_max, arr[row][col])

        # Set the value of each element in the row to the maximum
        for col in range(cols):
            arr[row][col] = row_max

    return arr

