public class Palindrome {

 public static String longestPalindrome(String s) {
 int n = s.length();
 boolean[][] dp = new boolean[n][n];
 String longestString = "";

 for (int i = 0; i < n; i++) {
  dp[i][i] = true;
  for (int j = i - 1; j >= 0; j--) {
   if (s.charAt(i) == s.charAt(j)) {
    if (i - j == 1 || dp[i - 1][j + 1]) {
     dp[i][j] = true;
     longestString = s.substring(j, i + 1);
    }
   }
  }
 }
 return longestString;
 }

 public static void main(String[] args) {
  String s = "aybabluemadam";
  System.out.println(Palindrome.longestPalindrome(s));
 }
}

struct Node* mergeList(struct Node* head1, struct Node* head2) 
{ 
    if (head1 == NULL) 
        return head2; 

    if (head2 == NULL) 
        return head1; 

    struct Node* mergedList; 
    if (head1->data < head2->data) 
    { 
        mergedList = head1; 
        mergedList->next = mergeList(head1->next, head2); 
    } 
    else 
    { 
        mergedList = head2; 
        mergedList->next = mergeList(head1, head2->next); 
    } 
    return mergedList; 
}

