def roman_to_integer(roman_string):
    M = 1000
    D = 500
    C = 100
    L = 50
    X = 10
    V = 5
    I = 1
    integer_value = 0
    current_numeral_position = 0
    last_numeral_position = 0

    for char in roman_string:
        if char == 'M':
            current_numeral_position = M
        elif char == 'D':
            current_numeral_position = D
        elif char == 'C':
            current_numeral_position = C
        elif char == 'L':
            current_numeral_position = L
        elif char == 'X':
            current_numeral_position = X
        elif char == 'V':
            current_numeral_position = V
        elif char == 'I':
            current_numeral_position = I

        if current_numeral_position > last_numeral_position:
            integer_value += current_numeral_position - 2 * last_numeral_position
        else:
            integer_value += current_numeral_position

        last_numeral_position = current_numeral_position

    return integer_value

