class MagicSquare {
public:
  MagicSquare(int n) {
    this->n = n;
    this->matrix= new int[n * n];
  }

  void generate() {
    int row = 0;
    int col = n / 2;

    matrix[row * n + col] = 1;

    for (int i = 2; i <= n * n; i++) {
      int prevRow = row;
      int prevCol = col;

      row -= 1; 
      col += 1;

      if (row < 0) 
        row = n - 1;

      if (col == n) 
        col = 0; 

      if (matrix[row * n + col] != 0) {
        row = prevRow + 1;
        col = prevCol;
      }

      matrix[row * n + col] = i;
    }
  }

  void display() {
    for (int row = 0; row < n; row++) {
      for (int col = 0;  col < n; col++) 
        cout << matrix[row * n + col] << " ";
      cout << endl;
    }
    cout << endl;
  }

private:
  int *matrix;
  int n;
};

int main() {
