public static boolean isAnagram(String s, String t) {
    // If the string lengths are different, return False.
    if (s.length() != t.length()) {
        return false;
    }

    // Create integers arrays for character counts for both strings
    int[] sCount = new int[26];
    int[] tCount = new int[26];
    for (int i = 0; i < s.length(); i++) {
        sCount[s.charAt(i) - 'a'] += 1;
        tCount[t.charAt(i) - 'a'] += 1;
    }
    // Compare the character count arrays.
    for (int i = 0; i < 26; i++) {
        if (sCount[i] != tCount[i]) {
            return false;
        }
    }
    return true;
}

def evaluate_expression(expression):
    # convert the expression into a list of tokens
    tokens = expression.split(' ')
    # perform the operations in the expression and store the result
    result = 0
    # perform the first operation
    if tokens[1] == '+':
        result = int(tokens[0]) + int(tokens[2])
    elif tokens[1] == '-':
        result = int(tokens[0]) - int(tokens[2])
    elif tokens[1] == '*':
        result = int(tokens[0]) * int(tokens[2])
    elif tokens[1] == '/':
        result = int(tokens[0]) / int(tokens[2])
    # perform the second operation
    if tokens[3] == '+':
        result += int(tokens[4])
    elif tokens[3] == '-':
        result -= int(tokens[4])
    elif tokens[3] == '*':
        result *= int(tokens[4])
    elif tokens[3] == '/':
        result /= int(tokens[4])    

    return result

