void generateUniqueCombos(char s[], int k) 
{
     int i;
     if (k == strlen(s)) 
     {
         printf("%s \n", s);
     } 
     else
     {
         for (i = k; i < strlen(s); i++)
         {
             char temp = s[k];
             s[k] = s[i];
             s[i] = temp;

             generateUniqueCombos(s, k + 1);

             temp = s[k];
             s[k] = s[i];
             s[i] = temp; 
         }
    }
}

