def bubbleSort(arr): 
    # Get size of array
    n = len(arr) 

    # Iterate through array
    for i in range(n): 

        # Last i elements are already in place
        for j in range(0, n-i-1): 

            # Swap if greater
            if arr[j] > arr[j+1] : 
                arr[j], arr[j+1] = arr[j+1], arr[j] 

    # Return sorted array
    return arr

