    private HandlerThread mBackgroundThread;

    private final CameraDevice.StateCallback mStateCallback = new CameraDevice.StateCallback() {

        @Override
        public void onOpened(CameraDevice cameraDevice) {
            mCameraDevice = cameraDevice;
            createCameraSession();
        }

        @Override
        public void onError(CameraDevice cameraDevice, int error) {
        }

        @Override
        public void onDisconnected(CameraDevice cameraDevice) {
            mCameraDevice.close();
        }
    };

    // Methods to set up the camera
    private void createCameraSession() {
        mImageReader = ImageReader.newInstance(1080, 1920, ImageFormat.JPEG, 2);
        // Create capture request
        mCaptureRequestBuilder = mCameraDevice.createCaptureRequest(CameraDevice.TEMPLATE_PREVIEW);
        // Set the output
        mCaptureRequestBuilder.addTarget(mImageReader.getSurface());

        // Create a frame handler to capture image data
        mImageReader.setOnImageAvailableListener(
            new ImageReader.OnImageAvailableListener() {
                @Override
                public void onImageAvailable(final ImageReader reader) {
                    Image image = reader.acquireLatestImage();
                    // Create byte array from image
                    if (image == null) {
                        return;
                    }
                    ByteBuffer buffer = image.getPlanes()[0].getBuffer();
                    byte[] bytes = new byte[buffer.remaining()];
                    buffer.get(bytes);
                    // Detect objects in the image
                    runObjectDetection(bytes);
                    image.close();
                }
            }, 
            mBackgroundHandler
        );

        // Request capture session from camera
        mCameraDevice.createCaptureSession(
            Arrays.asList(mImageReader.getSurface()),
            new CameraCaptureSession.StateCallback() {

                @Override
                public void onConfigured(CameraCaptureSession session) {
                    mCameraSession = session;
                    // Start camera
                    startCapture();
                }

                @Override
                public void onConfigureFailed(CameraCaptureSession session) {
                }
            },
            mBackgroundHandler
        );
    }

    private void startCapture() {
        try {
            // Start capture session
            mCameraSession.setRepeatingRequest(
                mCaptureRequestBuilder.build(),
                null,
                mBackgroundHandler
            );
        } catch (CameraAccessException e) {
        }
    }

    // Method that calls object-detection algorithm 
