public class EmailInboxProcessor {

 // Process the inbox and filter out all incoming spam messages
 public void processInbox(String username, String password) {
  List<Message> messages = new ArrayList<>();

  // Connect to the mailbox
  Store store = connect(username, password);

  // Get inbox folder
  Folder folder = store.getFolder("INBOX");

  // Open folder
  if (!folder.isOpen()) {
   folder.open(Folder.READ_WRITE);
  }

  // Get all messages in inbox
  messages = Arrays.asList(folder.getMessages());

  // Process each message to identify spam
  for (Message message : messages) {
   if (isSpam(message)) {
