    public static boolean isArmstrong(int num) { 
        int n = num;
        int sum = 0;
        while (n > 0) { 
            int digit = n % 10;
            sum += Math.pow(digit, 3);
            n /= 10;
        } 
        if (sum == num) {
            return true;
        } 
        else {
            return false;
        }
