def is_magic_square(mat):
    sum_diag_1 = 0
    sum_diag_2 = 0
    # check if all the rows, columns and diagonals have the same sum
    sum_all = sum(mat[0])
    # check if all the rows have the same sum
    for row in mat:
        if sum(row) != sum_all:
            return False
    # check if all the columns have the same sum 
    for col in range(3):
        col_sum = 0
        for row in range(3):
            col_sum += mat[row][col]
        if col_sum != sum_all:
            return False
    # check if the first diagonal has the same sum
    for row in range(3):
        sum_diag_1 += mat[row][row]
    if sum_diag_1 != sum_all:
        return False 
    # check if the second diagonal has the same sum
    j = 2
    for row in range(3):
        sum_diag_2 += mat[row][j]
        j -=1
    if sum_diag_2 != sum_all:
        return False
    # if all checks are passed the matrix is a magic square
    return True

