use std::cmp::min;

fn levenshtein_distance(word1:&String, word2:&String) -> u32 {
    let word1_len = word1.len();
    let word2_len = word2.len();

    // If either word is empty, the Levenshtein distance is the length of the other word
    if word1_len == 0 {
        return word2_len;
    } else if word2_len == 0 {
        return word1_len;
    }

    let mut distances = vec![vec![0; word2_len + 1]; word1_len + 1];

    for (i, c1) in word1.chars().enumerate() {
        distances[i + 1][0] = i + 1;
    }

    for (j, c2) in word2.chars().enumerate() {
        distances[0][j + 1] = j + 1;
    }

    for (i, c1) in word1.chars().enumerate() {
        for (j, c2) in word2.chars().enumerate() {
            let substitution_cost = if c1 == c2 { 0 } else { 1 };

            distances[i + 1][j + 1] = min(
                distances[i][j + 1] + 1,               // A deletion
                distances[i + 1][j] + 1,               // An insertion
                distances[i][j] + substitution_cost,    // A substitution
            );
        }
    }

    distances[word1_len][word2_len]
}

fn main() {
    let word1 = String::from("cat");
    let word2 = String::from("dog");
    let distance = levenshtein_distance(&word1, &word2);
    println!("The Levenshtein distance between {} and {} is {}", word1, word2, distance);
}

