public class BubbleSort {
    public static void sort(int[] arr) {
        int n = arr.length;
        for (int i = 0; i < n-1; i++) {
            for (int j = 0; j < n-i-1; j++) {
                if (arr[j] > arr[j+1]) {
                    // swap elements
                    int temp = arr[j];
                    arr[j] = arr[j+1];
                    arr[j+1] = temp;
                }
            }
        }
    }

    public static void main(String[] args) {
        int[] arr = {3, 5, 2, 4};

        // Before sort
        System.out.println("Before sort:");
        for (int element : arr) {
            System.out.print(element + " ");
        }
        System.out.println();

        // After sort
        sort(arr);
        System.out.println("After sort");
        for (int element : arr) {
            System.out.print(element + " ");
        }
    }
}

