def sort_rule(a, b):
    # if the first character of a is larger than the first character of b, then a should come before b
    if a[0] > b[0]:
        return -1
    # if the first character of a is smaller than the first character of b, then b should come before a
    elif a[0] < b[0]:
        return 1
    # if the first character of both strings are equal, 
    # then compare the second character onwards until the end of one of the strings
    else:
        i = 1
        # compare one character at a time
        while i < len(a) and i < len(b):
            if a[i] > b[i]:
                return -1
            elif a[i] < b[i]:
                return 1
            else:
                i += 1
        # if one string runs out of characters, the shorter string should come before the longer string
        if len(a) - i <= len(b):
            return -1
        else:
            return 1

