public class BST
{
    public Node AddNode(Node root, int key)
    {
        if (root == null)
            return new Node(key);

        if (key < root.data)
            root.left = AddNode(root.left, key);
        else if (key > root.data)
            root.right = AddNode(root.right, key);

        return root;
    }
}

def find_element(arr, key):
    low = 0
    high = len(arr) - 1
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == key:
            return mid
        elif arr[low] <= arr[mid]:
            if key >= arr[low] and key < arr[mid]:
                high = mid - 1
            else:
                low = mid + 1
        else:
            if key > arr[mid] and key <= arr[high]:
                low = mid + 1
            else:
                high = mid - 1
    return -1

