public class ONSort { 

    // A O(n) program to sort an array  
    public int[] sortArray(int arr[]) 
    { 
        int n = arr.length; 

        // Find maximum and minimum in arr[] 
        int max = arr[0], min = arr[0]; 
        for (int i = 1; i < n; i++) { 
            if (arr[i] > max) 
                max = arr[i]; 
            if (arr[i] < min) 
                min = arr[i]; 
        } 

        // Create an auxiliary array dom[] to  
        // count frequencies of elements 
        int dom[] = new int[max - min + 1]; 

        // add 1 to dom array for every element in arr[] 
        for (int i = 0; i < n; i++) 
            dom[arr[i] - min]++; 

        // Store cummulative occurrences of the values in 
        // dom array in sorted order. 
        for (int i = 1; i < max - min + 1; i++) 
            dom[i] += dom[i - 1]; 

        // Store elements in sorted order 
        int sortedArr[] = new int[n]; 
        for (int i = n - 1; i >= 0; i--) { 
            sortedArr[dom[arr[i] - min] - 1] = arr[i]; 
            dom[arr[i] - min]--; 
        } 

        // Return the sorted array 
        return sortedArr; 
    } 
}

