def operations_to_convert_words(word1, word2):
    # Start with the first word
    curr_state = word1

    # Initialize operations to an empty array
    operations = []

    # Loop until the current state is equal to the second word
    while curr_state != word2:

        # Find the index of the first different character
        inequality_index = find_mismatch(curr_state, word2)

        # Work out which operation to perform
        operation, result = get_op_and_res(curr_state, word2, inequality_index)

        # Add the operation to the array
        operations.append(operation)

        # Update the current state
        curr_state = result

    # Return the list of operations
    return operations

def find_mismatch(word1, word2):
    # Loop over the characters and find the index at which the characters don't match
    for i in range(len(word1)):
        if word1[i] != word2[i]:
            return i

def get_op_and_res(word1, word2, i):
    # Return the operation and result corresponding to the characters at the given index
    if word1[i] == '_':
        return ('add', word1[:i] + word2[i] + word1[i+1:])
    elif word2[i] == '_':
        return ('remove', word1[:i] + word1[i+1:])
    else:
        return ('replace', word1[:i] + word2[i] + word1[i+1:])

