contract Crowdfund {
  address public manager;
  uint256 public goal;
  uint256 public totalRaised;
  mapping(address => uint256) public balances;
  mapping(address => bool) public payers;
  event GoalReached(address _beneficiary, uint256 _amountRaised);
  event FundTransfer(address _from, address _to, uint256 _amount);

  constructor() public { 
  manager = msg.sender;
  }

  modifier onlyManager() { 
  require(msg.sender == manager, "You must be the manager to perform this action."); 
  _; 
  }

  function setGoal(uint256 _goal) public onlyManager {
  goal = _goal;
  }

  function donate() public payable {
  require(msg.value > 0, "You must donate a positive amount.");
  balances[msg.sender] += msg.value;
  payers[msg.sender] = true;
  totalRaised += msg.value;
  emit FundTransfer(0x0, msg.sender, msg.value);
  if(totalRaised > goal) {
  emit GoalReached(manager, totalRaised);
  }
  }

  function withdraw() public onlyManager {
  require(totalRaised > goal, "Goal must be reached first.");
  manager.transfer(this.balance);
  }

  function refund() public {
  uint256 amount = balances[msg.sender];
  balances[msg.sender] = 0;
  payers[msg.sender] = false;
  totalRaised -= amount;
  msg.sender.transfer(amount);
  }

  function getDonations() public view returns (bool isDonor, uint256 amount) {
  return (payers[msg.sender], balances[msg.sender]);
  }

}

