function convertNumberToWords(num) {
 let words = [];
 let digits = ["", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine"];
 let units = ["", "thousand", "million", "billion"];
 let extraUnits = ["", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen",
"eighteen", "nineteen"];
 let tens = ["", "ten", "twenty", "thirty", "fourty", "fifty", "sixty", "seventy", "eighty", "ninety"];

 // get each three-digit block
 let numS = num.toString();
 let blocks = Math.ceil(numS.length / 3);
 for (let i = 0; i < blocks; i++) {
  let start = numS.length - 3 * (i + 1);
  let block = numS.substring(start, start + 3);
  let ws = "";

  // get each digit within the block
  let d = parseInt(block[2]);
  let t = parseInt(block[1]);
  let h = parseInt(block[0]);

  // convert
  if (t == 1) {
   ws += extraUnits[d] + " ";
  } else {
   ws += digits[d] + " ";
   ws += tens[t] + " ";
  }
  if (h > 0) ws += digits[h] + " hundred ";

  // append units
  if (ws) {
   ws += units[i] + " ";
   words.unshift(ws);
  }
 }

 return words.join('');
}

