def calculate_roots(a, b, c):
    d = (b**2) - (4*a*c)

    if d < 0:
        return None
    elif d == 0: 
        return -b/(2*a), -b/(2*a)
    else:
        x1 = (-b + (d**0.5))/(2*a) 
        x2 = (-b - (d**0.5))/(2*a)
        return x1, x2

