def products_except_self(nums):
    length = len(nums)
    left = [1] * length
    right = [1] * length
    for i in range(1, length):
        left[i] = left[i-1] * nums[i-1]
    for i in reversed(range(length-1)):
        right[i] = right[i+1] * nums[i+1]
    output = []
    for i in range(length):
        output.append(left[i] * right[i])
    return output

