  else
   median = (double)numbers.get(numbers.size()/2); 
  System.out.println("Median: " + median); 
  // Standard Deviation 
  double temp = 0; 
  for(double num:numbers) 
   temp += (num-mean)*(num-mean); 
  double variance = temp/numbers.size(); 
  double std_dev = Math.sqrt(variance); 
  System.out.println("Standard Deviation: " + std_dev);  
