import java.util.HashMap;
import java.util.Map;
import java.util.Arrays;
import java.util.stream.Collectors;

public class WordFrequency {

    public static void main(String[] args) {
        String text = "This is a sample text with some words repeated";

        Map<String, Integer> wordFrequency = getWordFrequency(text);
        Map<String, Integer> topTenWords = getTopTenWords(wordFrequency);

        System.out.println("Top 10 most frequent words are:");
        topTenWords.forEach((word, frequency) -> System.out.println(word + ": " + frequency));
    }

    public static Map<String, Integer> getWordFrequency(String text) {
        String[] words = text.split("\\s+");

        Map<String, Integer> wordFrequency = Arrays.stream(words)
                                                  .collect(Collectors.toMap(word -> word, word -> 1, Integer::sum));
        return wordFrequency;
    }

    public static Map<String, Integer> getTopTenWords(Map<String, Integer> wordFrequency) {
        Map<String, Integer> topTenWords = new HashMap<>();

        wordFrequency.entrySet().stream()
                                .sorted(Map.Entry.<String, Integer>comparingByValue().reversed())
                                .limit(10)
                                .forEach(entry -> topTenWords.put(entry.getKey(), entry.getValue()));
        return topTenWords;
    }
}

