class Node { 
    int data; 
    Node next; 
}; 

class LinkedList { 
    Node head;  // head of list 

    /* Function to detect loop in the linked list */
    int detectLoop() 
    { 
        Node slow_p = head, fast_p = head; 
        while (slow_p != null && fast_p != null && fast_p.next != null) { 
            slow_p = slow_p.next; 
            fast_p = fast_p.next.next; 
            if (slow_p == fast_p) { 
                return 1; 
            } 
        } 
        return 0; 
    } 
};

def convert_to_rpn(exp):
    operators = set(['+', '-', '*', '/'])
    exp_list = []
    buffer = ""
    for char in exp:
        if char in operators:
            if buffer:
                exp_list.append(buffer)
                buffer = ""
            exp_list.append(char)
        else:
            buffer += char
        if len(exp_list) > 1 and exp_list[-1] in operators and exp_list[-2] in operators:
            exp_list[-3:], reduce_sum = exp_list[-3:], ""
            for i in range(len(exp_list)-2, len(exp_list)):
                reduce_sum += exp_list[i]
            exp_list = exp_list[:-3]
            exp_list.append(reduce_sum)
        if buffer:
            exp_list.append(buffer)
    return exp_list

