public static char mostFrequent(String str) 
{ 
    int len = str.length(); 

    // Initialize max frequency character 
    int maxCount = 0; 
    char maxChar = ' '; 

    // Count frequency of each character 
    for (int i=0; i<len; i++) 
    { 
        int currCount = 0; 

        for (int j=0; j<len; j++) 
        { 
            if (str.charAt(i) == str.charAt(j)) 
                currCount++; 
        } 

        // If current character's count is more 
        // than maxcount, then update maxcount 
        if (currCount > maxCount) 
        { 
            maxCount = currCount; 
            maxChar = str.charAt(i); 
        } 
    } 

    return maxChar; 
}

