def binary_search(arr, x):
    begin = 0
    end = len(arr) - 1
    while begin<=end:
        mid = (begin + end) // 2
        if x == arr[mid]:
            return mid
        elif x < arr[mid]:
            end = mid - 1
        else:
            begin = mid + 1
    return -1

