double stddev(int n, double x[]) {
    double mean=0.0, sum_deviation=0.0;
    int i;
    for(i=0; i<n;++i) {
        mean+=x[i];
    }
    mean=mean/n;
    for(i=0; i<n;++i)
        sum_deviation+=(x[i]-mean)*(x[i]-mean);
