def get_predecessor(node):
    # if the node has a left subtree, the predecessor node is the rightmost leaf in the left subtree
    if node.left is not None:
        current_node = node.left
        while current_node.right is not None:
            current_node = current_node.right
        return current_node
    # if the node does not have a left subtree, traverse the tree upwards to find the nearest ancestor that is smaller than the current node
    else:
        current_node = node
        ancestor = current_node.parent
        while ancestor is not None and ancestor.val < current_node.val:
            ancestor = ancestor.parent
        return ancestor

