def selection_sort(arr):
    for i in range(len(arr) - 1):
        min_indice = i
        for j in range(i + 1, len(arr)):
            if arr[j] < arr[min_indice]:
                min_indice = j
        arr[min_indice], arr[i] = arr[i], arr[min_indice]
    return arr

