public static void insertionSort(int[] array) {
    for(int i = 1; i < array.length; i++) {
        int cur = array[i];
        int j = i-1;
        while(j > -1 && array[j] > cur) {
            array[j+1] = array[j];
            j--;
        }
        array[j+1] = cur;
    }
}

