class Stack:
    def __init__(self):
        self.items = []
        self. minvalue = None

    def push(self, item):
        self.items.append(item)
        if self.minvalue is None or item < self.minvalue:
            self.minvalue = item

    def pop(self):
        item = self.items.pop()
        if self.minvalue == item:
            if len(self.items) > 0:
                self.minvalue = min(self.items)
            else:
                self.minvalue = None
        return item

def depth_first_search(tree, node):
    if tree == None:
        return False
    elif tree.data == node:
        return True
    else:
        left_search = depth_first_search(tree.left, node)
        if left_search == True:
            return True
        right_search = depth_first_search(tree.right, node)
        return right_search

