class MeanMedianMode {
    constructor(numbers) {
        this.numbers = numbers;
    }

    getMean() {
        const total = this.numbers.reduce((sum, number) => { 
            return sum + number;
        }, 0);
        return total / this.numbers.length;
    }

    getMedian() {
        const sortedNums = this.numbers.sort();
        if (sortedNums.length % 2 === 0) {
            const midIndex1 = (sortedNums.length / 2) - 1;
            const midIndex2 = midIndex1 + 1;
            return (sortedNums[midIndex1] + sortedNums[midIndex2]) / 2;
        } else {
            return sortedNums[Math.floor(sortedNums.length / 2)];
        }
    }

    getMode() {
        const modeObj = {};
        let highestNum = 0, highestFreq = 0;
        this.numbers.forEach((number) => {
            if (!modeObj[number]) modeObj[number] = 0;
            modeObj[number]++;
            if (modeObj[number] > highestFreq) {
                highestNum = number;
                highestFreq = modeObj[number];
            }
        });
        return highestNum;
	}
}

