def calculate_levenshtein_distance(string1, string2):
    row = len(string1) + 1
    col = len(string2) + 1

    distance = [[0 for x in range(col)] for x in range(row)]

    # Build up the distance matrix
    for i in range(row):
        for j in range(col):
            if i == 0:
                distance[i][j] = j
            elif j == 0:
                distance[i][j] = i
            else:
                if string1[i-1] == string2[j-1]:
                    cost = 0
                else:
                    cost = 1
                distance[i][j] = min(distance[i-1][j] + 1, 
                                     distance[i][j-1] + 1, 
                                     distance[i-1][j-1] + cost)

    return distance[row-1][col-1]

