def plan_route(start, goal): 
    graph = {
        'A': ['B', 'C'],
        'B': ['D'],
        'C': ['D', 'E'],
        'D': ['F'],
        'E': ['G'],
        'F': ['G']
    }

    fringe = []
    fringe.append([start]) 

    while len(fringe) > 0: 
        path = fringe.pop(0) 
        node = path[-1] 
        if node == goal: 
            return path 
        else: 
            for neighbour in graph[node]: 
                newPath = list(path) 
                newPath.append(neighbour)
                fringe.append(newPath)

    return None 

