function evaluateExpression(expression) {
    let tokens = expression.split(' ');
    let stack = [];

    let i = 0;
    while (i < tokens.length) {
        let token = tokens[i];
        if (isOperand(token)) {
            stack.push(token);
        }
        else {
            let a = stack[stack.length - 2];
            let b = stack.pop();
            let c = stack.pop();
            stack.push(eval(a + token + b));
        }
        i++;
    }
    return stack.pop();
}

