    let mut frequency = 0;
    let mut max_val = 0;
    let mut counter = std::collections::HashMap::new();
    for num in arr.iter() {
        let count = counter.entry(num).or_insert(0);
        *count += 1;
        if *count > frequency {
            frequency = *count;
            max_val = *num;
        }
    }
