def create_binary_tree(words):
    # Create a root node
    rootNode = Node(None, None, None)

    # Loop through all words
    for word in words:
        currNode = rootNode
        for ch in word:
            # Check if character already exist in the tree
            index = searchNode(currNode.children, ch)

            # If yes, continue from that node
            if index != -1:
                currNode = currNode.children[index]
            # If no, create a new node and continue
            else:
                newNode = Node(ch, None, None)
                currNode.children.append(newNode)
                currNode = newNode

    return rootNode

