  if (ActivityCompat.checkSelfPermission(this, Manifest.permission.ACCESS_COARSE_LOCATION)
   != PackageManager.PERMISSION_GRANTED) {
   ActivityCompat.requestPermissions(this, new String[]{Manifest.permission.ACCESS_COARSE_LOCATION}, 1);
  } else {
   fetchWeatherData();
  }
 }

 @Override
 public void onRequestPermissionsResult(int requestCode, @NonNull String[] permissions, @NonNull int[] grantResults) {
  if (requestCode == 1 && grantResults.length > 0 && grantResults[0] == PackageManager.PERMISSION_GRANTED)
   fetchWeatherData();
 }

 private void fetchWeatherData() {
  // Initialize the GetWeatherTask
  GetWeatherTask getWeatherTask = new GetWeatherTask();
  getWeatherTask.execute(this, temperatureTextView);
 }
}

class GetWeatherTask extends AsyncTask<Object, Void, String> {

 private Activity activity;
 private TextView textView;

 @Override
 protected String doInBackground(Object... objects) {
  activity = (Activity) objects[0];
  textView = (TextView) objects[1];

  // Get user's current location
  LocationManager locationManager = (LocationManager) activity.getSystemService(Context.LOCATION_SERVICE);
  Location location = locationManager.getLastKnownLocation(LocationManager.PASSIVE_PROVIDER);
  if (location != null) {
   // Request weather data from OpenWeatherMap
   String urlString = "http://api.openweathermap.org/data/2.5/weather?lat="
    + location.getLatitude() + "&lon=" + location.getLongitude() + "&appid=YOUR_API_KEY";

   URL url;
   int responseCode = 0;

   // Send GET request
   try {
    url = new URL(urlString);
    HttpURLConnection httpURLConnection = (HttpURLConnection) url.openConnection();
    httpURLConnection.setRequestMethod("GET");
    httpURLConnection.connect();

    responseCode = httpURLConnection.getResponseCode();
    if (responseCode == 200) {
     // Parsing the response
     String responseString = StreamUtils.convertToString(httpURLConnection.getInputStream());
     JSONObject responseJson = new JSONObject(responseString);

     // Get temperature from response
     JSONObject main = responseJson.getJSONObject("main");
     int temperature = main.getInt("temp") - 273; // convert kelvin to celsius

     // Return temperature in string format
     return temperature + "°C";
    }
   } catch (IOException | JSONException e) {
    e.printStackTrace();
   }
  }

  return null;
 }

 @Override
 protected void onPostExecute(String temperature) {
  // Set the temperature in the TextView
  textView.setText(temperature);
 }
}

