#define SIZE 100

typedef struct dict{
    char *key;
    int value;
}dict;

dict *hashtable[SIZE];

unsigned long hash(char *key){ 
    unsigned long hash = 5381; 
    while (*key){ 
        hash += (hash << 5) + (*key++); 
    } 
    return hash % SIZE; 
} 

void insert(char *key, int value) 
{ 
    unsigned long hashValue = hash(key); 
     dict *entry = (dict *)malloc(sizeof(dict)); 
    entry->key = key;
    entry->value = value; 
    hashtable[hashValue] = entry; 
} 

int getValue(char *key){ 
    unsigned long hashValue = hash(key); 
    dict *entry = hashtable[hashValue]; 
    if (entry == NULL) 
        return -1;
    else
        return entry->value; 
}

def merge_sorted_lists(list1, list2):
    merged_list = []

    while list1 and list2:
        if list1[0] < list2[0]:
            merged_list.append(list1.pop(0))
        else:
            merged_list.append(list2.pop(0))

    merged_list += list1 + list2

    return merged_list

