public int run(int[] A) {
    int N = A.length;
    int leader = -1;

    // Keep track of the counts of each element
    Map<Integer, Integer> map = new HashMap<>();
    for (int num : A) {
        int count = map.getOrDefault(num, 0) + 1;

        // Update the leader if we find one
        if (count > N/2) leader = num;

        // Store counts
        map.put(num, count);
    }

    return leader;
}

