// Function to print Fibonacci series
void printFibonacciSeries(int limit) 
{ 
	// Initializing starting point of the series 
	int a = 0, b = 1; 

	// Printing 0 and 1 
	printf("%d, %d, ", a, b); 

	for (int i = 0; i < limit; ++i) 
	{ 
		// Fibonacci number is sum of previous two numbers 
		int c = a + b; 
		printf("%d, ", c); 

		a = b; 
		b = c; 
	} 
} 

