long long fibonacci(int n) {
    long long f1 = 0;
    long long f2 = 1;
    long long f = 0;
    if (n == 0) return 0;
    if (n == 1) return 1;
    for (int i=2; i <= n; i++) {
        f = f1 + f2;
        f1 = f2;
        f2 = f;
    }
    return f;
