int main(){
 	double a[N][N] = { {1, 2, 3}, {1, 2, 3}, {1, 2, 3} };
 	double b[N][N] = { {1, 2, 3}, {1, 2, 3}, {1, 2, 3} };
 	double c[N][N];

 	/* Initialize the matrix */

	int i, j, k;
	for (i=0; i<N; i++){
		for (j=0; j<N; j++){
			c[i][j] = 0.0;
 		}
	}

 	/* Multiply two matrices with OpenMP */
 	omp_set_num_threads(8);
 	#pragma omp parallel for shared(a, b, c) private(i, j, k)
	for (i=0; i<N; i++) {
		for (j=0; j<N; j++) {
			for (k=0; k<N; k++) {
				c[i][j] += a[i][k] * b[k][j];
			}
		}
	}

	/* Print matrix C */
	for (i=0; i<N; i++){
		for (j=0; j<N; j++){
