function optimizeEvenSum(arr) {
  let evens = arr.filter(e => e % 2 === 0);
  let odds = arr.filter(o => o % 2 === 1);

  let optimizedEvenSum = 0;

  evens.sort().reverse().forEach((item, i) => {
    optimizedEvenSum += item * Math.pow(2, i);
  });

  odds.sort().reverse().forEach((item, i) => {
    optimizedEvenSum += item * Math.pow(2, i + evens.length);
  });

  return optimizedEvenSum;
}

