    public static int toDecimal(int binaryNumber){
        int decimalNumber = 0;
        int multiplier = 1;

        while(binaryNumber > 0){
            if(binaryNumber % 10 == 1){
                decimalNumber += multiplier;
            }
            multiplier *= 2;
            binaryNumber /= 10;
        }

        return decimalNumber;
    }

