def count_unique_words(sentence):
    # Create hashmap to store words
    word_map = {}
    # Split the string on whitespace
    words = sentence.split(' ')
    # Iterate over all the words
    for word in words:
        if word not in word_map:
            word_map[word] = 1
        else:
            word_map[word] += 1
    # Calculate number of unique words
