function greatestCommonDivisor(num1, num2) {
    let divisor = 2;
    let greatestDivisor = 1;

    while(num1 >= divisor && num2 >= divisor) {
        if(num1 % divisor == 0 && num2 % divisor == 0) {
            greatestDivisor = divisor;
        }
        divisor++;
    }

    return greatestDivisor;
}

