function daysInMonth(month, year) {
    // Create a new Date object and set it to the first of the month
    let date = new Date(year, month, 1);

    // Get the next month
    let nextMonth = month + 1;

    // Create a new Date object and set it to the first of the next month
    let nextMonthFirstDay = new Date(year, nextMonth, 1);

    // Subtract the two and set it to milliseconds
    let numDays = (nextMonthFirstDay - date) / (1000 * 60 * 60 * 24);

    return numDays;
}

