function maxSubarraySum(array, K) {
 let currentSum = 0;
 let maxSum = 0;

 // Calculte the sum of first 'K' elements
 for (let i = 0; i < K; i++) {
 currentSum += array[i];
 }

 // Slide the subarray and update the maxSum
 for (let i = K; i < array.length; i++) {
 currentSum += array[i] - array[i - K];
 maxSum = Math.max(maxSum, currentSum);
 }

 return maxSum;
}

