public class LinkedList { 
    Node head; 

    class Node { 
        int data; 
        Node next; 

        Node(int d) { 
            data = d; 
            next = null; 
        } 
    }    

    // Appends a new node within the linked list
    public void append(int new_data) 
    { 
        Node new_node = new Node(new_data); 

        if (head == null) { 
            head = new Node(new_data); 
            return; 
        } 

        new_node.next = null; 

        Node last = head;  
        while (last.next != null) 
            last = last.next; 

        last.next = new_node; 
        return; 
    }

    // Prints the linked list
    public void printList() 
    { 
        Node n = head; 
        while (n != null) { 
            System.out.print(n.data + " "); 
            n = n.next; 
        } 
    } 

    public static void main(String[] args) 
    { 
        LinkedList list = new LinkedList(); 

        list.append(1);
        list.append(2);
        list.append(3);

        list.printList(); 
    } 
}

