class MaxMinStack:
    def __init__(self): 
        self.stack = []
        self.minMaxStack = []

    def peek(self): 
        return self.stack[-1]

    def pop(self):
        self.minMaxStack.pop()
        return self.stack.pop()

    def push(self, data): 
        self.stack.append(data) 
        if len(self.minMaxStack): 
            if data > self.minMaxStack[-1][1]: 
                self.minMaxStack.append([data, data]) 
            else: 
                self.minMaxStack.append([self.minMaxStack[-1][0], data]) 
        else: 
            self.minMaxStack.append([data, data])

    def getMinMaxElement(self): 
        return self.minMaxStack[-1]

