class Node {
 constructor(val) {
 this.val = val;
 this.left = this.right = null;
 }
}

class BinarySearchTree {
 constructor() {
 this.root = null;
 }

 insert(val) {
 if (!this.root) {
 this.root = new Node(val);
 return;
 }

 let current = this.root;
 while (true) {
 if (val > current.val) {
 if (current.right) {
 current = current.right;
 }
 else {
 current.right = new Node(val);
 break;
 }
 }
 else {
 if (current.left) {
 current = current.left;
 }
 else {
 current.left = new Node(val);
 break;
 }
 }
 }
 }

 delete(val) {
 let parent = null;
 let current = this.root;
 while(current) {
 if (val > current.val) {
 parent = current;
 current = current.right;
 }
 else if (val < current.val) {
 parent = current;
 current = current.left;
 }
 else {
 if (current.left && current.right) {
 const replacementNode = current.right;
 let parent = current;
 while (replacementNode.left) {
 parent = replacementNode;
 replacementNode = replacementNode.left;
 }
 current.val = replacementNode.val;
 parent.left = null;
 }
 else if (!parent) {
 if (current.left) {
 this.root = current.left;
 }
 else {
 this.root = current.right;
 }
 }
 else if (parent.left === current) {
 parent.left = current.left || current.right;
 }
 else {
 parent.right = current.left || current.right;
 }
 break;
 }
 }
 }

 search(val) {
 let current = this.root;
 while (current) {
 if (val > current.val) {
 current = current.right;
 }
 else if (val < current.val) {
 current = current.left;
 }
 else {
 break;
 }
 }
 return current !== null;
 }
}

