// Geometry shader
#version 330

uniform mat4 view;
uniform float Frame;

layout(triangles) in;
layout(triangle_strip, max_vertices=18) out;

in vec4 v_color[];
out vec4 f_color;

void main() {
 vec4 P[3];
 vec4 center = vec4(0,0,0,1);

 for( int i = 0; i < 3; i++ )
  {
   P[i] = gl_in[i].gl_Position;
   center += P[i];
  }
 center /= 3.0;

 if( Frame == 0.0 )
  {
   for( int i = 0; i < 3; i++ )
    {
     gl_Position = gl_in[i].gl_Position;
     f_color = v_color[i];
     EmitVertex();
    }
   EndPrimitive();
  }
 else
  {
   mat4 rotation;
   rotation[0] = vec4( cos(Frame), 0.0, sin(Frame), 0.0 );
   rotation[1] = vec4( 0.0, 1.0, 0.0, 0.0 );
   rotation[2] = vec4( -sin(Frame), 0.0, cos(Frame), 0.0 );
   rotation[3] = vec4( 0.0, 0.0, 0.0, 1.0 );

   for( int i = 0; i < 3; i++ )
    {
     gl_Position = projection * view * ( P[i] - center ) * rotation + center;
     f_color = v_color[i];
     EmitVertex();
    }
   EndPrimitive();
  }
}

