binomial_coefficient <- function(n, k){

    #Calculate the factorial of n
    n_factorial <- 1
    for (x in 1:n){
        n_factorial <- n_factorial * x
    }

    #Calculate the factorial of k
    k_factorial <- 1
    for (x in 1:k){
        k_factorial <- k_factorial * x
    }

    #Calculate the factorial of (n-k)
    nk_factorial <- 1
    for (x in 1:(n-k)){
        nk_factorial <- nk_factorial * x
    }

    #Calculate the binomial coefficient
    binomial_coefficient <- n_factorial/(k_factorial*nk_factorial)
    return(binomial_coefficient)
}

def maze_solving(maze):
    # define directions 
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    # initialize queue
    queue = []
    queue.append([(0, 0)])

    while queue:
        current_path = queue.pop(0)

        # get current coordinate
        current_location = current_path[-1]

        # check if it is the goal
        if maze[current_location[0]][current_location[1]] == 2:
            break
        else:
            # search all possible neighors
            for neighbor in directions:
                # if neighbor is valid
                next_location = (current_location[0] + neighbor[0], current_location[1] + neighbor[1])
                if next_location[0] in range(len(maze)):
                    if next_location[1] in range(len(maze[0])):
                        if maze[next_location[0]][next_location[1]] != 0:
                            # generate new path
                            new_path = current_path + [next_location]
                            queue.append(new_path)

    # return final path if maze is solvable
    return current_path

