def count_paths(n):
    # Variables initialiaztion
    result = [[0 for x in range(n+1)] for y in range(n+1)]

    # Base cases 
    for i in range(n+1):
        result[0][i] = 1
        result[i][0] = 1

    # Loop through the matrix to calclulate the number of paths
    for i in range(1, n+1):
        for j in range(1, n+1):
            result[i][j] = result[i-1][j] + result[i][j-1]

    return result[n][n]

