 {
  string statement = "abcddd";

  bool duplicateCharacters = HasDuplicateCharacters(statement);

  Console.WriteLine("The string has duplicate characters: " + duplicateCharacters);
 }

 // Checks for duplicate characters in a string
 public static bool HasDuplicateCharacters(string statement)
 {
  int[] characters = new int[26]; // to store all lowercase characters

  for (int i = 0; i < statement.Length; i++)
  {
   int index = statement[i] - 'a'; // get the array index of the character

   // increment the array value for the character
   characters[index]++;

   // if array value is more than once, there is a duplicate character
   if (characters[index] > 1)
   {
    return true;
   }
  }

  return false;
 }
}

