function validateCreditCard(cardNo) {
  const regex = /^[0-9]{16}$/;
  if(regex.test(cardNo)) {
    const numbers = cardNo.split('').map(ele => parseInt(ele));
    let totalSum = 0;
    for (let i = numbers.length-1; i >= 0; i--) {
      let currentNum = numbers[i];
      if((numbers.length-i) %2 === 0) {
        currentNum *= 2;
        totalSum += currentNum > 9 ? (currentNum-9) : currentNum;
      } else {
        totalSum += currentNum;
      }
    }
    return totalSum % 10 === 0;
  }
  return false;
}

def edit_words(words, rules):
