def sortArray(arr): 
    less = []
    equal = []
    greater = []

    if len(arr) > 1:
        pivot = arr[0]
        for num in arr:
            if num < pivot:
                less.append(num)
            if num == pivot:
                equal.append(num)
            if num > pivot:
                greater.append(num)
        return sortArray(less)+equal+sortArray(greater) 
    else:  
        return arr

