def get_max_sequence_length(list_of_integers):
    max_length = 0
    current_length = 0

    for i in range(len(list_of_integers)):
        if i == 0:
            current_length = 1
        else:
            if list_of_integers[i] > list_of_integers[i-1]:
                current_length += 1
            else:
                if current_length > max_length:
                    max_length = current_length
                current_length = 1

    if current_length > max_length:
        max_length = current_length

    return max_length

