// Function to compare two strings lexicographically
int lexicographic_compare(char *s1, char *s2) 
{ 
    int s1len, s2len, i, j; 

    // Finds the length of given two strings 
    s1len = strlen(s1); 
    s2len = strlen(s2); 

    // Find the minimum length of strings 
    int len = (s1len <= s2len) ? s1len : s2len; 

    // Compare given strings character by character 
    for (i = 0, j = 0; i < len; i++, j++) { 
        if (s1[i] != s2[j]) { 
            break; 
        } 
    } 

    // If any difference found 
    if (s1[i] != s2[j]) { 
        return (s1[i] > s2[j]) ? 1 : -1; 
    } 

    // If there is no difference 
    else { 
        if (s1len > s2len) { 
            return 1; 
        } 
        if (s1len < s2len) { 
            return -1; 
        } 
        else { 
            return 0; 
        } 
    } 
} 

