public class PascalTriangle {
    public static void main(String[] args) {
        int linhas = 7;

        for (int i = 0; i < linhas; i++) {
            for (int j = 0; j <= i; j++) {
                System.out.print(calculate(i, j)+" ");
            }
            System.out.println();
        }
    }

    public static int calculate(int i, int j)
    {
        if (j == 0 || i == j)
            return 1;
        return calculate(i - 1, j - 1) + calculate(i - 1, j);
    }
}

