def calculate(expr): 
    def parse(value):
        if value.isdigit():
            return int(value)
        return value
    expr_list = [parse(x) for x in expr.split(' ')]
    stack = []
    for each in expr_list:
        if each == '+':
            stack.append(stack.pop() + stack.pop())
        elif each == '-':
            stack.append(-stack.pop() + stack.pop())
        elif each == '*':
            stack.append(stack.pop() * stack.pop())
        elif each == '/':
            stack.append(int(1/stack.pop() * stack.pop()))
        else:
            stack.append(each)

    return int(stack.pop())

