Since there is a need to store a large number of words, and searching for words needs to be fast, a Trie data structure would be the most appropriate. A Trie is a special type of tree used for storing strings. It allows for quick searching for a string by breaking it down into smaller chunks, i.e. its associated characters. With a Trie, searching for a word is simply a matter of going down the tree until it is found.

class TrieNode {
    constructor() {
        this.children = new Map();
        this.isEndOfWord = false;
    }
}

class Trie {
    constructor() {
        this.root = new TrieNode();
    }

    // Inserts a word into the trie
    insert(word) {
        let node = this.root;

        for (let char of word) {
            // If the character already exists in the dictionary, increase counters as normal
            if (node.children.has(char)) {  
                node = node.children.get(char);  
            }
            else {  // Character does not exist so we create a new TrieNode
                let newNode = new TrieNode();
                node.children.set(char, newNode);
                node = newNode;
            }
        }
        node.isEndOfWord = true;
    }

    // Finds if the given word is present in the Trie
    find(word) {
        let node = this.root;

        for (let char of word) {
            if (node.children.has(char)) {
                node = node.children.get(char);
            } else {
                return false;
            }
        }
        return (node.isEndOfWord);
    }
}

