function longestCommonSubstring(strings) {
  // convert strings to array
  inputStrings = strings.split(",");

  // set substring to the first element of the array
  substring = inputStrings[0];

  // check for common substring in the remaining elements
  for (let i = 0; i < inputStrings.length; i++) {
    let j = 0;
    while (j < substring.length) {
       if (!inputStrings[i].includes(substring)) {
         substring = substring.slice(0, substring.length - 1);
         j = 0;
       } else {
         j++; 
       }
    }
  }

  // assign global var with the longest common substring
  longestCommonSubstring = substring;
}

