class MyQueue(object):
    def __init__(self):
        self.items = []
        self.priorities = []

    def push(self, item, priority):
        self.items.append(item)
        self.priorities.append(priority)

    def pop(self):
        max_priority = max(self.priorities)
        max_idx = self.priorities.index(max_priority)
        return_item = self.items.pop(max_idx)
        self.priorities.pop(max_idx)
        return return_item

