// Function to remove duplicate characters 
// from the string
void remove_duplicate_characters(std::string& str) 
{ 
    // Create an empty set
    std::set<char> existing_characters;

    // Iterate through the string
    std::string::iterator itr = str.begin(); 
    while (itr != str.end()) 
    { 
        // Insert the current character 
        if (existing_characters.find(*itr) == 
                       existing_characters.end()) 
        { 
            existing_characters.insert(*itr); 
            ++itr; 
        } 
        else
        { 
            // Erase the duplicated element
            itr = str.erase(itr); 
        } 
    } 
}

