def triplets_sum_zero(nums):
    triplets = []
    nums.sort()
    for i in range(len(nums)-2):
        start = i + 1
        end = len(nums) - 1
        while start < end:
            sum = nums[i] + nums[start] + nums[end]
            if sum == 0:
                triplet = [nums[i], nums[start], nums[end]]
                triplets.append(triplet)
                start += 1
                end -= 1
            elif sum < 0:
                start +=1
            else:
                end -= 1
    return triplets

