def max_sum_combination(arr):
    # the first and last element will always be part of the max sum 
    sum_max = arr[0] + arr[-1]
    for i in range(len(arr) - 2):
        # calculate the sum of two elements
        sum = arr[i] + arr[i+2]
        if sum > sum_max:
