function sortArray(arr) {
  const swappedArr = arr.slice(0);
  let done = false;
  while(!done) {
    done = true;
    for(let i = 0; i < swappedArr.length - 1; i++) {
      if(swappedArr[i] > swappedArr[i + 1]) {
        done = false;
        let temp = swappedArr[i];
        swappedArr[i] = swappedArr[i + 1];
        swappedArr[i + 1] = temp;
      }
    }
  }
  return swappedArr;
}

