public class SumThread implements Runnable { 

    private int[] arr; 
    private int lowerIndex; 
    private int upperIndex; 

    private int sum = 0; 
    private static Object lock = new Object(); 

    public SumThread(int[] arr, int lowerIndex, int upperIndex) 
    { 
        this.arr = arr; 
        this.lowerIndex = lowerIndex; 
        this.upperIndex = upperIndex; 
    } 

    public int getSum() 
    { 
        return this.sum; 
    } 

    @Override
    public void run() 
    { 
        while (lowerIndex <= upperIndex) { 
            sum += arr[lowerIndex]; 
            lowerIndex++; 
        } 

        synchronized (lock) { 
            Main.totalSum += this.sum; 
        } 
    } 
} 

public class Main { 

    public static int totalSum = 0; 

    // Driver function 
    public static void main(String[] args) 
        throws InterruptedException 
    { 
        int[] arr = { 1, 2, 3, 4 }; 

        int noOfThreads = 2; 
        int totalElements = arr.length; 
        int partition = totalElements / noOfThreads; 

        SumThread[] threads = new SumThread[noOfThreads]; 

        for (int i = 0; i < noOfThreads; i++) { 
            int lowerIndex = i * partition; 
            int upperIndex = (i + 1) * partition - 1; 

            if (i == (noOfThreads - 1)) { 
                upperIndex += totalElements % noOfThreads; 
            } 

            threads[i] = new SumThread(arr, lowerIndex, upperIndex); 
            threads[i].start(); 
        } 

        for (int i = 0; i < noOfThreads; i++) { 
            threads[i].join(); 
        } 

        System.out.println("Sum of array elements is : " + totalSum); 
    } 
}

