// function to sort a given array 
void sortArray(int arr[], int l, int r) 
{ 
    //for single elements 
    if (l >= r) 
        return; 

    int mid = (l+r)/2; 

    //divide the array into two subarrays 
    thread t1(sortArray, arr, l, mid); 
    thread t2(sortArray, arr, mid + 1, r); 
    t1.join(); 
    t2.join(); 

    //merge the subarrays 
    int len1 = mid - l + 1; 
    int len2 = r - mid; 
    int a[len1], b[len2]; 

    for (int i = 0; i < len1; i++) 
        a[i] = arr[l + i]; 
    for (int i = 0; i < len2; i++) 
        b[i] = arr[mid + 1 + i]; 

    int i = 0, j = 0, k = l; 

    while (i < len1 && j < len2) { 
        if (a[i] < b[j]) 
            arr[k++] = a[i++]; 
        else
            arr[k++] = b[j++]; 
    } 

    //appending the remaining elements
    while (i < len1)  
        arr[k++] = a[i++]; 
    while (j < len2)  
        arr[k++] = b[j++]; 
} 

int main() 
{ 
    int arr[] = {4,6,2,3,1,5}; 
    int n = sizeof(arr)/sizeof(arr[0]); 

    // Calling merge sort 
    sortArray(arr, 0, n - 1); 

    cout << "Sorted array : "; 
    for (int i = 0; i < n; i++) 
        cout << arr[i] << " ";

    return 0; 
}

