def longest_run_of_palindromes(string):
    n = len(string)
    table = [[False for _ in range(n)] for _ in range(n)]
    max_len = 1
    i, j = 0, 0

    # every substring of length 1 is a palindrome
    for i in range(n):
        table[i][i] = True

    # check for substring length 2 
    for i in range(n - 1):
        if (string[i] == string[i + 1]):
            table[i][i + 1] = True
            max_len = 2
            i, j = i, i + 1

    # check for lengths greater than 2. k is length 
    # of substring 
    for k in range(3, n + 1): 
        for i in range(n - k + 1): 
            j = i + k - 1

            # print the substring 
            if (table[i + 1][j - 1] and string[i] == string[j]):
                table[i][j] = True

                if (k > max_len):
                    max_len = k

    return max_len

