# Class to represent a puzzle
class PuzzleNode:
    def __init__(self, x_pos, y_pos, parent = None, state = None):
        self.x_pos = x_pos
        self.y_pos = y_pos
        self.parent = parent
        self.state = state

    def __eq__(self, other):
        return self.state == other.state

# move the empty tile in a particular direction
def move(x, y, state):
    new_state = state.copy()
    new_state[x, y], new_state[x + 1, y] = new_state[x + 1, y], new_state[x, y]
    return PuzzleNode(x + 1, y, parent = state, state = new_state)

# Heuristic: calculate the total Manhattan distance of all tiles
def heuristic(state):
    h = 0
    x, y = find_empty(state)
    for i in range(3):
        for j in range(3):
            h += (abs(i - x) + abs(j - y)) * state[i, j]
    return h

