def is_valid_move(x, y, board):
    return 0 <= x < 3 and 0 <= y < 3 and board[x, y] == 0

# Find the position of the empty tile in the state
def find_empty(state):
    for i in range(3):
        for j in range(3):
            if state[i, j] == 0:
                return i, j

