def mean_squared_error(predicted_vals, actual_vals):
    if len(predicted_vals) != len(actual_vals):
        return -1 # invalid inputs
    error_sum = 0.0
    for i, (p_val, a_val) in enumerate(zip(predicted_vals, actual_vals)):
        error_sum += (p_val - a_val)**2
    return error_sum / len(predicted_vals)

def evaluate(expr):
    # Create a variable stack to store the variables
    var_stack = []

    # Create a variable to store the result
    result = 0

    # Iterate over the expression
    for char in expr:
        # Compute the result if an operator is found
        if char in "+-*/":
            if len(var_stack) < 2:
                raise ValueError("Stack cannot be empty")
            else:
                num2 = var_stack[-1]
                var_stack.pop()
                num1 = var_stack[-1]
                var_stack.pop()
                if char == "+":
                    result = num1 + num2
                    var_stack.append(result)
                elif char == "-":
                    result = num1 - num2 
                    var_stack.append(result)
                elif char == "*":
                    result = num1 * num2 
                    var_stack.append(result)
                elif char == "/":
                    result = num1 / num2 
                    var_stack.append(result)
        # Push the character onto the stack if its a number
        else:
            var_stack.append(int(char))
    return result

class ConnectFourGame{

    int rows, cols, player;
    int[][] board;

    ConnectFourGame(int r, int c){
        rows = r;
        cols = c;
        player = 1; 
        board = new int[rows][cols]; 
    }

    public boolean isMovePossible(){
        for (int r = 0; r < rows; r++) 
            for (int c = 0; c < cols; c++) 
                if (board[r][c] == 0) 
                    return true; 
        return false; 
    }

    public int getBestMove(){
        int bestVal = -1000; 
        int bestMove = -1; 

        for (int c = 0; c < cols; c++){ 
            if (isValidMove(c)){ 
                int score = minimax(0, false, c); 

                if (score > bestVal){ 
                    bestMove = c; 
                    bestVal = score; 
                } 
            } 
        } 
        return bestMove; 
    }

    public int minimax(int depth,boolean isMaximizing, int col){
        int score = evaluate(); 
        if (score == 10 || score == -10) 
            return score; 

        // If no more moves, score is 0 
        if (!isMovePossible()) 
            return 0; 

        // If maximizing player, find its best move 
        if (isMaximizing) { 
            int bestScore = -1000; 
            // Loop through all columns 
            for (int c = 0; c < cols; c++) { 
                if (isValidMove(c)) { 
                    makeMove(c); 
                    int score = minimax(depth+1, false, c); 
                    bestScore = Math.max(score, bestScore); 
                    unMakeMove(c); 
                } 
            } 
            return bestScore; 
        }else { 
            int bestScore = 1000; 
            for (int c = 0; c < cols; c++) { 
                if (isValidMove(c)) { 
                    makeMove(c); 
                    int score = minimax(depth+1, true, c); 
                    bestScore = Math.min(score, bestScore); 
                    unMakeMove(c); 
                } 
            } 
            return bestScore; 
        } 
    }
    //Set board position after move
    public void makeMove(int col){
        for (int r = rows-1; r >= 0; r--){ 
            if (board[r][col] == 0){ 
                board[r][col] = this.player; 
                break; 
            } 
        } 
        player = (player == 1) ? 2 : 1; 
    }

    //Undo board position after move
    public void unMakeMove(int col){
        for (int r = 0; r < rows; r++){ 
            if (board[r][col] == this.player) { 
                board[r][col] = 0; 
                break; 
            } 
        } 
        this.player = (player == 1) ? 2 : 1; 
    }

    //Check if move is valid
    public boolean isValidMove(int col){
        if (col < 0 || col >= rows) 
            return false; 

        if (board[0][col] != 0) 
            return false; 

        return true; 
    }

    //Evaluate board
    public int evaluate(){
        for (int r = 0; r < rows-3; r++){ 
            for (int c = 0; c < cols; c++){ 
                if (board[r][c] == board[r+1][c] && 
                    board[r][c] == board[r+2][c] && 
                    board[r][c]== board[r+3][c]){ 
                    if (board[r + 3][c] == this.player) 
                        return 10; 
                } 
            } 
        }
        return 0;
    }
}

