public static int getNthValuePascalTriangle(int n) {
    int[] result = new int[n];
    result[0] = 1;

    for (int i = 1; i < n; i++) {
        int prevValue = result[0];
        for (int j = 1; j <= i; j++) {
            int currentValue = result[j];
            result[j] = prevValue + currentValue;
            prevValue = currentValue;
        }
    }

    return result[n - 1];
}

