def longest_subsequence(A):
    result = []
    current_seq = []
    for i in range(len(A)):
        if current_seq == [] or A[i] > current_seq[-1]:
            current_seq.append(A[i])
        else:
            if len(current_seq) > len(result):
                result = current_seq
            current_seq = [A[i]]
    if len(current_seq) > len(result):
        result = current_seq
    return result

