//A class representing a Deck of Cards
public class Deck {
    static int numberOfSuits = 4;
    static int numberOfRanks = 13;
    static int numberOfCards = numberOfRanks * numberOfSuits;
    Card[] deckOfCards;

    //constructor
    public Deck(){
        this.deckOfCards = new Card[numberOfCards];
        int index = 0;
        for (int suit = 1; suit <= numberOfSuits; suit++) {
            for (int rank = 1; rank <= numberOfRanks; rank++) {
                this.deckOfCards[index] = new Card(rank, suit);
                index++;
            } 
        }
    }

    //function for shuffling the cards
    public void shuffle(){
        Random random = new Random();

        for (int i = 0; i < numberOfCards; i++) {
            int j = random.nextInt(numberOfCards);
            Card temp = this.deckOfCards[i];
            this.deckOfCards[i] = this.deckOfCards[j];
            this.deckOfCards[j] = temp;
        }
    }

    //function for displaying the cards
    public void display(){
        for (int i = 0;  i < numberOfCards; i++) {
            System.out.println(this.deckOfCards[i]);
        }
    }
}

