def longestCommonSubsequence(listA, listB):
    # Initialize a 2D list the same size as the two given lists
    lcs = [[0] * (len(listB) + 1) for i in range(len(listA) + 1)]

    # Traverse the two lists and fill the 2D list with LCS values
    for i in range(1, len(listA) + 1):
        for j in range(1, len(listB) + 1):
            if listA[i - 1] == listB[j - 1]:
                lcs[i][j] = lcs[i-1][j-1] + 1
            else:
                lcs[i][j] = max(lcs[i - 1][j], lcs[i][j - 1])

    # Track the LCS
    subsequence = []
    i,j = len(listA), len(listB)
    while i > 0 and j > 0:
        if listA[i - 1] == listB[j - 1]:
            subsequence.append(listA[i - 1])
            i -= 1
            j -= 1
        elif lcs[i - 1][j] > lcs[i][j - 1]:
            i -= 1
        else:
            j -= 1

    subsequence.reverse()
    return subsequence

