def check_balance(str): 
    stack = []

    for char in str: 
        if char in ["(", "{", "["]: 
            stack.append(char)
        elif char in [")", "}", "]"]: 
            if not stack: 
                return False
            if stack[-1] == "(" and char != ")": 
                return False
            if stack[-1] == "{" and char != "}": 
                return False
            if stack[-1] == "[" and char != "]": 
                return False
            stack.pop()

    if stack:
        return False
    else:    
        return True

