// Lambda function to shorten a URL

exports.handler = async (event) => {
    const url = require('url');
    const BitlyClient = require('bitly');

    // Your bit.ly access token
    const accessToken = '<your_access_token>'

    const bitly = new BitlyClient(accessToken);
    const { queryStringParameters } = event;
    const { originalUrl } = queryStringParameters;

    if(!originalUrl) {
        return {
            statusCode: 400,
            body: JSON.stringify({error: 'URL query string parameter is required.'})
        };
    }

    const originalUrlParsed = url.parse(originalUrl);
    const { hostname, pathname } = originalUrlParsed;

    if(!hostname || !pathname) {
        return {
            statusCode: 400,
            body: JSON.stringify({error: 'Invalid URL provided.'})
        };
    }

    const longUrl = `https://${hostname}${pathname}`;
    const { link } = await bitly.shorten(longUrl); 

    return {
        statusCode: 200,
        body: JSON.stringify({ shortUrl: link, longUrl }),
    };
};

