//Function to check whether two strings are anagrams or not
int isAnagram(char str1[], char str2[]) 
{ 
    int n1 = strlen(str1); 
    int n2 = strlen(str2); 

    // If length of both strings is not same, then 
    // they cannot be anagram 
    if (n1 != n2) 
        return 0; 

    // Sort both strings 
    qsort(str1, n1, sizeof(str1[0]), compare); 
    qsort(str2, n2, sizeof(str2[0]), compare); 

    // Compare sorted strings 
    for (int i = 0; i < n1; i++) 
        if (str1[i] != str2[i]) 
            return 0; 

    return 1; 
} 

