def most_common_words(words, n):
  # Create a dictionary to store the word and its count
  words_dict = {}
  # Count each word in the list and store them in the dictionary
  for word in words:
    if word not in words_dict:
      words_dict[word] = words.count(word)

  # Sort the dictionary based on the number of occurences
  sorted_words_dict = sorted(words_dict.items(), key = lambda kv: kv[1], reverse=True)
  # Return the top-n most common words
  return [sorted_words_dict[i][0] for i in range(n)]

