function maximumSumPath(matrix) {
    let maxSum = 0;

    let dp = new Array(matrix.length).fill(0).map(e => new Array(matrix[0].length).fill(0));
    dp[0][0] = matrix[0][0];

    for (let i = 1; i < dp.length; i++) 
        dp[i][0] = matrix[i][0] + dp[i - 1][0];

    for (let i = 1; i < dp[0].length; i++) 
        dp[0][i] = matrix[0][i] + dp[0][i - 1];

    for (let i = 1; i < dp.length; i++) {
        for (let j = 1; j < dp[0].length; j++) {
            dp[i][j] = matrix[i][j] + Math.max(dp[i][j - 1], dp[i - 1][j]);
        }
    }

    maxSum = dp[dp.length - 1][dp[0].length - 1];

    return maxSum;
}

