class TrieNode{
 constructor(){
  this.children = {};
  this.isEndOfWord = false;
  this.urlInfo = {};
 }
}

class UrlTrie{
 constructor(){
  this.root = new TrieNode();
 }

 insert(url){
  let currentNode = this.root;
  let arrayURL = url.split("/"); //Split the url into an array of strings
  for(let i=0; i < arrayURL.length; i++){
   const currentCharacter = arrayURL[i];
   //If the node doesn't exist in the Trie, then add it
   if(!currentNode.children[currentCharacter]){
    currentNode.children[currentCharacter] = new TrieNode();
   }
   currentNode = currentNode.children[currentCharacter];
  }
  //Mark the last node as an end of a word
  currentNode.isEndOfWord = true;
  currentNode.urlInfo = url;
 }

 search(url){
  let currentNode = this.root;
  let arrayURL = url.split("/");
  for(let i=0; i < arrayURL.length; i++){
   const currentCharacter = arrayURL[i];
   if(!currentNode.children[currentCharacter]){
    return false;
   }
   currentNode = currentNode.children[currentCharacter];
  }
  return currentNode.urlInfo;
 }

}

