 // in prime[i] will finally be false if i is 
 // Not a prime, else true. 
 let prime = [true];
 for (let i = 0; i < n; i++) {
 	prime.push(true);
 }

 for (let p = 2; p * p <= n; p++) {
  // If prime[p] is not changed, then it is 
  // a prime 
  if (prime[p] == true) {
   // Update all multiples of p 
   for (let i = p * 2; i <= n; i += p) 
     prime[i] = false; 
  } 
 } 

 // Print all prime numbers 
 for (let p = 2; p <= n; p++) 
  if (prime[p]) 
   console.log(p); 
} 

