# function to check if tree is valid BST
def isBST(node): 
    if node is None:
        return True

    # check if left node is valid
    if node.left is not None and node.data < node.left.data: 
        return False

    # check if right node is valid
    if node.right is not None and node.data > node.right.data: 
        return False

    # check if left and right subtrees are valid
    return isBST(node.left) and isBST(node.right)

