// Linked list data type
typedef struct Node {
  int data;
  struct Node *next;
} Node;

// Insert a node at beginning
void insert_beginning(Node **head, int data) {
  Node *new_node = (Node *)malloc(sizeof(Node));
  new_node->data = data;
  new_node->next = *head;
  *head = new_node;
}

// Insert a node at the end
void insert_end(Node **head, int data) {
  Node *new_node = (Node *)malloc(sizeof(Node));
  new_node->data = data;
  new_node->next = NULL;

  Node *current = *head;
  while (current->next != NULL) {
    current = current->next;
  }
  current->next = new_node;
}

// Delete a node from the list
Node* delete_node(Node *head, int data) {
  Node *current = head;
  Node *previous = NULL;

  // If the head contains the data, delete the head node
  if (current->data == data) {
    head = head->next;
    free(current);
    return head;
  }

  // Find the data in the list
  while (current != NULL && current->data != data) {
    previous = current;
    current = current->next;
  }

  // If the data is not in the list
  if (current == NULL) {
    return head;
  }

  // Delete the node
  previous->next = current->next;
  free(current);

  return head;
}

