    best_cost = (x-1)*(x-2)*(x-3)
    for xx in range(x-3, x+3):
        new_cost = (xx-1)*(xx-2)*(xx-3)
        if new_cost < best_cost:
            best_x = xx
            best_cost = new_cost
    return best_x

