public static int sumOfPrime(int n) {

 int sum = 0;

 boolean[] numbers = new boolean[n+1];

 for (int i = 0; i <= n; i++) {
  numbers[i] = true;
 }

 for (int i = 2; i*i <= n; i++) {
  if (numbers[i] == true) {
   for (int j = i*2; j <= n; j += i) {
    numbers[j] = false;
   }
  }
 }

 // sum of primes
 for (int i = 2; i <= n; i++) {
  if (numbers[i] == true) {
   sum += i;
  }
 }

 return sum;
}

