def binary_search(arr, value): 
    # Initialize the indices 
    l = 0
    r = len(arr) - 1 

    # Traverse the array 
    while l <= r: 

        m = (l + r) // 2

        # Check if the search value is found 
        if arr[m] == value: 
            return m 

        elif arr[m] < value: 
            l = m + 1 

