function base10To16(num) {
  let result = "";
  let base = 16;

  while (num > 0) {
    let mod = num % base;
    if (mod < 10) {
      result += mod.toString();
    } else {
      result += String.fromCharCode(mod + 55);
    }
    num = Math.floor(num / base);
  }

