def optimizedBinarySearch(arr, l, r, x): 
	# If the element is present 
	if l <= r: 

		# Calculate the mid element 
		mid_index = l + (r - l)//2

		# Check if x is present at mid 
		if arr[mid_index] == x: 
			return mid_index 

		# If x is smaller than middle element, 
		# then it can only be present in left subarray 
		elif arr[mid_index] > x: 
			return optimizedBinarySearch(arr, l, mid_index-1, x) 

		# Else the element can only be present 
		# in right subarray 
		else: 
			return optimizedBinarySearch(arr, mid_index+1, r, x) 

	else: 
		# Element is not present in the array 
		return -1


