public class NumberToRoman { 

    public static String intToRoman(int num) { 
        // List of Roman Numerals 
        String roman[] = { "M",  "CM", "D", "CD", 
                          "C", "XC", "L", "XL", 
                          "X", "IX", "V", "IV", 
                          "I" }; 

        // List of Decimal values corresponding to roman symbols 
        int dec[] = { 1000, 900, 500, 400, 
                      100, 90, 50, 40, 
                      10, 9, 5, 4, 
                      1 }; 

        // Initialize index of roman numerals 
        int i=0; 
        String result = ""; 

        // Traverse the given num 
        while(num > 0) { 

            // Find the biggest value out-of-the-list 
            int div = num / dec[i]; 

            // repeat roman value as per the counted numbers 
            while (div > 0) { 

                result += roman[i]; 
                div--; 
            } 

            // update the num 
            num %= dec[i]; 

            // Move on to the next index of roman numerals 
            i++; 
        } 

        return result; 
    } 

    public static void main(String[] args) { 
        System.out.println(intToRoman(1998)); 
    } 
}
