void replaceChars(char str[], int n) 
{ 
	char missingChar = '_'; 

	// Traverse the missing characters 
	for (int i = 0; i < n-1; i++) { 

		// Check if character needs to be replaced 
		if (str[i] == missingChar) { 

			// Get char to be replaced 
			int diff = str[i + 1] - str[i - 1]; 

			if (str[i + 1] == missingChar) 
				str[i] = str[i - 1]; 
			else
				str[i] = str[i - 1] + 1; 
		} 
	} 
} 

