public static float calculateMean(int[] dataSet) {
 float sum = 0f;
 for (int datum : dataSet) {
 sum += datum;
 }
 return sum / dataSet.length;
}

public static float calculateMedian(int[] dataSet) {
 Arrays.sort(dataSet);

 if (dataSet.length % 2 != 0) {
 return dataSet[dataSet.length / 2];
 }
 else {
 int middle1 = dataSet[(dataSet.length/2) - 1];
 int middle2 = dataSet[dataSet.length / 2];
 return (middle1 + middle2) / 2;
 }
}

public static float calculateMode(int [] dataSet) 
    { 
        int maxValue = 0, maxCount = 0; 

        for (int i = 0; i < dataSet.length; ++i) { 
            int count = 0; 
            for (int j = 0; j < dataSet.length; ++j) { 
                if (dataSet[j] == dataSet[i]) {
                    ++count; 
                }
            }

            if (count > maxCount) { 
                maxCount = count; 
                maxValue = dataSet[i]; 
            } 
        } 

        return maxValue; 
    }
}

