def closest_pair(points):
    min_dist = float('inf')
    closest_pair = None
    for i, p1 in enumerate(points):
        for j, p2 in enumerate(points[i+1:]):
            d = distance(p1, p2)
            if d < min_dist:
                min_dist = d
                closest_pair = p1, p2
    return closest_pair

