int maxSubArraySum(int arr[], int n) 
{ 
    int maxSumSoFar = 0; 
    int maxSumEndingHere = 0; 

    for (int i = 0; i < n; i++) 
    { 
        maxSumEndingHere += arr[i]; 
        if (maxSumEndingHere < 0) 
            maxSumEndingHere = 0;  
        if (maxSumSoFar < maxSumEndingHere) 
            maxSumSoFar = maxSumEndingHere; 
    } 
    return maxSumSoFar; 
}

