def longest_palindromic_subsequence(data):
    n = len(data)
    # Create a table of n x n dimension
    table = [[0]* n for _ in range(n)]

    # Every subsequence with one character is a palindrome
    for i in range(n):
        table[i][i] = 1

    # Check for subsequence of length 2
    for i in range(n-1):
        if data[i] == data[i+1]:
            table[i][i+1] = 2

    # Check for subsequences greater than length 2
    for sublen in range(2, n):
        for i in range(n-sublen):
            j = i + sublen
            if data[i] == data[j]:
                table[i][j] = table[i+1][j-1] + 2
            else:
                table[i][j] = max(table[i][j-1], table[i+1][j])

    return table[0][n-1]

