// Encryption function
string encrypt(string msg, int key) 
{ 
    string result = ""; 

    // One by one process message characters 
    for (int i = 0; i < msg.length(); i++) 
    { 
        // shift character by key value 
        if(msg[i] < 'A' && msg[i] != ' ') { 
            result += msg[i]; 
        }
        else if (msg[i] >= 'a' && msg[i] <= 'z') { 
            result += char(int(msg[i] + key - 97) % 26 + 97); 
        } 
        else { 
            result += char(int(msg[i] + key - 65) % 26 + 65); 
        } 
    } 

    // return the result string 
    return result; 
} 

