  public void saveDataSet(List<Float> data, String path) {
    // Code to write data set to a csv file
    String dataString = "";
    for (float element : data) {
      dataString += element + ",";
    }
    FileOutputStream outputStream;
    try {
      outputStream = openFileOutput(path, Context.MODE_PRIVATE);
      outputStream.write(dataString.getBytes());
      outputStream.close();
    } catch (Exception e) {
      e.printStackTrace();
    }
  }

