class PriorityQueue: 

    def __init__(self): 
        self.elements = [] 

    # To get the top element of the priority queue
    def top(self): 
        if len(self.elements) > 0:
            return self.elements[0]
        else: 
            return None

    # To check if the priority queue is empty or not
    def is_empty(self): 
        return len(self.elements) == 0 

    # To add an element to the priority queue
    def push(self, item): 
        self.elements.append(item) 
        self._heapify() 

    # To remove an element from the priority queue
    def pop(self): 
        length = len(self.elements) 
        if length == 0:
            return None 
        elif length == 1: 
            return self.elements.pop() 
        else: 
            top_element = self.elements[0] 
            self.elements[0] = self.elements.pop() 
            self._heapify() 
            return top_element 

    # To maintain the heap property of the priority queue
    def _heapify(self): 
        length = len(self.elements) 
        for i in range((length - 1) // 2, -1, -1): 
            self._max_heapify(i) 

    # To maintain the max heap property of the priority queue
    def _max_heapify(self, index): 
        left = 2 * index + 1 
        right = 2 * index + 2 

        largest = index
        if left < len(self.elements) and self.elements[left] > self.elements[largest]: 
            largest = left 
        if right < len(self.elements) and self.elements[right] > self.elements[largest]: 
            largest = right 
        if largest != index: 
            self.elements[largest], self.elements[index] = self.elements[index], self.elements[largest] 
            self._max_heapify(largest)

