public class RandomWalk {

  public static void main(String[] args) {
    int n = 10;                                    // Length of random walk
    int[] x = new int[n+1];                        // Array to store x coordinates
    int[] y = new int[n+1];                        // Array to store y coordinates

    x[0] = 0;                                      // Initial x coordinate is 0 
    y[0] = 0;                                      // Initial y coordinate is 0  

    for (int i=0; i<n; i++) {
      int r = (int)(Math.random() * 4);            // Generate a random number between 0 and 4 
      switch(r) {
        case 0 : x[i+1] = x[i] + 1; y[i+1] = y[i];  // Move right
        break;  
        case 1 : x[i+1] = x[i] - 1; y[i+1] = y[i];  // Move left
        break;
        case 2 : x[i+1] = x[i]; y[i+1] = y[i] + 1;  // Move up
        break;
         case 3 : x[i+1] = x[i]; y[i+1] = y[i] - 1;  // Move down
        break;
      }
    }
    // Print the grid
    for (int i=-12; i<12; i++) {
      for (int j=-12; j<12; j++) {
        if (i==0 && j==0)
          System.out.print("o ");
        else
          System.out.print((contains(x,y,i,j) ? "+ " : ". "));
      }
      System.out.println();
    }
  }
  // Helper method to check if an (x,y) pair is part of the path
  public static boolean contains(int[] x, int[] y, int xx, int yy) {
    for (int i=0; i<x.length; i++)
      if (x[i]==xx && y[i]==yy)
        return true;
    return false;
  }
}

