using namespace std; 

// function to print out the longest common subsequence
int LCS(string X, string Y, int m, int n) 
{ 
	int L[m + 1][n + 1]; 

	//fill in the matrix with memoization
	for (int i = 0; i <= m; i++) 
	{ 
		for (int j = 0; j <= n; j++) 
		{ 
			if (i == 0 || j == 0) 
				L[i][j] = 0; 

			else if (X[i - 1] == Y[j - 1]) 
				L[i][j] = L[i - 1][j - 1] + 1; 

			else
				L[i][j] = max(L[i - 1][j], L[i][j - 1]); 
		} 
	} 

	// start from the last cell of the matrix in order to find the longest common subsequence
	int index = L[m][n]; 
	char lc[index+1]; 
	lc[index] = '\0'; 

	int i = m, j = n; 
	while (i > 0 && j > 0) 
	{ 
		if (X[i - 1] == Y[j - 1]) 
		{ 
			lc[index - 1] = X[i - 1]; 
			i--; j--; index--;	 
		} 
		else if (L[i - 1][j] > L[i][j - 1]) 
			i--; 
		else
			j--; 
	} 

	cout << "LCS of " << X << " and " << Y << " is " << lc << endl; 
	return 0; 
} 

