// function to interpolate a given set of data points
function linearInterpolate(x, x_values, y_values) {
  // find index of x in x_values
  let index = x_values.indexOf(x);
  let val;

  // if x lies in x_values return corresponding y_values
  if (index > -1) {
    val = y_values[index];
  } else {
    // else calculate value using linear interpolation
    let dist = Infinity;
    let x1;
    let x2;
    // find two nearest x_values in either side of x
    for (let i = 0; i < x_values.length; i++) {
      let curr_dist = Math.abs(x - x_values[i]);
      if (curr_dist < dist) {
        dist = curr_dist;
        x1 = x_values[i];
        x2 = x_values[i + 1];
      }
    }

    // find y_values corresponding to x1 and x2
    let y1 = y_values[x_values.indexOf(x1)];
    let y2 = y_values[x_values.indexOf(x2)];

    // calculate interpolated value
    val =
      y1 +
      ((x - x1) / (x2 - x1)) * (y2 - y1);
  }

  return val;
}

