def calc_determinant(matrix):
    size = len(matrix)
    if size == 2:
        return matrix[0][0] * matrix[1][1] - matrix[0][1] * matrix[1][0] 
    else:
        det = 0
        for i in range(size):
            temp_matrix = [[matrix[j][k] for k in range(size) if k != i] for j in range(1, size)]
            det += (((-1) **i) * matrix[0][i] * calc_determinant(temp_matrix))
        return det

