    # create a dictionary that stores the count of characters
    dic = {}

    # count frequency of characters in both the strings
    for c in string1:
        if c in dic:
            dic[c]+=1
        else:
            dic[c]=1
    for c in string2:
        if c in dic:
            dic[c]-=1
        else:
            dic[c]=1

    anagrams = 1
    # calculate factorial
    for count in dic.values():
        if (count == 0):
            continue
        else:
            anagrams *= math.factorial(count)
    return anagrams

