public static int[] merge(int[] arr1, int[] arr2)
{
	int m = arr1.length;
	int n = arr2.length;
	int[] arr3 = new int[m+n];

	// Initialize the result array
	for(int i=0; i<m+n; i++)
		arr3[i] = 0;

	// Fill the result array
	int i = 0, j = 0, k = 0;
	while (i<m && j <n)
	{
		if (arr1[i] <= arr2[j])
			arr3[k++] = arr1[i++];
		else
			arr3[k++] = arr2[j++];
	}

	// Fill remaining elements of arr1[]
	while (i < m)
		arr3[k++] = arr1[i++];

	// Fill remaining elements of arr2[]
	while (j < n)
		arr3[k++] = arr2[j++];

	return arr3;
}

