public class MainActivity extends AppCompatActivity {

    private static final int LOCATION_REQUEST_CODE = 0;
    private List<Restaurant> restaurants;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        // set up the list of restaurants
        restaurants = new ArrayList<Restaurant>();
        restaurants.add(new Restaurant("Restaurant 1", 42.0, -72.9));
        restaurants.add(new Restaurant("Restaurant 2", 41.3, -71.4));
        restaurants.add(new Restaurant("Restaurant 3", 41.7, -71.2));
        restaurants.add(new Restaurant("Restaurant 4", 40.9, -72.7));
        restaurants.add(new Restaurant("Restaurant 5", 42.3, -73.5));

        // request the user's location
        requestLocationPermission();
    }

    private void requestLocationPermission() {
        // check if location permission is granted
        if (ContextCompat.checkSelfPermission(this, Manifest.permission.ACCESS_FINE_LOCATION) != PackageManager.PERMISSION_GRANTED) {
            // request location permission
            requestPermissions(new String[] { Manifest.permission.ACCESS_FINE_LOCATION }, LOCATION_REQUEST_CODE);
        } else {
            // permission already granted, get user's location
            getUserLocation();
        }
    }

    @Override
    public void onRequestPermissionsResult(int requestCode, String[] permissions, int[] grantResults) {
        if (requestCode == LOCATION_REQUEST_CODE && grantResults[0] == PackageManager.PERMISSION_GRANTED) {
            // permission granted, get the user's location
            getUserLocation();
        }
    }

    private void getUserLocation() {
        // get user's current location
        LocationManager locationManager = (LocationManager) getSystemService(Context.LOCATION_SERVICE);
        Location location = locationManager.getLastKnownLocation(LocationManager.GPS_PROVIDER);

        // calculate distances to each restaurant
        for (Restaurant restaurant : restaurants) {
            restaurant.calculateDistance(location.getLatitude(), location.getLongitude());
        }

        // sort restaurants based on distance
        Collections.sort(restaurants, new Comparator<Restaurant>()) {
            public int compare(Restaurant restaurant1, Restaurant restaurant2) {
                if (restaurant1.getDistance() < restaurant2.getDistance())
                    return -1;
                if (restaurant1.getDistance() > restaurant2.getDistance())
                    return 1;
                return 0;
            }
        });

        // display the sorted list of restaurants
        ListView listView = (ListView) findViewById(R.id.list_view);
        listView.setAdapter(new RestaurantAdapter(this, restaurants));
    }

}

