    high = len(arr) - 1
    while low <= high:
        mid = (low + high) //2
        if arr[mid] == target:
            return arr[mid]
        elif arr[mid] < target:
            low = mid + 1
        elif arr[mid] > target:
            high = mid - 1

    return arr[low-1] if abs(arr[low-1] - target) <= abs(arr[high] - target) else arr[high]

