public class MaximumSubarray {

    public static int[] maxSubarray(int[] arr) {
        if (arr == null || arr.length == 0) return null;
        int[] res = new int[2];
        int left = 0;
        int right = arr.length - 1;

        int maxSum = maxSubarray(arr, left, right, res);
        System.out.println("Max Sum: " + maxSum);
        System.out.println("Subarray Range: " + res[0] + " to " + res[1]);

        return res;
    }

    private static int maxSubarray(int[] arr, int left, int right, int[] res) {
        // Base case
        if (left == right) {
            res[0] = left;
            res[1] = right;
            return arr[left];
        }

        // Divide
        int mid = left + (right - left) / 2;
        int[] leftRes = new int[2];
        int leftSum = maxSubarray(arr, left, mid, leftRes);
        int[] rightRes = new int[2];
        int rightSum = maxSubarray(arr, mid + 1, right, rightRes);

        // Conquer
        int maxLeftBorderSum  = 0;
        int leftBorderSum  = 0;
        int maxLeftIndex = 0;
        for (int i = mid; i >= left; i--) {
            leftBorderSum += arr[i];
            if (leftBorderSum > maxLeftBorderSum) {
                maxLeftBorderSum = leftBorderSum;
                maxLeftIndex = i;
            }
        }

        int maxRightBorderSum = 0;
        int rightBorderSum = 0;
        int maxRightIndex = 0;
        for (int i = mid + 1; i <= right; i++) {
            rightBorderSum += arr[i];
            if (rightBorderSum > maxRightBorderSum) {
                maxRightBorderSum = rightBorderSum;
                maxRightIndex = i;
            }
        }

        int sum = maxLeftBorderSum + maxRightBorderSum;
        if (leftSum >= rightSum && leftSum >= sum) {
            res[0] = leftRes[0];
            res[1] = leftRes[1];
            return leftSum;
        } else if (rightSum >= leftSum && rightSum >= sum) {
            res[0] = rightRes[0];
            res[1] = rightRes[1];
            return rightSum;
        } else {
            res[0] = maxLeftIndex;
            res[1] = maxRightIndex;
            return sum;
        }
    }

    public static void main(String[] args) {
        int[] arr = {-1,5,2,7,9,-5,2,-2,5};
        maxSubarray(arr);
    }
}

