public class BinarySearchTree {

 private class Node {
 int key;
 Node left, right;

 public Node(int key) {
 this.key = key;
 left = right = null;
 }
 }

 private Node root;

 public BinarySearchTree() {
 root = null;
 }

 // Method to insert a node
 public void insert(int key) {
 root = insertRec(root, key);
 }

 // Recursive method to insert a node
 private Node insertRec(Node root, int key) {
 // Base case: if the tree is empty, create a new node
 if (root == null) {
 root = new Node(key);
 return root;
 }

 // Otherwise, recursively insert the node
 if (key < root.key)
 root.left = insertRec(root.left, key);
 else if (key > root.key)
 root.right = insertRec(root.right, key);

 return root;
 }

 // Method to find the maximum value
 public int findMax() {
 return findMaxRec(root);
 }

 // Recursive method to find the maximum value
 private int findMaxRec(Node root) {
 int maxVal = root.key;

 if (root.left != null)
 maxVal = Math.max(maxVal, findMaxRec(root.left));

 if (root.right != null)
 maxVal = Math.max(maxVal, findMaxRec(root.right));

 return maxVal;
 }
}

