public class RepeatedSubstringFinder 
{
    public List<string> FindRepeatedSubstrings(string s) 
    {
        List<string> substrings = new List<string>();

        int length = s.Length;
        bool[,] table = new bool[length, length];

        // Check each substring of length 1
        for (int i = 0; i < length; i++) 
        {
            table[i, i] = true;
            substrings.Add(s.Substring(i, 1));
        }

        // Check each substring of length greater that 1
        for (int k = 2; k <= length; k++) 
        {
            for (int i = 0; i <= length - k; i++) 
            {
                int j = i + k - 1;
                if (table[i + 1, j - 1] && s[i] == s[j]) 
                {
                    table[i, j] = true;
                    substrings.Add(s.Substring(i, k));
                }
            }
        }

        // Sort the output to get only unique substring
        substrings = substrings.Distinct().ToList();

        return substrings;
    }
}

