def breadth_first_search(root):
  # Set up a queue and a set
  queue = [root]
  visited = set()
  # While there are still nodes to visit
  while queue:
    node = queue.pop(0)
    if node not in visited:
      visited.add(node)
      if node.left:
        queue.append(node.left)
      if node.right:
        queue.append(node.right)
  return visited

