 // Calculate total seconds
 const parts = isoString.split(':');
 const totalSeconds = parseInt(parts[0], 10) * 86400 +
 parseInt(parts[1], 10) * 3600 +
 parseInt(parts[2], 10) * 60 +
 parseInt(parts[3], 10);

 // Calculate days, hours, minutes, and seconds separately
 const days = Math.floor(totalSeconds / 86400);
 const hours = Math.floor((totalSeconds - (days * 86400)) / 3600);
 const minutes = Math.floor((totalSeconds - (days * 86400) - (hours * 3600)) / 60);
 const seconds = totalSeconds - (days * 86400) - (hours * 3600) - (minutes * 60);

 // Create formatted string
 const formattedDuration = `${days} days, ${hours} hours, ${minutes} minutes, and ${seconds} seconds`;

 return formattedDuration;
}

