class MinHeap 
{
 public:
 // insert elements into the min heap
 void insert(int element); 

 // delete an element at a specified position in the min heap
 void remove(int index);

 // Find the minimum element in the min heap
 int findMin(); 

 // Sort the elements in the min heap
 void sort();

 private:
 // Pointer to the array representing the min heap
 int* heap; 

 // Number of elements currently in the min heap
 int size; 

 // Max capacity of the min heap 
 int capacity; 

 // Helper functions
 void swap(int* a, int* b);
 void heapDown(int index);
 void heapUp(int index);
};

// Insert an element into the min heap
void MinHeap::insert(int element) 
{
 // Check if the min heap has reached its max capacity
 if(size == capacity) {
  std::cout << "Heap is full! Cannot insert more elements!\n";
  return;
 }

 // Perform the insertion operation
 heap[size] = element;
 heapUp(size);
 size++;
}

// Remove an element from the min heap
void MinHeap::remove(int index) 
{
 // Check if min heap is empty
 if(size == 0) {
  std::cout << "Heap is empty! Cannot remove elements!\n";
  return;
 }

 // Perform the deletion operation
 size--;
 int temp = heap[index];

 heap[index] = heap[size];

 heapDown(index);

 // Destroy the element
 heap[size] = temp;
}

// Find the minimum element in the min heap
int MinHeap::findMin() 
{
 // Check if the min heap is empty
 if(size == 0) {
  std::cout << "Heap is empty! Cannot find the minimum element!\n";
  return -1;
 }

 // Perform the search operation
 return heap[0];
}

// Sort the min heap
void MinHeap::sort() 
{
 // Check if the min heap is empty
 if(size == 0) {
  std::cout << "Heap is empty! Cannot sort the elements!\n";
  return;
 } 

 // Perform the sorting operation
 int lastIndex = size - 1;

 for(int index = 0; index < lastIndex; index++) {
  swap(&heap[0], &heap[lastIndex]);
  heapDown(0);
  lastIndex--;
 }
}

// Helper functions
void MinHeap::swap(int* a, int* b) 
{
 int temp = *b;
 *b = *a;
 *a = temp;
}

void MinHeap::heapDown(int index)
{
 int leftIndex = 2 * index + 1;
 int rightIndex = 2 * index + 2;

 int smallestIndex = index;

 // Check if left child is smaller than the parent. If true, set the smallestIndex to the left child's index
 if(leftIndex < size && heap[leftIndex] < heap[smallestIndex]) {
  smallestIndex = leftIndex;
 }

 // Check if right child is smaller than the parent. If true, set the smallestIndex to the right child's index
 if(rightIndex < size && heap[rightIndex] < heap[smallestIndex]) {
  smallestIndex = rightIndex;
 }

 // Swap the parent with the smallest child if required
 if(smallestIndex != index) {
  swap(&heap[index], &heap[smallestIndex]);
  heapDown(smallestIndex);
 }
}

void MinHeap::heapUp(int index)
{
 int parentIndex = (index - 1) / 2;

 // Swap the child with the parent if required
 if(heap[index] < heap[parentIndex]) {
  swap(&heap[index], &heap[parentIndex]);
  heapUp(parentIndex);
 }    
}

