public static String longestCommonSubstring(String str1, String str2) {
    int l1 = str1.length();
    int l2 = str2.length();
    int[][] arr = new int[l1+1][l2+1];
    int result = 0;
    String str = "";
    for (int i = 1; i <= l1; i++) {
        for (int j = 1; j <= l2; j++) {
            if(str1.charAt(i-1) == str2.charAt(j-1)) {
                arr[i][j] = arr[i-1][j-1] + 1;
            if(arr[i][j] > result) {
                result = arr[i][j];
                str = str1.substring(i-result, i);
            }
            }
        }
    }
    return str;
}

