public static String maxCommonSubString(String str1, String str2) 
{ 
    int n1 = str1.length(); 
    int n2 = str2.length();  
    int max = 0;
    String resultString = ""; 

    int[][] dp = new int[n1][n2]; 

    for (int i = 0; i < n1; i++) { 
        for (int j = 0; j < n2; j++) { 
            if (str1.charAt(i) == str2.charAt(j)) { 
                if (i == 0 || j == 0) { 
                    dp[i][j] = 1; 
                } 
                else { 
                    dp[i][j] = dp[i - 1][j - 1] + 1; 
                    max = Math.max(max, dp[i][j]); 
                } 
            } 
        } 
    } 

    if (max == 0) { 
        return ""; 
    } 

    for (int i = 0; i < n1; i++) { 
        for (int j = 0; j < n2; j++) { 
            if (dp[i][j] == max) { 
                resultString = str1.substring(i - max + 1, i + 1); 
            } 
        } 
    } 

    return resultString; 
}

