void swap_odd_even(int arr[], int n) 
{ 
    int even = 0, odd = 1; 

    while (true) 
    {  
        while (even < n && arr[even] % 2 == 0) 
            even += 2; 

        while (odd < n && arr[odd] % 2 == 1) 
            odd += 2; 

        if (even < n && odd < n) 
            swap(arr[even], arr[odd]); 
        else
            break; 
    } 
}

