def longestPalSubstr(string): 
    n = len(string) 
    # store longest palindrome substring
    longest_pal_substr = ""

    # check all possible substrings
    for i in range(n): 
        for j in range(i + 1, n): 

            # check if substring from i to j is a palindrome
            if isPalindrome(string, i, j):
                pal_substr = string[i : j + 1]
                if len(pal_substr) > len(longest_pal_substr):
                    longest_pal_substr = pal_substr

    return longest_pal_substr

