    if (index === len) {
      result.push(current.slice());
      return;
    }

    for (let i = start; i < arr.length; i++) {
      current.push(arr[i]);
      findCombinationsUtil(arr, len, i + 1, index + 1);
      current.pop();
    }
  }

  findCombinationsUtil(arr, len, 0, 0);

