public class GeneratePassword {

    static char[] passwordSource = { 'a', 'A', 'b', 'B', 'c', 'C', 'd', 'D',
            'e', 'E', 'f', 'F', 'g', 'G', 'h', 'H', 'i', 'I', 'j', 'J', 'k',
            'K', 'l', 'L', 'm', 'M', 'n', 'N', 'o', 'O', 'p', 'P', 'q', 'Q',
            'r', 'R', 's', 'S', 't', 'T', 'u', 'U', 'v', 'V', 'w', 'W', 'x',
            'X', 'y', 'Y', 'z', 'Z', '1', '2', '3', '4', '5', '6', '7', '8',
            '9', '0', '~', '!', '@', '#', '$', '%', '^', '&', '*', '(', ')',
            '-', '_', '+', '=', '|', '\\', '/', '[', ']', '{', '}', '<', '>',
            '.', '?' };

    public static String generatePassword() {

        Random random = new Random();
        char[] password = new char[8];
        boolean hasUppercase = false;
        boolean hasLowercase = false;
        boolean hasDigit = false;
        boolean hasSpecialCharacter = false;

        // Initializing password with random characters
        for (int i = 0; i < password.length; i++) {
            int randomNumber = random.nextInt(passwordSource.length);
            password[i] = passwordSource[randomNumber];

            if (Character.isUpperCase(password[i])) {
                hasUppercase = true;
            } else if (Character.isLowerCase(password[i])) {
                hasLowercase = true;
            } else if (Character.isDigit(password[i])) {
                hasDigit = true;
            } else {
                hasSpecialCharacter = true;
            }

        }

        // Replacing characters until all requirements are met
        while (!(hasUppercase && hasLowercase && hasDigit && hasSpecialCharacter)) {
            for (int i = 0; i < password.length; i++) {
                int randomNumber = random.nextInt(passwordSource.length);
                password[i] = passwordSource[randomNumber];

                if (Character.isUpperCase(password[i])) {
                    hasUppercase = true;
                } else if (Character.isLowerCase(password[i])) {
                    hasLowercase = true;
                } else if (Character.isDigit(password[i])) {
                    hasDigit = true;
                } else {
                    hasSpecialCharacter = true;
                }
            }
        }

        // Convert character array to String
        String passwordString = new String(password);
        return passwordString;
    }
}

