int binarySearch(int array[], int n, int element) {
 int left = 0;
 int right = n - 1;
 while (left <= right) {
 int mid = (left + right) / 2;
 if (array[mid] == element) {
 return mid;
 } else if (array[mid] < element) {
 left = mid + 1;
 } else {
 right = mid - 1;
 }
 }

 return -1;
}

