def three_sum_check(arr, target_sum):
    """ Returns True if three numbers in arr sum up to target_sum, False otherwise """
    # Sort the array
    arr.sort()

    # Loop through the array, evaluating each combination
    for i in range(len(arr)):
        left = i+1
        right = len(arr) - 1

        while (left < right):
            current_sum = arr[i] + arr[left] + arr[right]
            if current_sum ==  target_sum:
                return True
            elif current_sum > target_sum:
                right -= 1
            else:
                left += 1

    return False

