def fill_board(board, row_idx, col_idx, num):
  if row_idx == 9 and col_idx == 0:
    output_board(board)
    return True

  # move to next column if reaching the end of row
  if col_idx == 9:
    col_idx = 0
    row_idx += 1
  # skip filled cells in the board
  if board[row_idx][col_idx] != 0:
    fill_board(board, row_idx, col_idx + 1, 0)
    return False

  legal_nums = find_legal_nums(board, row_idx, col_idx)

  for num in legal_nums:
    board[row_idx][col_idx] = num
    if fill_board(board, row_idx, col_idx + 1, num):
      return True
  board[row_idx][col_idx] = 0

  return False

def find_legal_nums(board, row_idx, col_idx):
  row_nums = set(board[row_idx]) 
  col_nums = set([r[col_idx] for r in board])
  box_x, box_y = row_idx // 3, col_idx // 3
  box_nums = set(board[box_x*3][box_y*3:box_y*3+3] + 
    board[box_x*3+1][box_y*3:box_y*3+3] + 
    board[box_x*3+2][box_y*3:box_y*3+3])
  return set(range(1,10)) - (row_nums | col_nums | box_nums)

