public static void rotate(int[] arr, int rotations) 
{ 
    // length of the array 
    int n = arr.length; 
    rotations = rotations % n; 
    int g_c_d = gcd(n, rotations); 

    // divide arrays in sets
    for (int i = 0; i < g_c_d; i++) 
    { 
        int temp = arr[i]; 
        int j = i; 

        // rotate set
        while (true) 
        { 
            int k = j + rotations; 
            if (k >= n) 
                k = k - n; 

            if (k == i) 
                break; 

            arr[j] = arr[k]; 
            j = k; 
        } 
        arr[j] = temp; 
    } 
} 

