def huffman_encoding(data): 

    # Calculate frequency
    freq = {} 
    for char in data: 
        if char in freq: 
            freq[char] += 1
        else: 
            freq[char] = 1

    # Build Huffman tree
    huffman_tree = HuffmanTree(freq)

    # Generate encoding dictionary
    encoding_dict = huffman_tree.encode() 

    # Generated encoded data
    encoded_data = "" 
    for char in data:
        encoded_data += encoding_dict[char]

    return encoded_data

