    let greatest = 0;
    let factor = 2;

    while (factor < number) {
        if (number % factor === 0) {
            isPrime = true;
            for (let p = 2; p < factor; p++) {
                if (factor % p === 0) {
                    isPrime = false;
                    break;
                }
            }
            if (isPrime) {
                greatest = factor;
            }
        }
        factor++;
    }
    return greatest;
}

