function lcs(str1, str2) { 
  var m = str1.length,
      n = str2.length,
      dp = Array(m + 1).fill(0).map(() => Array(n + 1).fill(0));

  for (let i = 0; i <= m; i++) {
    for (let j = 0; j <= n; j++) {
      if (i === 0 || j === 0) {
        dp[i][j] = 0; 
      }
      else if (str1.charAt(i - 1) === str2.charAt(j - 1)) {
        dp[i][j] = dp[i - 1][j - 1] + 1; 
      }
      else {
        dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]); 
      }
    }
  }

  let index = dp[m][n],
      lcsStr = '';

  let i = m, j = n;
  while (i > 0 && j > 0) {
    if (str1.charAt(i - 1) === str2.charAt(j - 1)) { 
      lcsStr = str1.charAt(i - 1) + lcsStr; 
      i--;
      j--;  
    } 
    else if (dp[i - 1][j] > dp[i][j - 1]) { 
      i--; 
    }
    else {
      j--; 
    }
  }

  return lcsStr;
}

