function parseURL(url) {
  const urlReg = /^(?:([A-Za-z]+):)?(\/{0,3})([0-9.\-A-Za-z]+)(?::(\d+))?(?:\/([^?#]*))?(?:\?([^#]*))?(?:#(.*))?$/;
  const matches = url.match(urlReg);
  return {
    path: matches[5],
    queryParams: matches[6].split("&").reduce((a, param) => {
      const [key, value] = param.split("=");
      a[key] = value;
      return a;
    }, {})
  }
}

