class Node {
public:
    int value;
    Node* next;
    Node() {
        value = 0;
        next = nullptr;
    }
};


class LinkedList {
public:
    Node* head;
    Node* tail;
    int size;
    LinkedList() {
        head = tail = nullptr;
        size = 0;
    }

    // adds node to the end of list
    void add(int val) {
        Node* n = new Node();
        n->value = val;
        n->next = nullptr;
        if (head == nullptr) {
            head = n;
            tail = n;
        } else {
            tail->next = n;
            tail = n;
        }
        size++;
    } 

    //prints elements in a single linked list
    void print() {
        Node* curr = head;
        while (curr != nullptr) {
            cout << curr->value << " ";
            curr = curr->next;
        }
        cout << endl;
    }
};

