// A utility function to swap two elements 
void swap(int *x, int *y) 
{ 
    int temp = *x; 
    *x = *y; 
    *y = temp; 
} 

// Function to sort an array in decreasing order 
void BubbleSort(int nums[], int n) 
{ 
    int i, j; 
    for (i = 0; i < n-1; i++)      

    // Last i elements are already in place 
    for (j = 0; j < n-i-1; j++)  
        if (nums[j] < nums[j+1]) 
            swap(&nums[j], &nums[j+1]); 
} 

