public class Change {

    public static int calculateMinimumNumberOfCoins(int amount, int[] denominations) {
        // Initialize array to hold minimum number of coins
        // necessary to make change for each amount
        int[] minCoinCounts = new int[amount + 1];
        minCoinCounts[0] = 0; // Base case

        for (int curAmount = 1; curAmount <= amount; curAmount++) {
            int minCoinCount = curAmount; // worst case

            // Loop through all given denominations
            for (int j = 0; j < denominations.length; j++) {
                int denomination = denominations[j];
                if (denomination <= curAmount) {
                    int count = minCoinCounts[curAmount - denomination] + 1;
                    if (count < minCoinCount) minCoinCount = count;
                }
            }

            minCoinCounts[curAmount] = minCoinCount;
        }

        return minCoinCounts[amount];
    }

}

