def edit_distance(str1, str2):
    m = len(str1)
    n = len(str2)
    edit_table = [[0 for x in range(n+1)] for x in range(m+1)] 

    for i in range(m+1): 
        for j in range(n+1): 
            if i == 0: 
                edit_table[i][j] = j
            elif j == 0: 
                edit_table[i][j] = i
            elif str1[i-1] == str2[j-1]: 
                edit_table[i][j] = edit_table[i-1][j-1] 
            else: 
                edit_table[i][j] = 1 + min(edit_table[i][j-1], edit_table[i-1][j], edit_table[i-1][j-1]) 

    return edit_table[m][n]

def isAnagram(word1, word2):
    # remove white space and convert words to lower case
    word1 = word1.replace(" ", "").lower()
    word2 = word2.replace(" ", "").lower()

    # return False if length of words are not equal
    if len(word1) != len(word2):
        return False

    # create dictionaries with the count of each character in the respective words
    count_dict_word1 = {}
    for letter in word1:
        if letter in count_dict_word1:
            count_dict_word1[letter] += 1
        else:
            count_dict_word1[letter] = 1

    count_dict_word2 = {}
    for letter in word2: 
        if letter in count_dict_word2:
            count_dict_word2[letter] += 1
        else:
            count_dict_word2[letter] = 1

    # return True is the dictionaries are equal
    return count_dict_word1 == count_dict_word2

