function permutations(arr) {
    if (arr.length === 0) {
        return [];
    } else if (arr.length === 1) {
        return [arr];
    } else {
        let result = [];
        for (let i = 0; i < arr.length; i++) {
            let first_elem = arr.shift();
            let other_permutations = permutations(arr);
            other_permutations.forEach(function(p) {
                result.push([first_elem].concat(p))
            });
            arr.push(first_elem);
        }
        return result;
    }
}

def cluster_size(arr): 
  if len(arr) <= 1:
    return arr

  # Initializing the sorted array table
  cluster = [[arr[0]]]

  for i in range(1, len(arr)): 
    added = False
    for j in range(len(cluster)): 
      if arr[i] - 1 == cluster[j][-1] or arr[i] + 1 == cluster[j][-1]: 
        # If found add to the cluster 
        cluster[j].append(arr[i]) 
        added = True
        break

    # If not added to any cluster start new one
    if not added: 
      cluster.append([arr[i]]) 
  return cluster

