// This function will check if a given binary tree is a binary search tree
function isBST(node) {
    // base case
    if (node == null) {
        return true;
    }

    // check if the left subtree is a BST
    if (!isBST(node.left)) {
        return false;
    }

    // Check for every node if its data is greater than the max value in the left subtree.
    if (node.data < maxValue(node.left)) {
        return false;
    }

    // Check for every node if its data is smaller than the min value in the right subtree.
    if (node.data >= minValue(node.right)) {
        return false;
    }

    // Check if the right subtree is a BST
    if (!isBST(node.right)) {
        return false;
    }

    return true;
}

// function to get the maximum value in the left subtree
function maxValue(node) {
    let current = node;
    while (current.right != null) {
        current = current.right;
    }
    return current.data;
}

// function to get the mininum value in the right subtree
function minValue(node) {
    let current = node;
    while (current.left != null) {
        current = current.left;
    }
    return current.data;
}

