function path(GRAPH, START, GOAL) {
    // Create an empty path
    let path = [];
    // Add START to the path
    path.push(START);
    // WHILE the path does not reach GOAL
    while(path[path.length - 1] !== GOAL) {
        // Get the last node from the path
        let lastNode = path[path.length - 1];
        // For each neighbour
        for(let neighbour of GRAPH[lastNode]) {
            // IF the neighbour is not in the path
            if(!(path.includes(neighbour))) {
                // Add the neighbour to the path
                path.push(neighbour);
            }
        }
    }
    return path;
