def detect_biggest_square(matrix):
    '''This function takes a matrix and returns the coordinates for the biggest square 
    in the matrix. If there are multiple squares with the same size, it will return 
    the coordinates of any of them.'''
    max_size = 0
    coords = None

    for i in range(len(matrix)):
        for j in range(len(matrix[0])):
            size = 0
            if matrix[i][j] == 1:
                while i + size < len(matrix) and j + size < len(matrix[0]):
                    for x in range(i, i+size+1):
                        for y in range(j, j+size+1):
                            if matrix[x][y] == 0:
                                break
                    else:
                        size += 1
                    coords = (i, j, i+size, j+size)

            if size > max_size:
                max_size = size
                coords = (i, j, i+size, j+size)

    return coords

