def lcs(s1, s2): 
    m = len(s1) 
    n = len(s2) 

    matrix = [[0]*(n+1) for i in range(m+1)] 

    longest_length = 0
    lcs_set = set()

    for i in range(1, m + 1): 
        for j in range(1, n + 1): 
            if s1[i-1] == s2[j-1]: 
                matrix[i][j] = matrix[i-1][j-1] + 1
                if matrix[i][j] > longest_length: 
                    longest_length = matrix[i][j]
                    lcs_set = set()

                    lcs_set.add(s1[i-longest_length:i])

            else:
                matrix[i][j] = 0 

    if longest_length == 0: 
        return 0
    else:
        return lcs_set

