    return results;

    function getSubsetsHelper(arr, index, current){
        //add all elements to the results
        results.push([ ...current]);

        for (let i = index; i < arr.length; i++) {
            current.push(arr[i]);
            // move on to the next element
            getSubsetsHelper(arr, i + 1, current);
            // pop off the current element after exploring all 
            // its possibilities
