def traverse_spiral(matrix):
  # initialize the array to store the traversed path in
  path = [];

  # determine the number of rows and columns in the matrix
  rows = len(matrix);
  cols = len(matrix[0]);

  # start from the (0, 0) position
  row = 0;
  col = 0;

  # iterate through the rows and columns until the end of the matrix is reached
  while (row < rows and col < cols):
    # iterate through the columns of the current row
    for i in range(col, cols):
      path.append(matrix[row][i]);

    # increment the row
    row += 1;

    # iterate through the rows of the current column
    for i in range(row, rows):
      path.append(matrix[i][cols - 1]);

    # decrement the column
    cols -= 1;

    # check if we reached the final column
    if col < cols:
      # iterate through the columns in reverse order
      for i in range(cols-1, col-1, -1):
        path.append(matrix[rows-1][i]);

      # decrement the row
      rows -= 1;

    # check if we reached the final row
    if row < rows:
      # iterate through the rows in reverse order
      for i in range(rows-1, row-1, -1):
        path.append(matrix[i][col]);

      # increment the column
      col += 1; 

  # return the traversed path
  return path

