public static String getMixedColor(String color1, String color2) {
    // convert inputs to hex codes
    String hex1 = getHexCodeFromColor(color1);
    String hex2 = getHexCodeFromColor(color2);

    // calculate the mixed hex code
    String mixedHex = Integer.toString(Integer.parseInt(hex1, 16) ^ Integer.parseInt(hex2, 16));

    // convert hex to color
    return getColorFromHexCode(mixedHex);
}

