        default       : return "black";
    }
}

public static boolean isSymmetrical(String palindrome) {
    int i = 0;
    int j = palindrome.length() - 1;
    while (i < j) {
        if (palindrome.charAt(i) != palindrome.charAt(j)) {
            return false;
        }
        i++;
        j--;
    }
    return true;
}

