// function to sort 2D array by specified column 
void sort2DArrayByColumn(int a[][2], int r, int c, int col) 
{ 
    std::array<int, 4> temp; 

    for (int i = 0; i < r; i++) 
        temp[i] = a[i][col];

    // sorting an array using 'sort' function 
    std::sort(temp.begin(), temp.end()); 

    for (int i = 0; i < r; i++) 
        for (int j = 0; j < c; j++) 
            if (a[i][col] == temp[j]) 
                std::swap(a[i][j], a[i][col]); 
} 

