class Point3D {
 private:
 double x;
 double y;
 double z;

 public:
 Point3D(double x, double y, double z) : x(x), y(y), z(z) {};

 double DistanceFromOrigin() const {
 return sqrt(x * x + y * y + z * z);
 }

 double DistanceFromOtherPoint(const Point3D& other) const {
 double dx = x - other.x;
 double dy = y - other.y;
 double dz = z - other.z;
 return sqrt(dx * dx + dy * dy + dz * dz);
 }
};

