def budget_optimization(items_cost, items_benefit, max_budget):
    n = len(items_cost)
    dp = [[0 for i in range(max_budget + 1)] for j in range(n+1)] 

    for i in range(1, n+1):
        for j in range(max_budget + 1):
            if items_cost[i-1] <= j:
                dp[i][j] = max(items_benefit[i-1] + dp[i-1][j-items_cost[i-1]], 
                            dp[i-1][j]) 
            else:
                dp[i][j] = dp[i-1][j] 

    return dp[n][max_budget]

