fn count_characters(s: &str) -> std::collections::HashMap<char, usize> {
 let mut hashmap = std::collections::HashMap::new();

 for c in s.chars() {
  if hashmap.contains_key(&c) {
   hashmap.insert(c, hashmap.get(&c).unwrap() + 1);
  } else {
   hashmap.insert(c, 1);
  }
 }

 return hashmap;
}

