bool isPalindrome(int x) 
{ 
    int number = x; 
    int reverse = 0; 

    // calculate the reverse 
    while (number != 0) { 
        int remainder = number % 10; 
        reverse = (reverse * 10) + remainder; 
        number /= 10; 
    } 

    // Check if the original and reverse  
    // number is same or not 
    return (x == reverse); 
} 

