};

Node* optimize_queue(Node* head) {
   if (head == NULL || head->next == NULL)
     return head;

   Node* slow = head; 
   Node* fast = head->next; 

   // Check for duplicate elements
   while (fast != NULL) {
     if (slow->value == fast->value) {
       slow->next = fast->next; 
       delete(fast);
     }
     else {
        slow = fast;
     }
     fast = slow->next;
   }
   return head;
}

