def findMinimumCoins(coins, total):
    T = [float('inf') for i in range(total + 1)]
    T[0] = 0

    for i in range(1, total+1):
        for c in coins:
            if c <= i:
                coins_used = T[i - c] + 1
            else:
                coins_used = float('inf')
            T[i] = min(T[i], coins_used) 
