const int MAX = 100;  

class Queue { 
  int arr[MAX]; 
  int front; 
  int rear; 

  public: 
  Queue() 
  { 
    front = -1;  
    rear = -1; 
  } 

  void enqueue(int x); 
  int dequeue(); 
  bool isEmpty(); 
}; 

bool Queue::isEmpty() 
{ 
    return (front == -1 && rear == -1); 
} 

void Queue::enqueue(int x) 
{ 
    if (rear == MAX - 1)  
        cout << "Queue is Full\n"; 
    else { 
        if (front == -1) 
            front = 0; 
        arr[++rear] = x; 
        cout << x << " enqueued to queue\n"; 
    } 
} 

int Queue::dequeue() 
{ 
    if (isEmpty())  
        return -1; 
    int data = arr[front]; 
    arr[front] = -1; 
    if (front == rear) 
        front = rear = -1; 
    else
        front++; 
    return data; 
} 

