	int length = inputMatrix.length;
	int[][] outputMatrix = new int[length][length];

	for (int row = 0; row < length; row++) {
		for (int col = 0; col < length; col++) {
			outputMatrix[col][length - 1 - row] = inputMatrix[row][col];
		}
	}

	for (int row = 0; row < length; row++) {
		for (int col = 0; col < length; col++) {
