public static int convertBinaryToInteger(String binaryString) {
    int result = 0;
    int power = 0;

    for(int i = binaryString.length()-1; i >= 0; i--) {
        result += Character.getNumericValue(binaryString.charAt(i)) * Math.pow(2, power);
        power++;
    }
    return result;
}

