def validate_cc(number):
    """This function validates a credit card number according to the Luhn algorithm."""
    # ------------------
    # Reverse the number by taking off the last digit and adding it to the front
    reversed_number = number[-1] + number[:-1]

    # Create a list of numbers
    num_list = list(map(int, reversed_number))

    # Double every other number
    for i in range(0,len(num_list), 2):
        num_list[i] *= 2

    # Subtract 9 from numbers over 9
    for i in range(0, len(num_list)):
        if num_list[i] > 9:
            num_list[i] -= 9

    # Get the sum of all the numbers
    if sum(num_list) % 10 == 0:
        return True
    else:
