    static char getCharOnce(String string1, String string2) 
    { 
        // Make an array to store all characters 
        // appearing in the first string 
        int[] characters = new int[256]; 

        // Increase the count for all  
        // characters in the first string 
        for (int i = 0; i < string1.length(); i++)  
            characters[string1.charAt(i)]++; 

        // Decrease the count for all  
        // characters in the second string 
        for (int i = 0; i < string2.length(); i++)  
            characters[string2.charAt(i)]--; 

        // Iterate through the array to find the character 
