function isValidCard(cardNumber) {
  // Sanity check
  if (!cardNumber || typeof cardNumber !== 'string') {
    return false;
  } 

  // Convert card number to have correct format
  cardNumber = cardNumber.replace(/\s*/g, '').replace(/-*/g, ''); 

  // Check if length of card number is correct
  if (cardNumber.length < 13 || cardNumber.length > 19) {
    return false;
  } 

  // Check that each character is valid
  for (let i = 0; i < cardNumber.length; i++) {
    let char = cardNumber[i];
    if (!/[0-9]/.test(char)) {
      return false;
    } 
  } 

  // Check if Luhn algorithm is valid
  let flag = true;
  let sum = 0;
  for (let i = cardNumber.length - 1; i >= 0; i--) {
    let char = cardNumber[i];
    // Double the sum for every second digit
    if ((cardNumber.length - i) % 2 === 0) {
      let doubled = parseInt(char, 10) * 2;
      doubled = (doubled >= 10 ? doubled - 9 : doubled);
      sum += doubled;
    } else {
      let num = parseInt(char, 10);
      sum += num;
    }
  }
  if (sum % 10 !== 0) {
    flag = false;
  }

  return flag;
}

