    for char in infixExpression:
        if char in "ABCDEFGHIJKLMNOPQRSTUVWXYZ" or char in "0123456789":
            postfixExpression = postfixExpression + char
        else:
            stack.append(char)

    while len(stack) > 0:
        postfixExpression = postfixExpression + stack.pop()

    return postfixExpression

