public class Library {
    public class Book {
        public int id;
        public String title;
        public Book previous;
        public Book next;

        public Book(int id, String title) {
            this.id = id;
            this.title = title;
        }
    }

    private Book head;
    private Book tail;

    public void addBook(Book book) {
        if (head == null) {
            head = book;
            tail = book;
            book.previous = null;
        } else {
            tail.next = book;
            book.previous = tail;
            tail = book;
        }
    }

    public void removeBook(Book book) {
        if (head == book) {
            head = book.next;
            if (head != null)
                head.previous = null;
            else
                tail = null;
        } else if (tail == book) {
            tail = book.previous;
            if (tail != null)
                tail.next = null;
        } else {
            book.previous.next = book.next;
            book.next.previous = book.previous;
        }
    }
}

