double convertStringToDouble(string str) 
{ 
    int decimal_position = str.find("."); 
    string whole_string = str.substr(0, decimal_position); 
    string fraction_string = str.substr(decimal_position + 1); 
    int whole_number = stoi(whole_string); 
    int fraction_number = stoi(fraction_string); 
    double fractional_part = fraction_number / pow(10, fraction_string.length()); 
    return whole_number + fractional_part; 
} 

