function leastSquares(data) {
  let sumX = 0;
  let sumY = 0;
  let sumXY = 0;
  let sumXX = 0;
  let n = data.length;

  data.forEach(point => {
    sumX += point[0];
    sumY += point[1];
    sumXY += point[0] * point[1];
    sumXX += point[0] * point[0];
  });

  let b = (sumXY - (sumX * sumY) / n) / (sumXX - (sumX * sumX) / n);
  let a = (sumY - b * sumX) / n;

  return [a, b];
}

def quick_sort(arr):

    if len(arr) < 2:
        return arr

    pivot = arr[0]
    left_arr, right_arr = [], []

    for i in range(1, len(arr)):
        if arr[i] <= pivot:
            left_arr.append(arr[i])

        else:
            right_arr.append(arr[i])

    return quick_sort(left_arr) + [pivot] + quick_sort(right_arr)

