class ItemPriceInfo { 
  private Map<String, Double> itemPrices; 
  private Map<String, Map<Month, Double>> itemMonthlyPrices; 

  public ItemPriceInfo() { 
    itemPrices = new HashMap<>(); 
    itemMonthlyPrices = new HashMap<>(); 
  } 

  // Sets the current price of an item 
  public void setPrice(String itemName, double price) { 
    itemPrices.put(itemName, price); 
  } 

  // Sets the price of an item for a specific month 
  public void setPriceForMonth(String itemName, Month month, double price) { 
    if (!itemMonthlyPrices.containsKey(itemName)) { 
      Map<Month, Double> prices = new HashMap<>(); 
      itemMonthlyPrices.put(itemName, prices); 
    } 
    itemMonthlyPrices.get(itemName).put(month, price); 
  } 

  // Get the current price of an item 
  public double getPrice(String itemName) { 
    if (!itemPrices.containsKey(itemName)) { 
      return 0.0; 
    } 
    return itemPrices.get(itemName); 
  } 

  // Get the price of an item for a specific month 
  public double getPriceForMonth(String itemName, Month month) { 
    if (!itemMonthlyPrices.containsKey(itemName)) { 
      return 0.0; 
    } 
    if (!itemMonthlyPrices.get(itemName).containsKey(month)) { 
      return 0.0; 
    } 
    return itemMonthlyPrices.get(itemName).get(month); 
  } 
}

