def compress_string(input_string): 
    result = "" 

    count = 1
    prev_char = input_string[0] 
    result += prev_char 

    for i in range(1,len(input_string)): 
        curr_char = input_string[i] 
        if (prev_char == curr_char): 
            count+=1
        else: 
            if(count > 1): 
                result += str(count)
            prev_char = curr_char 
            result += prev_char 
            count = 1
    if(count > 1): 
        result += str(count)

    return result 

