#include <stack>

void reverseStack(std::stack<int>& s) {
 // If stack is empty, exit 
 if (s.empty()) {
  return;
 }

 int top = s.top();
 s.pop();

 // Recursively call function to reverse stack
 reverseStack(s);

 // Push one element into result and then rest of the stack
 pushToBottom(s, top);

 // Utility function to push element to bottom of stack
 void pushToBottom(std::stack<int>& s, int data) {
  if (s.empty()) {
   s.push(data);
   return;
  }
  // Pop element from stack
  int top = s.top();
  s.pop();
  // Recursively push all elements except the last one to bottom of stack
  pushToBottom(s, data);
  // Push the last element into the stack
  s.push(top);
 }
}

