def longest_common_subsequence(s1, s2): 
    # Create a table to store sizes of subproblems
    matrix = [[0]*(len(s2)+1) for _ in range(len(s1)+1)]

    # Iterate through the string to find the longest common subsequence
    for i in range(len(s1)):
        for j in range(len(s2)):
            if s1[i]==s2[j]:
                matrix[i+1][j+1] = matrix[i][j] +1
            else:
                # choose the length of the larger subsequence
                matrix[i+1][j+1] = max(matrix[i+1][j], matrix[i][j+1])

    # calculate the length of the longest common subsequence 
    result = matrix[-1][-1] 

    # build the longest common subsequence
    lcs = "" 
    x, y = len(s1), len(s2) 
    while x != 0 and y != 0: 
        # Check if the current character in s1 and s2 are same
        if s1[x-1] == s2[y-1]: 
            # Append the character to the result 
            lcs = s1[x-1] + lcs 
            # reduce values of x and y
            x-=1
            y-=1
        elif matrix[x-1][y] > matrix[x][y-1]: 
            # Move up in matrix 
            x-=1
        else: 
            # Move left in matrix
            y-=1

    return (lcs, result)

