int maxSubArraySum(int arr[], int n, int k) 
{ 
    int max_sum = 0; 

    for (int i = 0; i < k; i++) 
        max_sum += arr[i]; 

    int current_sum = max_sum; 

    for (int i = k; i < n; i++) { 
        current_sum += arr[i] - arr[i - k]; 
        max_sum = max(current_sum, max_sum); 
    } 

    return max_sum; 
} 

