// Function to find the symmetric difference of two sets
vector<int> symmetric_diff(vector<int> a, vector<int> b){
 vector<int> result;

 // For each element in Set A, check if it is in Set B.
 // If it is not in Set B, add it to the result.
 for (int i=0; i<a.size(); i++)
 {
 if (find(b.begin(), b.end(), a[i]) == b.end())
 result.push_back(a[i]);
 }

 // For each element in Set B, check if it is in Set A.
 // If it is not in Set A, add it to the result.
 for (int i=0; i<b.size(); i++)
 {
 if (find(a.begin(), a.end(), b[i]) == a.end())
 result.push_back(b[i]);
 }

 return result;
}

