const int motorPin3 = 10;      // Motor 3 pin
const int motorPin4 = 11;      // Motor 4 pin

bool forward = true;        // Set motor motion forward
int position = 0;           // Initial position

void setup()
{ 
 pinMode(limitSwitchPin, INPUT);
 pinMode(motorPin1, OUTPUT);
 pinMode(motorPin2, OUTPUT);
 pinMode(motorPin3, OUTPUT);
 pinMode(motorPin4, OUTPUT);
}

void loop()
{
 // Check if the limit switch is pressed 
 if (digitalRead(limitSwitchPin) == HIGH) {
  stopMotor();
  forward = false;
 }

 if (forward) {
  moveStepper(position);
  position++;

  if (position == 3600) {
   forward = false;
   position = 0; 
  } 
 }
 delay(1);
}

void moveStepper(int step)
{
 digitalWrite(motorPin1, step % 2);
 digitalWrite(motorPin2, (step + 1) % 2);
 digitalWrite(motorPin3, (step + 2) % 2);
 digitalWrite(motorPin4, (step + 3) % 2);
}

void stopMotor()
{
 digitalWrite(motorPin1, LOW);
 digitalWrite(motorPin2, LOW);
 digitalWrite(motorPin3, LOW);
 digitalWrite(motorPin4, LOW);
}

