public class PalindromeNumber {
    public static boolean isPalindrome(int n) {
        int original = n; 
        int reverse = 0;

        while(n != 0) {
            reverse *= 10; 
            reverse += n % 10;
            n /= 10;
        }

        return (reverse == original);
    }

    public static void main(String[] args) {
        int num = 14541;
        if(isPalindrome(num)) {
            System.out.println("The number "+num+" is a palindrome.");
