function calculator(expression) {
    let queue = []
    let result = 0
    let num = ''
    let operator

    // iterate through the expression
    for (let i = 0; i < expression.length; i++) {
        let ch = expression[i]

        if (isOperator(ch)) {
            // push number to queue
            if (num !== '') queue.push(parseFloat(num))
            // push operator to queue
            queue.push(ch)
            num = ''
        } else {
            // store the number
            num += ch
        }
    }
    // push the last number to queue
    if (num !== '') queue.push(parseFloat(num))

    // iterate through the queue and calculate result
    while (queue.length > 0) {
        if (isOperator(queue[0])) {
            operator = queue[0]
            let num1 = queue[1]
            let num2 = queue[2]

            switch (operator) {
                case '+':
                    queue.splice(0, 3, num1 + num2)
                    break
                case '-':
                    queue.splice(0, 3, num1 - num2)
                    break
                case '*':
                    queue.splice(0, 3, num1 * num2)
                    break
                case '/':
                    queue.splice(0, 3, num1 / num2)
                    break
            }
        } else {
            result = queue[0]
            queue.splice(0, 1)
        }
    }

    return result
}

function isOperator(ch) {
    return ch === '+' || ch === '-' || ch === '*' || ch === '/'
}

