def bubble_sort(nums): 
    # Swap the elements to arrange in order 
    for i in range(len(nums)-1,0,-1): 
        for j in range(i): 
            if nums[j]>nums[j+1]: 
                temp = nums[j] 
                nums[j] = nums[j+1] 
                nums[j+1] = temp 

    return nums

def max_min(a,b,c):
    max = a 
    min = a

    if b > max:
        max = b

    if c > max:
        max = c

    if b < min:
        min = b

    if c < min:
        min = c

    return max, min

