// Function to check if a number is prime 
function isPrime(num) 
{ 
    // 1 is not a prime 
    if (num <= 1) 
        return false; 

    // Since 2 is prime 
    if (num == 2)  
        return true; 

    // 3 is prime 
    if (num == 3)  
        return true; 

    // Numbers divisible by 2, 3 are not prime 
    if (num % 2 == 0 || num % 3 == 0) 
        return false; 

    // Check if number is divisible upto square root 
    for (var i = 5; i * i <= num; i = i + 6)  
    { 
        if (num % i == 0 || num % (i + 2) == 0) 
            return false; 
    } 

    return true; 
}

