struct ListNode *getIntersectionNode(struct ListNode *a, struct ListNode *b)
{
    int lenA = 0, lenB = 0;
    struct ListNode *currA = a, *currB = b;

    while (currA != NULL) 
    {
        lenA++;
        currA = currA->next;
    }

    while (currB != NULL) 
    {
        lenB++;
        currB = currB->next;
    }

    currA = a;
    currB = b;
    if (lenA > lenB) 
    {
        for (int i = 0; i < lenA - lenB; i++)
            currA = currA->next;
    }
    else 
    {
        for (int i = 0; i < lenB - lenA; i++)
            currB = currB->next;
    }
    while (currA != NULL && currB != NULL)
    {
        if (currA == currB) return currA;
        currA = currA->next;
        currB = currB->next;
    }
    return NULL;
}

