# Constants for the game
X = "X"
O = "O"
EMPTY = None

class NoughtsAndCrosses: 
 def __init__(self):
 self.board = [[EMPTY, EMPTY, EMPTY],
 [EMPTY, EMPTY, EMPTY],
 [EMPTY, EMPTY, EMPTY]]

 # Player X goes first
 self.turn = X

 # Total number of moves played
 self.count = 0

 def move(self, row, col):
 # Validate move
 if self.board[row][col] != EMPTY:
 return

 # Apply move
 self.board[row][col] = self.turn

 # Update turn and move count
 if self.turn == X:
 self.turn = O
 else:
 self.turn = X
 self.count += 1

 def game_over(self):
 # Check for a draw
 if self.count == 9:
 return True

 # Check for a winner
 for i in range(0, 3):
 # Check Horizontal 
 if self.board[i][0] == self.board[i][1] == self.board[i][2] != EMPTY:
 return True
 # Check Vertical 
 if self.board[0][i] == self.board[1][i] == self.board[2][i] != EMPTY:
 return True
 # Check Diagonal
 if self.board[0][0] == self.board[1][1] == self.board[2][2] != EMPTY:
 return True
 if self.board[0][2] == self.board[1][1] == self.board[2][0] != EMPTY:
 return True

 return False

 # Print board
 def display_board(self):
 print('---' * 3)
 for row in self.board:
 print('|', end=" ")
 for cell in row:
 if cell == EMPTY:
 print(' ', end=" | ")
 elif cell == X:
 print('X', end=" | ")
 else:
 print('O', end=" | ")
 print('')
 print('---' * 3)

