def mostCommonSubstring(string, n, k):
    # create a dictionary to store the substrings
    # key: substring, value: count
    substr_dict = {}

    # iterate through the characters in the string
    for i in range(len(string)-k+1):
        # loop over the range of the substring
        for j in range(i+k, i+k+n):
            # create the substring
            substr = string[i:j]
            # increment the count for the substring
            if substr in substr_dict:
                substr_dict[substr] += 1
            else:
                substr_dict[substr] = 1

    # find the most common substring
    max_val = 0
    max_substr = ""
    for key, value in substr_dict.items():
        if value > max_val:
            max_val = value
            max_substr = key

    # return the most common substring
    return max_substr

