def infix_to_postfix(expression):
    stack = []
    result = []

    for char in expression:
        if char.isdigit():
            result.append(char)
        elif char == '(':
            stack.append(char)
        elif char == ')':
            while stack[-1] != '(':
                result.append(stack.pop())
            stack.pop()
        else:
            while stack and priority(char) <= priority(stack[-1]):
                result.append(stack.pop())
            stack.append(char)
    while stack:
        result.append(stack.pop())
    return result

