public class LowestCommonAncestor {

  // Root of the Binary Tree 
  Node root;

  // Finds the path from root node to given root of the tree. 
  ArrayList<Integer> path1 = new ArrayList<>(); 
  ArrayList<Integer> path2 = new ArrayList<>(); 

  // Finds the path from root node to given root of the tree, Stores the 
  // path in a vector path[], returns true if path exists otherwise false 
  boolean findPath(Node root, int n1, ArrayList<Integer> path) {

    // base case 
    if (root == null) 
        return false; 

    // Store this node . The node will be removed if 
    // not in path from root to n1. 
    path.add(root.data); 

    if (root.data == n1) 
        return true; 

    // Check if n1 is found in left or right sub-tree 
    if (findPath(root.left, n1, path) 
            || findPath(root.right, n1, path)) 
        return true; 

    // If not present in subtree rooted with root, remove root from 
    // path[] and return false 

    path.remove(path.size() - 1); 

    return false; 
  } 

  // Returns LCA if node n1 , n2 are present in the given binary tree, 
  // otherwise return -1 
  int findLCA(int n1, int n2) {
    // To store paths to n1 and n2 from the root 
    ArrayList<Integer> path1 = new ArrayList<>(); 
    ArrayList<Integer> path2 = new ArrayList<>(); 

    // Find paths from root to n1 and root to n2. 
    // If either n1 or n2 is not present , return -1  
    if (!findPath(root, n1, path1) || !findPath(root, n2, path2)) 
        return -1; 

    int i; 
    for (i = 0; i < path1.size() && i < path2.size(); i++) 

        // Check if the array elements are same 
        // at index i 
        if (!path1.get(i).equals(path2.get(i))) 
            break; 

    return path1.get(i - 1); 
  }

}

