// Function to merge two sorted arrays 
// into one sorted array 
void merge(int arr1[], int size1, 
           int arr2[], int size2,  
           int arr3[]) 
{ 
    int i = 0, j = 0, k = 0; 

    // Merging the two sorted arrays 
    while (i<size1 && j <size2) 
    { 
        // Check which element is smaller 
        // and insert it into the array 
        if (arr1[i] < arr2[j]) 
            arr3[k++] = arr1[i++]; 
        else
            arr3[k++] = arr2[j++]; 
    } 

    // Inserting remaining elements of arr1 
    while (i < size1) 
        arr3[k++] = arr1[i++]; 

    // Inserting remaining elements of arr2 
    while (j < size2) 
        arr3[k++] = arr2[j++]; 
} 

// Function to print the merged array 
void display(int arr3[], int size) 
{ 
    for (int i=0; i < size; i++) 
        printf("%d ", arr3[i]); 
} 

