        let result; 
        if (a[key] > b[key]) { 
            result = 1; 
        } else if (a[key] < b[key]) { 
            result = -1; 
        } else { 
            result = 0; 
        } 

        if (order === "desc") { 
            result *= -1; 
        } 
        return result; 
    }; 
    arr.sort(compare); 
    return arr; 
}

public class LongestIncreasingSubsequence {
	// Returns the length of the longest increasing subsequence
	public static int findLIS(int[] arr) {
		int n = arr.length, max = 1;

		// Create an array to store individual
		// LIS of each index
		int[] lis = new int[n];

		Arrays.fill(lis, 1);

		// Compute longest increasing subsequence
		// for each index
		for (int i = 1; i < n; i++)
			for (int j = 0; j < i; j++)
				if (arr[i] > arr[j] && lis[i] < lis[j] + 1)
					lis[i] = lis[j] + 1;

		// Find the maximum value
		for (int i = 0; i < n; i++)
			if (max < lis[i])
				max = lis[i];

		return max;
	}

	public static void main(String[] args) {
		int arr[] = { 10, 9, 2, 5, 3, 7, 101, 18 };
		int n = arr.length;
		System.out.println("Length of lis is " + findLIS(arr));
	}
}

// Factorial function
function factorial(num) {
  if (num == 0) {
    return 1;
  }
  else {
    return num * factorial(num - 1);
  }
}

// Fibonacci function
function fibonacci(num) {
  if (num == 0 || num == 1) {
    return num;
  }
  else {
    return fibonacci(num - 1) + fibonacci(num - 2);
  }
}

