public static String replaceAllSubstrings(String str, String find, String replace) {
    // Get the start position of the substring
    int pos = str.indexOf(find);

    // If the substring is not present, returns the original string
    if (pos == -1) return str;

    // Create the new string and replace each occurrence of the substring
    StringBuilder sb = new StringBuilder();
    while (pos != -1) {
        sb.append(str.substring(0, pos));
        sb.append(replace);
        pos += find.length();
        str = str.substring(pos);
        pos = str.indexOf(find);
    }
    sb.append(str);

    // Return the updated string
    return sb.toString();
}

