def reduceTimeComplexity(n, arr): 

    dp = [1 for i in range(n+1)] 

    for i in range(1, n+1): 

        for j in range(i + 1, n+1): 
            if arr[i - 1] > arr[j - 1] and dp[j] < dp[i] + 1: 
                dp[j] = dp[i] + 1

    return max(dp)

