    static int kFib(int n, int k)
    { 
        int f[] = new int[n + 1]; 

        f[0] = 0; 
        f[1] = 1; 

        for (int i = 2; i <= n; i++) 
        { 
            int sum = 0; 
            for (int j = 1; j <= k && j <= i ; j++) 
            sum += f[i-j]; 

            f[i] = sum; 
        } 

