def allocate_processes(processors, costs):
    num_processors = len(processors)
    num_processes = len(costs)
    dp = [[[0 for k in range(num_processes)] for j in range(num_processors)] 
          for i in range(num_processes)]


    for i in range(num_processors):
        dp[0][i][0] = costs[0][i]

    for i in range(num_processes):
        dp[i][0][i] = costs[i][0]

    for i in range(1, num_processors):
        for j in range(1, num_processes):
            temp_cost = float('inf')
            for k in range(j):
                new_cost = dp[k][i - 1][j - 1] + costs[j][i]
                if new_cost < temp_cost:
                    temp_cost = new_cost
            dp[j][i][j] = temp_cost

    return dp[-1][-1]

