def knapsack(weights, values, maxW): 
    if len(values) == 0 or maxW == 0 : 
        return 0

    if (weights[-1] > maxW): 
        return knapsack(weights[:-1], values[:-1], maxW) 

    return max(values[-1] + knapsack(weights[:-1], values[:-1], 
                                        maxW - weights[-1]), 
                   knapsack(weights[:-1], values[:-1], maxW))

