func evaluatePostfix(expression: String) -> Int {
    var stack: [Int] = []

    let expressionItems = expression.characters.split(separator: " ").map(String.init)

    for item in expressionItems {

        if let number = Int(item) {
            stack.append(number)
        } else {
            if stack.count < 2 {
                return -1
            }

            guard let op1 = stack.popLast(), let op2 = stack.popLast() else {
                return -1
            }
            switch item {
            case "+":
                stack.append(op1 + op2)
            case "-":
                stack.append(op2 - op1)
            case "*":
                stack.append(op1 * op2)
            default:
                stack.append(op2 / op1)
            }
        }
    }

    guard let result = stack.last else {
        return -1
    }

    return result
}

