public class FindMinPath {
  public static int minCost(int[][] matrix) {
    int m = matrix.length;
    int n = matrix[0].length;

    int[][] dp = new int[m][n];

    dp[0][0] = matrix[0][0];

    // Initialize first row of dp table
    for (int i = 1; i < n; i++)
      dp[0][i] = dp[0][i - 1] + matrix[0][i];

    // Initialize first column of dp table
    for (int i = 1; i < m; i++)
      dp[i][0] = dp[i - 1][0] + matrix[i][0];

    // Construct the remaining dp table
    for (int i = 1; i < m; i++) {
      for (int j = 1; j < n; j++)
        dp[i][j] = Math.min(dp[i - 1][j], dp[i][j - 1]) + matrix[i][j];
    }

    return dp[m - 1][n - 1];
  }

  public static void main(String[] args) {
    int[][] matrix = { { 3, 4, 2 }, { 1, 8, 7 }, { 5, 6, 4 } };
    System.out.println("Minimum cost: " + minCost(matrix));
  }
}

