function calculateRPN(tokens) {
 let stack = [];
 for (let i = 0; i < tokens.length; i++) {
 let token = tokens[i];
 if (!isNaN(token)) {
 stack.push(token);
 } else {
 let b = parseInt(stack.pop(), 10);
 let a = parseInt(stack.pop(), 10);

 switch (token) {
 case '+':
 stack.push(a + b);
 break;
 case '-':
 stack.push(a - b);
 break;
 case '*':
 stack.push(a * b);
 break;
 case '/':
 stack.push(a / b);
 break;
 }
 }
 }

 return parseInt(stack.pop(), 10);
}

