def getIntersectionNode(headA, headB): 
    currA = headA 
    currB = headB

    # Traverse both lists, if either of them reaches the end, 
    # switch traversal list. 
    while (currA != currB): 

        # If one of them reaches the end, switch head
        if currA == None: 
            currA = headB 
        else: 
            currA = currA.next

        if currB == None: 
            currB = headA 
