def longestPalindrome(string):
    longestPal = ""
    for i in range(len(string)):
        # get the longest odd length palindrom
        oddPal = palindromHelper(string, i, i)
        if len(oddPal) > len(longestPal):
            longestPal = oddPal

        # get the longest even length palindrom
        evenPal = palindromHelper(string, i, i+1)
        if len(evenPal) > len(longestPal):
            longestPal = evenPal

    return longestPal

def palindromHelper(string, left, right):
    while(left >= 0 and right <len(string) and string[left] == string[right]):
        left-=1
        right+=1
    return string[left+1:right]

