public class Calculator {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String input;
        double first, second, result;
        char operation;

        System.out.print("Enter equation: ");
        input = scanner.nextLine();

        int index = input.indexOf('+');
        if (index != -1) {
            first = Double.parseDouble(input.substring(0, index));
            second = Double.parseDouble(input.substring(index + 1));
            operation = '+';
        } else {
            index = input.indexOf('-');
            if (index != -1) {
                first = Double.parseDouble(input.substring(0, index));
                second = Double.parseDouble(input.substring(index + 1));
                operation = '-';
            } else {
                index = input.indexOf('*');
                if (index != -1) {
                    first = Double.parseDouble(input.substring(0, index));
                    second = Double.parseDouble(input.substring(index + 1));
                    operation = '*';
                } else {
                    index = input.indexOf('/');
                    if (index != -1) {
                        first = Double.parseDouble(input.substring(0, index));
                        second = Double.parseDouble(input.substring(index + 1));
                        operation = '/';
                    }
                }
            }
        }

        switch (operation) {
            case '+':
                result = first + second;
                break;
            case '-':
                result = first - second;
                break;
            case '*':
                result = first * second;
                break;
            case '/':
                result = first / second;
                break;
            default:
                result = 0;
                break;
        }

        System.out.println(input + " = " + result);
    }
}

