function longestPalindrome(str) {
  let longestPalindrome = "";

  for (let i = 0; i < str.length; i++) {
    for (let j = 0; j < 2; j++) {
      let leftIndex = i;
      let rightIndex = i + j;

      while (str[leftIndex] && str[rightIndex] && str[leftIndex] === str[rightIndex]) {
        let subString = str.slice(leftIndex, rightIndex + 1);
        if (subString.length > longestPalindrome.length) {
          longestPalindrome = subString;
        }
        leftIndex--;
        rightIndex++;
      }
    }
  }
  return longestPalindrome;
}

