func solve(board: inout [[Int]]) -> [[Int]] {
    let rows = board.count
    let columns = board[0].count

    for i in 0..<rows {
        for j in 0..<columns {
            if board[i][j] == 0 {
                for num in 1...9 {
                    if checkValidity(num, i, j, board) {
                        board[i][j] = num
                        if solve(board: &board) {
                            return board
                        } else {
                            board[i][j] = 0
                        }
                    }
                }
                return board
            }
        }
    }
    return board
}

func checkValidity(_ target: Int, _ row: Int, _ column: Int, _ board: [[Int]]) -> Bool {
    for i in 0..<board[0].count {
        if board[row][i] == target {
            return false
        }
        if board[i][column] == target {
            return false
        }
    }

    let rowStartIndex = row - row % 3
    let colStartIndex = column - column % 3

    for i in rowStartIndex..<rowStartIndex + 3 {
        for j in colStartIndex..<colStartIndex + 3 {
            if board[i][j] == target {
                return false
            }
        }
    }
    return true
}

