function minOperations(text1, text2) {
 const m = text1.length;
 const n = text2.length;
 const dp = new Array(m + 1); 

 for (let i = 0; i <= m; i++) {
   dp[i] = new Array(n + 1).fill(0);
 }

 for (let i = 1; i <= m; i++) 
   for (let j = 1; j <= n; j++) 
     if (text1.charAt(i - 1) === text2.charAt(j - 1)) 
       dp[i][j] = dp[i - 1][j - 1] + 1; 
     else
       dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]); 

 return m + n - (2 * dp[m][n]); 

}

