public Node middleNode(Node head) 
    { 
         // Base cases 
        if (head == null) 
            return head; 
        if (head.next == null) 
            return head; 

        Node slow = head; 
        Node fast = head; 

        // Move fast by two and slow by one 
        // Finally slow will point to the middle node 
        while (fast != null && fast.next != null) { 
            slow = slow.next; 
            fast = fast.next.next; 
        } 

        return slow; 
    }

public static void rotate(int[] array, int k) {
