// Function to find the maximum value
int optimalValue(int weight[], int val[], int n, int capacity) 
{ 
    // Base case
    if (n == 0 || capacity == 0) 
        return 0; 

    // If the item can't fit in the bag then can't include
    if (weight[n - 1] > capacity) 
        return optimalValue(weight, val, n - 1, capacity); 

    // Otherwise follow the below recurrence
    else { 
        // include the nth item
        int includeNth = val[n - 1] + optimalValue(weight, val, n - 1, capacity - weight[n - 1]); 

        // exclude the nth item
        int excludeNth = optimalValue(weight, val, n - 1, capacity); 

        return max(includeNth, excludeNth); 
    } 
} 

// return likes of the items chosen
int[] optimalSolution(int weight[], int val[], int n, int capacity) 
{ 
    // stores the items chosen
    int included[] = new int[n];

    int optimal_value = optimalValue(weight, val, n, capacity); 

    int opValue = optimal_value;

    int i = n - 1; 
    while (i > 0 && opValue > 0) { 
        // if the value is same after excluding the 
        // last item, the item was not part of the
        // optimal solution
        if (opValue == optimalValue(weight, val, i, 
                                              capacity)) 
        { 
            included[i] = 0; 
        } 
        else {
            // else include the item
            included[i] = 1; 
            // the value of the solution decreases  
            // by the value of the item included
            opValue = opValue - val[i]; 
            // decrease the capacity by the item's 
            // weight
            capacity = capacity - weight[i]; 
        } 
        i--; 
    } 

    if (optimal_value == optimalValue(weight, val, i, capacity)) 
        included[i] = 0; 
    else
        included[i] = 1; 

    return included; 
  }

