def eval(expr):
  if expr == '':
    return 0
  tokens = expr.split()
  stack = []
  for token in tokens:
    if token in ['+', '-', '*', '/']:
      op2 = stack.pop()
      op1 = stack.pop()
      result = eval(str(op1) + token + str(op2))
      stack.append(result)
    else:
      stack.append(int(token)) 
  return stack.pop()

