// Function to encrypt a string
string encryption(string text, int shift) {
  string result = "";
  for (int i = 0; i < text.length(); i++) {
    char character = text[i];
    // Preserve whitespace
    if (character == ' ') {
      result += ' ';
    } else {
      // Encrypt both capital and lower case letter
      if (character >= 65 && character <= 90) {
        int characterNum = character + shift;
        if (characterNum > 90) { 
          characterNum = (characterNum - 90) + 64; 
        }
        character = (char)characterNum;
      } else if (character >= 97 && character <= 122) {
        int characterNum = character + shift; 
        if (characterNum > 122) { 
          characterNum = (characterNum - 122) + 96; 
        }
        character = (char)characterNum;
      } else {
        character = character;
      }
      result += character;
    }
  }
  return result;
}

