	public static String encryptDecrypt(String inputString, byte[] keyStream) { 
		char[] inputStringArray = inputString.toCharArray(); 

		for (int i = 0; i < inputStringArray.length; i++) { 
			inputStringArray[i] = (char) (inputStringArray[i] ^ (keyStream[i % keyStream.length])); 
		} 

		return new String(inputStringArray); 
	} 
}

