function shortestPath(startX, startY, endX, endY) {
 let path = [];
 let stepX = (endX - startX) / Math.abs(endX - startX);
 let stepY = (endY - startY) / Math.abs(endY - startY);

 let x = startX;
 let y = startY;

 while (x != endX || y != endY) {
 let deltaX = (Math.abs(endX - x) < Math.abs(stepX)) ? Math.abs(endX - x) : Math.abs(stepX);
 let deltaY = (Math.abs(endY - y) < Math.abs(stepY)) ? Math.abs(endY - y) : Math.abs(stepY);

 if (deltaX > deltaY) {
 path.push({x, y + deltaY * stepY});
 y += deltaY * stepY;
 } else {
 path.push({x + deltaX * stepX, y});
 x += deltaX * stepX;
 }
 }

 return path;
}

