 let i = 0;
 let j = str.length - 1;
 let count = 0;

 while (j > i){
  if (str[i] === str[j]){
   i++;
   j--;
  } else {
   count++;
   if (str[i+1] === str[j]){ // Add char to begining
    str = str.slice(0, i) + str[j] + str.slice(i);
    i++;
    j--;
   } else { // Add char to end 
    str = str.slice(0, j+1) + str[i] + str.slice(j+1);
    i++;
    j--;
   }
  }
 }

 return count;
