// function for bubble sort 
void bubbleSort(int arr[], int n)  
{  
    // Outer loop - need n-1 iteration
    for (int i = 0; i < n-1; i++)          
    { 
        // Inner loop - last i elements are already in place  
        for (int j = 0; j < n-i-1; j++)  
            if (arr[j] > arr[j+1])  
            { 
                // swap arr[j] and arr[j+1] 
                int temp = arr[j]; 
                arr[j] = arr[j+1]; 
                arr[j+1] = temp; 
            } 
    } 
} 

