    public static int mostOccurrences(int[] arr) {
        int count = 0;
        int num = Integer.MIN_VALUE;
        HashMap<Integer, Integer> occurMap = new HashMap<>();
        for (int i = 0; i < arr.length; i++) {
            if (occurMap.containsKey(arr[i])) {
                occurMap.put(arr[i], occurMap.get(arr[i]) + 1);
                if (occurMap.get(arr[i]) > count) {
                    count = occurMap.get(arr[i]);
                    num = arr[i];
                }
            } else {
                occurMap.put(arr[i], 1);
            }
        }
        return num;
    }

