def n_queen(n):
    board = [[0]*n for _ in range(n)]

    def solve(row):
        if row==n:
            return True

        for col in range(n):
            if isSafe(board, row, col):
                board[row][col]=1

                if solve(row+1):
                    return True

                else:
                    board[row][col]=0

        return False

    def isSafe(board, row, col):
        for i in range(row):
            if board[i][col]==1:
                return False

        i,j = row,col
        while i>=0 and j>=0:
            if board[i][j]==1:
                return False
            i -=1
            j -=1

        i,j = row,col
        while i>=0 and j<n:
            if board[i][j]==1:
                return False
            i -=1
            j +=1

        return True

    return solve(0)

