function areAnagrams(s1, s2) {
    if (s1.length !== s2.length) {
        return false;
    }

    const s1map = new Map();
    for (let i = 0; i < s1.length; i++) {
        const s1char = s1.charAt(i);
        if (s1map.has(s1char)) {
            const cnt = s1map.get(s1char);
            s1map.set(s1char, cnt + 1);
        } else {
            s1map.set(s1char, 1);
        }
    }

    for (let j = 0; j < s2.length; j++) {
        const s2char = s2.charAt(j);
        if(!s1map.has(s2char)) {
            return false;
        }
        const cnt = s1map.get(s2char);
        if (cnt === 1) {
            s1map.delete(s2char);
        } else {
            s1map.set(s2char, cnt - 1);
        }
    }

    return s1map.size === 0;
}

