// Insert a Node at the front of the doubly linked list 
void insertAtFront(Node** head_ref, int key) 
{ 
    Node* newNode = getNewNode(key); 

    // If linked list is empty 
    if (*head_ref == NULL) 
    { 
        *head_ref = newNode; 
        return; 
    } 

    // Change next of new node 
    newNode->next = *head_ref; 

    // Change prev of head node 
    (*head_ref)->prev = newNode; 

    // Change head to point to new node 
    *head_ref = newNode; 
} 

// Search for a given key in a doubly linked list
// Return true if key is present, false otherwise 
bool searchList(Node* head, int key) 
{ 
    Node* curr = head; 
    while (curr != NULL) 
    { 
        if (curr->key == key) 
            return true; 
        curr = curr->next; 
    } 
    return false; 
} 

// Delete a node with a given key in a doubly linked list
void deleteNode(Node** head_ref, int key) 
{ 
    // Store head node 
    Node* temp = *head_ref, *prev; 

    // If head node itself holds the key to be deleted 
    if (temp != NULL && temp->key == key) 
    { 
        *head_ref = temp->next; // Changed head 
        free(temp); // free memory 
        return; 
    } 

    // Search for the key to be deleted, keep track of the 
    // previous node as we need to change 'prev->next' 
    while (temp != NULL && temp->key != key) 
    { 
        prev = temp; 
        temp = temp->next; 
    } 

    // If key was not present in linked list 
    if (temp == NULL) return; 

    // Unlink the node from linked list 
    prev->next = temp->next; 

    free(temp); // Free memory 
}

