char* formate_date(char* date, const char* format) {
    int date_len = strlen(date);
    int format_len = strlen(format);
    char* new_date = (char*)malloc(date_len + 1);

    int i, j; 
    for (i = 0, j = 0; i < format_len && j < date_len; i++) {
        if (format[i] == 'M') {
            new_date[i] = date[j]; 
            j++; 
        } else if (format[i] == 'D') {
            new_date[i] = date[j + 1]; 
            j += 2; 
        } else if (format[i] == 'Y') {
            new_date[i] = date[j + 3]; 
            j += 4; 
        } else {
            new_date[i] = ' ';
        }
    }

    new_date[date_len] = '\0'; 

    return new_date;
}

