void removeDuplicate(int arr[], int n) 
{ 
    // Bit array is used to mark seen elements 
    bool bit_arr[n+1]; 
    memset(bit_arr, 0, sizeof(bit_arr)); 

    // Traverse array elements and mark them 
    for (int i=0; i<n; i++) 
    { 
        if (bit_arr[arr[i]] == 0) 
        { 
            bit_arr[arr[i]] = 1; 
        } 
    } 

    // Traverse array elements and remove duplicates 
    int ind = 0; 
    for (int i=0; i<n; i++) 
    { 
        if (bit_arr[arr[i]] == 1) 
            { 
                arr[ind++] = arr[i]; 
                bit_arr[arr[i]] = 0; 
            } 
        } 
    arr[ind] = 0; 
}

