def identify_outliers(nums):
    mean = sum(nums) / len(nums)
    stdev = 0

    for num in nums:
        stdev += (num - mean) ** 2
    stdev = math.sqrt(stdev / len(nums))

    outliers = []
    for num in nums:
        if (num > mean + stdev) or (num < mean - stdev):
            outliers.append(num)
    return outliers

