    spam_words = 0
    non_spam_words = 0

    # Split text into individual words 
    words_in_text = text.split()

    # Loop through words in text 
    for word in words_in_text:
        # Check if word is in words
        if word in words: 
            # Check if word is spam or non-spam 
            if words[word] == "spam":
                spam_words += 1
            else: 
