def ticTacToe(board):
  # Evaluate each row
  for row in board:
    if row[0]==row[1]==row[2]!="":
      return row[0]

  # Evaluate each column
  for c in range(3):
    if board[0][c]==board[1][c]==board[2][c]!="":
      return board[0][c]

  # Evaluate diagonals
  if board[0][0]==board[1][1]==board[2][2]!="":
    return board[0][0]
  if board[0][2]==board[1][1]==board[2][0]!="":
    return board[0][2]

  return None

