def evaluate_postfix(expression):

    stack = []
    for char in expression:
        if char.isdigit():
            stack.append(char)
        else:
            b = int(stack.pop())
            a = int(stack.pop())
            stack.append(str(eval("a" + char + "b")))
    return int(stack.pop())

