public class ListNode {
   public int val;
   public ListNode next;
   public ListNode(int x) { val = x; }
}

public ListNode ReverseList(ListNode head) 
{
    ListNode prev = null;
    ListNode current = head;
    ListNode next = null;

    while (current != null) 
    {
        next = current.next;
        current.next = prev;
        prev = current;
        current = next;
    }
    head = prev;
    return head;
}

