// Function to find the nth Fibonacci number 
int findNthFibonacci(int n) 
{ 
    int dp[n + 2]; // array to store result for subproblems 

    // base cases initialization 
    dp[0] = 0; 
    dp[1] = 1; 

    // Logic to find the nth Term 
    for (int i = 2; i <= n; i++) { 
        dp[i] = dp[i - 1] + dp[i - 2]; 
    } 

    return dp[n]; 
}

