import java.util.Random;

public class CarRace {

 // Generate a random track of 10 spaces
 // A '*' indicates an obstacle
 private static char[] track = new char[10];

 public static void main(String[] args) {
  // Generate random track
  generateTrack();

  // Create car objects
  Car car1 = new Car('A', 0);
  Car car2 = new Car('B', 0);

  // Simulate car race
  while (car1.getPosition() < track.length && car2.getPosition() < track.length) {
   car1.move();
   car2.move();
  }

  System.out.println("Car Race Simulation");
  System.out.println("Track: " + String.valueOf(track));
  System.out.println("Car A Position: " + car1.getPosition());
  System.out.println("Car B Position: " + car2.getPosition());
  System.out.println("Winner: Car " + getWinner(car1, car2));
 }

 // Get Winner
 private static char getWinner(Car c1, Car c2) {
  if (c1.getPosition() > c2.getPosition()) return c1.getName();
  else return c2.getName();
 }

 // Generate random track
 private static void generateTrack() {
  Random rand = new Random();
  for (int i=0; i < 10; i++) {
   int randomNum = rand.nextInt(2);
   if (randomNum == 0) track[i] = '-';
   else track[i] = '*';
  }
 }

 // Car class
 private static class Car {
  private char name;
  private int position;

  public Car(char name, int position) {
   this.name = name;
   this.position = position;
  }

  public char getName() {
   return this.name;
  }

  public int getPosition() {
   return this.position;
  }

  public void move() {
   if (this.position < track.length && track[this.position] != '*')
    this.position++;
  }
 }
}

