class Tree {
 constructor() {
  this.root = null;
 }
 add(value) {
  let node = new Node(value);
  if (this.root === null) {
   this.root = node;
  } else {
   let current = this.root;
   while (true) {
    if (value < current.value) {
     if (!current.left) {
      current.left = node;
      break;
     } else {
      current = current.left;
     }
    } else {
     if (!current.right) {
      current.right = node;
      break;
     } else {
      current = current.right;
     }
   }
  }
 }

 printInOrder() {
  let node = this.root;
  let tree = [];
  function traverse(node) {
   node.left && traverse(node.left);
   tree.push(node.value);
   node.right && traverse(node.right);
  }
  traverse(node);
  return tree;
 }
}

