    static int findMedian(int a[], int n) 
    { 
        // First we sort the array 
        Arrays.sort(a); 

        // check for even case 
        if (n % 2 != 0) 
            return a[n / 2]; 

        return (a[(n - 1) / 2] + a[n / 2]) / 2; 
    } 

