// Returns maximum value in a binary tree 
int maxValue(struct node* node) 
{ 
    int max = node->data; 
    int left_max, right_max;
    if (node->left != NULL) 
        left_max = maxValue(node->left); 
    if (node->right != NULL) 
        right_max = maxValue(node->right); 

    if (left_max > max) 
        max = left_max; 
    if (right_max > max) 
        max = right_max; 

    return max; 
} 

