def valid_address(address):
    #To check address length should be 27 - 34
    if not 27 <= len(address) <= 34:
        return False

    # To check address start with character 1 or 3
    if not (address[0] == '1' or address[0] == '3'):
        return False

    # To check characters in address should be lowercase alphanumeric
    for ch in address:
        if not (ch >= '0' and ch <= '9' or ch >= 'a' and ch <= 'z'):
            return False

    # Calculate checksum
    decoded = base58_decode(address)
    h = hashlib.sha256(hashlib.sha256(decoded[:-4]).digest()).digest()

    if h[0:4] == decoded[-4:]:
        return True

    return False

