public class Queue
{
    private int[] queueArray;
    private int front;
    private int back;
    private int count;

    public Queue(int size)
    {
        queueArray = new int[size];
        front = 0;
        back = -1;
        count = 0;
    }

    public void Enqueue(int value)
    {
        if (count == queueArray.Length)
            throw new System.InvalidOperationException("The Queue is full!");
        back = (back + 1) % queueArray.Length;
        queueArray[back] = value;
        count++;
    }

    public int Dequeue()
    {
        if (count == 0)
            throw new System.InvalidOperationException("The Queue is empty!");
        int dequeuedValue = queueArray[front];
        front = (front + 1) % queueArray.Length;
        count--;
        return dequeuedValue;
    }
}

