public static void insertionSort(int[] input) { 
    int n = input.length; 

    // Loop through the array 
    for (int i = 1; i < n; i++) { 
        // Set the current element to a variable 
        int current = input[i]; 
        int j = i - 1; 

        // Check if the current element is less than the sorted elements
        while (j >= 0 && input[j] > current) { 
            // Move the sorted element one position right 
            input[j + 1] = input[j];  
            j--; 
        } 

        // Insert the current element in its correct position 
        input[j + 1] = current;  
    } 
}

