def find_LIS(arr): 
    n = len(arr) 
    lis = [1]*n

    # Compute optimized LIS values in bottom up manner 
    for i in range (1 , n): 
        for j in range(0 , i): 
            if arr[i] > arr[j] and lis[i]< lis[j] + 1 : 
                lis[i] = lis[j]+1

    # Initialize maximum to 0 to get the maximum of all LIS 
    maximum = 0
    for i in range(n): 
        maximum = max(maximum , lis[i]) 
    return maximum

