char most_frequent_char(std::string s) {
    std::map<char, int> char_freq_map;

    for (int i = 0; i < s.length(); i++) {
        char_freq_map[s[i]]++;   
    }

    int max_freq = 0;
    char most_freq_char = ' ';

    for (auto it = char_freq_map.begin(); it != char_freq_map.end(); ++it) {
        int curr_freq = it->second;
        if (curr_freq > max_freq) {
            max_freq = curr_freq;
            most_freq_char = it->first;
        }
    }

    return most_freq_char;
}

int main() {
    std::string s = "Hello World";
    char ch = most_frequent_char(s);
    std::cout << "Most frequent char: " << ch << std::endl;
    return 0;
}

