void quickSort(int array[], int left, int right) 
{ 
    int i = left, j = right; 
    int tmp; 
    int pivot = array[(left + right) / 2]; 

    /* partition */
    while (i <= j) { 
        while (array[i] < pivot) 
            i++; 
        while (array[j] > pivot) 
            j--; 
        if (i <= j) { 
            tmp = array[i]; 
            array[i] = array[j]; 
            array[j] = tmp; 
            i++; 
            j--; 
        } 
    }; 

    /* recursion */
    if (left < j) 
        quickSort(array, left, j); 
    if (i < right) 
        quickSort(array, i, right); 
}

