def longest_common_substring(s1, s2):
    # create an 2D array of len(s1) + 1 and len(s2) + 1 to store the subproblems 
    substr_matrix = [[ 0 for i in range(len(s1) + 1)]  
                      for j in range(len(s2) + 1)] 

    for i in range(1, len(s1) + 1): 
        for j in range(1, len(s2) + 1): 
            # if characters are same, increase max-length of common substring
            if s1[i - 1] == s2[j - 1]: 
                substr_matrix[i][j] = substr_matrix[i - 1][j - 1] + 1
            else: 
                # else assume longest common substring length is 0 
                substr_matrix[i][j] = 0

    max_length = 0

    # iterate the 2D array to find the longest common substring
    for i in range(len(s1) + 1): 
        for j in range(len(s2) + 1): 
            if substr_matrix[i][j] > max_length: 
                max_length = substr_matrix[i][j] 

    # if found, return the longest common substring
    if max_length > 0:
        return s1[i-max_length:i]
    else:
        return None


