public class InsertionSort 
{ 
    public int[] sort(int[] input) 
    { 
        int n = input.Length; 
        for (int i = 1; i < n; ++i) 
        { 
            int key = input[i]; 
            int j = i - 1; 

            while (j >= 0 && input[j] > key) 
            { 
                input[j + 1] = input[j]; 
                j = j - 1; 
            } 
            input[j + 1] = key; 
        } 
        return input; 
    } 
}

