def palindrome_probability(string):
    n = len(string)
    if n == 0:
        return 1.0
    else:
        num_permutations = n * n
        num_palindromes = 0
        for i in range(n):
            for j in range(n):
                if string[i] == string[j] and i != j:
                    num_palindromes += 1

    return num_palindromes / num_permutations

