function quickSort(array) {
 // Base case
 if (array.length <= 1) {
 return array;
 }

 // Pick a pivot
 let pivot = array[0];

 // Divide into two parts
 let left = [];
 let right = [];
 for (let i = 1; i < array.length; i++) {
 if (array[i] < pivot) {
 left.push(array[i]);
 } else {
 right.push(array[i]);
 }
 }

 // Sort left and right
 left = quickSort(left);
 right = quickSort(right);

 // Combine left, pivot, and right
 return left.concat(pivot, right);
};

