 public static int findMaxSum(int[] arr) {
  // base case
  if(arr == null)
   return 0;

  int include = arr[0];
  int exclude = 0;

  for(int i=1; i<arr.length; i++){
   int incl = exclude + arr[i];
   int excl = Math.max(include, exclude);

   include = incl;
   exclude = excl;
  }

