// Function to replace string with given substring 
void replaceString(char s[], char orig[], 
				char replace[]) 
{ 
	char buffer[100]; 
	int x, k = 0; 

	for (x = 0; s[x] != '\0'; x++) { 
		if (s[x] == orig[0]) { 
			// Check whether the original string 
			// is present in the main string 
			int i, flag = 0; 
			for (i = 0; orig[i] != '\0'; i++) { 
				if (s[x + i] != orig[i]) 
					flag = 1; 
			} 
			// If flag is 0 then the original 
			// string if present in the main string 
			if (flag == 0) { 
				for (i = 0; replace[i] != '\0'; i++) { 
					// Replacing the original string 
					// with the replace string 
					buffer[k++] = replace[i]; 
				} 
				x = x + i - 1; 
			} else
				buffer[k++] = s[x]; 
		} else
			buffer[k++] = s[x]; 
	} 

	buffer[k] = '\0'; 

	// Copy the buffer into the original string 
	for (int l = 0; l < k; l++) 
		s[l] = buffer[l]; 
} 

