for (let i = 0; i < arr.length; i++) {

    // Step 3: Set the minIndex as the current index
    minIndex = i;

    // Step 4: Compare the current element with the remaining elements
    for (let j = i + 1; j < arr.length; j++) {

        // Step 5: Update the minIndex if a smaller element than the current element is found
