public class Stack
{
    private int[] stack;
    private int maxSize;
    private int top;

    public Stack(int size)
    {
        maxSize = size;
        stack = new int[maxSize];
        top = -1;
    }

    public void Push(int value)
    {
        if (top == maxSize - 1)
            Console.WriteLine("Stack is full");
        else
        {
            stack[++top] = value;
            Console.WriteLine("Pushed " + value);
        }
    }

    public int Pop()
    {
        int value = 0;
        if (top == -1)
            Console.WriteLine("Stack is empty");
        else
        {
            value = stack[top--];
            Console.WriteLine("Popped " + value);
        }
        return value;
    }
}

