def parse_html(html_string):
    # Initialize the array
    elements = {}
    # Split the HTML string by the '<' character
    tags = html_string.split('<')[1:]
    # Iterate over each tag 
    for tag in tags:
        # Split the tag by the '>' character
        name, content = tag.split('>')
        # If the tag has attributes, split them by the space
        if ' ' in name:
            name, attributes = name.split(' ')
            elements[name] = {'content': content, 'attributes': attributes}
        else:
            elements[name] = content
    return elements

