            while (i != 0 and self.arr[self.parent(i)] > self.arr[i]): 
                self.arr[i], self.arr[self.parent(i)] = self.arr[self.parent(i)], self.arr[i] 
                i = self.parent(i) 

    def deleteKey(self, i):  
        if i >= len(self.arr): 
            return

        self.arr[i] = self.arr[-1] 
        del self.arr[-1] 

        self.heapify(i) 

    def heapify(self, i): 
        l = 2 * i + 1     
        r = 2 * i + 2     
        smallest = i 
        if l < len(self.arr) and self.arr[i] > self.arr[l]: 
            smallest = l 

        if r < len(self.arr) and self.arr[smallest] > self.arr[r]: 
            smallest = r 

        if smallest != i: 
            self.arr[i], self.arr[smallest] = self.arr[smallest], self.arr[i] 
            self.heapify(smallest) 

    def getMin(self): 
        return self.arr[0] if len(self.arr) else None

