{
  public static string RemoveDuplicatesFromString(string str)
  {
    HashSet<char> seen = new HashSet<char>();
    string newStr = "";

    foreach (char ch in str)
    {
        if (!seen.Contains(ch))
        {
            seen.Add(ch);
            newStr += ch;
        }
    }
    return newStr;
  }

