public static int findMax(int[] arr) {
 // BASE CASE: If array is empty, return 0
 if (arr == null || arr.length == 0) return 0;

 int start = 0;
 int end = arr.length - 1;

 // Iterate until start == end
 while (start < end) {
 // Find the middle point
 int mid = (start + end) / 2;

 // Compare mid with its right neighbor
 if (arr[mid] < arr[mid + 1]) {
 // If mid < mid + 1, then maximum must be in the 
 // second half of the array
 start = mid + 1;
 }
 else {
 // If mid > mid + 1, maximum must be in the first
 // half of the array
 end = mid;
 }
 }

 // When start == end, we have found the maximum
 return arr[start];
}

