function areAnagrams(str1, str2) {
    if (str1.length !== str2.length) {
        return false;
    }

    let letterCount = {};
    for (let i = 0; i < str1.length; i++) {
        if (letterCount[str1[i]]) {
            letterCount[str1[i]]++;
        } else {
            letterCount[str1[i]] = 1;
        }
    } 
    for (let i = 0; i < str2.length; i++) {
        if (!letterCount[str2[i]]) {
            return false;
        } else {
            letterCount[str2[i]]--;
        }
    }
    return true;
}

