def binarySearch(list, item):
    leftIndex = 0
    rightIndex = len(list) - 1

    while (leftIndex <= rightIndex):
        midIndex = (leftIndex + rightIndex) // 2

        if list[midIndex] == item:
             return midIndex
        elif list[midIndex] > item:
            rightIndex = midIndex - 1
        else:
            leftIndex = midIndex + 1

    return -1

