public static int[] bubbleSort(int[] array) {
    int n = array.length;
    int temp = 0;

    for(int i = 0; i < n; i++){
        for(int j = 1; j < (n-i); j++){
            if(array[j-1] > array[j]){
                //swap the elements
                temp = array[j-1];
                array[j-1] = array[j];
                array[j] = temp;
            }
        }
    }    
    return array;
}

