void generatePrimeNumbers(int lower, int upper) 
{ 
    // Create a boolean array "prime[0..upper]" and 
    // initialize all entries it as false. A value in 
    // prime[i] will finally be true if i is a prime, 
    // else false 
    bool prime[upper+1]; 
    memset(prime, true, sizeof(prime)); 

    for (int p=2; p*p<=upper; p++) 
    { 
        // If prime[p] is not changed, then it is a 
        // prime 
        if (prime[p] == true) 
        { 
            // Update all multiples of p 
            for (int i=p*p; i<=upper; i += p) 
                prime[i] = false; 
        } 
    } 

    // Print all prime numbers 
    for (int p=lower; p<=upper; p++) 
       if (prime[p]) 
          cout << p << " "; 
} 

