def nearest_prime(n):
    # Check if n is prime
    isprime = 1
    for i in range(2, n):
        if (n % i == 0):
            isprime = 0
            break

    # if not prime
    if (isprime == 0):
        # search for next prime
        for j in range(n+1, n*n):
            for k in range(2, j):
                if (j % k == 0):
                    isprime = 0
                    break
            if (isprime == 1):
                return j
    else:
        return n

