def sort_matrix(m):
    # We will use bubble sort to sort the matrix
    for i in range(len(m)): 
        for j in range(0, len(m[0])-i-1): 
            if m[i][j] > m[i][j+1] : 
                m[i][j], m[i][j+1] = m[i][j+1], m[i][j] 

    # iterate through row
    for i in range(len(m)): 
        for j in range(len(m[0])): 
            # bubble sort column wise
            for row in range(len(m)-1):
                if (m[row][j] > m[row+1][j]): 
                    # swap the elements 
                    m[row][j],m[row+1][j] = m[row+1][j],m[row][j]
    return m

