def quick_sort(array):
  if len(array) <= 1:
    return array
  else:
    left, right, pivot = [], [], array[0]
    for i in array[1:]:
      if i <= pivot:
        left.append(i)
      else:
        right.append(i)
    return quick_sort(left) + [pivot] + quick_sort(right)

