def find_mode(lst):
    mode = 0
    max_count = 0
    current_number = None
    current_count = 0
    for num in lst:
        if num == current_number:
            current_count += 1
        else:
            if current_count > max_count:
                max_count = current_count
                mode = current_number
            current_number = num
            current_count = 1

    if current_count > max_count:
        mode = current_number

    return mode

