// A utility function to check whether a string is palindrome or not
bool isPalindrome(char str[])
{
    // Start form leftmost and rightmost corner of str
    int l = 0;
    int h = strlen(str) - 1;

    // Keep comparing characters while they are same
    while (h > l)
    {
        if (str[l++] != str[h--])
            return false;
    }
    return true;
}

