def addStrings(string1: String, string2: String) : String = {
  val string1Length = string1.length
  val string2Length = string2.length

  // Handle equal length strings
  if (string1Length == string2Length) {
    var digitSum = 0
    var carry = 0
    var result = ""

    for (i <- 0 until string1Length) {
      digitSum = string1.charAt(string1Length - 1 - i).asDigit + string2.charAt(string2Length - 1 - i).asDigit
      if (carry > 0) {
        digitSum += carry
        carry = 0
      }
      if (digitSum > 9) {
        carry = digitSum / 10
        digitSum = digitSum % 10
      }
      result = result + digitSum.toString
    }
    if (carry > 0) {
      result = result + carry.toString
    }
    return result.reverse

  // Handle unequal lengths
  } else if (string1Length > string2Length) {
    return addStrings(string1.take(string1Length - string2Length) +
      string2, string1.takeRight(string2Length))
  } else {
    return addStrings(string1, string2.takeRight(string2Length - string1Length) +
      string1)
  }
}

