vector<pair<int, int>> findSumPairs(vector<int> arr, int limit) {
vector<pair<int, int>> result;

for (int i = 0; i < arr.size()-1; i++) {
 for (int j = i+1; j < arr.size(); j++) {
 if (arr[i] + arr[j] == limit) {
 result.push_back(make_pair(arr[i], arr[j]));
 }
 }
 }

return result;
}

