public class StringManip {
    public static string DeleteRedundantChars(string input){
        string res = "";

        for (int i = 0; i < input.Length; i++){
            bool flag = true;
            for (int j = 0; j < res.Length; j++) {
                if (input[i] == res[j]) {
                    flag = false;
                    break;
                }
            }
            if (flag) {
                res += input[i];
            }
        }

        return res;
    }

    public static void Main (string[] args){
        string str = "mellow yellow";
        Console.WriteLine("Result after removing redundant characters: {0}", DeleteRedundantChars(str));
    }
}

