def prime_factors(n):
    prime_numbers = []
    i = 2
    while i * i <= n: 
        if (n % i == 0): 
            prime_numbers.append(i)
            n = n / i
        else:
            i += 1
    if (n > 1):
        prime_numbers.append(int(n))
    return prime_numbers

