public class DeleteElement {
 public static int[] deleteElement(int[] arr, int index) {

 // Create a copy of the array, as we can't delete from the original array
 int[] copy = new int[arr.length - 1];

 // Copy all element except the one at the given index
 int j = 0;
 for (int i = 0; i < arr.length; i++) {
 if (i != index) {
 copy[j] = arr[i];
 j++;
 }
 }

 return copy;
 }

