func mostFrequent(array: [Int]) -> Int? {
    var counts: [Int: Int] = [:]
    var maxCount = 0
    for item in array {
        counts[item, default: 0] += 1
        maxCount = max(maxCount, counts[item, default: 0])
    }
    for (key, count) in counts {
        if count == maxCount {
            return key
        }
    }
    return nil
}

