void shortestPath(int nodeA, int nodeB, std::vector<std::list<int>> &graph) 
{ 
    // Create a vector to store the shortest path 
    std::vector<int> distance(graph.size(), INT_MAX); 

    // Mark the source node as visited 
    distance[nodeA] = 0; 

    // Create a queue for BFS 
    std::list<int> queue; 
    queue.push_back(nodeA); 

    // Iterate through the queue and update the distance 
    // to the adjacent nodes, if possible. 
    while (!queue.empty()) { 
        // Pop the queue 
        int curr = queue.front(); 
        queue.pop_front(); 

        // Calculate the distance of the node 
        // from the source node. 
        int curr_distance = distance[curr]; 

        // Iterate through all the adjacent nodes 
        // of the current node 
        for (auto it = graph[curr].begin(); it != graph[curr].end(); it++) 
        { 
            // Update the distance if it is lower than 
            // the current distance 
            if (distance[*it] > curr_distance + 1) { 
                distance[*it] = curr_distance + 1; 
                queue.push_back(*it); 
            } 
        } 
    } 

    // Print the shortest path from nodeA to nodeB. 
    std::cout << "Shortest path between Node " << nodeA << 
            " and Node " << nodeB << " is " << 
            distance[nodeB] << std::endl; 
} 

