 // Function that finds the maximum product of three
 public static int findMaxProduct(int[] arr) {

 // Initialize the maxProduct
 int maxProduct = Integer.MIN_VALUE;

 // Sort the array
 Arrays.sort(arr);

 // Compute the product of the last three elements 
 int product = arr[arr.length - 1] * arr[arr.length - 2] * arr[arr.length - 3];
 if (product > maxProduct) {
  maxProduct = product;
 }

 // Compute the product of the first two and last element
 product = arr[0] * arr[1] * arr[arr.length - 1];
 if (product > maxProduct) {
  maxProduct = product;
 }

 // Return the maximum product
 return maxProduct;

 }

