const huffman = (data) => {
  // Count the frequency of each character
  let frequencies = {};
  for (let i = 0; i < data.length; i++) {
    let char = data[i];
    frequencies[char] = frequencies[char] || 0;
    frequencies[char]++;
  }

  // Build a huffman tree
  let queue = Object.keys(frequencies).map((char) => ({
    char,
    freq: frequencies[char]
  }));

  while (queue.length > 1) {
    let a = queue.shift();
    let b = queue.shift();

    queue.push({
      char: null,
      freq: a.freq + b.freq,
      left: a,
      right: b
    });

    queue.sort((a, b) => a.freq > b.freq);
  }

  let huffmanTree = queue.shift();

  // Generate a lookup table for the encoded values
  let lookupTable = {};
  const traverse = (node, path) => {
    if (node.char != null) {
      lookupTable[node.char] = path;
    }
    if (node.left) traverse(node.left, path + '0');
    if (node.right) traverse(node.right, path + '1');
  };

  traverse(huffmanTree, '');

  // Generate the compressed data
  let encoded = '';
  for (let i = 0; i < data.length; i++) {
    encoded += lookupTable[data[i]];
  }

  return encoded;
}

