public static boolean isPalindrome(String s)  
{  
    // Initialize left and right pointer 
    int left = 0;  
    int right = s.length() - 1;  

    // Traverse to find matching characters from both sides 
    while (left < right )  
    {  

        // Increament lft pointer if the character is not alphanumeric  
        if (!Character.isLetterOrDigit(s.charAt(left)))  
        {  
           left++;  
        }  
        // Decrement right pointer if the character is not alphanumeric 
        else if (!Character.isLetterOrDigit(s.charAt(right)))  
        {  
            right--;  
        }  
        // Compare characters at left pointer and right pointer 
        else if (Character.toLowerCase(s.charAt(left)) != Character.toLowerCase(s.charAt(right)))  
        {  
            return false;  
        }  
        // Both characters match, increment left pointer 
        // and decrement right pointer 
        else
        {  
            left++;  
            right--;  
        }  
    }  

    // If loop completed and characters match then return true
    return true;
}

