public class Stack
{
    private int top; 
    private int[] stackArray;  

    public Stack(int size) 
    { 
        stackArray = new int[size]; 
        top = -1; 
    } 

    public boolean isEmpty() 
    { 
        return (top == -1); 
    }   
    public boolean push(int key) 
    { 
        if (top+1 >= stackArray.length) 
        { 
            System.out.println("Stack Overflow"); 
            return false; 
        } 
        else
        { 
            stackArray[++top] = key; 
            return true; 
        } 
    } 

    public int pop() 
    { 
        if (top < 0) 
        { 
            System.out.println("Stack Underflow"); 
            return 0; 
        } 
        else
        { 
            int key = stackArray[top--]; 
            return key; 
        } 
    } 
}

