def build_bst(arr, N): 
    # Create a root node
    root = Node(arr[0]) 

    for i in range(1, N): 
        insert(root, arr[i]) 

    return root 

def insert(node, data): 

    # If the tree is empty, return a new node 
    if node is None: 
        return Node(data) 

    # Otherwise recur down the tree 
    if data < node.data: 
        node.left = insert(node.left, data)
    elif data > node.data: 
        node.right = insert(node.right, data) 

    # Return the node 
    return node 

