int dpFibonacci(int n) {
    // Set all entries to 0
    int memo[n + 1]; 
    memset(memo, -1, sizeof(memo)); 

    // base case assignment
    memo[0] = 0;
    memo[1] = 1;

    // Memoization (Top-Down Approach)
    for (int i = 2; i <= n; i++) { 
        if (memo[i] == -1) 
            memo[i] = memo[i-1] + memo[i-2]; 
    }
    return memo[n]; 
