import nltk
import numpy as np

def sentiment(text):
    tokens = nltk.word_tokenize(text) # Tokenize the text.
    words = []

    # Remove punctuation and convert all words to lowercase.
    for token in tokens:
        token = token.lower()

        if token.isalpha():
            words.append(token)

    # Calculate the sentiment score
    sentiments = []
    for word in words:
        try:
            score = nltk.sentiment.vader.polarity_scores(word)["compound"]
            sentiments.append(score)
        except:
            continue

    if len(sentiments) == 0:
        return 0.0
    else:
        return np.mean(sentiments)

