public static bool CheckParenthesisMatching(string input)
{
    if (input == null)
    {
        return false;
    }
    Stack<char> stack = new Stack<char>();
    for (int i = 0; i < input.Length; ++i)
    {
        if (input[i] == '(')
        {
            stack.Push(input[i]);
        }
        else if (input[i] == ')')
        {
            if (stack.Count > 0)
            {
                stack.Pop();
            }
            else
            {
                return false;
            }
        }
    }
    return stack.Count == 0;
}

