public class Palindrome {
static boolean isPalindrome(String inputString) {
    int left = 0;
    int right = inputString.length() - 1;
    while (left < right) {
        if (!Character.isLetter(inputString.charAt(left))) {
            left++;
            continue;
        }
        if (!Character.isLetter(inputString.charAt(right))) {
            right--;
            continue;
        }
        if (inputString.charAt(left) != inputString.charAt(right)) 
            return false; 

        left++; 
        right--; 
    } 

    return true; 
}

public static void main(String[] args) {
    String inputString = "racecar";
    boolean isPalindrome = isPalindrome(inputString);
    System.out.println(isPalindrome); // Output: true
    }
}

