   public static void main(String[] args) {
      //array of numbers
      int [] numbers = {2, 4, 3, 5, 7, 8, 9};
      //given sum
      int sum = 7;

      //map to store numbers and their index
      Map<Integer, Integer> indexMap = new HashMap<Integer, Integer>();

