def align_dna_sequences(dna1, dna2):
  mat = [[0 for j in range(len(dna2) + 1)] for i in range(len(dna1) + 1)]

  # Fill in match and mismatch scores
  for i in range(len(dna1)+1):
    for j in range(len(dna2)+1):
      if i == 0 or j == 0:
        mat[i][j] = 0
      elif dna1[i-1] == dna2[j-1]:
        mat[i][j] = mat[i-1][j-1] + 1
      else:
        mat[i][j] = max(mat[i-1][j], mat[i][j-1])

  return mat[len(dna1)][len(dna2)]

