def smallestWindow(string, pattern): 
    windowSize = len(string) + 1

    needToFind = len(pattern) 
    hasFound = {} 
    windowStart = 0
    for i in range(len(pattern)): 
        hasFound[pattern[i]] = 0

    count = 0

    # Look for the characters of pattern in string 
    for j in range(len(string)): 
        ch = string[j]

        if ch in hasFound: 
            hasFound[ch] += 1 

            # If all the characters are present 
            if hasFound[ch] == needToFind[ch]: 
                count += 1

            # If all the characters are present, 
            # we reduce the window size 
            if count == needToFind: 
                while hasFound[string[windowStart]] > needToFind[string[windowStart]]: 
                    if hasFound[string[windowStart]] > needToFind[string[windowStart]]: 
                        hasFound[string[windowStart]] -= 1 
                    windowStart += 1 
                windowLen = j - windowStart + 1

                if windowSize > windowLen: 
                    windowSize = windowLen 

    return windowSize

