// Recursive solution
func extractValues(_ root: TreeNode?, _ targetSum: Int) -> [Int] {
 guard let root = root else { return [] }
 var values: [Int] = []
 if root.value == targetSum {
 values.append(root.value)
 }
 let leftValues = extractValues(root.left, targetSum - root.value)
 let rightValues = extractValues(root.right, targetSum - root.value)
 return values + leftValues + rightValues
}

// Iterative solution
struct NodeWithPath {
 let node: TreeNode
 let path: [Int]
}
func extractValues(_ root: TreeNode?, _ targetSum: Int) -> [Int] {
 guard let root = root else { return [] }
 var queue: Queue<NodeWithPath> = Queue()
 queue.enqueue(NodeWithPath(node: root, path: [root.value]))
 var values: [Int] = []
 while let nodeWithPath = queue.dequeue() {
 if nodeWithPath.node.left != nil {
 let path = nodeWithPath.path + [nodeWithPath.node.left!.value]
 queue.enqueue(NodeWithPath(node: nodeWithPath.node.left!, path: path))
 }
 if nodeWithPath.node.right != nil {
 let path = nodeWithPath.path + [nodeWithPath.node.right!.value]
 queue.enqueue(NodeWithPath(node: nodeWithPath.node.right!, path: path))
 }
 if nodeWithPath.path.reduce(0, +) == targetSum {
 values.append(nodeWithPath.path)
 }
 }
 return values
}

