# define a parser
parser = nltk.RegexpParser('''
 EQUATION: {<NUMBER>+<OPERATOR>+<NUMBER>+}
''')

# util function to convert string token to int
def to_int(tok):
    try:
        return int(tok)
    except ValueError:
        return None

# function to solve equation
def solve_equation(eq):
    tokens = nltk.word_tokenize(eq)
    tree = parser.parse(tokens)
    print(tree)

    equation = []
    for subtree in tree.subtrees():
        if subtree.label() == 'EQUATION':
            equation.append([
                to_int(subtree.leaves()[0][0]),
                subtree.leaves()[1][0],
                to_int(subtree.leaves()[2][0])
            ])

    answer = equation[0][0]
    operator,operand = equation[0][1], equation[0][2]

    if operator == '+':
        answer += operand
    elif operator == '-':
        answer -= operand
    elif operator == '*':
        answer *= operand
    else:
        answer /= operand

    return answer

