public class MinMax {
    public static void minMax (int[] arr, int low, int high, int min, int max) {
        if (arr.length == 0) {
            System.out.println("No elements to find min and max.");
            return;
        }
        if (high == low) {
            System.out.println("Minimum : " + arr[min]);
            System.out.println("Maximum : " + arr[max]);
            return;
        }
        if (arr[high] > arr[max]) {
            max = high;
        }
        if (arr[low] < arr[min]) {
            min = low;
        }
        minMax(arr, low + 1, high, min, max);
    }

    public static void main(String[] args) {
        int[] arr = {12, 1, 9, 8, 2, 7, 5};
        minMax(arr, 0, arr.length-1, 0, arr.length-1);
    }
}

