{ 
    let frequencyMap = {}; 
    let maxFrequencyChar = str[0]; 
    let maxFrequencyCount = 1; 

    for (let i = 0; i < str.length; i++) { 
        const char = str[i]; 
        if (frequencyMap[char] == null) 
            frequencyMap[char] = 1; 
        else
            frequencyMap[char] += 1; 

        if (frequencyMap[char] > maxFrequencyCount) { 
            maxFrequencyCount = frequencyMap[char]; 
            maxFrequencyChar = char; 
