const App = () => {
 const [step, setStep] = useState(1);
 const [form, setForm] = useState({
  step1: "",
  step2: "",
  step3: ""
 });

 const onChange = (e) => {
  setForm({
   ...form,
   [e.target.name]: e.target.value
  });
 };

 const onSubmit = (e) => {
  e.preventDefault();
  alert(`Submitting Form:"${form.step1}" ${form.step2} ${form.step3}`);
  // clear form
  setForm({
   step1: "",
   step2: "",
   step3: ""
  });
  // go back to first step
  setStep(1);
 };

 const onNext = (e) => {
  e.preventDefault();
  setStep((prevState) => prevState + 1);
 };

 const onPrevious = (e) => {
  e.preventDefault();
  setStep((prevState) => prevState - 1);
 };

 return (
  <Form onSubmit={onSubmit}>
   {step === 1 && (
    <Form.Group controlId="formStep1">
     <Form.Label>Step 1</Form.Label>
     <Form.Control
      type="input"
      name="step1"
      value={form.step1}
      onChange={onChange}
     />
    </Form.Group>
   )}
   {step === 2 && (
    <Form.Group controlId="formStep2">
     <Form.Label>Step 2</Form.Label>
     <Form.Control
      type="input"
      name="step2"
      value={form.step2}
      onChange={onChange}
     />
    </Form.Group>
   )}
   {step === 3 && (
    <Form.Group controlId="formStep3">
     <Form.Label>Step 3</Form.Label>
     <Form.Control
      type="input"
      name="step3"
      value={form.step3}
      onChange={onChange}
     />
    </Form.Group>
   )}
   {step > 1 && (
    <Button variant="primary" onClick={onPrevious}>
     Previous
    </Button>
   )}
   {step < 3 && (
    <Button variant="primary" onClick={onNext}>
     Next
    </Button>
   )}
   {step === 3 && (
    <Button variant="primary" type="submit">
     Submit
    </Button>
   )}
  </Form>
 );
};

