// Function to find number 
// with maximum frequency 
// in a sorted array 
int mostFrequentNumber(int A[], int n) 
{ 
    // traverse the array 
    int current = A[0], count = 1, result = A[0]; 
    int max_count = 1; 
    for (int i = 1; i < n; i++) { 

        // if A[i] is same as current 
        if (A[i] == current) 
            count++; 

        // Update the result if count  
        // of current element is more 
        else { 
            if (count > max_count) { 
                max_count = count; 
                result = current; 
            } 
            current = A[i]; 
            count = 1; 
        } 
    } 

    // comparing the last element 
    // with the result 
    if (count > max_count) { 
        max_count = count; 
        result = current; 
    } 
    return result; 
} 

