    for i in range(len(arr)):
        swap_pairs = [arr[j] > arr[j+1] for j in range(len(arr)-1)] # check current element with the next element
        if any(swap_pairs): # if current element greater than next element, swap elements
            for k, j in enumerate(swap_pairs): 
                if j:
                    arr[k], arr[k+1] = arr[k+1], arr[k]
    return arr

