public class LinkedList {
  public Node head;
  public Node tail;
  public int size;

  public LinkedList() {
    this.head = null;
    this.tail = null;
    this.size = 0;
  }

  public class Node {
    public int data;
    public Node next;

    public Node(int data) {
      this.data = data;
      this.next = null;
    }
  }

  public void Add(int data) {
    Node node = new Node(data);

    if (head == null) {
      head = node;
      tail = node;
    } else {
      tail.next = node;
      tail = node;
    }

    size++;
  }
}

