public static boolean isPalindrome(LinkedListNode head) {
 // A linked list of 0 or 1 nodes is a palindrome
 if (head == null || head.next == null) {
  return true;
 }

 LinkedListNode reversed = reverseAndClone(head);
 return isEqual(head, reversed);
}

// Reverses a LinkedList and clones all nodes
public static LinkedListNode reverseAndClone(LinkedListNode node) {
 LinkedListNode head = null;

 while (node != null) {
  LinkedListNode n = new LinkedListNode(node.data); // Clone
  n.next = head;
  head = n;

  node = node.next;
 }

 return head;
}

// Compares two lists to check their equality
public static boolean isEqual(LinkedListNode one, LinkedListNode two) {
 while (one != null && two != null) {
  if (one.data != two.data) {
   return false;
  }

  one = one.next;
  two = two.next;
 }

 return one == null && two == null;
}

