vector<int> find_primes(int n)
{
    vector<bool> sieve(n, true);
    sieve[0] = false;
    sieve[1] = false;

    for (int i = 2; i <= sqrt(n); ++i)
        if (sieve[i] == true)
            for (int j = i * i; j < n; j += i)
                sieve[j] = false;

    vector<int> result;
    for (int i = 2; i < n; ++i)
        if (sieve[i] == true)
            result.push_back(i);

    return result;
}

