function longest_common_substring(str1, str2) 
{ 
    // Create a matrix to store the lengths of 
    // longest common substrings 
    var Matrix = [[]]; 
    for (var i = 0; i <= str1.length; i++) 
    { 
        for (var j = 0; j <= str2.length; j++) 
        { 
            Matrix[i] = Matrix[i] || []; 
            Matrix[i][j] = 0; 
        } 
    } 

    // Maximum length of the common substring 
    // will be stored in the variable maxlen 
    var maxlen = 0; 

    // Check each substring one by one 
    for (var i = 0; i < str1.length; i++) 
    { 
        for (var j = 0; j < str2.length; j++) 
        { 
            // If current character of first string 
            // matches with that of second string 
            if (str1[i] == str2[j]) 
            { 
                // Increase the maxlen by 1 
                if (Matrix[i][j] < (Matrix[i - 1][j - 1] + 1)) 
                { 
                    Matrix[i][j] = Matrix[i - 1][j - 1] + 1; 
                } 

                // Update maxlen 
                if (maxlen < Matrix[i][j])  
                { 
                    maxlen = Matrix[i][j]; 
                } 
            } 
        } 
    } 

    return maxlen; 
} 

