def longestPalSubstr(string): 
    # isPal will be used as a 2-D array to store palindromic 
    # substring decisions 
    n = len(string) 
    # all substrings of length 1 are palindromes 
    isPal = [[0 for x in range(n)] for x in range(n)] 
    l, start = 1, 0
    for i in range(n): 
        isPal[i][i] = True
    # check for sub-string of length 2. 
    for i in range(n-1): 
        if string[i] == string[i+1]: 
            isPal[i][i+1] = True
            start = i 
            l = 2
    # Check for lengths greater than 2. 
    # k is length of substring 
    for k in range(3, n+1): 
        for i in range(n-k+1): 
            j = i + k - 1
            if string[i] == string[j] and isPal[i+1][j-1]: 
                isPal[i][j] = True
