def delete(self, key):
    if self.root is None:
        return
    # Call the delete method
    self.root = self._delete_value(self.root, key)

def _delete_value(self, node, key):
    if node is None:
        return node

    if key < node.val:
        node.left = self._delete_value(node.left, key)
    elif key > node.val:
        node.right = self._delete_value(node.right, key)
    else: # key == node.val
        if node.left is None and node.right is None:
            node = None
        elif node.left is None:
            node = node.right
        elif node.right is None:
            node = node.left
        # if node has two children
        else:
            predecessor = self.get_predecessor(node.left)
            node.val = predecessor.val
            # predecessor is a leaf or has a single child 
            node.left = self._delete_value(node.left, predecessor.val)
    return node

def get_predecessor(self, node):
    if node.right is not None:
        node = node.right

    while node.left is not None:
        node = node.left

    return node

