def classify_email(email):
    """This function classifies an email as spam or not-spam using Naive Bayes."""
    # Split the email into words
    words = email.split()

    # Calculate the probability of each word appearing in a spam message
    spam_words_probs = {}
    total_spam = 0
    for word in words:
        if word in spam_words_probs:
            spam_words_probs[word] += 1
            total_spam += 1
        else:
            spam_words_probs[word] = 1
            total_spam += 1

    # Calculate the conditional probability of each word appearing in a spam message
    for word in spam_words_probs:
        spam_words_probs[word] /= total_spam

    # Calculate the conditional probability of the words in the email message 
    # given that it is a spam message
    prob_spam = 1
    for word in words:
        prob_spam *= spam_words_probs[word]

    # Classify the email as spam or not spam
    if prob_spam > 0.5:
        return "spam"
    else:
        return "not spam"

