const findMostFrequentLetter = (str) => {
    // Create an array of the letters in str
    const letters = str.split('');

    // Create an object to store the count of each letter
    const letterCounts = {};

    // Iterate over each letter, keeping track of the count
    letters.forEach(letter => {
        letterCounts[letter] = (letterCounts[letter] || 0) + 1;
    });

    // Create an array of the top 4 most frequent letters
    const topFour = Object.keys(letterCounts).sort((a, b) => letterCounts[b] - letterCounts[a]).slice(0, 4);

    // Return an array of the top four most frequent letters
    return topFour;
