public static int[] rearrangeOddEven(int[] arr){
    int oddPointer = 0;
    int evenPointer = arr.length-1;

    while(oddPointer < evenPointer){
        if(arr[oddPointer] % 2 == 0){
            int temp = arr[oddPointer];
            arr[oddPointer] = arr[evenPointer];
            arr[evenPointer] = temp;
            evenPointer--;
        } else {
            oddPointer++;
        }
    }

