def find_shortest_route(graph, source, destination):
    queue = [[source]]
    visited = set()

    while queue:
        path = queue.pop(0)
        node = path[-1]
        if node == destination:
            return path
        if node not in visited:
            visited.add(node)
            for neighbour in graph.neighbours(node):
                new_path = list(path)
                new_path.append(neighbour)
                queue.append(new_path)

