import UIKit

class ViewController: UIViewController {

    let buttonOne = UIButton()
    let buttonTwo = UIButton()
    let labelResult = UILabel()
    var storedNum = 0
    var operation = "="

    override func viewDidLoad() {
        super.viewDidLoad()
        setupViews()
        layoutViews()
    }

    func setupViews() {
        // Set the numbers
        buttonOne.setTitle("1", for: .normal)
        buttonOne.addTarget(self, action: #selector(calculate(sender:)), for: .touchUpInside)

        buttonTwo.setTitle("2", for: .normal)
        buttonTwo.addTarget(self, action: #selector(calculate(sender:)), for: .touchUpInside)

        labelResult.text = "0"
    }

    func layoutViews() {
        // Add subviews to the main view
        let views = [buttonOne, buttonTwo, labelResult]
        for view in views {
            self.view.addSubview(view)
        }

        // Setup constraints based on size of the view
        let safeLayout = self.view.safeAreaLayoutGuide
        buttonOne.translatesAutoresizingMaskIntoConstraints = false
        buttonOne.centerYAnchor.constraint(equalTo: safeLayout.centerYAnchor, constant: -40).isActive = true
        buttonOne.centerXAnchor.constraint(equalTo: safeLayout.centerXAnchor, constant: -40).isActive = true

        buttonTwo.translatesAutoresizingMaskIntoConstraints = false
        buttonTwo.centerYAnchor.constraint(equalTo: safeLayout.centerYAnchor, constant: -40).isActive = true
        buttonTwo.centerXAnchor.constraint(equalTo: safeLayout.centerXAnchor, constant: 40).isActive = true

        labelResult.translatesAutoresizingMaskIntoConstraints = false
        labelResult.centerXAnchor.constraint(equalTo: safeLayout.centerXAnchor).isActive = true
        labelResult.centerYAnchor.constraint(equalTo: safeLayout.centerYAnchor).isActive = true
    }

    @objc func calculate(sender: UIButton) {
        if let buttonText = sender.titleLabel?.text {
            let newNumber = Int(buttonText)!
            if operation == "+" {
                storedNum = storedNum + newNumber
            } else {
                storedNum = newNumber
            }
            labelResult.text = String(storedNum)
            operation = "+"
        }
    }
}

