def is_anagram(s1, s2): 
    # Remove all white spaces from strings
    s1 = s1.replace(" ", "") 
    s2 = s2.replace(" ", "") 

    # If two strings have different length, 
    # then they cannot be anagrams
    if (len(s1) != len(s2)): 
        return False

    # Create empty dictionary
    count = {}

    for char in s1: 
        # Increment count of character in dictionary
        if char in count: 
            count[char] += 1
        else: 
            count[char] = 1

    for char in s2: 
        # Decrement count of characters in dictionary
        if char in count: 
            count[char] -= 1
        else: 
            count[char] = 1

    # Check if all count values are 0
    for k in count: 
        if count[k] != 0: 
            return False

    return True

