procedure Sum_Of_Primes is
  Sum : Integer := 0;
  Lower_Limit, Upper_Limit : Integer;
  I : Integer;

begin
  Get(Lower_Limit);
  Get(Upper_Limit);

  -- Iterate through all numbers from lower limit to upper limit inclusively
  for I in Lower_Limit..Upper_Limit loop 

    -- A number is prime if it is divisible by itself and 1
