def findPath(x, y, grid, visited, targetX, targetY): 

    # if current cell is equal to target cell, return true 
    if (x == targetX and y == targetY): 
        return True

    # check if current cell is valid
    if (x < 0 or x > 7 or y < 0 or y > 9 or visited[x][y]): 
        return False

    # mark current cell as visited
    visited[x][y] = True

    # explore all possible 8 directions
    if (findPath(x-1, y, grid, visited, targetX, targetY)): 
        return True

    if (findPath(x+1, y, grid, visited, targetX, targetY)): 
        return True

    if (findPath(x, y-1, grid, visited, targetX, targetY)): 
        return True

    if (findPath(x, y+1, grid, visited, targetX, targetY)): 
        return True

    if (findPath(x-1, y-1, grid, visited, targetX, targetY)): 
        return True

    if (findPath(x-1, y +1, grid, visited, targetX, targetY)): 
        return True

    if (findPath(x+1, y-1, grid, visited, targetX, targetY)):  
        return True

    if (findPath(x+1, y+1, grid, visited, targetX, targetY)): 
        return True

    # if none of the above movements work then BACKTRACK 
    visited[x][y] = False
    return False

