public class ReverseEachWord { 
    static String reverseStringWordWise(String inputString) 
    { 
        // Splitting the input string into words 
        String[] words = inputString.split(" "); 

        String reverseString = ""; 

        // Traversing each word in the input string 
        for (int i = 0; i < words.length; i++) { 
            String word = words[i]; 

            // Initializing empty string for storing 
            // the single word to be reversed 
            String reverseWord = ""; 

            // Reversing each word 
            for (int j = word.length() - 1; j >= 0; j--) { 
                // Appending each character in reverse 
                // order to the reverseWord 
                reverseWord = reverseWord + word.charAt(j); 
            } 

            // Appending reverseWord with a space character 
            reverseString = reverseString + reverseWord + " "; 
        } 

        return reverseString; 
    } 

