bool isAnagram(std::string s1, std::string s2) {
    // Ensure both strings contain the same number of characters
    if (s1.length() != s2.length()) {
        return false;
    }

    // Sort strings
    std::sort(s1.begin(), s1.end());
    std::sort(s2.begin(), s2.end());

    // Check if strings are the same
    if (s1 == s2) {
        return true;
    } else {
        return false;
    }
}

