public class MyStack {
    private int[] stack;
    private int top;
    private int size;

    public MyStack(int size) {
        this.size = size;
        stack = new int[this.size];
        top = -1;
    }

    public boolean isEmpty(){
        return (top == -1);
    }

    public boolean isFull(){
        return (top == size-1);
    }

    public void push(int data) {
        if(!isFull()) {
            stack[++top] = data;
        } else {
            System.out.println("Stack is full!");
        }
    }

    public int pop(){
        if(!isEmpty()) {
            return stack[top--];
        } else {
            System.out.println("Stack is empty!");
            return -1; 
        }
    }

    public int peek(){
        if(!isEmpty()) {
            return stack[top];
        } else {
            System.out.println("Stack is empty!");
            return -1; 
        }
    }
}

