"""
A function that takes two strings s1 and s2 and returns true if the strings interleave to form s3
"""

def interleave(s1, s2, s3):
    #create lookup table to store checked values
    lookup_table = [[0 for i in range(len(s2) + 1)] for j in range(len(s1) + 1)]
    #fill lookup table
    for i in range(len(s1) + 1): 
        for j in range(len(s2) + 1): 
            #since both string are empty
            if i == 0 and j == 0: 
                lookup_table[i][j] = True
            #if only first string is empty 
            elif i == 0: 
                if s2[j - 1] == s3[j - 1]: 
                    lookup_table[i][j] = lookup_table[i][j - 1] 
            #if only second string is empty 
            elif j == 0: 
                if s1[i - 1] == s3[i - 1]: 
                    lookup_table[i][j] = lookup_table[i - 1][j]
            #if both strings are not empty 
            else: 
                if s1[i - 1] == s3[i + j - 1] and s2[j - 1] != s3[i + j - 1]: 
                    lookup_table[i][j] = lookup_table[i - 1][j] 
                elif s1[i - 1] != s3[i + j - 1] and s2[j - 1] == s3[i + j - 1]: 
                    lookup_table[i][j] = lookup_table[i][j - 1]
                elif s1[i - 1] == s3[i + j - 1] and s2[j - 1] == s3[i + j - 1]: 
                    lookup_table[i][j] = lookup_table[i - 1][j] or lookup_table[i][j - 1]
                else: 
                    lookup_table[i][j] = False
    return lookup_table[len(s1)][len(s2)]

