public class MaxSumSubarray {
    public static int maxSumK(int[] array, int k) {
        int currSum = 0, maxSum = Integer.MIN_VALUE;
        int start = 0, end = 0;
        while (end < array.length) {
            currSum += array[end++];
            while (end - start >= k) {
                maxSum = Math.max(maxSum, currSum);
                currSum -= array[start++];
            }
        }
        return maxSum;
    }
}

