#include <stdlib.h>

#define MAX_STACK_SIZE 10
#define MAX_INPUT_LENGTH 20

int evaluate_postfix(char* expression);

int main() {
   char expression[MAX_INPUT_LENGTH] = {1, 2, '+', 3, '-'};

   printf("value of expression %s is %d\n", expression, evaluate_postfix(expression));
   return 0;
}

int evaluate_postfix(char* expression) {
   int stack[MAX_STACK_SIZE]; 
   int top = -1; 
   int i;

   // Scan all characters one by one 
   for (i = 0; expression[i] != '\0'; i++) { 
      // If the scanned character is an operand (number here), 
      // push it to the stack. 
      if (expression[i] >= '0' && expression[i] <= '9')
         stack[++top] = expression[i] - '0';

      // If the scanned character is an operator, pop two 
      // elements from stack apply the operator 
      else { 
         int val1 = stack[top--]; 
         int val2 = stack[top]; 
         switch (expression[i]) { 
            case '+': stack[top] = val2 + val1; break; 
            case '-': stack[top] = val2 - val1; break; 
         } 
      } 
   } 
   return stack[top]; 
}

