def calculate_total_cost(shipping_order):
    total_cost = 0

    # Calculate the number of boxes needed based on the size of the order
    number_of_boxes = 1 if shipping_order.size <= 10 else shipping_order.size / 10

    # Calculate the cost based on the package weight and distance
    if shipping_order.distance <= 100:
        total_cost += 10 * number_of_boxes
    elif shipping_order.distance <= 500:
        total_cost += 15 * number_of_boxes
    elif shipping_order.distance <= 1000:
        total_cost += 20 * number_of_boxes
    else:
        total_cost += 25 * number_of_boxes

    # Calculate the cost based on the package weight
    if shipping_order.weight <= 1:
        total_cost += 5 * number_of_boxes
    elif shipping_order.weight <= 5:
        total_cost += 10 * number_of_boxes
    else:
        total_cost += 15 * number_of_boxes

    # Calculate the cost of additional services depending on their availability and the user's preference 
    if shipping_order.insurance == true:
        total_cost += 5 * number_of_boxes
    if shipping_order.tracking_number == true:
        total_cost += 3 * number_of_boxes

    return total_cost

