def mult_matrices(A, B):
    mA = len(A)
    nA = len(A[0])
    mB = len(B)
    nB = len(B[0])

    if nA != mB:
        return "Matrices cannot be multiplied!"
    else:
        C = [[0]*nB for row in range(mA)]
        # iterate through rows
        for i in range(mA):
            # iterate through the columns 
            for j in range(nB):
                for k in range(nA):
                    C[i][j] += A[i][k] * B[k][j]
        return C

