def longest_increasing_subsequence(arr): 
    n = len(arr) 

    # Initialize LIS values for all indexes 
    LIS = [1]*n 

    # Compute optimized LIS values in bottom up manner 
    for i in range (1 , n):
        for j in range(0 , i): 
            if arr[i] > arr[j] and LIS[i] < LIS[j] + 1 : 
                LIS[i] = LIS[j]+1

    # Pick maximum of all LIS values 
    return max(LIS) 

