def longest_common_substring(str1, str2):
    longest_str = ""
    for i in range(len(str1)):
        sub_str1 = str1[i:]
        for j in range(len(str2)):
            sub_str2 = str2[j:]
            min_len = min(len(sub_str1), len(sub_str2))
            for k in range(min_len):
                if (sub_str1[k] == sub_str2[k]):
                    if k+1 > len(longest_str):
                        longest_str = sub_str1[:k+1]
                else:
                    break
    return longest_str

