bool isPrime (int input) 
{ 
    // Corner cases 
    if (input <= 1) 
        return false; 
    if (input <= 3) 
        return true; 

    // This is checked so that we can skip 
    // middle five numbers in below loop 
    if (input % 2 == 0 || input % 3 == 0) 
        return false; 

    for (int i = 5; i * i <= input; i = i + 6) 
        if (input % i == 0 || input % (i + 2) == 0) 
            return false; 

    return true; 
}

