 if (string1.length() != string2.length()) {
 return false;
 }

 int[] counter = new int[26];

 for (int i = 0; i < string1.length(); i++) {
 counter[string1.charAt(i) - 'a']++;
 counter[string2.charAt(i) - 'a']--;
 }

 for (int count : counter) {
