}

public static void removeDuplicates(int[] arr) {
    Set<Integer> set = new HashSet<>();

    for(int i = 0; i < arr.length; i++) {
        set.add(arr[i]);
    }

    int[] arrWithoutDuplicates = new int[set.size()];
    int k = 0;
    for(Integer num : set) {
        arrWithoutDuplicates[k] = num;
        k++;
    }

    arr = arrWithoutDuplicates;
}

