// Function to delete all the occurrences
// of a value x in the linked list
void deleteAllOccurrences(struct Node** head, int x)
{
	// Store head node
	struct Node* current = *head;
	struct Node* prev = NULL;

	// Case-1: When the value at head has to be deleted
	while (current != NULL && current->data == x)
	{
		*head = current->next;
		free(current);
		current = *head;
	}

	// Case-2: When the value at head is different
	while (current != NULL)
	{
		// Find the last occurrence of x
		while (current != NULL && current->data != x)
		{
			prev = current;
			current = current->next;
		}

		// If there is no x in linked list
		if (current == NULL) return;

		// Remove the last occurrence of x
		prev->next = current->next;

		// Free memory
		free(current);
		current= prev->next;
	}
}

