 }

 // create 2D array matrix to store values
 // matrix[i][j] stores the maximum value for weight j using items 0 to i
 int[][] matrix = new int[weights.length][maxWeight+1];

 // base case values, i.e. when no items are used
 for (int i = 0; i <= maxWeight; i++) {
 matrix[0][i] = 0;
 }

 // build matrix by looping through items
 for (int i = 1; i < weights.length; i++) {
 for (int j = 0; j <= maxWeight; j++) {
 if (weights[i] <= j) {
 // max of including or excluding item
 matrix[i][j] = Math.max(values[i] + matrix[i-1][j-weights[i]], matrix[i-1][j]);
 } else {
 matrix[i][j] = matrix[i-1][j];
 }
 }
 }

 // return maximum value
 return matrix[weights.length-1][maxWeight];
}

