int sumPrimeOdd(int low, int high) 
{ 
    // To store sum of odd prime numbers 
    int sum = 0; 

    // iterating through all odd numbers 
    for (int num = low; num <= high; num++) 
    { 
        // ascertain whether the num is odd or not 
        boolean isOdd = num % 2 != 0; 

        // confirm if the num is prime or not 
        boolean isPrime = isPrimeNumber(num); 

        if (isOdd && isPrime) 
            sum += num; 
    } 
    return sum; 
} 

// Function to check prime number or not 
boolean isPrimeNumber(int n) 
{ 
    // check if the num is divisible by any number 
    // between 2 and n-1 
    for (int i = 2; i < n; i++) 
        if (n % i == 0) 
            return false; 

    return true; 
}

