function findPermutations(arr)  {
    const permutations = [];

    // base case
    if (arr.length === 1)  {
        permutations.push(arr);
        return permutations;
    } 

    // recursive case
    for (let i = 0; i < arr.length; i++) {
        const currentNumber = arr[i];
        const remaining = [...arr.slice(0, i), ...arr.slice(i + 1)];
        const recursiveResults = findPermutations(remaining);
        for (let j = 0; j < recursiveResults.length; j++) {
            permutations.push([currentNumber, ...recursiveResults[j]]);
        }
    }
    return permutations;   
}

