def longest_common_substring_align(str1, str2):
    '''This function aligns two strings based on the longest common substring.'''
    lcs = []
    for i in range(len(str1)):
        for j in range(len(str2)):
            if str1[i] == str2[j]:
                if len(lcs) > 0 and i > lcs[len(lcs)-1][1]:
                    lcs.append([j,i])
                elif len(lcs) == 0:
                    lcs.append([j,i])
    align_str1 = []
    align_str2 = []

    align_str1.append(str1[0:lcs[0][0]])
    align_str2.append(str2[0:lcs[0][1]])

    for i in range(len(lcs)-1):
        align_str1.append(str1[lcs[i][1]+1:lcs[i+1][0]])
        align_str2.append(str2[lcs[i][0]+1:lcs[i+1][1]])
    align_str1.append(str1[lcs[len(lcs)-1][1]+1:])
    align_str2.append(str2[lcs[len(lcs)-1][0]+1:])
    return align_str1, align_str2

