def binary_search(arr, target): 
    left = 0
    right = len(arr)

    while left <= right:
        mid = (left + right) // 2
        middle_element = arr[mid]
        if target == middle_element:
            return mid
        elif target > middle_element:
            left = mid + 1
        else:
            right = mid - 1

    return -1

