class MaxSubarraySum {
    constructor() {
        this.maxSum = 0;
        this.prefixSum = [0];
        this.startIndex = 0;
        this.endIndex = 0;
    }

    updateMaxSum(value) {
        let currSum = this.prefixSum[this.prefixSum.length - 1] + value;
        let minIndex = this.getMinIndex();
        let currSumWithoutMin = currSum - this.prefixSum[minIndex];

        if (currSumWithoutMin > this.maxSum) {
            this.startIndex = minIndex + 1;
            this.endIndex = this.prefixSum.length - 1;
            this.maxSum = currSumWithoutMin;
        }

        this.prefixSum.push(currSum);
    }

    getMaxSum() {
        return this.maxSum;
    }

    getStartIndex() {
        return this.startIndex;
    }

    getEndIndex() {
        return this.endIndex;
    }

    getMinIndex() {
        let minValue = this.prefixSum[0];
        let minIndex = 0;
        for (let i = 1; i < this.prefixSum.length; i++) {
            if (this.prefixSum[i] < minValue) {
                minValue = this.prefixSum[i];
                minIndex = i;
            }
        }

        return minIndex;
    }
}

