# Function to check the game status 
def check_game_status(): 
    # Check if the player has won 
    if check_win(PLAYER_X): 
        return "X won!" 
    elif check_win(PLAYER_O): 
        return "O won!" 
    # Check if the game is a draw 
    elif check_draw(): 
        return "Draw!"
    # If the game is not over yet 
    else:
        return "Game in progress..."

# Function to check the winning condition 
def check_win(player): 
    # Check if the player has won in a row 
    for row in board: 
        if row.count(player) == BOARD_SIZE: 
            return True
    # Check if the player has won in a column 
    for col in range(BOARD_SIZE): 
        if board[0][col] == board[1][col] == board[2][col] == player: 
            return True 
    # Check if the player has won in a diagonal 
    if board[0][0] == board[1][1] == board[2][2] == player: 
        return True 
    if board[0][2] == board[1][1] == board[2][0] == player: 
        return True
    # Return false if the player did not win 
    return False 

# Function to check if the game is a draw 
def check_draw(): 
    for row in board: 
        for cell in row: 
            if cell == EMPTY: 
                return False 
    return True

