def findTriplets(arr, n):
    triplets = []
    arr.sort()
    for i in range (len(arr)-2):
        l = i+1
        r = len(arr)-1
        while l < r:
            s = arr[i] + arr[l] + arr[r]
            if s == n:
                triplets.append([arr[i],arr[l],arr[r]])
                l +=1
                r-=1
            elif s < n:
                l+=1
            else:
                r-=1
    return triplets 

