def binary_search(list_nums, target):
  # set the initial range for the search 
  start = 0
  end = len(list_nums) - 1

  # loop until range is exhausted
  while start <= end:
    mid_index = (start + end) // 2
    mid_num = list_nums[mid_index]

    # check against the target
    if target == mid_num:
      return mid_index
    elif target < mid_num:
      end = mid_index - 1
    else:
      start = mid_index + 1

  return -1 # not found

