import java.util.ArrayList;
import java.util.List;
import java.awt.Point;

public class NearestPoint {

    public static Point getNearestPoint(Point currentLocation) {
        List<Point> points = getAllPossiblePoints();

        double minDistance = Integer.MAX_VALUE;
        Point nearestPoint = null;

        for (Point point : points) {
            double distance = calculateDistance(currentLocation, point);
            if (distance < minDistance) {
                minDistance = distance;
                nearestPoint = point;
            }
        }
        return nearestPoint;
    }

    private static List<Point> getAllPossiblePoints() {
        List<Point> points = new ArrayList<>();
        for (int x = 0; x <= 10; x++) {
            for (int y = 0; y <= 10; y++) {
                points.add(new Point(x, y));
            }
        }
        return points;
    }

    private static double calculateDistance(Point currentLocation, Point point) {
        return Math.sqrt(
                Math.pow(currentLocation.x - point.x, 2) +
                Math.pow(currentLocation.y - point.y, 2));
    }

}

