public static Node reverseLinkedList(Node head) {
    if (head == null || head.next == null) {
        return head;
    }

    Node prev = null;
    Node current = head;
    Node next = null;

    while (current != null) {
        // Store the next node for pointer reversal 
        next = current.next;
        // Reverse the pointer
        current.next = prev;
        // Move to the next node
        prev = current;
        current = next;
    }
    return prev;
}

