class BinaryTree {
    private Node root;

    // Constructor
    public BinaryTree() {
        root = null;
    }

    // Returns true if the tree is empty
    public boolean isEmpty() {
        return root == null;
    }

    // Inserts an item into the tree
    public void insert(int data) {
        root = insert(root, data);
    }

    // Method to recursively insert a node into a subtree
    private Node insert(Node node, int data) {
        if (node == null) {
            node = new Node(data);
        } else {
            if (data <= node.data) {
                node.left = insert(node.left, data);
            } else {
                node.right = insert(node.right, data);
            }
        }
        return node;
    }

    // Method to delete a node from the tree
    public void delete(int k) {
        if (isEmpty()) {
            System.out.println("Tree Empty");
        } else if (search(k) == false) {
            System.out.println("Sorry "+ k +" is not present");
        } else {
            root = delete(root, k);
            System.out.println(k+ " deleted from the tree");
        }
    }
    private Node delete(Node root, int k) {
        Node p, p2, n;
        if (root.data == k) {
            Node lt, rt;
            lt = root.left;
            rt = root.right;
            if (lt == null && rt == null) {
                return null;
            } else if (lt == null) {
                p = rt;
                return p;
            } else if (rt == null) {
                p = lt;
                return p;
            } else {
                p2 = rt;
                p = rt;
                while (p.left != null) {
                    p = p.left;
                }
                p.left = lt;
                return p2;
            }
        }
        if (k < root.data) {
            n = delete(root.left, k);
            root.left = n;
        } else {
            n = delete(root.right, k);
            root.right = n;             
        }
        return root;
    }

    // Method to search for an element in the tree
    public boolean search(int val) {
        return search(root, val);
    }
    private boolean search(Node r, int val) {
        boolean found = false;
        while ((r != null) && !found) {
            int rval = r.data;
            if (val < rval) {
                r = r.left;
            } else if (val > rval) {
                r = r.right;
            } else {
                found = true;
                break;
            }
            found = search(r, val);
        }
        return found;
    }

    // Method to find the inorder successor
    public int inorderSucc(int k) {
        return inorderSucc(root, k);
    }
    private int inorderSucc(Node root, int k) {
        Node succ = null;
        if (root == null) {
            return 0;
        }
        // search for the key
        while (root.data != k) {
            if (k < root.data) {
                succ = root;
                root = root.left;
            } else {
                root = root.right;
            }
        }
        // if key is found, the successor is the minimum key in the right subtree
        if (root.right != null) {
            Node temp = root.right;
            while (temp.left != null) {
                temp = temp.left;
            }
            succ = temp;
        }
        return succ.data;
    }

    // Method to find the preorder successor
    public int preorderSucc(int k) {
        return preorderSucc(root, k);
    }
    private int preorderSucc(Node root, int k) {
        Node succ = null;
        if (root == null) {
            return 0;
        }
        // search for the key
        while (root.data != k) {
            if (k < root.data) {
                root = root.left;
            } else {
                succ = root;
                root = root.right;
            }
        }
        // if key is found, the predecessor is the largest key in the left subtree
        if (root.left != null) {
            Node temp = root.left;
            while (temp.right != null) {
                temp = temp.right;
            }
            succ = temp;
        }
        return succ.data;
    }

    // Method to determine the height of a node
    public int minimum() {
        return minimumNode(root);
    }
    private int minimumNode(Node node) {
        if (node.left == null) {
            return node.data;
        }
        return minimumNode(node.left);
    }
    // Method to determine the height of a node
    public int height(int key) {
        return height(root, key, 0);
    }
    private int height(Node root, int key, int level) {
        if (root == null) {
            return 0;
        }
        if (root.data == key) {
            return level;
        }
        int nextLevel = level + 1;
        if (root.data < key) {
            return height(root.right, key, nextLevel);
        } else {
            return height(root.left, key, nextLevel);
        }
    }

    // Method to print the tree
    public void printTree() {
        if (isEmpty()) {
            System.out.println("Tree Empty");
            return;
        }
        System.out.println("===================");
        printTree(root);
        System.out.println("===================");
    }

    private void printTree(Node root) {
        if (root != null) {
            printTree(root.left);
            System.out.println(root.data);
            printTree(root.right);
        }
    }

    // Node class
    private class Node {
        private int data;
        private Node left;
        private Node right;

        public Node() {
            left =null;
            right = null;
        }
        public Node(int n) {
            data = n;
            left = null;
            right = null;
        }
    }
}

