def compress_string(input_str):
    compressed_str = ""
    cur_char = ""
    count = 0
    for char in input_str:
        if char != cur_char:
            if count > 0:
                compressed_str += (cur_char + str(count))
            cur_char = char
            count = 1
        else:
            count += 1
    compressed_str += (cur_char + str(count))
    return compressed_str

