function primeFactors(n) { 
   let count = 0; 
    while (n % 2 == 0) { 
        count++; 
        n = n / 2; 
    } 
    for (let i = 3; i <= Math.sqrt(n); i = i + 2) { 
        while (n % i == 0) { 
            count++; 
            n = n / i; 
        } 
    } 
    if (n > 2) 
        count++; 

    return count; 
} 

