const sum = (num1, num2) => {
  let carry;
  while (num2) {
    let add = num1 ^ num2;  // get the sum of the numbers without carry
    carry = num1 & num2;    // carry
    num1 = add;
    num2 = carry << 1;
  }
  return num1;
}

