public static int getNthFibonacci(int n) {
    int first = 0, second = 1, next, i;

    if (n == 0) {
        return 0;
    }
    if (n == 1) {
        return 1;
    }

    for(i = 2; i <= n; i++) {
        next = first + second;
        first = second;
        second = next;
    }

    return next;
}

