public static void findMostFrequent(String s1, String s2) {
 List<String> words = new ArrayList<String>();
 words.addAll(Arrays.asList(s1.split(" ")));
 words.addAll(Arrays.asList(s2.split(" ")));

 Map<String, Integer> wordCounts = new HashMap<>();
 for (String word : words) {
 if (wordCounts.containsKey(word)) {
 wordCounts.put(word, wordCounts.get(word) + 1);
 } else {
 wordCounts.put(word, 1);
 }
 }

 int max = 0;
 List<String> mostFrequentWords = new ArrayList<>();
 for (Map.Entry<String, Integer> entry : wordCounts.entrySet()) {
 if (entry.getValue() > max) {
 mostFrequentWords.clear();
 mostFrequentWords.add(entry.getKey());
 max = entry.getValue();
 } else if(entry.getValue() == max){
 mostFrequentWords.add(entry.getKey());
 }
 }

 System.out.println(mostFrequentWords);
}

