// Function to print the first prime number greater than a given number
int main()
{
    int k = 100;  // given number
    int num = k + 1;  // number to check whether it is prime or not

    // run an infinite loop
    while (1)
    {
        int divisor = 2;

        // for each number check whether it is prime or not
        while (divisor <= num / 2)
        {
            if (num % divisor == 0)
            {
                break;
            }
            divisor++;
        }

        // if the number is prime then print it
        if (divisor > num / 2)
        {
            cout << "The first prime number greater than " << k << " is " << num << endl;
            return 0;
        }

        // if the number is not prime then increment it
        num++;
    }

    return 0;
}

