function numberOfUniquePaths(m, n) {
 // create a 2D array to store results
 const result = Array(m).fill(1).map(() => Array(n).fill(1));

 // fill all cells from the second row 
 // since first row has only one path in each cell
 for (let i = 1; i < m; i++) {
  for (let j = 1; j < n; j++) {
   // fill each cell of result matrix with 
   // sum of values from previous row and column
   result[i][j] = result[i - 1][j] + result[i][j - 1];
  }
 }

 return result[m - 1][n - 1];
}

