const int years_to_repay = 5; // years
const double annual_interest_rate = 0.04; // 4%

double calculateTotalPayableAmount(double principal)
{
    double totalAmountPayable = 0;
    double interestAmount = 0;
    for(int i = 0; i < years_to_repay; i++)
    {
        interestAmount = principal * pow(1 + annual_interest_rate, i);
        totalAmountPayable += interestAmount;
    }
    totalAmountPayable += principal;

    return totalAmountPayable;
}

