class Stack {
 constructor() {
  this.items = [];
  this.length = 0;
 }

 // Pushs an element to the top of the stack
 push(element) {
  this.items[this.length] = element;
  this.length += 1;
  return this.length;
 }

 // Pops an element from the top of the stack
 pop() {
  if (this.length === 0) return undefined;
  const element = this.items[this.length-1];
  delete this.items[this.length-1];
  this.length -= 1;
  return element;
 }
}

class Queue(object):
    def __init__(self):
        self.items = []

    def isEmpty(self):
        return self.items == []

    def enqueue(self, item):
        self.items.insert(0, item)

    def dequeue(self):
        return self.items.pop()

    def size(self):
        return len(self.items)

