class Carousel extends Component {
	constructor(props) {
		super(props);
		this.state = {
			slides: props.slides,
			currentIndex: 0
		};
	}

	goToNext = () => {
		this.setState({
			currentIndex: (this.state.currentIndex + 1) % this.state.slides.length
		});
	}

	goToPrev = () => {
		this.setState({
			currentIndex: (this.state.currentIndex + this.state.slides.length - 1) % this.state.slides.length
		});
	}

	render() {
		const { currentIndex, slides } = this.state;
		const currentSlide = slides[currentIndex];
		return (
			<div>
				<div>{currentSlide}</div>
				<button onClick={this.goToPrev}>Previous</button>
				<button onClick={this.goToNext}>Next</button>
			</div>
		);
	}
}

