def BFS(tree):
    queue = []
    visited = []

    root = tree.root
    queue.append(root)

    while len(queue) > 0:
        node = queue.pop(0)
        visited.append(node)
        for child in node.children:
            if child not in visited and child not in queue:
                queue.append(child)
    return visited

