    """Find all the prime numbers up to a given integer

    Args:
        n (int): Upper limit upto which the prime numbers should be found

    Returns:
        List[int]: List of all prime numbers between 0 and n
    """
    if n < 2:
        return []
    primes_list = [2]
    for i in range(3, n+1):
        is_prime = True
        for j in primes_list:
            if i % j == 0:
                is_prime = False
