def generate_binary_tree(lst):
    if len(lst) == 0:
        return None
    root = TreeNode(lst[0])
    queue = [root]
    i = 1
    while queue and i <= len(lst)-1:
        temp = queue.pop(0)

        value = lst[i]
        if value != 'null':
            temp.left = TreeNode(value)
            queue.append(temp.left)
        i += 1
        if i > len(lst)-1:
            break

        value = lst[i]
        if value != 'null':
            temp.right = TreeNode(value)
            queue.append(temp.right)
        i += 1
    return root

