function deleteList(head) {
    if (head == null) {
        return;
    }
    let currentNode = head;
    let nextNode = head.next;
    while (nextNode) {
        // delete current node
        delete currentNode;
        // move to the next node
        currentNode = nextNode;
        nextNode = nextNode.next;
    }
    // delete the last node
    delete currentNode;
    // set head to null
    head = null;
}

