  for (let i = 0; i < passwordLength; i++) {
    let randomCharIndex = Math.floor(Math.random() * allowedChars.length);
    let randomChar = allowedChars.charAt(randomCharIndex);

    if (arrayCheck.indexOf(randomChar) === -1) {
      randomPwd += randomChar;
