function secondToLastIndex(arr, item) {
  let lastIndex = -1;
  let prevIndex = -1;

  for (let i = 0; i < arr.length; i++) {
    if (arr[i] === item) {
      lastIndex = i;
      if (prevIndex !== -1) {
        return prevIndex;
      }
    }
    prevIndex = lastIndex;
  }
  return -1;
}

