public static ArrayList<int[]> findPrimePairs(int givenNumber) {
	// Initialize a list to store all the pairs 
	ArrayList<int[]> primePairs = new ArrayList<int[]>();

	// Iterate through each pair of numbers till givenNumber 
	for (int i = 0; i < givenNumber; i++) {
		for (int j = 0; j < givenNumber; j++) {
			// Add the pair to the list if 
			// it is a prime pair
			if (isPrime(i) && isPrime(j) && (i + j ==givenNumber)) {
				int[] temp = new int[2];
				temp[0] = i;
				temp[1] = j;
				primePairs.add(temp);
			}
		}
	}

	// Return the list of prime pairs 
	return primePairs;
}

