let ballX = 50;
let ballY = 50;
let ballVelY = 0;
let ballRadius = 10;

// setup of slopes
const liftWidth = 50;
const liftHeight = 20;
const rampHeight = 250;

// draw the lift
ctx.fillRect(0, canvas.height - liftHeight, liftWidth, liftHeight)

// draw the ramp
ctx.fillRect(liftWidth, canvas.height - liftHeight - rampHeight, canvas.width, rampHeight);

// animation loop
function update(){
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = "#F00";
    ctx.fillRect(0, canvas.height - liftHeight, liftWidth, liftHeight);
    ctx.fillRect(liftWidth, canvas.height - liftHeight - rampHeight, canvas.width, rampHeight);

  ballY += ballVelY;
  ballVelY += 0.15;

  ctx.fillStyle = "#000";
  ctx.beginPath();
  ctx.arc(ballX, ballY, ballRadius, 0, Math.PI * 2);
  ctx.fill();

  // if it has hit the bottom of the ramp, reset the ball
  if (ballY > canvas.height - liftHeight - ballRadius){
    ballX = 50;
    ballY = 50;
    ballVelY = 0;
  }
  requestAnimationFrame(update);
}

