fn main() {
    let arr = vec![3, 11, 2, 9, 1];
    let sorted_arr = merge_sort(arr);
    println!("{:?}", sorted_arr);
}

fn merge_sort(arr: Vec<i32>) -> Vec<i32> {
    let len = arr.len();
    if len <= 1 {
        return arr;
    }

    let mid = len / 2;
    let left = arr[0..mid].to_vec();
    let right = arr[mid..len].to_vec();

    let left_arr = merge_sort(left);
    let right_arr = merge_sort(right);

    merge(&left_arr, &right_arr)
}

fn merge(left_arr: &[i32], right_arr: &[i32]) -> Vec<i32> {
    let mut left_index = 0;
    let mut right_index = 0;
    let mut merged_arr: Vec<i32> = Vec::new();

    while left_index < left_arr.len() && right_index < right_arr.len() {
        if left_arr[left_index] < right_arr[right_index] {
            merged_arr.push(left_arr[left_index]);
            left_index += 1;
        } else {
            merged_arr.push(right_arr[right_index]);
            right_index += 1;
        }
    }

    while left_index < left_arr.len() {
        merged_arr.push(left_arr[left_index]);
        left_index += 1;
    }

    while right_index < right_arr.len() {
        merged_arr.push(right_arr[right_index]);
        right_index += 1;
    }

    merged_arr
}

