function permutations(arr) {
  let result = [];

  function recurse(arr, m = []) {
    if (arr.length === 0 && m.length > 0) {
      result.push(m);
    }
    for (let i = 0; i < arr.length; i++) {
      let current = arr.slice();
      let next = current.splice(i, 1);
      recurse(current.slice(), m.concat(next));
    }
  }

  recurse(arr);
  return result;
}

