public class ContactsApp extends Application {

    public static void main(String[] args) {
        launch(args);
    }

    @Override
    public void start(Stage primaryStage) {
        primaryStage.setTitle("Contacts App");
        GridPane grid = new GridPane();
        grid.setHgap(10);
        grid.setVgap(10);
        TextField nameTf = new TextField();
        TextField emailTf = new TextField();
        Button addBtn = new Button("Add Contact");
        Button editBtn = new Button("Edit Contact");
        Button deleteBtn = new Button("Delete Contact");
        ListView<String> contactsList = new ListView<String>();

        // Set up event handlers
        addBtn.setOnAction(e -> {
            contactsList.getItems().add(nameTf.getText() + " - " + emailTf.getText());
        });

        editBtn.setOnAction(e -> {
            String contact = contactsList.getSelectionModel().getSelectedItem();
            if (contact != null) {
                String name = contact.split(" - ")[0];
                String email = contact.split(" - ")[1];
                nameTf.setText(name);
                emailTf.setText(email);
            }
        });

        deleteBtn.setOnAction(e -> {
            String contact = contactsList.getSelectionModel().getSelectedItem();
            if (contact != null) {
                contactsList.getItems().remove(contact);
            }
        });

        grid.add(new Label("Name:"), 0, 0);
        grid.add(nameTf, 1, 0);
        grid.add(new Label("Email:"), 0, 1);
