        grid.add(editBtn, 2, 1);
        grid.add(deleteBtn, 2, 2);
        grid.add(contactsList, 0, 2, 2, 1);

        Scene scene = new Scene(grid, 300, 200);
        primaryStage.setScene(scene);
        primaryStage.show();
    }

}

import java.util.Arrays;

public class KnapsackOptimizer {
    public static void main(String[] args) {
        int[] weights = { 5, 10, 15 };
        int[] values = { 10, 30, 20 };
        int maxWeight = 20;

        // Compute the number of objects
        int numItems = weights.length;

        // Create a 2D array to store the solutions
        int[][] solutionTable = new int[numItems+1][maxWeight+1];

        // Iterate over the objects
        for (int i = 1; i <= numItems; i++) {
            for (int w = 1; w <= maxWeight; w++) {
                // Get the current weight and value
                int weight = weights[i - 1];
                int value = values[i - 1];

                // Check if the current object fits in the knapsack
                if (weight <= w) {
                    // Compute the new weight and value
                    int newWeight = w - weight;
                    int newValue = value + solutionTable[i - 1][newWeight];

                    // Update the solution table
                    solutionTable[i][w] = Math.max(solutionTable[i - 1][w], newValue);
                }
                else {
                    // The current object doesn't fit in the knapsack
                    solutionTable[i][w] = solutionTable[i - 1][w];
                }
            }
        }

        // Print the solution table
        for (int[] row : solutionTable) {
            System.out.println(Arrays.toString(row));
        }
    }
}

