        return currentChannel;
    }

    public void setCurrentChannel(int channel) {
        this.currentChannel = channel;
    }

    public int getCurrentVolume() {
        return currentVolume;
    }

    public void setCurrentVolume(int volume) {
        this.currentVolume = volume;
    }

    public boolean isMuted() {
        return isMuted;
    }

    public void setMuted(boolean muted) {
        this.isMuted = muted;
    }

    // Method for changing the channel
    public void changeChannel(int channel) {
        this.currentChannel = channel;
    }

    // Method for turning the volume up or down
    public void adjustVolume(int amount) {
        if (amount > 0) {
            this.currentVolume += amount;
        } else {
            this.currentVolume -= Math.abs(amount);
        }
    }

    // Method for muting or unmuting the tv
    public void toggleMute() {
        this.isMuted = !this.isMuted;
    }
}

def find_prime_numbers(num):
    prime_numbers = []

    # Traverse through all numbers 
    for i in range(2, num + 1):
        count = 0
        for j in range(2, i // 2 + 1):
            if (i % j == 0):
                count += 1
                break

        # If the number is prime then print it 
        if (count == 0 and i != 1):
            prime_numbers.append(i)

    return prime_numbers

