// Function to convert a base-N number
// to base-10.
int ConvertToBase10(string num, int base) 
{ 
    int len = num.length(); 
    int power = 1;
    int number = 0; 

    for (int i = len - 1; i >= 0; i--) { 
        if (num[i] >= '0' && num[i] <= '9') { 
            number += (num[i] - '0') * power; 
            power = power * base; 
        } 
    } 

    return number;
} 

