public bool isTreesEqual(TreeNode root1, TreeNode root2) {
  // Base Cases
  if (root1 == null && root2 == null) {
    return true;
  }

  if (root1 != null && root2 != null) {
    if (root1.data == root2.data && isTreesEqual(root1.left, root2.left) && isTreesEqual(root1.right, root2.right)) {
      return true;
    }
  }

  return false;
}

