import java.util.ArrayList;
import java.util.List;

public class KMeansClustering {

	public static void main(String[] args) {
		int k = 2;
		List<Integer> data = new ArrayList<>();
		data.add(1);data.add(7);data.add(8);data.add(10);
		data.add(12);data.add(15);data.add(19);

		List<List<Integer>> clusters = kMeansClustering(data, k);

		System.out.println("Clusters:");
		for(List<Integer> cluster: clusters) {
			System.out.println(cluster);
		}
	}

	private static List<List<Integer>> kMeansClustering(List<Integer> data, int k) {

		// Step 1 - Randomly assign points to k clusters;
		List<List<Integer>> clusters = new ArrayList<>();
		for(int i=0; i<k; i++) {
			clusters.add(new ArrayList<>());
		}

		int index = 0;
		for(Integer num: data) {
			clusters.get(index).add(num);
			index = (index + 1) % k; 
		}

		// Step 2 - Compute mean of each cluster
		List<Integer> means = new ArrayList<>();
		for(int i=0; i<k; i++) {
			int sum = 0;
			for(Integer num: clusters.get(i)) {
				sum += num;
			}

			int mean = sum / clusters.get(i).size();
			means.add(mean);
		}

		// Step 3 - Assign each data point to closest mean
		for(int i=0; i<data.size(); i++) {
			int num = data.get(i);
			int minIndex = 0;
			for(int j=0; j<means.size(); j++) {
				if(Math.abs(num - means.get(minIndex)) > Math.abs(num - means.get(j))) {
					minIndex = j;
				}

				// update cluster
				clusters.get(minIndex).add(num);
			}
		}

		return clusters;
	}

}

