class TreeNode {
  constructor(value) {
    this.value = value;
    this.left = null;
    this.right = null;
  }
}

class BinaryTree {
  constructor(root) {
    this.root = new TreeNode(root);
  }

  insert(node, root = this.root) {
    if (!node) { return; }
    if (node.value < root.value) {
      if (root.left === null) {
        root.left = node;
      } else {
        this.insert(node, root.left);
      }
    } else {
      if (root.right === null) {
        root.right = node;
      } else {
        this.insert(node, root.right);
      }
    }
  }

  search(item, root = this.root) {
    if (item === root.value) {
      return true; 
    } else {
      if (item < root.value) {
        if (root.left === null) {
          return false;
        } else {
          return this.search(item, root.left);
        }
      } else {
        if (root.right === null) {
          return false;
        } else {
          return this.search(item, root.right);
        }
      }
    }
  }
}

