public static string LongestCommonSubsequence(string str1, string str2){ 
    int n = str1.Length; 
    int m = str2.Length; 
    int[,] memMatrix = new int[n+1,m+1]; 

    // Memoization 
    for (int i = 0; i < n; i++) 
    { 
        for (int j = 0; j < m; j++) 
        { 
            if (i == 0 || j == 0) 
                memMatrix[i, j] = 0; 
            else if (str1[i - 1] == str2[j - 1]) 
                memMatrix[i, j] = memMatrix[i - 1, j - 1] + 1; 
            else
                memMatrix[i, j] = Math.Max(memMatrix[i - 1, j], memMatrix[i, j - 1]); 
        } 
    } 
    // Result 
    int index = memMatrix[n, m]; 

    char[] result = new char[index + 1]; 
    result[index] = '\0'; // char array to store the result 

    int i = n, j = m; 
    while (i > 0 && j > 0)  
    { 
        if (str1[i - 1] == str2[j - 1])  
        { 
            result[index - 1] = str1[i - 1];  
            i--;  j--; index--;    
        } 
        else if (memMatrix[i - 1, j] > memMatrix[i, j - 1]) 
            i--; 
        else
            j--; 
    } 
    return result; 
}

