// Function to find the longest common subsequence between two strings 
static String lcs(String s1, String s2) 
{ 
    int m = s1.length(), n = s2.length(); 

    int[][] L = new int[m + 1][n + 1]; 

    // Construct the length matrix 
    for (int i = 0; i <= m; i++) 
    { 
        for (int j = 0; j <= n; j++) 
        { 
            if (i == 0 || j == 0) 
                L[i][j] = 0; 
            else if (s1.charAt(i - 1) == s2.charAt(j - 1)) 
                L[i][j] = L[i - 1][j - 1] + 1; 
            else
                L[i][j] = Math.max(L[i - 1][j], L[i][j - 1]); 
        } 
    } 

    // Create the string to store the LCS 
    int index = L[m][n]; 
    char[] lcsStr = new char[index + 1]; 
    lcsStr[index] = '\0'; 

    int i = m, j = n; 
    while (i > 0 && j > 0) 
    { 
        // If current character in s1 and s2 are same, 
        // then current character is part of LCS 
        if (s1.charAt(i - 1) == s2.charAt(j - 1)) 
        { 
            lcsStr[index - 1] = s1.charAt(i - 1);  
            i--; 
            j--; 
            index--;      
        } 

        // If not same, consider the use of either 
        // s1 or s2 and find the longest 
        else if (L[i - 1][j] > L[i][j - 1]) 
            i--; 
        else
            j--; 
    } 

    // Return the LCS 
    return String.valueOf(lcsStr); 
 }

