import numpy as np

def costFunction(x):
    return (3 * x) + np.sqrt(x) + 5

def geneticOptimization(numGenerations, populationSize, mutationRate, crossoverRate):
    population = np.random.randint(-10, 10, size=(populationSize,1))
    for _ in range(numGenerations):
        new_pop = []
        for i in range(populationSize):
            indv_1, indv_2 = np.random.choice(populationSize, size=2, replace=False)
            crossover_arr = np.random.randint(2, size=1)
            if crossover_arr == 0:
                new_pop.append(population[indv_1])
            else:
                mutated_gene_1 = population[indv_1] + mutationRate * np.random.randint(-10, 10, size=1)
                mutated_gene_2 = population[indv_2] + mutationRate * np.random.randint(-10, 10, size=1)
                new_pop.append(np.where(costFunction(mutated_gene_1) < costFunction(mutated_gene_2), mutated_gene_1, mutated_gene_2))
        population = np.asarray(new_pop)
        best_solution = population[np.argmin(costFunction(population))]
    return best_solution, costFunction(best_solution)

