function findPaths(grid){
    const path = [];
    let visited = new Set();
    function dfs(cR, cC){
        if(cR === grid.length - 1 && cC === grid[0].length - 1){
            return path.push(path.slice());
        }
        visited.add(cR + ',' + cC);
        if(cR + 1 < grid.length && !visited.has((cR+1) + ',' + cC) && grid[cR+1][cC] === 0){
            path.push([cR,cC]);
            dfs(cR+1, cC);
            path.pop();  
        } 
        if(cC + 1 < grid[0].length && !visited.has(cR + ',' + (cC + 1)) && grid[cR][cC + 1] === 0){
            path.push([cR,cC]);
            dfs(cR, cC+1);
            path.pop(); 
        }
        visited.delete(cR + ',' + cC);
    }
    dfs(0, 0);
    console.log(visited);
    return path;
}

