function countChar(str) { 

    // Create an associative array to 
    // store the count of each character 
    var count = {}; 

    // Iterate through the given string 
    for (let  i = 0; i < str.length; i++) { 

        // Initialize the current character 
        // if not found in the count object 
        if (count[str.charAt(i)] === undefined){ 
            count[str.charAt(i)] = 1; 
        } 
        else { 
            // Increment the character count 
            count[str.charAt(i)]++; 
        } 
    } 

    // Find the maximum occurring character 
    var max = 0; 

    for (let i = 0; i < str.length; i++) { 
        if (count[str.charAt(i)] > max) { 
            max = count[str.charAt(i)]; 
        } 
    } 

    return max; 
}

