vector<int> removeDuplicates(vector<int> input)
{
    unordered_set<int> seen;
    vector<int> output;

    for (int i : input)
    {
        if (seen.find(i) == seen.end())
        {
            seen.insert(i);
            output.push_back(i);
        }
    }

    return output;
}

