def find_all_primes(n):
  # Initialize a list 
  primes = []
  # Loop from 2 to n
  for num in range(2, n + 1):
    is_prime = True
    for i in range(2, num):
        if (num % i == 0):
            is_prime = False
            break
    if (is_prime):
        primes.append(num)
  # Return a list of primes
  return primes

