// A Binary Tree node  
struct Node  
{  
    int data;  
    Node *left, *right;  
}; 

// Function to print all the levels of binary tree  
void printLevelOrder(Node *root)  
{  
    // Base Case  
    if (root == NULL)  return;  

    // Create an empty queue for level order traversal  
    queue<Node *> q;  

    // Enqueue Root and initialize height  
    q.push(root);  

    while (q.empty() == false)  
    {  
        // nodeCount (queue size) indicates number of nodes  
        // at current level.  
        int nodeCount = q.size();  

        // Dequeue all nodes of current level and Enqueue all  
        // nodes of next level  
        while (nodeCount > 0)  
        {  
            Node *node = q.front();  
            cout << node->data << " ";  
            q.pop();  
            if (node->left != NULL)  
                q.push(node->left);  
            if (node->right != NULL)  
                q.push(node->right);  
            nodeCount--;  
        }  
        cout << endl;  
    }  
}

