using namespace std;

template<typename T>
class Stack {
 private:
     // underlying data structure to store elements 
     stack<T> data;

 public:
     // add an element to the top of the stack
     void push(T element) {
         data.push(element);
     }

     // remove the element at the top of the stack
     void pop() {
         data.pop();
     }

     // get the element at the top of the stack
     T top() {
         return data.top();
     }

     // check if the stack is empty
     bool isEmpty() {
         return data.empty();
     }
};

