const romanNumeral = num => {
    let roman = {
      1: 'I',
      4: 'IV',
      5: 'V',
      9: 'IX',
      10: 'X',
      40: 'XL',
      50: 'L',
      90: 'XC',
      100: 'C',
      400: 'CD',
      500: 'D',
      900: 'CM',
      1000: 'M'
    }

    let digits = String(+num).split('').reverse().map((val,i) => Math.pow(10,i)*val);

    let romanNum = digits.map(val => Object.entries(roman).find(n => n[0] === val)).reverse().join('');

    return romanNum;
}

