import javax.swing.*; 
import java.awt.event.*; 
import java.awt.*; 

public class Calculator extends JFrame implements ActionListener {
    private JTextField expression;
    private JButton calculate; 
    private JLabel result; 

    public Calculator(){ 
        // Create frame
        super("Calculator"); 
        setLayout(new FlowLayout(FlowLayout.CENTER)); 

        // Create text field
        expression = new JTextField(32); 
        add(expression); 

        // Create button
        calculate = new JButton("Calculate"); 
        add(calculate); 

        calculate.addActionListener(this); 

        // Create result Label
        result = new JLabel("Result"); 
        add(result); 

        setSize(320,180); 
        setVisible(true); 
    } 

    public void actionPerformed(ActionEvent e){ 
        if(e.getSource()==calculate){ 
            // Evaluate expression
            String expr = expression.getText(); 
            double res = eval(expr);

            // Display result
            result.setText("Result: "+res); 
        } 
    } 

    public static double eval(final String str) {
        return new Object() {
            int pos = -1, ch;

            void nextChar() {
                ch = (++pos < str.length()) ? str.charAt(pos) : -1;
            }

            boolean eat(int charToEat) {
                while (ch == ' ') nextChar();
                if (ch == charToEat) {
                    nextChar();
                    return true;
                }
                return false;
            }

            double parse() {
                nextChar();
                double x = parseExpression();
                if (pos < str.length()) throw new RuntimeException("Unexpected: " + (char)ch);
                return x;
            }

            // Grammar:
            // expression = term | expression `+` term | expression `-` term
            // term = factor | term `*` factor | term `/` factor
            // factor = `+` factor | `-` factor | `(` expression `)`
	          //        | number | functionName factor | factor `^` factor

            double parseExpression() {
                double x = parseTerm();
                for (;;) {
                    if      (eat('+')) x += parseTerm(); // addition
                    else if (eat('-')) x -= parseTerm(); // subtraction
                    else return x;
                }
            }

            double parseTerm() {
                double x = parseFactor();
                for (;;) {
                    if      (eat('*')) x *= parseFactor(); // multiplication
                    else if (eat('/')) x /= parseFactor(); // division
                    else return x;
                }
            }

            double parseFactor() {
                if (eat('+')) return parseFactor(); // unary plus
                if (eat('-')) return -parseFactor(); // unary minus

                double x;
                int startPos = this.pos;
                if (eat('(')) { // parentheses
                    x = parseExpression();
                    eat(')');
                } else if ((ch >= '0' && ch <= '9') || ch == '.') { // numbers
                    while ((ch >= '0' && ch <= '9') || ch == '.') nextChar();
                    x = Double.parseDouble(str.substring(startPos, this.pos));
                } else if (ch >= 'a' && ch <= 'z') { // functions
                    while (ch >= 'a' && ch <= 'z') nextChar();
                    String func = str.substring(startPos, this.pos);
                    x = parseFactor();
                    if (func.equals("sqrt")) x = Math.sqrt(x);
                    else if (func.equals("sin")) x = Math.sin(Math.toRadians(x));
                    else if (func.equals("cos")) x = Math.cos(Math.toRadians(x));
                    else if (func.equals("tan")) x = Math.tan(Math.toRadians(x));
                    else throw new RuntimeException("Unknown function: " + func);
                } else {
                    throw new RuntimeException("Unexpected: " + (char)ch);
                }

                if (eat('^')) x = Math.pow(x, parseFactor()); // exponentiation

                return x;
            }
        }.parse();
    }

    public static void main(String[] args) {
        Calculator calc = new Calculator(); 
    } 
}

#include <iostream>
using namespace std;

struct Node
{
 int data;
 struct Node *next;
}*top=NULL;

void push(int x)
{
 struct Node* temp = (struct Node*)malloc(sizeof(struct Node));

 if(temp == NULL)
 {
 cout<<"Stack Overflow\n";
 exit(1);
 }

 temp->data = x;
 temp->next = top;
 top = temp;
}

int pop()
{
 int x;
 struct Node *temp;

 if(top==NULL)
 {
 cout<<"Stack Underflow\n";
 exit(1);
 }
 temp = top;
 x = top->data;
 top = top->next;
 free(temp);

 return x;
}

bool isEmpty()
{
 return top == NULL;
}

int main()
{
 push(3);
 push(2);
 push(4);

 cout<<pop()<<endl;
 cout<<pop()<<endl;
 cout<<pop()<<endl;

 return 0;
}

def permutations(s):
    # If the string is empty, return
    if not s:
        return

    # Create an empty list to store all the permutations
    permutations = []

    # Base case: if the input string is of length 1, return the only permutation of the string
    if len(s) == 1:
        permutations.append(s)
        return permutations

    # Otherwise, iterate through the characters of the string
    for i, c in enumerate(s):
        # Generate all the permutations of the string without the character at index i
        partials = permutations(s[:i] + s[i + 1:])
        # Add the character at index i to the beginning of each partial, and add to permutations
        for p in partials:
            permutations.append(c + p)

    return permutations

