def most_frequent(list_nums):
    freq_dict = {} 
    for i in list_nums: 
        if i not in freq_dict:
            freq_dict[i] = 1
        else:
            freq_dict[i] += 1
    max_val = 0
    max_key = None
    for key, val in freq_dict.items(): 
        if val > max_val: 
            max_val = val
            max_key = key
    return max_key

