"""
Design and implement an algorithm to find the longest common subsequence of two sequences
"""
def lcs(seq1, seq2):
    if not seq1 or not seq2:
        return ""

    if seq1[0] == seq2[0]:
        return seq1[0] + lcs(seq1[1:], seq2[1:])

    else:
        temp1 = lcs(seq1[1:], seq2)
        temp2 = lcs(seq1, seq2[1:])
        if len(temp1) > len(temp2):
            return temp1
        else:
            return temp2

