def findNthLargest(arr, n):
    left = 0
    right = len(arr)

    while left <= right:
        pivot = partition(arr, left, right)
        if pivot == n - 1:
            return arr[pivot]
        if pivot > n - 1:
            right = pivot - 1
        else:
            left = pivot + 1
    return -1

def partition(arr, left, right):
    pivot = arr[right]
    j = left
    for i in range(left, right):
        if arr[i] > pivot:
            arr[i], arr[j] = arr[j], arr[i]
            j += 1
    arr[j], arr[right] = arr[right], arr[j]
    return j

