function intervalsOverlapping (intervals) {
  // Create an array to store the overlapping intervals
  let overlapping = [];
  // Sort the intervals by startTime
  intervals.sort((a, b) => a.startTime - b.startTime);

  // Loop through the array of intervals 
  for (let i = 0; i < intervals.length; i++) {
    // store the current interval
    const current = intervals[i];

    // Loop through the remaining intervals 
    for (let j = i + 1; j < intervals.length; j++) {
      // store the next interval
      const next = intervals[j];

      // Check if the two intervals are overlapping
      if (next.startTime < current.endTime) {
        // push overlapping intervals to the overlapping array
        overlapping.push([current, next]);
      }
    }
  }
  return overlapping;
}

