class Program
    {
        static void Main(string[] args)
        {
            Console.WriteLine("Displaying the calendar for April, 2020");
            Console.WriteLine("\nSu Mo Tu We Th Fr Sa");

            for (int i = 0; i < GetDayOfWeek(4, 1, 2020); i++)
                Console.Write("   ");

            for (int day = 1; day <= GetNumberOfDays(4, 2020); day++)
            {
                Console.Write(day.ToString().PadLeft(2, ' ') + " ");

                if (((day + GetDayOfWeek(4, 1, 2020)) % 7) == 0)
                    Console.WriteLine();
            }

            Console.ReadLine();
        }

        static int GetNumberOfDays(int month, int year)
        {
            int[] days = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
            int result = days[month - 1];
            if (month == 2 && (year % 4 == 0 && year % 100 != 0 || year % 400 == 0))
                result++;
            return result;
        }

        static int GetDayOfWeek(int month, int day, int year)
        {
            int[] t = { 0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4 };
            year -= (month < 3) ? 1 : 0;
            return (year + year / 4 - year / 100 + year / 400 + t[month - 1] + day) % 7;
        }
    }

