def isPalindrome(input):
  if len(input) == 0:
    return True
  else:
    left = 0
    right = len(input)-1

    while (left < right):
      if (input[left] != input[right]):
        return False
      else:
        left += 1
        right -= 1

  return True


def minPalindromeReplace(input):
  if isPalindrome(input):
    return 0
  else:
    # Initialize a counter to record the minimum number of replacements
    count = 0
    # Set the positions of left and right
    left = 0
    right = len(input)-1

    while (left < right):
      # If the positions are not equal, replace the right element
      # with the left element
      if (input[left] != input[right]):
        input[right] = input[left]
        count += 1
      # Move to the next pair of positions
      left += 1
      right -= 1

    # Return the minimum number of replacements
    return count

