// This function check if email is valid or not. 
// It returns true if valid, false otherwise.
bool isEmailValid(string email)
{
    if (email.find('@') == string::npos) {
        return false;
    }

    int count = 0;
    for (int i = 0; i < email.length(); i++) {
        if (email[i] == '@') {
            count++;
        }
    }
    if (count > 1) {
        return false;
    }

    // split string
    int index = email.find('@');
    string left = email.substr(0, index);
    string right = email.substr(index + 1);

    // check local part. It should not contain any special characters
    // like %, $ etc
    for (int i = 0; i < left.length(); i++) {
        if (!isalnum(left[i])) {
            return false;
        }
    }

    // check domain part. It should contain at least a dot
    if (right.find('.') == string::npos) {
        return false;
    }

    return true;
}

