class MemoryAllocator():
    def __init__(self, size):
        self.size = size
        self.memory = [None] * size
        self.free_list = [(0, size)]

    def malloc(self, size):
        """Allocate a block of memory of the given size. Return a pointer to the start
        of the block, or -1 to indicate failure."""
        for start, end in self.free_list:
            if end - start >= size:
                self.free_list.remove((start, end))
                self.free_list.append((start + size, end))
                for i in range(start, start + size):
                    self.memory[i] = 1
                return start
        return -1

    def free(self, pointer):
        """Free the memory allocated at the given pointer."""
        size = 0
        while self.memory[pointer + size] is not None:
            size += 1
            self.memory[pointer + size] = None
        self.free_list.append((pointer, pointer + size))

