// Class Declaration
class Triangle 
{
  private:
    int side1;
    int side2;
    int side3;

  public:
    Triangle();                                 // Empty Constructor
    Triangle (int a, int b, int c);             // Constructor
    float  perimeter();                         // Method to calculate the perimeter
    float  area();                              // Method to calculate the area
    void   setSides (int a, int b, int c);      // Method to define the sides
};

// Constructor (Empty)
Triangle::Triangle()
{
  side1 = 0;
  side2 = 0;
  side3 = 0;
};

// Constructor (Non-Empty)
Triangle::Triangle (int a, int b, int c)
{
  side1 = a;
  side2 = b;
  side3 = c;
};

//Method to define the sides
void Triangle::setSides (int a, int b, int c)
{ 
  side1 = a;
  side2 = b;
  side3 = c;
};

//Method to calculate the perimeter
float Triangle::perimeter()
{
  return (side1 + side2 + side3);
};

//Method to calculate the area
float Triangle::area()
{
  //According to Heron's formula
  float s = (side1 + side2 + side3) / 2;
  return sqrt(s * (s - side1) * (s - side2) * (s - side3));
};

