def sec_smallest(arr):
    smallest = None
    second_smallest = None

    for num in arr:
        if smallest is None:
            smallest = num
            continue
        if num <= smallest:
            second_smallest = smallest
            smallest = num
        elif second_smallest is None or num < second_smallest:
            second_smallest = num
    return second_smallest

