public class ScoreSortingSystem {

    public static int[] sortScores(int[] scores) {
        // sort scores in descending order
        Arrays.sort(scores);
        int[] sorted = new int[scores.length];
        int idx = 0;
        for (int i = scores.length - 1; i >= 0; --i) {
            sorted[idx] = scores[i];
            idx++;
        }
        return sorted;
    }

    public static void main(String[] args) {
        int[] scores = {70, 60, 50, 40, 30, 20, 10};
        int[] sortedScores = sortScores(scores);
        for (int i : sortedScores) {
            System.out.println(i);
        }
    }

}

// Output: 70 60 50 40 30 20 10

