def find_power_set(s): 
    powerset = [] 
    n = len(s) 
    for i in range(1 << n): 
        powerset_subset = []
        for j in range(n): 
            if (i & (1 << j)) > 0:
               powerset_subset.append(s[j])
        powerset.append(powerset_subset) 
    return powerset

