function totalDaysInYear(year) {
   // checks if the year is a leap year 
   if(year % 400 == 0 || (year % 100 != 0 && year % 4 == 0)) 
     // If a leap year, Feb consists of 29 days
     return (365 + 29); 

   else
     // If a normal year, Feb consists of 28 days
     return (365 + 28); 
}

