public static void insertionSort(int[] Arr){
    for (int i = 1; i < Arr.length; i++) {
        int key = Arr[i];
        int j = i - 1;

        while (j >= 0 && Arr[j] > key) {
            Arr[j + 1] = Arr[j];
            j = j - 1;
        }
        Arr[j + 1] = key;
    }
}

