def replaceElements(matrix):
    m = len(matrix)
    n = len(matrix[0])
    # Maintain two arrays to indicate if row or column needs to be set as zero
    rows = [0]*m
    cols = [0]*n

    for i in range(m):
        for j in range(n):
            if matrix[i][j] == 0:
                # set this row and column as zero
                rows[i] = 1
                cols[j] = 1

    # If a row/column need to be set as zero, set all elements as 0 for that particular row/column
    for i in range(m):
        for j in range(n):
            if rows[i] or cols[j]:
                matrix[i][j] = 0

