def minimumSubstringContainingTarget(s, t):
    min_length = len(s)
    min_substring = ""

    for i in range(len(s)):
        start = i
        end = i + len(t) 
        search_substring = s[start:end]

        if set(search_substring).issuperset(t):
            if end - start < min_length:
                min_length = end - start
                min_substring = search_substring
    return min_substring

