using System;

namespace sorting
{
    class Program
    {
        static void Main(string[] args)
        {
            // Array of integers
            int[] arr = { 45,87,14,32,74,50 };

            // Performs quick sort
            QuickSort(arr, 0, arr.Length - 1);

            // Print the sorted array
            Console.WriteLine(string.Join(",", arr));
        }

        public static void QuickSort(int[] arr, int low, int high)
        {
            // Check for empty or null array 
            if (arr == null || arr.Length == 0)
            {
                return;
            }

            if (low >= high)
            {
                return;
            }

            // Get the pivot element from the middle of the list 
            int middle = low + (high - low) / 2;
            int pivot = arr[middle];

            // Divide into two lists
            int i = low;
            int j = high;

            // Traverse through the list
            while (i <= j)
            {
                // If the current value from the left list is smaller than the pivot element,
                // then get the next element from the left list
                while (arr[i] < pivot)
                {
                    i++;
                }

                // If the current value from the right list is larger than the pivot element,
                // then get the next element from the right list
                while (arr[j] > pivot)
                {
                    j--;
                }

                // If we have found a values in the left list which is greater than pivot
                // and if we have found a value in the right list which is smaller than pivot 
                if (i <= j)
                {
                    // Swap values
                    int temp = arr[i];
                    arr[i] = arr[j];
                    arr[j] = temp;

                    // Move the target index to the correct position
                    i++;
                    j--;
                }
            }

            // Divide the array into two parts and call 
            // recursive method for each part 
            if (low < j)
            {
                QuickSort(arr, low, j);
            }

            if (high > i)
            {
                QuickSort(arr, i, high);
            }
        }
    }
}

def predict(data, tree):
    if tree['node_type'] == 'leaf':
        return tree['value']
    feature_index = tree['feature_index']
    if data[feature_index] < tree['value']:
        return predict(data, tree['left_child'])
    else:
        return predict(data, tree['right_child'])

