// Function to find the nearest prime number
int nearestPrimeNumber(int number) {
    int start = number;

    // check if 'number' is even
    if (number % 2 == 0) {
        start--;
    }

    // check if a number is prime or not
    while (true) {
        bool isPrime = true;

        // iterate from 3 to sqrt(start) to find if it is prime
        for (int i = 3; i <= sqrt(start); i++) {
            if (start % i == 0) {
                isPrime = false;
                break;
            }
        }
        if (isPrime)
            break;
        start = start - 2;
    }
    return start;
}

