// Create a function in Java to take a 2d array of integers, and return the average value of all the elements in the array.
public static double average2Darray(int[][] arr){
    // initializing sum and count for calculating average
    int sum = 0;
    int count=0;
    for (int i = 0; i< arr.length; i++) {
        for (int j = 0; j < arr[i].length; j++) {
            // accumulation of sum 
            sum = sum + arr[i][j];
            count++;
        }
    }
    // calculating average and returning
    return (double)(sum / count);
}

