def findMostFrequentWords(sentence): 
    word_count = {} 

    words = sentence.split() 

    for word in words: 
        if word in word_count: 
            word_count[word] += 1
        else: 
            word_count[word] = 1

    # sorting the words returned by most frequent occurring words 
    words = sorted(word_count.items(), key = lambda kv:(kv[1], kv[0]), reverse = True) 

    # print the 3 most frequent occurring words 
