def is_partitionable(arr):
size = len(arr)
sum_total = sum(arr)
sum_half = sum_total // 2
dp = [[False for _ in range(sum_half + 1)] for i in range(size + 1)]

for i in range(size + 1):
    dp[i][0] = True

for s in range(1, sum_half + 1):
    dp[0][s] = False

for i in range(1, size + 1):
    for s in range(1, sum_half + 1):
        if arr[i - 1] <= s:
            dp[i][s] = dp[i - 1][s - arr[i - 1]] or dp[i - 1][s]
        else:
            dp[i][s] = dp[i - 1][s]

return dp[size][sum_half]

