def is_anagram(str1, str2):
    # Store character counts
    char_counts = {}

    # Iterate over first string
    for char in str1:
        char_counts[char] = char_counts.get(char, 0) + 1

    # Iterate over second string
    for char in str2:
        if char in char_counts:
            char_counts[char] -= 1
        else:
            char_counts[char] = 1

    for count in char_counts.values():
        if count != 0:
            return False

    return True

