function isDivisibleBy11(number) {
    // convert number into string
    let str = number.toString();

    // calculate difference between first and second digits
    let diff1 = Math.abs(str[0] - str[1]);
    // calculate difference between second and third digits
    let diff2 = Math.abs(str[1] - str[2]);

    // check for divisibility
    return diff1 % 11 === 0 && diff2 % 11 === 0;
