    "3": ["d", "e", "f"],
    "9": ["w", "x", "y", "z"]
  };

  // get all combinations
  let combinations = [];
  let tmp = [];
  backtrack(combinations, tmp, num, map, 0);

  return combinations;
}

function backtrack(combinations, tmp, num, map, index) {
  if (index === num.length) {
    combinations.push([...tmp].join(""));
    return;
  }

  let digits = map[num[index]];
  for (let i = 0; i < digits.length; i++) {
    tmp.push(digits[i]);
    backtrack(combinations, tmp, num, map, index + 1);
    tmp.pop();
  }
}

