def huffman_encoding(s):
    huffman_dict = {}

    # Step 1 - Get the frequency of the characters
    for char in s:
        if char not in huffman_dict:
            huffman_dict[char] = s.count(char)

    # Step 2 - Sort in descending order according to the frequency
    huffman_dict = dict(sorted(huffman_dict.items(), key=lambda x: x[1], reverse=True))

    # Step 3 - Create a Huffman tree
    while len(huffman_dict) > 1:
        p1 = huffman_dict.popitem()
        p2 = huffman_dict.popitem()
        freq = p1[1] + p2[1]
        huffman_dict[p1[0] + p2[0]] = freq
        huffman_dict = dict(sorted(huffman_dict.items(), key=lambda x: x[1], reverse=True))

    # Step 4 - Create a Huffman Code
    huffman_code = {}

    def huffman_traversal(root_node, binary_code="", output_code={}):
        if len(root_node) == 1: # Leaf Node
            output_code[root_node] = binary_code
        else:
            huffman_traversal(root_node[0], binary_code+"0", output_code)
            huffman_traversal(root_node[1], binary_code+"1", output_code)

        return output_code

    huffman_code = huffman_traversal(list(huffman_dict.keys())[0], "", huffman_code)

    # Step 5 - Generate Encoded String
    encoded_string = ""
    for char in s:
        encoded_string += huffman_code[char]

    return encoded_string, huffman_code

