// A function to perform linear search on a singly linked list
node* linearSearch(node *head, int item) {
    // Initialize current node
    node* currNode = head;

    // Traverse the list looking for match
    while (currNode != NULL) {
        // If node has matching value, return pointer
        if (currNode->value == item) {
            return currNode;
        }
        // Otherwise traverse to next node
        else {
            currNode = currNode->next;
        }
    }

    // Return NULL if item not found
    return NULL;
}

