def decipher(encoded_text):
    # Create a empty list to store the decrypted text
    decoded_text = []

    for char in encoded_text:
        # Get the character unicode
        char_code = ord(char)
        #Decrement the character unicode and append
        decoded_text.append(chr(char_code - 1))

    return ''.join(decoded_text)

