public class LongestPalindrome {

	public static String findLongestPalindrome(String str) {
		int n = str.length();
		boolean[][] isPalindrome = new boolean[n][n];
		int start = 0;
		int maxLen = 0;
		for (int i = 0; i < n; i++) {
			isPalindrome[i][i] = true;
			if (i < n - 1 && str.charAt(i) == str.charAt(i + 1)) {
				isPalindrome[i][i + 1] = true;
				start = i;
				maxLen = 2;
			}
		}

		for (int k = 3; k <= n; k++) {
			for (int i = 0; i < n - k + 1; i++) {
				int j = i + k - 1;
				if (str.charAt(i) == str.charAt(j) && isPalindrome[i + 1][j - 1]) {
					isPalindrome[i][j] = true;
					start = i;
					maxLen = k;
				}
			}
		}

		return str.substring(start, start + maxLen);
	}

	public static void main(String[] args) {
		String str = "abceffedcba";
		System.out.println("The longest palindrome substring is: " + findLongestPalindrome(str));
	}
}

# Create a dictionary to easily access the numeric values of the Roman Numerals
ROMAN_NUMERALS = {'I': 1,'IV': 4,'V': 5,'IX': 9,'X': 10,'XL': 40,'L': 50,'XC': 90,'C': 100,'CD': 400,'D': 500,'CM': 900,'M': 1000}

# Create a function to convert Roman numerals to numbers
def convertRomanToNumber(numeral):
   number = 0
   i = 0
   while i < len(numeral):
       s1 = ROMAN_NUMERALS[numeral[i]]

       # If next character is greater than current char, generate value
       if i+1 < len(numeral): 
           s2 = ROMAN_NUMERALS[numeral[i+1]] 
           # Add current char if lower
           if s1 >= s2: 
               number = number + s1 
               i = i + 1
           else:
               number = number + s2 - s1 
               i = i + 2
       else: 
           number = number + s1 
           i = i + 1

   return number

