// Bubble sort function
func bubbleSort(arr: [Int]) -> [Int] {
    var numbers = arr

    // Iterate over each element
    for i in 0..<arr.count {
        // Iterate over elements after i
        for j in (i + 1)..<arr.count {
            if numbers[i] > numbers[j] {
                let temp = numbers[i]
                numbers[i] = numbers[j]
                numbers[j] = temp
            }
        }
    }
    return numbers
}

