def isAnagram(string1, string2):
    # Check if length is different
    if len(string1) != len(string2):
        return False

    # Create dictionaries for the two strings
    dic1 = {}
    dic2 = {}

    for char in string1:
        dic1[char] = dic1.get(char, 0) + 1

    for char in string2:
        dic2[char] = dic2.get(char, 0) + 1

    # Check if characters in both dictionaries are equal
    for char in dic1:
        if char not in dic2 and dic1[char] != dic2[char]:
