struct ListNode {
	int data;
	ListNode* next;
};

ListNode* newNode(int data) {
	ListNode* temp = new ListNode;
	temp->data = data;
	temp->next = NULL;
	return temp;
}

int getSum(ListNode* head1, ListNode* head2) {
	int sum = 0;
	while (head1 != NULL || head2 != NULL) {
		if (head1 != NULL) {
			sum += head1->data;
			head1 = head1->next;
		}

		if (head2 != NULL) {
			sum += head2->data;
			head2 = head2->next;
		}
	}
	return sum;
}

int main()
{
	ListNode* head1 = newNode(7);
	head1->next = newNode(1);
	head1->next->next = newNode(6);

	ListNode* head2 = newNode(9);
	head2->next = newNode(7);
	head2->next->next = newNode(8);

	std::cout << "Sum of two list is " << getSum(head1, head2);
	return 0;
}

