def sort(array):
    for i in range(len(array)):
        min_index = i
        for j in range(i + 1, len(array)):
            if array[min_index] > array[j]:
                min_index = j
        array[i], array[min_index] = array[min_index], array[i]
    return array

function normal_distribution(mean, variance) {
    var factor = Math.sqrt(variance * 2 * Math.PI);
    return function() {
        var r1 = Math.random();
        var r2 = Math.random();

        var result = Math.sqrt(-2 * Math.log(r1)) * Math.cos(2 * Math.PI * r2);
        result = mean + result * Math.sqrt(variance);

        return result;
    };
}

