const initialState = {
 cart: [],
};

// define the reducer
function cartReducer(state = initialState, action) {
 switch (action.type) {
 case 'CART_ADD':
 // add item to cart
 return {
 ...state,
 cart: [...state.cart, action.payload],
 };
 case 'CART_UPDATE':
 // update quantity for item in cart
 return {
 ...state,
 cart: state.cart.map(item => {
