func addHandler(w http.ResponseWriter, r *http.Request) {
 if r.Method != http.MethodGet {
  http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
  return
 }

 // Get the query parameters
 x, ok := r.URL.Query()["x"]
 if !ok {
  http.Error(w, "x query parameter is required", http.StatusBadRequest)
  return
 }

 y, ok := r.URL.Query()["y"]
 if !ok {
  http.Error(w, "y query parameter is required", http.StatusBadRequest)
  return
 }

 // Do the calculation
 xInt, err := strconv.Atoi(x[0])
 if err != nil {
  http.Error(w, "Error parsing x parameter", http.StatusBadRequest)
  return
 }

 yInt, err := strconv.Atoi(y[0])
 if err != nil {
