def add(x, y):
    # Find the MSB of both x and y
    x_msb = x >> 1
    y_msb = y >> 1

    # Calculate the sum of x and y with no carry
    sum_no_carry = x ^ y

    # Calculate the carry of x and y
    carry = x_msb & y_msb

    # Recursively add the carry to sum
    if carry == 0:
        return sum_no_carry
    else:
        return add(carry << 1, sum_no_carry)

