import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.PriorityQueue;

public class AStar {

 // Stores the coordinates of a node
 public class Node {
  int x;
  int y;

  public Node(int x, int y) {
   this.x = x;
   this.y = y;
  }
 }

 // Callback interface for traversing the path
 public interface PathCallback {
  void onPath(Node node);
 }

 // Array for traversing the path
 private ArrayList<Node> path = new ArrayList<>();

 // Comparator for prioritize queue
 private Comparator<Node> nodeComparator = new Comparator<Node>() {
  @Override
  public int compare(Node n1, Node n2) {
   if (n1.f > n2.f) {
    return 1;
   }
   else if (n1.f < n2.f) {
    return -1;
   }
   return 0;
  }
 };

 // Create and return a new Astar path finder
 public static AStar create() {
  return new AStar();
 }

 // Calculate the shortest path between start and goal nodes
 public void findPath(int startX, int startY,
   int goalX, int goalY, PathCallback callback) {

  // Create starting and goal nodes
  Node startNode = new Node(startX, startY);
  Node goalNode = new Node(goalX, goalY);

  // Keep track of visited nodes
  HashMap<Node, Node> visitedNodes = new HashMap<>();

  // Create priority queue for exploring nodes
  PriorityQueue<Node> queue = new PriorityQueue<>(nodeComparator);

  queue.add(startNode);
  visitedNodes.put(startNode, null);

  boolean isPathFound = false;

  // Continue to explore nodes until the queue is empty
  while (!queue.isEmpty()) {
   // Get the first node from the queue
   Node currentNode = queue.poll();

   // If the goal is reached, stop
   if (currentNode.equals(goalNode)) {
    isPathFound = true;
    break;
   }

   // Get the neighboring nodes and add them to the queue
   ArrayList<Node> neighboringNodes = getNeighbors(currentNode);
   for (Node node : neighboringNodes) {

    // Skip visited node and add it to the queue
    if (!visitedNodes.containsKey(node)) {
     queue.add(node);
     visitedNodes.put(node, currentNode);
    }
   }
  }

  // If the goal is reached, construct the path
  if (isPathFound) {
   Node currentNode = goalNode;
   while (currentNode != null) {
    path.add(currentNode);
    currentNode = visitedNodes.get(currentNode);
   }

   // Flip the route so it is from start to goal direction
   for (int i = 0; i < path.size() / 2; i++) {
    Node temp = path.get(i);
    path.set(i, path.get(path.size() - 1 - i));
    path.set(path.size() - 1 - i, temp);
   }

   // Call the callback for each node
   for (Node node : path) {
    callback.onPath(node);
   }
  }
 }

 // Get the neighbors of a node
 private ArrayList<Node> getNeighbors(Node a) {
  ArrayList<Node> neighbors = new ArrayList<>();

  // Choose 8 directions
  for (int x = -1; x <= 1; x++) {
   for (int y = -1; y <= 1; y++) {

    // Avoid starting direction
    if (!(x == 0 && y == 0)) {

     Node b = new Node(a.x + x, a.y + y);
     neighbors.add(b);

    }
   }
  }

  return neighbors;
 }

}

