def findLongestCommonSubstring(str1, str2):
    str1_len = len(str1)
    str2_len = len(str2)

    LCS = [[0 for x in range(str2_len+1)] for y in range(str1_len+1)]
    longest_substring = 0
    longest_substring_end = 0

    for i in range(1, str1_len+1):
        for j in range(1, str2_len+1):
            if (str1[i-1] == str2[j-1]):
                LCS[i][j] = LCS[i-1][j-1] + 1

                if (LCS[i][j] > longest_substring):
                    longest_substring = LCS[i][j]
                    longest_substring_end = i
    return str1[longest_substring_end-longest_substring: longest_substring_end]

