public int MinimizeSumDifference(int[] array) {  
    int n = array.Length;  

    int check = (1 << n) - 1; // All n bits are set -> all is 1

    int minDiff = int.MaxValue; 

    // Iterate through all the masks
    while (check > 0)   
    {        
        int temp = check;
        int mask1 = 0; 
        int mask2 = 0;
        int k = 0;

        // Generate all the possible masks
        while (temp > 0)   
        {           
            if ((temp & 1) == 1) 
            {
                mask1 += (1 << k);                        
            } 
            else
            {
                mask2 += (1 << k);
            }
            k++; 
            temp >>= 1; 
        }  

        // Calculate the sum of both masks
        int sum1 = 0, sum2 = 0;  

        for (int i = 0; i < n; i++)  
        {  
            if ((mask1 & (1 << i)) > 0) {
                sum1 += array[i];
            }
            else if ((mask2 & (1 << i)) > 0) {
                sum2 += array[i];
            } 
        }

        int diff = Math.abs(sum1 - sum2);

        // Minimize the difference
        minDiff = Math.Min(minDiff, diff);  

        // Decrease the check to get next loops
        check --; 
    }
    return minDiff; 
}

