import java.util.Random;

public class Pattern{

    public static void main(String[] args){
        String pattern = "Abe12*";

        String result = generate(pattern);
        System.out.println(result);
    }

    public static String generate(String pattern){
        char[] patternArray = pattern.toUpperCase().toCharArray();
        StringBuilder output = new StringBuilder();

        for(char c : patternArray){
            if(Character.isLetter(c)){
                output.append(generateLetter());
            } else if(Character.isDigit(c)){
                output.append(generateNumber());
            } else if(c == '*'){
                output.append(generateSymbol());
            } else{
                throw new IllegalArgumentException("Invalid pattern");
            }
        }
        return output.toString();
    }

    private static char generateLetter(){
        Random r = new Random();
        int low = 65;
        int high = 90;

        return (char)(r.nextInt(high - low) + low);
    }

    private static char generateNumber(){
        Random r = new Random(); 
        int low = 0;
        int high = 9;

        return (char)(r.nextInt(high - low) + low + 48);
    }

    private static char generateSymbol(){
        Random r = new Random();
        int low = 33;
        int high = 47;

        return (char)(r.nextInt(high - low) + low);
    }
}

