char* delete_repeat_characters(char str[]) 
{ 
    int i, j, length; 
    i = 0; 
    length = strlen(str); 

    while (i < length)
    { 
        if (str[i] == str[i + 1]) { 
            j = i; 

            // Shift all characters after i
            while (j < length) { 
                str[j] = str[j + 1]; 
                j++; 
            } 

            length--; 
        } 
        else { 
            i++; 
        } 
    } 

    return str; 
} 

