// Returns longest common substring
string LCS(string s1, string s2) {
    int n = s1.length();
    int m = s2.length();
    int mxlen = 0;
    string res = "";

    int dp[n+1][m+1];

    for(int i = 0; i <= n; ++i) {
        for(int j = 0; j <= m; ++j) {
            if (i == 0 || j == 0) {
                dp[i][j] = 0;
            }
            else if (s1[i-1] == s2[j-1]) {
                dp[i][j] = dp[i-1][j-1] + 1;
                if (dp[i][j] > mxlen) {
                    mxlen = dp[i][j];
                    res = s1.substr(i-mxlen, mxlen);
                }
            }
            else {
                dp[i][j] = 0;
            }
        }
    }

    return res;
}

