def decimalToHex(decimal): 
    result = ""
    hex_values = {10: "A", 11: "B", 12: "C", 13: "D", 14: "E", 15: "F" }
    while decimal > 0:
        remainder = decimal % 16 
        distinct = False
        if remainder > 9:
            remainder = hex_values[remainder]
            distinct = True
        if distinct:
            result = remainder + result
        else:
            result = str(remainder) + result            
        decimal //= 16 
