procedure Selection_Sort is
   type Array_Type is array (1 .. 10) of Integer;
   Numbers : Array_Type;
   Size : Natural := 10;
   Pos, j : Integer;
begin
   -- Fill the array with sample numbers
   Numbers(1) := 3;
   Numbers(2) := 8;
   Numbers(3) := 2;
   Numbers(4) := 1;
   Numbers(5) := 5;
   Numbers(6) := 7;
   Numbers(7) := 18;
   Numbers(8) := 6;
   Numbers(9) := 20;
   Numbers(10) := 19;

   -- Output the unsorted array
   Put_Line("Unsorted list:");
   for i in Numbers'Range loop
      Put(Numbers(i), 0);
   end loop;
   New_Line;

   -- Sort the array
   for Pos in Numbers'Range loop
      -- Find the index of the smallest element
      j := Pos;
      for i in Numbers'Range(Pos+1 .. Size) loop
         if Numbers(i) < Numbers(j) then
            j := i;
         end if;
      end loop;
      -- Swap the smallest element with the current element
      if Numbers(j) /= Numbers(Pos) then
         Swap(Numbers(Pos), Numbers(j));
      end if;
   end loop;

   -- Output the sorted array
   Put_Line("Sorted list:");
   for i in Numbers'Range loop
      Put(Numbers(i), 0);
   end loop;
   New_Line;
end Selection_Sort;

procedure Swap(Left, Right : in out Integer) is
   Temp : Integer;
begin
   Temp := Right;
   Right := Left;
   Left := Temp;
end Swap;

