def is_anagram(str1, str2):
    str1 = str1.lower().replace(' ','')
    str2 = str2.lower().replace(' ','')

    # Edge Case to check if same number of letters 
    if len(str1) != len(str2):
        return False

    counts = {}

    # Fill dictionary for first string 
    for letter in str1:
        if letter in counts:
            counts[letter] += 1
        else:
            counts[letter] = 1

    # Fill dictionary for second string
    for letter in str2:
        if letter in counts:
            counts[letter] -= 1
        else:
            counts[letter] = 1

    # Check that all counts are 0 
    for k in counts:
        if counts[k] != 0:
            return False

    # Otherwise they are anagrams 
    return True

