class Node:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

def construct_tree(arr):
    root = Node(arr[0])
    for value in arr[1:]:
        insert(root, value)

    return root

def insert(node, value):
    if value < node.value:
        if node.left is None:
            node.left = Node(value)
        else:
            insert(node.left, value)
    else:
        if node.right is None:
            node.right = Node(value)
        else:
            insert(node.right, value)

