    op, x, y = expr.split() 
    if op == '+' : 
        return float(x) + float(y) 
    if op == '-' : 
        return float(x) - float(y) 
    if op == '*' :
        return float(x) * float(y) 
    if op == '/' :
        return float(x) / float(y) 
    if op == '%':
        return float(x) % float(y)

def addWithoutPlus(x, y): 
    if y == 0: 
        return x 

    sum = x ^ y 
    carry = (x & y) << 1 
    return addWithoutPlus(sum, carry)

