func bubbleSort(_ list: [Int]) -> [Int] {
    var sortedList = list

    for i in 0..<sortedList.count {
        for j in (1..<sortedList.count-i).reversed() {
            if (sortedList[j] < sortedList[j - 1]) {
                let temp = sortedList[j]
                sortedList[j] = sortedList[j - 1]
                sortedList[j - 1] = temp
            }
        }
    }
    return sortedList
}

