        return True 
    if sum != 0 and len(arr) == 0: 
        return False 

    if arr[-1] > sum: 
        return subset_sum(arr[:-1], sum) 

    return subset_sum(arr[:-1], sum) or subset_sum(arr[:-1], sum-arr[-1])

public class CheckPowerOfTwo {
    public static boolean isPowerOfTwo(int num) {
        if (num == 0)
            return false;
        while (num != 1) {
            if (num % 2 != 0)
                return false;
            num = num / 2;
        }
        return true;
    }

    public static void main(String[] args) { 
        int num = 16;
        System.out.println(isPowerOfTwo(num)); // Outputs: true
    }
}

