char *findLongestString(char strings[][50], int n) 
{ 
    char *longString = strings[0]; 
    int len = strlen(strings[0]); 
    int i; 

    for (i = 1; i < n; i++) { 

        // Compare len of current string 
        int currLen = strlen(strings[i]); 

        // If current string's len is 
        // greater, then it becomes 
        // longest string 
        if (currLen > len) { 
            len = currLen; 
            longString = strings[i]; 
        } 
    } 

    return longString; 
}

