public class UserPreference {
    private Map<String, Set<String>> preferenceMap;

    public UserPreference() {
        this.preferenceMap = new HashMap<>();
    }

    public void addPreference(String userId, String preference) {
        preferenceMap.computeIfAbsent(userId, k -> new HashSet<>()).add(preference);
    }

    public Set<String> getPreferences(String userId) {
        return preferenceMap.getOrDefault(userId, Collections.emptySet());
    }

    public void deletePreference(String userId, String preference) {
        preferenceMap.computeIfPresent(userId,
            (userIdKey, prefs) -> {
                prefs.remove(preference);
                return prefs;
            });
    }
}

