function findMinNumberInArray(arr) {
    if (arr.length == 1) {
        return arr[0];
    } else {
        let min = arr[0];
        let current = arr[0];
        let subArray = arr.slice(1);
        let recursiveMin = findMinNumberInArray(subArray);

        if (recursiveMin < current) {
            min = recursiveMin;
        }
        return min;
    }
