import random

def shuffle(A):
    shuffled = [None] * len(A)
    for i in range(len(A)):
        # randomly pick an element to place in the shuffled array 
        random_index = random.randint(0, len(A) - 1)
        for j in range(len(A)):
            # make sure no element of the array is placed more than once
            while shuffled[random_index] != None:
                random_index = random.randint(0, len(A) - 1)
        shuffled[random_index] = A[i]
    return shuffled

