# Calculate the Levenshtein Distance between two strings
def levenshteinDistance(str1, str2):
    # Make sure they are the same length
    if len(str1) > len(str2):
        str1, str2 = str2, str1

    # Initialize an empty matrix
    matrix = [[0] * (len(str2) + 1)] * (len(str1) + 1)

    # Fill in the first row and column
    for i in range(len(str1) + 1):
        matrix[i][0] = i
    for j in range(len(str2) + 1):
        matrix[0][j] = j

    # Calculate the rest of the matrix 
    for i in range(1, len(str1) + 1):
        for j in range(1, len(str2) + 1):
            if str1[i - 1] == str2[j - 1]:
                cost = 0
            else:
                cost = 1
            matrix[i][j] = min(matrix[i - 1][j] + 1, matrix[i][j - 1] + 1, 
                         matrix[i - 1][j - 1] + cost)

    # Return the resultant matrix
    return matrix[-1][-1]

def find_highest_occurrence_words(word_list):
    # Create a dictionay to count the occurance of words
    word_dictionary = {}
    for word in word_list:
        if word in word_dictionary:
            word_dictionary[word] += 1
        else:
            word_dictionary[word] = 1

    # Find the word with highest occurance
    highest_occurance = 0
    highest_occurance_word = None
    for word in word_dictionary:
        if word_dictionary[word] > highest_occurance:
            highest_occurance = word_dictionary[word]
            highest_occurance_word = word

    # Output the word with the highest occurance
    return (highest_occurance_word, highest_occurance)

