def detect_plagiarism(text1, text2): 

    # convert both texts to lowercase strings  
    text1 = text1.lower() 
    text2 = text2.lower() 

    # calculate the frequency of each character in both strings 
    frequencies1 = dict() 
    frequencies2 = dict() 

    for character in text1: 
        if character in frequencies1: 
            frequencies1[character] += 1
        else: 
            frequencies1[character] = 1

    for character in text2: 
        if character in frequencies2: 
            frequencies2[character] += 1
        else: 
            frequencies2[character] = 1

    # Calculate the difference in character frequencies  
    difference = 0
    for character in frequencies1: 
        if character in frequencies2: 
            difference += abs(frequencies1[character] - frequencies2[character]) 
        else: 
            difference += frequencies1[character] 
    for character in frequencies2: 
        if character not in frequencies1: 
            difference += frequencies2[character] 

    # Calculate percentage of plagiarism 
    total_length = len(text1) + len(text2)
    similarity_percentage = 100 - (difference * 100) / total_length 

    return similarity_percentage

