  int rows;
  int cols;

  public Board(int rows, int cols) {
    board = new ArrayList<>();
    this.rows = rows;
    this.cols = cols;
  }

  public void resetBoard() {
    for (int i = 0; i < rows; i++) {
      List<String> row = new ArrayList<>();
      for (int j = 0; j < cols; j++) {
        row.add("-");
      }
      board.add(row);
    }
  }

  public boolean setMarker(int row, int col, String marker) {
    if (board.get(row).get(col).equals("-")) {
      board.get(row).set(col, marker);
      return true;
    }
    return false;
  }
}

