def is_prime(n):
    #Checks if a given number is prime

    #1 is not a prime number
    if n <= 1:
        return False

    #Check for numbers 2 and 3
    if n == 2 or n == 3:
        return True

    #Check all other numbers
    for i in range (2, int(math.sqrt(n))+1):
        if n % i == 0:
            return False

    return True

