def one_edit_away(str1, str2):
    # Check if the strings are the same
    if str1 == str2:
        return True

    # If the strings have a different length, they can't be one edit away
    if abs(len(str1) - len(str2)) > 1:
        return False

    # Initialize variables for looping through strings
    i, j, num_edits = 0, 0, 0

    # Find first non-matching character in both strings
    while i < len(str1) and j < len(str2) and num_edits <=1:
        # If the characters don't match, increment the number of edits
        if str1[i] != str2[j]:
            num_edits += 1
            if len(str1) < len(str2):
                j += 1
            elif len(str1) > len(str2):
                i += 1
            else:
                i += 1
                j += 1
        else:
            i += 1
            j += 1
    # Check to see if the number of edits is greater than one and return the result
    return num_edits <= 1

def hash_algorithm(dictionary):
    hashmap = {}
    for key, value in dictionary.items():
        hashed_value = hash(key) % len(dictionary)
        hashmap[hashed_value] = value
    return hashmap

