// Convert a single linked list into a double linked list
// End of list is indicated by NULL

// Head of single linked list
ListNode* singleLL = head;

// Head of double linked list
ListNode* doubleLL;
ListNode *prev, *next;

// Traverse the single LL
while(singleLL != NULL) { 
 // Create a new node 
 ListNode* newNode = new ListNode(singleLL->data); 

 // Link the new node with the previous node 
 if(prev != NULL) 
	 prev->next = newNode; 
 else
	 doubleLL = newNode; // Set the head of the double linked list 

 // Set the previous and the next node 
 prev = newNode; 
 next = singleLL->next; 

 // Link the new node to the next node 
