// Sub-function to find the length of the longest increasing subsequence of a given sequence
// Input : array A
// Output : length of the longest increasing subsequence of A
int LIS(int A[], int n)
{
    int lis[n], i, j, max=0;
    for (i = 0; i < n; i++)
        lis[i] = 1;

    for (i = 1; i < n; i++)
        for (j = 0; j < i; j++)
            if (A[i] > A[j] && lis[i] < lis[j] + 1)
                lis[i] = lis[j] + 1;

    for (i = 0; i < n; i++)
        if (max < lis[i])
            max = lis[i];

    return max;
}

