    // The email address must be a string
    if (typeof(email) !== 'string') {
        return false;
    }

    // The email address must contain one '@' character
    if (email.indexOf('@') === -1) {
        return false;
    }

    // The email address must not contain more than one '@' character
    if (email.indexOf('@') !== email.lastIndexOf('@')) {
        return false;
    }

    // The '@' character must not be the first or last character
    if (email.indexOf('@') === 0 || email.indexOf('@') === email.length - 1) {
        return false;
    }

    // Return true if all conditions are met
