#include <algorithm> 

bool isAnagram(string s1, string s2) 
{ 
    // Get lengths of both strings 
    int n1 = s1.length(); 
    int n2 = s2.length(); 

    // If lengths of both strings 
    // are not same, then they 
    // cannot be anagram 
    if (n1 != n2) 
        return false; 

    // Sort both strings 
    sort(s1.begin(), s1.end()); 
    sort(s2.begin(), s2.end()); 

    // Compare sorted strings 
    for (int i = 0; i < n1; i++) 
        if (s1[i] != s2[i]) 
            return false; 

    return true; 
}

