def decimal_to_hex(n):
    # Converting decimal to its equivalent hexadecimal
    hex_string = ""
    while n > 0:
        remainder = n % 16
        if remainder < 10:
            hex_string += str(remainder)
        else:
            hex_string += chr(remainder + 55)  # Convert number to its equivalent ASCII value
        n //= 16
    return hex_string[::-1] # Reverse the string for the final result

print(decimal_to_hex(255))  # Output: FF

