// Function to detect anomalies in network traffic data
function detectAnomalies(data) {
 // Calculate the mean of the data
 let mean = calculateMean(data);

 // Calculate the standard deviation of the data
 let stdev = calculateStdev(data);

 // Initialize the results array
 let results = []; 

 // Iterate over the data and find anomalies
 for (let i = 0; i < data.length; i++) {
 let element = data[i];

 // Calculate the z-score
 let z_score = (element - mean)/stdev; 

 // Check if the z-score is 3 standard deviations away from the mean
 if (z_score > 3 || z_score < -3) {
 // If yes, add the element to the results 
 results.push(element);
 }
 }

 return results;
}

