public class Stack {
    private int top;
    private int[] arr;
    private int size;

    public Stack(int size) {
        arr = new int[size];
        this.size = size;
        top = -1;
    }

    public void push(int element) {
        if (top == size - 1) {
            System.out.println("Stack is full");
        } else {
            arr[++top] = element;
        }
    }

    public int pop() {
        if (top == -1) {
            System.out.println("Stack is empty");
            return -1;
        } else {
            return arr[top--];
        }
    }

    public int peek() {
        if (top == -1) {
            System.out.println("Stack is empty");
            return -1;
        } else {
            return arr[top];
        }
    }

    public boolean isEmpty() {
        return (top == -1);
    }

    public boolean isFull() {
        return (top == size - 1);
    }
}

