    elif nltk.word_tokenize(sentence).count('good') > 0:
        score += 1
    elif nltk.word_tokenize(sentence).count('awesome') > 0:
        score += 1
    elif nltk.word_tokenize(sentence).count('amazing') > 0:
        score += 1
    elif nltk.word_tokenize(sentence).count('bad') > 0:
        score -= 1
    elif nltk.word_tokenize(sentence).count('horrible') > 0:
        score += 1

    # classify sentiment
    if score > 0:
        return 'positive'
    elif score < 0:
        return 'negative'
    else:
