function isArmstrong(num1, num2)
{
    // Store length of the two numbers
    var len1 = num1.toString().length;
    var len2 = num2.toString().length;

    // Calculate the Armstrong Number
    var sum1 = 0, sum2 = 0;
    while(num1 != 0)
    {
        var rem1 = num1 % 10;
        sum1 += Math.pow(rem1, len1);
        num1 = Math.floor(num1 / 10);
    }
    while(num2 != 0)
    {
        var rem2 = num2 % 10;
        sum2 += Math.pow(rem2, len2);
        num2 = Math.floor(num2 / 10);
    }

    // Check if the numbers are armstrong numbers
    if(sum1 == num1 && sum2 == num2)
        return true;
    else
        return false;
}

