function calculateMinCoins(amount) {
  // coins available
  const coins = [1, 5, 10, 25];

  // array of minimum number of coins for each amount
  let minCoins = [];
  minCoins.push(0);

  // compute minimum number of coins for each amount
  for (let i = 1; i <= amount; i++) {
    minCoins[i] = Number.MAX_SAFE_INTEGER;

    for (let j = 0; j < coins.length; j++) {
      if (coins[j] <= i) {
        let newValue = minCoins[i - coins[j]] + 1;
        minCoins[i] = Math.min(minCoins[i], newValue);
      }
    }
  }

  return minCoins[amount];
}

