public class StringToInt {
    public static int convert(String str) {
        int result = 0;
        int multiplier = 1;
        for (int i = str.length() - 1; i >= 0; i--) {
            int currDigit = Character.getNumericValue(str.charAt(i)); 
            result += currDigit * multiplier;
            multiplier *= 10;
        }
        return result;
    }
}

