def find_shortest_path(graph, start, end):
    # keep track of all visited nodes
    visited = set()
    # keep track of the shortest path 
    shortest_path = []
    # Keep track of how far each node is from the start
    # using a dictionary, with node names as the keys and
    # node distances as the values
    distances = {start: 0}

    while end not in visited:
        lowest_distance_node = None
        for node in graph.keys():
            if node not in visited and node in distances:
                if lowest_distance_node is None:
                    lowest_distance_node = node
                elif distances[node] < distances[lowest_distance_node]:
                    lowest_distance_node = node

        # update the visited set and the lowest distance 
        visited.add(lowest_distance_node)
        lowest_neighbors = graph[lowest_distance_node]
        for key, value in lowest_neighbors.items(): 
            if key not in visited: 
                new_distance = value + distances[lowest_distance_node]
                if key not in distances or new_distance < distances[key]: 
                    distances[key] = new_distance
                    # As we backtrack and find the shortest path, 
                    # add this information to the backtrack list 
                    shortest_path = [lowest_distance_node, key]

    #print the shortest path at the end 
    print(shortest_path)

