def traverse_tree_smallest_level(tree):
  if tree is None:
    return

  q = []
  level_smallest = []
  smallest = float('inf')
  q.append(tree)

  while len(q) > 0:
    current_level_size = len(q)
    for i in range(0, current_level_size):  
      tree_node = q.pop(0)
      smallest = min(smallest, tree_node["value"])
      if tree_node["left"] is not None:
          q.append(tree_node["left"])
      if tree_node["right"] is not None:
          q.append(tree_node["right"])
    level_smallest.append(smallest)
    smallest = float("inf")

  return level_smallest

