// Java program to sort an array of objects by name
import java.util.Arrays;

class SortByName {
    // class of object to sort
    static class Employee {
        private String name;
        private int salary;

        public Employee(String name, int salary) {
            this.name = name;
            this.salary = salary;
        }

        public String getName() {
            return name;
        }

        public int getSalary() {
            return salary;
        }
    }

    // comparator to sort the employee array
    public static class SortByNameComparator implements Comparator<Employee> {
        @Override
        public int compare(Employee e1, Employee e2) {
            return e1.getName().compareTo(e2.getName());
        }
    }

    // function to sort an array
    public static void sortEmployees(Employee[] employees) {
        //sort employees array using SortByNameComparator
        Arrays.sort(employees, new SortByNameComparator());
    }

    public static void main(String[] args) {
        Employee[] employees = { 
            new Employee("John", 20000),
            new Employee("Dave", 30000),
            new Employee("Alice", 10000)
        };

        sortEmployees(employees);
        // print sorted employees array
        System.out.println("Sorted Employees list by name:");
        for (int i = 0; i < employees.length; i++) {
            Employee e = employees[i];
             System.out.println("Name: " + e.getName() + ", Salary: $" + e.getSalary());
        }
    }
}

