// recursive approach 
int getTreeSum(Node root){
    // base case
    if(root == null)
        return 0;

    // return sum of current node plus left and right subtree
    return root.data + getTreeSum(root.left) + getTreeSum(root.right);
}

// iterative approach 
int getTreeSum(Node root){
    int sum = 0;
    Queue<Node> q = new LinkedList<Node>();
    q.add(root);

    // loop to traverse through the tree 
    while(! q.isEmpty()){
        Node node = q.poll();
        sum += node.data;

        // add left and right child of poll node 
        if(node.left != null)
            q.add(node.left);
        if(node.right != null)
            q.add(node.right);
    }
    return sum;
}

