fn merge_lists(list1: &mut Option<Box<Node>>, list2: &mut Option<Box<Node>>) -> Option<Box<Node>> {
    let mut merged_list: Option<Box<Node>> = None;
    let mut head = &mut merged_list;

    let mut l1 = list1;
    let mut l2 = list2;

    while let (Some(node1), Some(node2)) = (l1, l2) {
        if node1.data < node2.data {
            *head = Some(node1);
            l1 = &mut node1.next;
        } else {
            *head = Some(node2);
            l2 = &mut node2.next;
        }

        head = &mut head.as_mut().unwrap().next;
    }

    if let Some(node) = l1 {
        *head = Some(node);
    } else if let Some(node) = l2 {
        *head = Some(node);
    }

    merged_list
}

