 % This function solves the cubic equation ax3+bx2+cx+d=0

 coefs = [a b c d];

 % Compute the discriminant 
 delta = b^2 - 3*a*c;

 % Compute the 3 roots r1,r2, and r3

 % There are 3 real roots
 if delta > 0
  r1 = (-b + sqrt(delta))/(3*a);
  r2 = (-b - sqrt(delta))/(3*a);
  r3 = -c/(a*r1);

  % At least two real roots
 elseif delta == 0
  r1 = (-b + sqrt(delta))/(3*a);
  r2 = r1;
  r3 = -c/(a*r1);

