def permutations(s): 
    if len(s) == 1:
        return [s]

    permutation_list = []
    for a in s:
        remaining_elements = [x for x in s if x != a]
        z = permutations(remaining_elements)
        for t in z:
            permutation_list.append([a] + t)

    return permutation_list

