func generateWords(string: String) -> [String] {
    if string.count == 0 {
        return []
    }
    if string.count == 1 {
        return [String(string.first!)]
    }

    var words = [String]()
    let firstChar = string.first!
    let remainChars = String(string.dropFirst())
    let remainWords = generateWords(string: remainChars)

    for word in remainWords {
        words.append(String(firstChar) + word)
        words.append(word)
    }

    return words
}

