 private class GetRestaurantsTask extends AsyncTask<String, Void, List<Restaurant>> {

 @Override
 protected List<Restaurant> doInBackground(String... urls) {
 try {
 URL url = new URL(urls[0]);
 HttpURLConnection connection = (HttpURLConnection) url.openConnection();

 InputStream stream = connection.getInputStream();
 BufferedReader reader = new BufferedReader(new InputStreamReader(stream));

 String line;
 StringBuilder builder = new StringBuilder();

 while ((line = reader.readLine()) != null) {
 builder.append(line);
 }

 // Parse result
 JSONObject restaurants = new JSONObject(builder.toString());
 JSONArray dataArray = restaurants.getJSONArray("data");

 List<Restaurant> restaurantList = new ArrayList<>();

 for (int i = 0; i < dataArray.length; i++) {
 JSONObject restaurantObject = dataArray.getJSONObject(i);
 String name = restaurantObject.getString("name");
 double rating = restaurantObject.getDouble("rating");

 Restaurant restaurant = new Restaurant(name, rating);
 restaurantList.add(restaurant);
 }

 return restaurantList;

 } catch (MalformedURLException e) {
 Log.e("GetRestaurantsTask", "MalformedURLException", e);
 } catch (IOException e) {
 Log.e("GetRestaurantsTask", "IOException", e);
 } catch (JSONException e) {
 Log.e("GetRestaurantsTask", "JSONException", e);
 }

 return null;
 }

 @Override
 protected void onPostExecute(List<Restaurant> restaurants) {
 // Display results
 RestaurantAdapter adapter = new RestaurantAdapter(MainActivity.this,
 R.layout.list_item, restaurants);
 listView.setAdapter(adapter);
 }
 }

}

