public static boolean detectCycle(Node head) { 
    Node fast = head;
    Node slow = head;

    while (fast != null && fast.getNext() != null) { 
        fast = fast.getNext().getNext(); 
        slow = slow.getNext(); 

        if (fast == slow) { 
            return true; 
        } 
    } 

    // no cycle is present
    return false; 
}

