int secondLargest(int array[], int n) 
{ 
    int firstMax = array[0]; 
    int secondMax = INT_MIN; 

    for (int i=0; i<n; i++) 
    { 
        if (array[i] > firstMax) 
        { 
            secondMax = firstMax; 
            firstMax = array[i]; 
        } 

        else if (array[i] > secondMax && array[i] != firstMax ) 
            secondMax = array[i]; 
    } 

    return secondMax; 
}

