public static double Divide(int a, int b)
{
    int remainder = 0;
    int quotient = 0;
    while (remainder < b)
    {
        remainder += a;
        if (remainder >= b)
        {
            quotient++;
            remainder -= b;
        }
    }
    return (double)quotient;
}

