void permute(std::string a, int l, int r) 
{ 
   int i; 
   if (l == r) 
     std::cout << a << "\n"; 
   else
   { 
       for (i = l; i <= r; i++) 
       { 
          //swap 
          std::swap(a[l], a[i]); 

          //recursion with next positions 
          permute(a, l+1, r); 

          //backtrack 
          std::swap(a[l], a[i]); 
       } 
   } 
} 

