#include <iostream>

using namespace std;

class Stack
{
private:
    static const int MAX = 100; // Maximum size of the stack
    int top; // Position of the topmost element in the stack.
    int a[MAX]; // An array of integers with size MAX

public:
    Stack()  // Constructor to initialize the stack
    { 
        top = -1; 
    }

    bool push(int x); // Pushes an element onto the stack
    int pop(); // Removes an element from the stack and returns it
    int peek();  // Returns the topmost element in the stack without removing it
    int size(); // Returns the number of elements in the stack
    bool isEmpty(); // Returns true if the stack is empty, false otherwise
};

bool Stack::push(int x)
{
    if (top >= (MAX-1))
    {
        cout << "Stack Overflow";
        return false;
    }
    else
    {
        a[++top] = x;
        return true;
    }
}

int Stack::pop()
{
    if (top < 0) 
    {
        cout << "Stack Underflow";
        return 0;
    }
    else 
    {
        int x = a[top--];
        return x;
    }
}

int Stack::peek()
{
    if (top < 0) 
    {
        cout << "Stack is Empty";
        return 0;
    }
    else 
    {
        int x = a[top];
        return x;
    }
}

int Stack::size()
{
    return top+1;
}

bool Stack::isEmpty()
{
    return (top < 0);
}

