def lab(s):

    max_len = 0
    substring = ""

    # Initializing dictionary
    count = {}

    # Loop through the string to find the longest substring
    for i in range(len(s)):

        count[s[i]] = count.get(s[i], 0) + 1

        if len(count) > 2:
            del count[s[i-max_len-1]]
        else:
            max_len += 1

        if len(count) ==2 and max_len > len(substring):
            substring = s[i-max_len+1:i+1]

    return substring

