class DoublyLinkedList:
    def __init__(self):
        self.head = self.tail = None

    # adds a node at the end of the list 
    def add_node(self, data):
        if self.head is None:
            n = Node(data)
            self.head = self.tail = n
        else:
            n = Node(data)
            self.tail.next = n
            n.prev = self.tail
            self.tail = n

    # deletes a node at a given position
    def delete_node(self, pos):
        if self.head is None:
            return
        temp = self.head 
        if pos == 0: 
            self.head = temp.next
            temp = None
            return
        for i in range(pos -1 ): 
            temp = temp.next
            if temp is None: 
                break
        if temp is None: 
            return 
        if temp.next is None: 
            return
        next_node = temp.next.next
        temp.next = None
        temp.next = next_node
        next_node.prev = temp 

    def print_list(self):
        temp = self.head
        while temp:
            print(temp.val)
            temp = temp.next

