int waveFrequency(int frequency, int duration) 
{ 
  // vector to store the wave times
  std::vector<int> waveTimes;

  // loop from 0 to total duration
  for (int i = 0; i <= duration; i += frequency)
  {
    waveTimes.push_back(i);
  }

  // sort wave times
  std::sort(waveTimes.begin(), waveTimes.end());

  // print wave times
  std::cout << "The wave times are: " << std::endl;
  for (auto wave_time: waveTimes)
  {
    std::cout << wave_time << " ";
  }

  return waveTimes.size();
}

