// Merge and sort two sorted arrays into one sorted array
// Take 3 pointer variables, one each pointing to head of the two given sorted arrays and third pointing to head of the resultant array.
void sortedMerge(int arr1[], int arr2[], int n1, 
                             int n2, int arr3[])
{
    int i = 0, j = 0, k = 0;

    // Traverse both array
    while (i<n1 && j <n2)
    {
        // Check if current element of first
        // array is smaller than current element
        // of second array. If yes, store first
        // array element and increment first array
        // index. Otherwise do same with second array
        if (arr1[i] < arr2[j])
            arr3[k++] = arr1[i++];
        else
            arr3[k++] = arr2[j++];
    }

    // Store remaining elements of first array
    while (i < n1)
        arr3[k++] = arr1[i++];

    // Store remaining elements of second array
    while (j < n2)
        arr3[k++] = arr2[j++];
}

/// Driver program to test above function
int main()
{
    int arr1[] = {1, 3, 9};
    int n1 = sizeof(arr1) / sizeof(arr1[0]);

    int arr2[] = {2, 4, 7};
    int n2 = sizeof(arr2) / sizeof(arr2[0]);

    int arr3[n1+n2];
    sortedMerge(arr1, arr2, n1, n2, arr3);

    cout << "After Merge : ";
    for (int i=0; i < n1+n2; i++)
        cout << arr3[i] << " ";
    return 0;
}

