int minCoins(int amount, vector<int> coins) {
    int table[amount+1];  
    table[0] = 0;

    //Fill all values starting from 1  
    for (int i = 1 ; i <= amount ; i++) {
        // Initialize the table with some huge value 
        table[i] = INT_MAX;
        for (int c = 0 ; c < coins.size() ; c++) {
            if (coins[c] <= i) {
                int sub_res = table[i - coins[c]]; 
                /* We have added this inside if so that 
                it won't repeat the calculation again 
                if the same coin is used multiple times */
                if (sub_res != INT_MAX && 
                    sub_res + 1 < table[i]) 
                     table[i] = sub_res + 1; 
            } 
        }  
     } 
     return table[amount];
 }

