import numpy as np

class AI_Agent():

def __init__(self, num_items, explore_factor):
    self.num_items = num_items
    self.explore_factor = explore_factor
    self.q_table = np.random.rand(num_items, 4) * 0.2 - 0.1

def train(self, curr_state, action, reward):
    # Update Q table using Bellman Equation
    self.q_table[curr_state][action] += self.alpha * (reward + self.gamma * np.max(self.q_table[curr_state]) - self.q_table[curr_state][action])

def act(self, curr_state):
    # If in exploration mode, choose random action
    if np.random.random_sample() < self.explore_factor:
        action = np.random.randint(0, self.num_items)
    # Otherwise choose the action with the highest expected reward
    else:
        action = np.argmax(self.q_table[curr_state])
    return action

def get_recommendations(self, user_profile):
    # Select user preferences using user profile
    prefs = np.argmax(user_profile, axis=1)
    # Use Q table to select recommended items
    recommendation = np.argmax(self.q_table[prefs])
    return recommendation

