class TicTacToeGame extends JFrame {

    // instance variables
    private JButton[][] board;
    private String tic = "X";
    private boolean gameDone = false;
    private JButton resetButton;

    public TicTacToeGame() {
        setSize(500, 500);
        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        setLocationRelativeTo(null);
        setTitle("Tic Tac Toe");

        // layout
        setLayout(new GridLayout(4, 3, 10, 10));

        // buttons
        board = new JButton[3][3];
        for (int row = 0; row < 3; row++) {
            for (int col = 0; col < 3; col++) {
                board[row][col] = new JButton();
                board[row][col].setText("");
                board[row][col].addActionListener(new BoardAction());
                board[row][col]. setPreferredSize( new Dimension(100, 100));
                add(board[row][col]);
            }
        }
        resetButton = new JButton("Reset");
        resetButton.addActionListener(new ResetAction());
        add(resetButton);
    }

    private class BoardAction implements ActionListener {
        public void actionPerformed(ActionEvent e) {
            int row = -1, col = -1;
            JButton b = (JButton)e.getSource();

            // determine click location
            for (int r = 0; r < 3; r++) {
                for (int c = 0; c < 3; c++) {
                    if (board[r][c] == b) {
                        row = r;
                        col = c;
                    }
                }
            }

            // update
            if (board[row][col].getText().equalsIgnoreCase("")) {
                if (tic.equalsIgnoreCase("X")) {
                    b.setText("X");
                    tic="O";
                }
                else if (tic.equalsIgnoreCase("O")) {
                    b.setText("O");
                    tic = "X";
                }
            }

            // check for win
            if (checkWin()) {
                gameDone = true;
                JOptionPane.showMessageDialog(null, "Game over!");
            }
        }
    }

    private boolean checkWin() {
        //checks horizontal
        for(int row=0; row<3; row++) {
            if(board[row][0].getText().equals(board[row][1].getText()) && board[row][1].getText().equals(board[row][2].getText()) && !board[row][0].getText().equals("")) {
                return true;
            }
        }
        //checks vertical
        for(int col=0; col<3; col++) {
            if(board[0][col].getText().equals(board[1][col].getText()) && board[1][col].getText().equals(board[2][col].getText()) && !board[0][col].getText().equals("")) {
                return true;
            }
        }
        //checks diagonal
        if(board[0][0].getText().equals(board[1][1].getText()) && board[1][1].getText().equals(board[2][2].getText()) && !board[0][0].getText().equals("")) {
            return true;
        } else if(board[0][2].getText().equals(board[1][1].getText()) && board[1][1].getText().equals(board[2][0].getText()) && !board[0][2].getText().equals("")) {
            return true;
        }
        return false;
    }

    private class ResetAction implements ActionListener {
        public void actionPerformed(ActionEvent e) {
            for(int row=0; row<3; row++)
                for(int col=0; col<3; col++)
                    board[row][col].setText("");
            tic="X";
            gameDone = false;
        }
    }
}

