function getBestMove(board, player) {
  let bestMove = null;
  let bestScore = -Infinity;
  for (let col = 0; col < board.length; col++) {
    const newBoard = cloneBoard(board);
    if (makeMove(newBoard, col, player) == null) continue;
    const score = minimax(newBoard, player, 0);
    if (score > bestScore) {
      bestScore = score;
      bestMove = col;
    }
  }
  return bestMove;
}

function minimax(board, player, depth) {
  const result = checkWinner(board);
  if (result == player) return 10 - depth;
  if (result != null) return depth - 10;

  let bestScore = player == 1 ? -Infinity : Infinity;

  for (let col = 0; col < board.length; col++) {
    const newBoard = cloneBoard(board);
    if (makeMove(newBoard, col, player) == null) continue;
    const score = minimax(newBoard, 1-player, depth + 1);

    bestScore = player == 1 ? Math.max(score, bestScore) : Math.min(score, bestScore);
  }
  return bestScore;
}

