const uuidV4 = require('uuid/v4');
const net = require('net');
const blockchain = require('./blockchain');

const PORT = 5000;
const peers = {};

// Create a TCP server
const server = net.createServer(socket => {
 // Create an ID for each peer
 socket.uuid = uuidV4();
 peers[socket.uuid] = socket;

 // Reply with blockchain data
 socket.write(JSON.stringify(blockchain.data));

 socket.on('data', data => {
  const parsedData = JSON.parse(data);
  // reply with updated blockchain
  socket.write(JSON.stringify(blockchain.handleData(parsedData)));
 });

 socket.on('end', () => delete peers[socket.uuid]);
});

