public class GroceryStore {
 private HashMap<String, Integer> inventory;

 public GroceryStore() {
 this.inventory = new HashMap<>();
 }

 public void addItem(String item, int quantity) {
 if (this.inventory.containsKey(item)) {
 this.inventory.put(item, this.inventory.get(item) + quantity);
 } else {
 this.inventory.put(item, quantity);
 }
 }

 public void removeItem(String item, int quantity) {
 if (this.inventory.containsKey(item)) {
 if(this.inventory.get(item)>quantity){
 this.inventory.put(item, this.inventory.get(item) - quantity);
 }else{
 this.inventory.remove(item);
 }
 }
 }

 public boolean checkAvailability(String item) {
 return this.inventory.containsKey(item);
 }
}

