public class RomanNumeral {
 public static int romanToInteger(String romanNumeral) {
  Map<Character, Integer> map = new HashMap<>();
  map.put('I', 1);
  map.put('V', 5);
  map.put('X', 10);
  map.put('L', 50);
  map.put('C', 100);
  map.put('D', 500);
  map.put('M', 1000);

  int result = 0;

  for (int i = 0; i < romanNumeral.length(); i++) {
   int value = map.get(romanNumeral.charAt(i));
   int nextValue = (i + 1 < romanNumeral.length()) ? map.get(romanNumeral.charAt(i + 1)) : -1;

   if (value < nextValue) {
    result -= value;
   } else {
    result += value;
   }
  }
  return result;
 }

 public static String integerToRoman(int num) {
  String s[] = {"M","CM","D","CD","C","XC","L","XL","X","IX","V","IV","I"};
  int a[] = {1000,900,500,400,100,90,50,40,10,9,5,4,1};

  String result = "";
  for(int i=0;i<a.length;i++)
  {
   int n = num/a[i];
   for(int j=1;j<=n;j++)
    result = result + s[i];
   num = num%a[i];
  }
  return result;
 }
}

