public class TestStack {

    public static void main(String[] args) {
        Stack<Integer> stack = new Stack<>();

        // push items onto the stack
        stack.push(12);
        stack.push(3);
        stack.push(22);

        // pop last item
        Integer lastItem = stack.pop();
        System.out.println("Last item popped: " + lastItem);

        // peek at the top item
        Integer topItem = stack.peek();
        System.out.println("Top item on stack: " + topItem);

        // loop over the stack
        for (int i = stack.size()-1; i >= 0; i--) {
            System.out.println("Item " + i + ": " + stack.get(i));
        }
    }

}

