#include <stdio.h>
#include <math.h>

int isPrime(int n) 
{ 
    for (int i = 2; i <= sqrt(n); ++i) 
        if (n % i == 0) 
            return 0; 
    return 1; 
} 

int* findPrimes(int* arr, int arr_size) 
{ 
    int* primes; 
    int i, j; 

    primes = (int*)malloc(arr_size * sizeof(int)); 

    for (i = 0, j = 0; i < arr_size; i++) 
        if (isPrime(arr[i])) 
            primes[j] = arr[i], j++; 

    return primes; 
} 

int main() 
{ 
    int array[] = {2, 4, 8, 10};
    int arrsize = sizeof(array) / sizeof(array[0]);

    int* primes = findPrimes(array, arrsize); 

    for (int i = 0; i < arrsize; i++) 
        printf("%d ", primes[i]); 

    return 0; 
}

