"""
Check if a given number is in the Fibonacci series
"""

public static boolean isFibonacci(int n) {
    if (n == 0) {
        return false;
    }
    // initialize the first and second numbers
    int firstNum = 0;
    int secondNum = 1;
    // loop until n is greater than or equal to 1
    while (firstNum <= n) {
        // check for equality
        if (firstNum == n) {
            return true;
        }
        // generate the next Fibonacci number
        int sum = firstNum + secondNum;
        firstNum = secondNum;
        secondNum = sum;
    }
    // return false
    return false;
}

