void pivotSort(int arr[], int n) 
{ 
    int pivot = arr[n-1]; // taking the last element of array as pivot 

    // variable to store index of 
    // smaller (than pivot) element 
    int j = -1; 

    for (int i=0; i<n-1; i++) 
    { 
        // If current element is smaller than the pivot 
        if (arr[i] < pivot) 
        { 
            j++; 

            int temp = arr[j]; //swapping the elements
            arr[j] = arr[i]; 
            arr[i] = temp; 
        } 
    } 

    //swapping the elements by placing the pivot element at its correct position
    int temp = arr[j+1]; 
    arr[j+1] = arr[n-1]; 
    arr[n-1] = temp; 
}

