def quicksort(arr: Array[Int]): 
    if (arr.length < 2)  
        return arr

    val pivotIdx = arr.length / 2 // Choose a pivot element at the array center
    val pivot = arr(pivotIdx)

    def isSmallerThanPivot(a: Int): 
        a < pivot
    def isLargerThanPivot(a: Int):
        a > pivot

    val smallerThanPivot = arr.filter(isSmallerThanPivot)
    val largerThanPivot = arr.filter(isLargerThanPivot)

    // Recurse the quicksort process 
    quicksort(smallerThanPivot) ++ Array(pivot) ++ quicksort(largerThanPivot)

