def selection_sort(head):
    curr = head
    while curr.next is not None:
        min = curr
        temp = curr.next
        while temp is not None:
            if temp.data < min.data:
                min = temp
            temp = temp.next
        if min != curr:
            min.data, curr.data = curr.data, min.data
        curr = curr.next
    return head

