@IBDesignable
class CircularProgressBar: UIView {
   var progressLayer = CAShapeLayer()
   var trackLayer = CAShapeLayer()

   @IBInspectable var progressLineWidth: Int = 8 {
     didSet {
       progressLayer.lineWidth = CGFloat(progressLineWidth)
     }
   }

   @IBInspectable var progressColor: UIColor = .systemBlue {
     didSet {
       progressLayer.strokeColor = progressColor.cgColor
     }
   }

   @IBInspectable var trackLineWidth: Int = 8 {
     didSet {
       trackLayer.lineWidth = CGFloat(trackLineWidth)
     }
   }

   @IBInspectable var trackColor: UIColor = UIColor.lightGray {
     didSet {
       trackLayer.strokeColor = trackColor.cgColor
     }
   }

   var progress: CGFloat = 0

   override func draw(_ rect: CGRect) {
     super.draw(rect)

     self.createCircularPath()
   }

   func createCircularPath() {
     let circularPath = UIBezierPath(arcCenter: CGPoint(x: frame.size.width/2, y: frame.size.height/2), radius: frame.size.width/2 - progressLineWidth, startAngle: -CGFloat.pi/2, endAngle: 3 * CGFloat.pi/2, clockwise: true)

     trackLayer.path = circularPath.cgPath
     trackLayer.fillColor = UIColor.clear.cgColor

     progressLayer.path = circularPath.cgPath
     progressLayer.strokeStart = 0
     progressLayer.strokeEnd = progress
     progressLayer.fillColor = UIColor.clear.cgColor
     progressLayer.lineCap = .round

     layer.addSublayer(trackLayer)
     layer.addSublayer(progressLayer)
   }
}

