 let matrix = [];

 // -- Create matrix with all 0's
 for (let i = 0; i < rows; i++) {
  matrix[i] = [];

  for (let j = 0; j < cols; j++) {
   matrix[i][j] = 0;
  }
 }

 // -- Create starting position
 let x = 0;
 let y = 0;

 // -- Move towards the bottom right corner
