public class PalindromeDetection
{
    static void findPalindromes(String str)
    {
        // Initialize an empty array of Strings
        ArrayList<String> palindromes = new ArrayList<>();

        // Create a String to hold each word
        String word = "";

        // Iterate through the string 
        for (int i = 0; i < str.length(); i++)
        {
            if (str.charAt(i) != ' ')
            {
                word = word + str.charAt(i); 
            }
            else
            {
                // If a word is complete, check if it is a palindrome
                if (isPalindrome(word)) 
                {
                    // If so, store it in an array
                    palindromes.add(word); 
                } 
                // Reset the word
                word = ""; 
            }
        }
        // Print all the palindromes
        System.out.println("Palindrome words in given string: " + palindromes); 
    }
    // Function to check if a word is a palindrome
    static boolean isPalindrome(String word)
    {
        // Create the reverse of the word
        String reverseWord = "";
        for (int i =word.length() - 1; i >= 0; i--)
        {
            reverseWord = reverseWord + word.charAt(i);
        }
        // Check if the reverse of the word is same as the given word 
        return (reverseWord.equals(word));
    }
    public static void main (String[] args)
    {
        String str = "Madam anna racecar greg";
        findPalindromes(str);
    }
}

