def sentiment_classifier(text):
    pos_words = ["good", "great", "happy", "fun", "nice"]
    neg_words = ["bad", "sad", "unhappy", "ugly", "horrible"]
    sentiment = 0

    for word in text.lower().split(" "):
        if word in pos_words:
            sentiment += 1
        elif word in neg_words:
            sentiment -= 1

    if sentiment > 0:
        return "positive"
    elif sentiment < 0:
        return "negative"
    else:
        return "neutral"

