def generate(arr, length):
  result = []

  if length <= 0:
    return result

  if length == 1: 
    for c in arr:
      result.append(c)

    return result

  for i in range(len(arr)-length+1):
    prefix = arr[i]
    suffixes = generate(arr[i+1:], length-1)
    for s in suffixes:
      result.append(prefix + s)
  return result

