// Java program to find length of the longest common substring 
public class LongestCommonSubstring { 

    // Function to find length of the longest common substring 
    public static int LCSubStr(String X, String Y, int m, int n) 
    { 
        // Create and initialize a matrix
        int LCStuff[][] = new int[m + 1][n + 1]; 
        int result = 0; 

        // LCStuff[i][j] contains length of the 
        // longest common substring of X[0..i-1] 
        // and Y[0..j-1] 
        for (int i = 0; i <= m; i++) { 
            for (int j = 0; j <= n; j++) { 
                if (i == 0 || j == 0) 
                    LCStuff[i][j] = 0; 

                else if (X.charAt(i - 1) == Y.charAt(j - 1)) { 
                    LCStuff[i][j] = LCStuff[i - 1][j - 1] + 1; 
                    result = Integer.max(result, LCStuff[i][j]); 
                } 

                else
                    LCStuff[i][j] = 0; 
            } 
        } 
        return result; 
    } 

    public static void main(String[] args) 
    { 
        String X = "lifeisgood"; 
        String Y = "lifeiswhatsup"; 

        int m = X.length(); 
        int n = Y.length(); 

        System.out.println("Length of Longest Common Substring is "
         + LCSubStr(X, Y, m, n)); 
    } 
}

