// Algorithm to calculate the factorial of a number 

// Step 1: Function with the signature, int factorial(int num)

// Step 2: Initialize a result variable to 1 

// Step 3: Iterate from 2 to num 

// Step 4: Calculate the product of result and the current number

// Step 5: Update the value of result after each iteration

// Step 6: Return result after loop completion

// Function implementation 
int factorial(int num) 
{ 
    int result = 1; 

    // Iterate from 2 to num 
    for (int i = 2; i <= num; i++) 
        result *= i; 

    return result; 
}

