// function to find the longest increasing subsequence
public static int longest_increase_subsequence(int[] array) {
    int longest = 0;
    int start_index = 0;
    int end_index = 0;
    int current_length = 1;

    for (int i = 0; i < array.length - 1; i++) {
        if (array[i] < array[i + 1]) {
            current_length++;
        }else{
            if (current_length > longest) {
                longest = current_length;
                start_index = i - longest + 1;
                end_index = i + 1;
            }
            current_length = 1;
        }
    }

    // return the longest increasing subsequence
    int[] longest_subsequence = new int[longest];
    for (int i = 0; i < longest; i++) {
        longest_subsequence[i] = array[start_index + i];
    }

    return longest_subsequence;
}

