class HashTable:
 def __init__(self):
 self.table = [None] * 10

 def hash(self, key):
 return hash(key) % 10

 def insert(self, key, value):
 h = self.hash(key)
 if self.table[h] is None:
 self.table[h] = [key, value]
 else:
 self.table[h].append([key, value])

 def search(self, key):
 h = self.hash(key)
 entry = self.table[h]
 if entry is None:
 return None
 else:
 for k, v in entry:
 if k == key:
 return v
 return None

 def delete(self, key):
 h = self.hash(key)
 entry = self.table[h]
 if entry is None:
 return None
 else:
 for i, (k, v) in enumerate(entry):
 if k == key:
 entry.pop(i)
 return v
 return None

 def update(self, key, value):
 h = self.hash(key)
 entry = self.table[h]
 if entry is not None:
 for i, (k, v) in enumerate(entry):
 if k == key:
 entry[i][1] = value
 return
 else:
 self.insert(key, value)

