// node struct for doubly linked list 
struct Node {
 int value;
 Node *prev;
 Node *next;
};

class DoublyLinkedList {
private:
 Node *head;
 Node *tail;
public:
 // Constructor
 DoublyLinkedList();
 // Insert a node at given position
 void insertNode(int value, int pos);
 // Delete a node from a given position
 void deleteNode(int pos);
 // Iterate through the list
 void traverseList();
 // Destructor
 ~DoublyLinkedList();
};

// Constructor
DoublyLinkedList::DoublyLinkedList() {
 head = nullptr;
 tail = nullptr;
}

// Insert a node at given pos
void DoublyLinkedList::insertNode(int value, int pos) {
 // create a new node
 Node *t = new Node;
 t->value = value;
 t->next = nullptr;
 t->prev = nullptr;

 // insert node at beginning of list
 if(pos == 0) {
 t->next = head;
 head = t;
 } else {
 Node *curr = head;
 // find the node at given position
 for(int i=0; i<pos-1; i++) {
 curr = curr->next;
 }
 // insert current node at given position
 t->next = curr->next;
 if(curr->next != NULL)
 curr->next->prev = t;
 curr->next = t;
 t->prev = curr;
 }

 // update tail ptr in case of insertion at end
 if (pos == -1)
 tail = t;
}

// Delete a node from a given position
void DoublyLinkedList::deleteNode(int pos) {
 Node *curr = head;

 // find the node at given position
 for(int i=0; i<pos-1; i++) {
 curr = curr->next;
 }

 Node *temp = curr->next;

 // delete the node 
 curr->next = temp->next;
 temp->next->prev = curr;
 delete temp;
}

// Iterate through linked list
void DoublyLinkedList::traverseList() {
 Node *curr = head;

 while (curr != nullptr) { 
 std::cout << curr->value << " ";
 curr = curr->next; 
 } 
 std::cout << std::endl;
}

// Destructor
DoublyLinkedList::~DoublyLinkedList() {
 Node *curr = head;
 while(curr != nullptr) {
 head = curr;
 curr = curr->next;
 delete head;
 }
}

