func maxProductThreeNumbers(nums: [Int]) -> Int {
    let sortedNums = nums.sorted()
    let maxPossibleProduct = sortedNums[sortedNums.count - 1] * sortedNums[sortedNums.count - 2] * sortedNums[sortedNums.count - 3]
    let minPossibleProduct = sortedNums[0] * sortedNums[1] * sortedNums[sortedNums.count - 1]

    return max(maxPossibleProduct, minPossibleProduct)
}

def quick_sort(arr):
    if len(arr) <= 1:
        return arr
    pivot = arr[int(len(arr) / 2)]
    left = [x for x in arr if x < pivot]
    middle = [x for x in arr if x == pivot]
    right = [x for x in arr if x > pivot]
    return quick_sort(left) + middle + quick_sort(right)

print(quick_sort([3, 5, 7, 1, 4, 2]))

def longest_increasing_subarray(arr):
    increasing_counters = [1] * len(arr)
    for i, elem in enumerate(arr[1:]):
      if elem > arr[i]:
        increasing_counters[i+1] += increasing_counters[i]
    return max(increasing_counters)

