 super.onStart();
 FirebaseUser currentUser = mAuth.getCurrentUser();
 if (currentUser != null) {
 sendToMain();
 }
 }

private void sendToMain() {
 Intent mainIntent = new Intent(LoginActivity.this, MainActivity.class);
 startActivity(mainIntent);
 finish();
 }
}

