def multiplyMatrix(A, B):
    rowsA, colsA = len(A), len(A[0])
    rowsB, colsB = len(B), len(B[0])
    if colsA != rowsB:
        return

    result = [ [0 for j in range(colsB)] for i in range(rowsA) ]
    for i in range(rowsA):
        for j in range(colsB):
            sum = 0
            for k in range(colsA):
                sum += A[i][k] * B[k][j]
            result[i][j] = sum
    return result

def knapsack(items, capacity):
    #Initialize a 2D matrix with the size of n x capacity
    n = len(items)
    matrix = [[0 for j in range(capacity + 1)] for i in range(n + 1)]

    #Fill in the matrix row by row
    for i, (weight, value) in enumerate(items):
        for j in range(capacity + 1):
            if j < weight:
                matrix[i + 1][j] = matrix[i][j]
            else:
                matrix[i + 1][j] = max(matrix[i][j], matrix[i][j - weight] + value)

    #Return the result
    return matrix[n][capacity]

