def bubbleSort(arr): 
    n = len(arr) 
    for i in range(n):
        for j in range(0, n - i - 1):
            if arr[j] > arr[j + 1] : 
                arr[j], arr[j + 1] = arr[j + 1], arr[j]
    return arr

def calculateMaxOverlap(rectangles):
  # set up a 2-dimensional grid and store the intervals covered by each rectangle as start/end points
  grid = [[] for i in range(len(rectangles))] 
  for i, rect in enumerate(rectangles): 
    for col in range(rect[0], rect[2] + 1): 
      grid[i].append((rect[1], rect[3])) 

  # search for the maximum overlap
  maxOverlap = 0 
  for i in range(len(grid[0])): 
    tempOverlap = 0 
    activeHeap = [] 

    # push all starting points to heap
    for j in range(len(rectangles)): 
      if len(grid[j]) > i: 
        start, end = grid[j][i] 
        heapq.heappush(activeHeap, (start, end)) 

    while activeHeap: 
      start, end = heapq.heappop(activeHeap) 
      tempOverlap += 1

      # merge overlapping intervals 
      while activeHeap and activeHeap[0][0] <= end: 
        start, end = heapq.heappop(activeHeap) 
        start = max(start, end) 
        heapq.heappush(activeHeap, (start, end)) 

    maxOverlap = max(maxOverlap, tempOverlap) 
  return maxOverlap

function quickSort(arr) {
  if (arr.length <= 1) {
    return arr;
  }

  const left = [];
  const right = [];
  const pivot = arr[arr.length - 1];

  for (let i = 0; i < arr.length - 1; i++) {
    if (arr[i] < pivot) {
      left.push(arr[i]);
    } else {
      right.push(arr[i]);
    }
  }

  return [...quickSort(left), pivot, ...quickSort(right)];
}

