// Algorithm to find the second largest number in the list
// 
// 1. Initialize the second largest number (smax) to 0 
// 2. Iterate the list 
// 3. For each item in the list, compare it to the current max
//   3.1. If the current item is larger than the current max 
//			3.1.1. Move the current max to smax
//			3.1.2. Set the current item as max
// 4. Once the list is iterated, smax will be the current second largest item

function findSecondLargest(list) { 
	let max = 0;
	let smax = 0; 

	for (let item of list) { 
		if (item > max) { 
			smax = max; 
			max = item; 
		} 
	} 

	return smax; 
} 

