const validateCreditCard = n => {
  const reversedCardNumber = n
    .toString()
    .split('')
    .reverse()
    .map(num => +num); 

  const doubledSecondDigits = reversedCardNumber.map((num, index) => {
    if (index % 2 === 1) return num * 2;
    return num;
  });

  const subtractNine = doubledSecondDigits.map(num => {
    if (num > 9) return num - 9;
    return num;
  });

  const sumDigits = subtractNine.reduce((acc, curr) => acc + curr);

  if (sumDigits % 10 === 0) {
    return true;
  }

  return false;
};

