function mostFrequent(arr){
  // create an object to store the frequency of occurrences
  let frequencyObject = {};
  // loop through the array
  for(let i = 0; i < arr.length; i++){
    // if the item is in the object, increment its frequency
    if(arr[i] in frequencyObject){
      frequencyObject[arr[i]]++;
    // otherwise, add it to the object
    } else{
      frequencyObject[arr[i]] = 1;
    }
  }
  // create variables to store the result and highest frequency
  let result = 0;
  let highestFrequency = 0;
  // loop through the object
  for(key in frequencyObject){
    // if the frequency of the current item is higher than the highest frequency,
    // update the result and highest frequency variables
    if(frequencyObject[key] > highestFrequency){
      result = key;
      highestFrequency = frequencyObject[key];
    }
  }
  // return the result
  return result;
}

