        self.prev = None

class DoublyLinkedList: 
    def __init__(self): 
        self.head = None

    def add(self, data): 
        new_node = Node(data) 

        if self.head is None: 
            new_node.prev = None
            self.head = new_node 
        else: 
            cur = self.head 
            while cur.next: 
                cur = cur.next
            cur.next = new_node 
            new_node.prev = cur 

    def delete(self, data):
        cur = self.head
        while cur:
            if cur.data == data and cur == self.head:
                self.head = cur.next
            elif cur.data == data:
                cur.prev.next = cur.next
                cur.next.prev = cur.prev
            cur = cur.next

    def search(self, target):
        cur = self.head
        while cur:
            if cur.data == target:
                return True
            cur = cur.next
        return False

