public class HappyNumber {

    // method to calculate the next number
    static int nextNumber(int num){
        int total = 0;
        while(num > 0){
            int d = num % 10;
            num = num / 10;
            total += (d * d);
        }
        return total;
    }

    // method to check if a number is happy
    static boolean isHappyNumber(int num){
        int n1 = num;
        int n2 = num;
        while(n2 != 1 && n2 != 4){
            n1 = nextNumber(n1);
            n2 = nextNumber(nextNumber(n2));
        }
        return (n2 == 1);
    }

    // Driver method
    public static void main(String[] args) {

        int num = 19;
        if(isHappyNumber(num))
            System.out.println(num + " is a Happy number");
        else
            System.out.println(num + " is not a Happy number");
    }
}

