def build_tree(strings):
    if not strings:
        return None
    root = TreeNode(strings[0])
    prev, curr = root, root
    for i in range(1, len(strings)):
        curr = TreeNode(strings[i])
        prev.add_child(curr)
        prev = curr
    return root

