bool is_anagram(char* str1, char* str2)
{
    int len1 = strlen(str1);
    int len2 = strlen(str2);

    if (len1 != len2) 
        return false; 

    int count[256] = { 0 }; 
    for (int i = 0; i < len1; i++) 
        count[str1[i]]++; 

    for (int i = 0; i < len2; i++) { 
        count[str2[i]]--; 
        if (count[str2[i]] < 0) 
            return false; 
    } 
    return true;
}

