def find_longest_common_substring(string1, string2):
    m = len(string1)
    n = len(string2)
    longest_common_substring = 0  
    end = 0 

    # Create a matrix which stores 
    # the longest common substring 
    L = [[0 for j in range(n + 1)]  
        for i in range(m + 1)] 

    for i in range(m + 1): 
        for j in range(n + 1): 
            if i == 0 or j == 0: 
                L[i][j] = 0
            elif string1[i - 1] == string2[j - 1]: 
                L[i][j] = L[i - 1][j - 1] + 1
                if L[i][j] > longest_common_substring: 
                    longest_common_substring = L[i][j] 
                    end = i 
            else: 
                L[i][j] = 0

    return string1[end - longest_common_substring: end]

