def has_cycle(head):
    # Initialize slow and fast pointers
    slow = fast = head
    # Loop until fast is not None
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
        if slow == fast:
            return True
    return False

public static String intToString(int n){
    if(n == 0){
        return "0";
    }

    StringBuilder sb = new StringBuilder();

    if(n < 0){
        n = -n;
        sb.append('-');
    }

    while(n > 0){
        sb.append(n % 10);
        n /= 10;
    }

    return sb.reverse().toString();
