def rotate_list(lst, k): 
    # rotating the elements k times 
    for i in range(k):
        last = lst[-1]
        for i in range(len(lst)-1, 0, -1):
            lst[i] = lst[i-1]
        lst[0] = last
    return lst

function findPrimes(N) {
  let primes = [];
  for (let i = 2; i <= N; i++) {
    let isPrime = true;

    for (j = 2; j < i; j++) {
      if (i % j == 0) {
        isPrime = false;
        break;
      }
    }

    if (isPrime) {
      primes.push(i);
    }
  }
  return primes;
}

