class ViewController: UIViewController {

     private let imagePicker = UIImagePickerController()
     private var timelineView = UIScrollView()

     override func viewDidLoad() {
        super.viewDidLoad()
        setupImagePicker()
        setupTimelineView()
     }

     private func setupImagePicker() {
        imagePicker.sourceType = .photoLibrary
        imagePicker.allowsEditing = false
        imagePicker.delegate = self
     }

     private func setupTimelineView() {
        timelineView.translatesAutoresizingMaskIntoConstraints = false
        view.addSubview(timelineView)
        timelineView.topAnchor.constraint(equalTo: view.topAnchor).isActive = true
        timelineView.leadingAnchor.constraint(equalTo: view.leadingAnchor).isActive = true
        timelineView.trailingAnchor.constraint(equalTo: view.trailingAnchor).isActive = true
        timelineView.bottomAnchor.constraint(equalTo: view.bottomAnchor).isActive = true
        timelineView.backgroundColor = UIColor.white
     }

     @IBAction func addPhoto(_ sender: UIButton) {
        present(imagePicker, animated: true, completion: nil)
     }
 }

extension ViewController: UIImagePickerControllerDelegate, UINavigationControllerDelegate {
     func imagePickerController(_ picker: UIImagePickerController, didFinishPickingMediaWithInfo info: [UIImagePickerController.InfoKey : Any]) {
         guard let photo = info[.originalImage] as? UIImage else { return }
         let imageView = UIImageView(image: photo)
         imageView.contentMode = .scaleAspectFit

         timelineView.addSubview(imageView)
         imageView.translatesAutoresizingMaskIntoConstraints = false

         let leadingAnchor: NSLayoutAnchor<NSLayoutXAxisAnchor>
         if timelineView.subviews.isEmpty {
             leadingAnchor = timelineView.leadingAnchor
         } else {
             let previousImage = timelineView.subviews.last!
             leadingAnchor = previousImage.trailingAnchor
         }

         NSLayoutConstraint.activate([
            imageView.topAnchor.constraint(equalTo: timelineView.topAnchor),
            leadingAnchor.constraint(equalTo: imageView.leadingAnchor),
            imageView.bottomAnchor.constraint(equalTo: timelineView.bottomAnchor),
            imageView.widthAnchor.constraint(equalTo: timelineView.widthAnchor, multiplier: 1.0/3.0)
         ])

         UIImageWriteToSavedPhotosAlbum(photo, nil, nil, nil)
         dismiss(animated: true, completion: nil)
     }
}

public class MaxAverageSubarr {
    // Function to find the subarray with maximum average
    public static int[] findMaxAveSubarray(int[] arr) {
        int n = arr.length;
        // Kadane's algorithm
        int max_end_here = 0;
        int max_so_far = 0;
        int best_start = 0;
        int best_end = 0;
        for (int i = 0; i < n; i++) {
            max_end_here += arr[i];
            if (max_end_here < 0) {
                max_end_here = 0;
            } else {
                if (max_so_far < max_end_here) {
                    max_so_far = max_end_here;
                    best_end = i;
                }
            }
        }
        int total = 0;
        for (int i = best_end; i >= 0; i--) {
            total += arr[i];
            if (total == max_so_far) {
                best_start = i;
                break;
            }
        }
        int[] result = new int[best_end - best_start + 1];
        int idx = 0;
        for (int i = best_start; i <= best_end; i++) {
            result[idx++] = arr[i];
        }
        return result;
    }

    public static void main(String[] args) {
        int[] arr = { 1, 3, 4, 7, 8 };
        int[] result = findMaxAveSubarray(arr);
        System.out.println("The subarray with the max average is: ");
        for (int i : result) {
            System.out.print(i + " ");
        }
    }
}

