import UIKit

func isPalindrome(inputString: String) -> Bool {
  let charactersArray = Array(inputString)
  var regionalIndex = 0
  var isPalindrome = true

  for character in charactersArray {
    let reversedIndex = charactersArray.count - regionalIndex - 1
    if reversedIndex <= regionalIndex {
      break
    }
    if character != charactersArray[reversedIndex] {
      isPalindrome = false
      break
    }
    regionalIndex += 1
  }

  return isPalindrome
}

