// create a function to calculate median 
fn median(list : &[i32]) -> f32 {

    // sort the array
    let mut list = list.to_vec();
    list.sort();

    let length = list.len() as f32;
    let mid = length / 2.0;

    if length % 2 == 0 { 
        // If array length is even
        // take mean of middle two elements
        let sum_of_middle_elememts = list[mid as usize] + list[(mid - 1.0) as usize];
        return sum_of_middle_elememts as f32 / 2.0; 
    } 
    // if array length is odd
    // take middle element
    return list[mid as usize] as f32; 
}

