"""Design an algorithm that combines two strings, alternating their characters.
"""

def combine_strings(str1, str2):
    combined_str = ""
    # loop through both strings
    for i in range(max(len(str1), len(str2))):
        # if a character is present in both strings, append both
        if i < len(str1) and i < len(str2):
            combined_str += str1[i] + str2[i]
        # if a character is only present in one string, append only that
        elif i < len(str1):
            combined_str += str1[i]
        elif i < len(str2):
            combined_str += str2[i]
    return combined_str

