import nltk
import re
from nltk.tokenize import sent_tokenize

def generate_summary(text):
    sentences = nltk.sent_tokenize(text)
    tokenized_sentences = [nltk.word_tokenize(sentence) for sentence in sentences]

    # Calculate frequency of words in the corpus
    frequency = calculate_frequency(tokenized_sentences)

    # Generate the summary
    summary = []
    for sentence in sentences:
        sentence_scores = score_sentence(frequency, sentence)
        threshold = compute_threshold(sentence_scores)
        if (sentence_scores >= threshold):
            summary.append(sentence)

    return summary

def calculate_frequency(tokenized_sentences):
    frequency = {}
    for sentence in tokenized_sentences:
        for word in sentence:
            if word not in frequency.keys():
                frequency[word] = 1
            else:
                frequency[word] += 1

    return frequency

def score_sentence(frequency, sentence):
    score = 0
    tokenized_sentence = nltk.word_tokenize(sentence)
    for word in tokenized_sentence:
        if word in frequency.keys():
            score += frequency[word]
    return score

def compute_threshold(sentence_score):
    return sentence_score * 0.3

