fn bubble_sort(arr: &mut [&str]) {
    let mut i: usize;
    let mut j: usize;
    let n: usize;
    n = arr.len();

    for i in 0..n {
        for j in 0..n-i-1 {
            // Do a swap if a[j] is greater than a[j+1]
            if arr[j] > arr[j+1] {
                let temp = arr[j];
                arr[j] = arr[j+1];
                arr[j+1] = temp;
            }
        }
    }
}

