int binaryToDecimal(string binaryNumber)
{
  int decimalNumber = 0;

  for (int i = 0; i < binaryNumber.length(); ++i) {
    int x = binaryNumber.length() - i - 1;
    decimalNumber += (binaryNumber[i] - '0') * pow(2, x);
  }

  return decimalNumber;
}

