      type: `image/${fileType}`,
    });
    const options = {
      method: 'POST',
      body: formData,
      headers: {
        Accept: 'application/json',
        'Content-Type': 'multipart/form-data',
      },
    };
    try {
      const response = await fetch(
        "https://your-upload-endpoint.com",
        options
      );
      const { uri } = await response.json();
      setUploadedUri(uri);
    } catch (err) {
      console.log(err);
    }
  };

  return (
    <View style={styles.container}>
      <View style={styles.camera}>
        {
          Platform.OS === "android" && hasPermission === null && requestPermission()
        }
        {
          hasPermission === true &&
