            type={Camera.Constants.Type.back}
            ref={ref => {
              setCameraRef(ref);
            }}
            style={styles.camera}
          />
        }
      </View>
      {
        photoUri && <Image source={{ uri: photoUri }} style={styles.photo} />
      }
      {
        photoUri ?
        <Button title="Upload Photo" onPress={uploadPhoto} />:
        <Button title="Snap Photo" onPress={snapPhoto} />
      }
      {
        uploadedUri && <Text>Photo uploaded successfully!</Text>
      }
    </View>
  );
};

