function mergeSort(arr1, arr2) {
  let resultArr = [];
  let i = 0;
  let j = 0;

  while (i < arr1.length && j < arr2.length) {
    if (arr1[i] <= arr2[j]) {
      resultArr.push(arr1[i]);
      i++;
    } else {
      resultArr.push(arr2[j]);
      j++;
    }
  }

  // Merge leftovers from bigger array
  while (i < arr1.length) {
    resultArr.push(arr1[i]);
    i++;
  }

  while (j < arr2.length) {
    resultArr.push(arr2[j]);
    j++;
  }

  return resultArr;
}

