public static string MakePalindrome(string s) {
    int start = 0;
    int end = s.Length - 1;

    while (start < end)
    {
        if (s[start] == s[end])
        {
            start++;
            end--;
        }
        else if (s[start] != s[end])
        {
            s = s.Insert(end, s[start].ToString());
            start++;
        }
    }

    return s;
}

def max_product_two(arr):
    first_max = max(arr[0], arr[1])
    second_max = min(arr[0], arr[1])

    # Traverse through the array starting from index 2  
    for num in range(2, len(arr)):

        # Compare with the first max and update
        # if the element is greater 
        if (arr[num] > first_max): 
            second_max = first_max 
            first_max = arr[num]; 

        # Compare with the second max and update 
        # if the element is greater 
        elif (arr[num] > second_max): 
            second_max = arr[num]
    return  (first_max * second_max)

