def longestCommonPrefix(strings):
    if len(strings) == 0:
        return ""

    prefix = strings[0]
    for i in range(1, len(strings)):
        j = 0
        while j < len(prefix) and j < len(strings[i]) and strings[i][j] == prefix[j]:
