Construct an algorithm to generate the nth Fibonacci number in a given sequence 
"""

def fibonacci(n):
    # Return the 0th fibonacci number (0) if input is 0
    if n == 0:
        return 0
    # Return the 1st fibonacci number (1) if input is 1
    elif n == 1:
        return 1
    # Otherwise, generate the nth Fibonacci number by adding the two previous numbers
    else:
        return fibonacci(n-1) + fibonacci(n-2)

