    if len(str1) != len(str2):
        return False

    no_of_distinct_char = 0
    str_dict = dict()
    for i in range(len(str1)):
        if str1[i] not in str_dict:
            str_dict[str1[i]] = 1
            no_of_distinct_char += 1
        else:
            str_dict[str1[i]] += 1

        if str2[i] not in str_dict:
            str_dict[str2[i]] = -1
            no_of_distinct_char += 1
        else:
            str_dict[str2[i]] -= 1

    for i in str_dict.values():
        if i != 0:
            return False
    return True

