void quickSort(int arr[], int left, int right) 
{ 
    int pivotIdx = left + (right - left) / 2; 
    int pivot = arr[pivotIdx];
    int i = left;
    int j = right;

    while (i <= j)  
    {
        while (arr[i] < pivot) 
            i++; 
        while (arr[j] > pivot) 
            j--; 

        if (i <= j)  
        { 
            int temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
            i++; 
            j--; 
        } 
    }

    if (left < j) 
        quickSort(arr, left, j); 
    if (i < right) 
        quickSort(arr, i, right); 
}

