def binary_search(arr, x, start, end):
    if start > end: 
        return False

    mid = (start + end)//2

    if arr[mid] == x: 
        return True 

    if arr[mid] > x: 
        return binary_search(arr, x, start, mid-1) 

    return binary_search(arr, x, mid+1, end)

