public static int searchNumber(int[] sortedArray, int searchNumber) {
    int left = 0;
    int right = sortedArray.length - 1;
    while(left <= right) {
        int mid = left + (right - left) / 2;
        if(sortedArray[mid] == searchNumber) {
            return mid;
        } else if (sortedArray[mid] < searchNumber) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    return -1;
}

