def factorial(n): 
    if n == 0: 
        return 1
    else: 
        return n * factorial(n-1)

def is_balanced(expression): 
    stack = []

    for character in expression: 
        if character in ['(', '{', '[']: 
            stack.append(character) 
        elif character == ')': 
            if not stack or stack[-1] != '(': 
                return False
            else: 
                stack.pop() 
        elif character == ']': 
            if not stack or stack[-1] != '[': 
                return False
            else: 
                stack.pop() 
        elif character == '}': 
            if not stack or stack[-1] != '{': 
                return False
            else: 
                stack.pop() 

    return not stack

