struct RandomForest {
    n_estimators: i32,
    max_depth: i32
}

impl RandomForest {
    pub fn new(n_estimators: i32, max_depth: i32) -> Self {
        Self {
            n_estimators,
            max_depth
        }
    }

    pub fn fit(&mut self, X: &DataFrame, y: &DataFrame) {
        let mut rng = rand::thread_rng();
        let n_features = X.shape()[1];

        // Train each tree
        for _ in 0..self.n_estimators {
            // Generate features to be used for the tree
            let features = (0..n_features).map(|_| {
                Normal::new(0.0, 1.0).unwrap().sample(&mut rng) as i32
            }).collect::<Vec<_>>();

            // Train a new tree
            let tree = DecisionTree::new(self.max_depth, features);
            tree.fit(&X, &y);
        }
    }
}

