    self.name = name
    self.average = 0.0
  }

  func addGrade(grade: Int) {
    self.grades.append(grade)
    self.updateAverage()
  }

  func updateAverage() {
    var sum = 0
    for grade in self.grades {
      sum += grade
    }
    self.average = Double(sum) / Double(self.grades.count)
  }

}

