const game = new Array(9).fill(null);

// Create the game board
const createBoard = () => {
  let board = document.createElement("div");
  board.setAttribute("id", "board");

  for (let i = 0; i < 9; i++) {
    let square = document.createElement("div");
    square.classList.add("square");
    board.appendChild(square);
  }

  document.body.appendChild(board);

  for (let i = 0; i < 9; i++) {
    let square = document.querySelector(".square");
    square.addEventListener("click", handleClick);
  }
};

// Function to handle click events
const handleClick = (e) => {
  // Checks if the square has a value
  if (e.target.innerText.length === 0) {
    game[parseInt(e.target.id)] = "X";
    e.target.innerText = "X";
  }

  // Checks win conditions
  checkWin();
  // AI turn
  computerTurn();
};

// Computer turn
const computerTurn = () => {
  // finds empty square and updates it
  for (let i = 0; i < 9; i++) {
    if (game[i] == null) {
      game[i] = "O";
      if (document.querySelector(`# ${i}`) !== null) {
        document.querySelector(`# ${i}`).innerText = "O";
      }
    }
  }
  // Checks win conditions
  checkWin();
};

// Check for win
const checkWin = () => {
  // winning combinations
  const winCombos = [
    [0, 1, 2],
    [3, 4, 5],
    [6, 7, 8],
    [0, 3, 6],
    [1, 4, 7],
    [2, 5, 8],
    [0, 4, 8],
    [2, 4, 6],
  ];

  // itteratie over winCombos
  for (let i = 0; i < winCombos.length; i++) {
    let hasWinner = true;
    for (let j = 0; j < winCombos[i].length; j++) {
      // checks to make sure the spot isn't blank
      if (game[winCombos[i][j]] == null) {
        hasWinner = false;
      }
      // checks to make sure all the players have the same move
      if (
        game[winCombos[i][0]] !== game[winCombos[i][1]] ||
        game[winCombos[i][1]] !== game[winCombos[i][2]]
      ) {
        hasWinner = false;
      }
    }
    if (hasWinner) {
      alert(`${game[winCombos[i][0]]} has won`);
    }
  }
};

