    #check if the first 3 characters are digits
    if not ssn[:3].isdigit():
        return False
    #check if the 4th character is a hyphen 
    if ssn[3] != '-':
        return False
    #check if the next two characters are digits
    if not ssn[4:6].isdigit():
        return False
    #check if the 7th character is a hyphen 
    if ssn[6] != '-':
        return False
    #check if the next four characters are digits
