public class Classification {

    public static void main(String[] args) throws Exception{
        //Number of rows and columns in the input pictures
        final int numRows = 28;
        final int numColumns = 28;
        int outputNum = 10;
        int batchSize = 128;
        int rngSeed = 123;
        int numEpochs = 15;

        //Load the data into memory
        RecordReader rr = new CSVRecordReader();
        rr.initialize(new FileSplit(new ClassPathResource("mnist_test.csv").getFile()));
        DataSetIterator dsi = new RecordReaderDataSetIterator(rr,batchSize,0,outputNum);

        //Create multi layer configuration
        MultiLayerConfiguration conf = new NeuralNetConfiguration.Builder()
            .seed(rngSeed)
            .l2(0.005)
            .weightInit(WeightInit.XAVIER)
            .updater(new Nesterovs(0.02, 0.9))
            .list()
            .layer(0, new DenseLayer.Builder().nIn(numRows * numColumns).nOut(256)
            .activation(Activation.RELU)
            .build())
            .layer(1, new DenseLayer.Builder().nIn(256).nOut(128)
            .activation(Activation.RELU)
            .build())
            .layer(2, new OutputLayer.Builder(LossFunctions.LossFunction.NEGATIVELOGLIKELIHOOD)
            .activation(Activation.SOFTMAX)
            .nIn(128).nOut(outputNum).build())
            .build();

        MultiLayerNetwork nnModel = new MultiLayerNetwork(conf);
        nnModel.init();
        nnModel.setListeners(new ScoreIterationListener(10));

        for( int i=0; i<numEpochs; i++ ){
            nnModel.fit(dsi);
        }

        //Test classfication
        RecordReader testRR = new CSVRecordReader();
        testRR.initialize(new FileSplit(new ClassPathResource("mnist_test.csv").getFile()));
        DataSetIterator testDSI = new RecordReaderDataSetIterator(testRR,1,0,outputNum);

        Evaluation eval = new Evaluation(outputNum);

        while(testDSI.hasNext()){
            DataSet next = testDSI.next();
            INDArray output = nnModel.output(next.getFeatures());

            eval.eval(next.getLabels(), output);
        }

        //Load a given input
        int[] inputData = ...
        INDArray input =   Nd4j.create(inputData);

        //Classfy the given input
        INDArray output = nnModel.output(input);
        int intLabel = output.argMax().getInt(0);
        System.out.println("Predicted Label: " + intLabel);
    }
}

