import random, string

def generate_password(min_length=8):
    """
    Generate a random password with the following specifications:
    must be at least 8 characters, must contain 1 uppercase letter,
    and must contain 1 number. 
    """
    # Generate a random string of at least 8 characters
    password = ''.join(random.choice(string.ascii_letters + string.digits) 
                       for x in range(min_length+random.randint(1,10)))

    # Count the number of uppercase letters and numbers in the string
    num_upper = 0
    num_digit = 0
    for char in password:
        if char.isupper():
            num_upper += 1
        if char.isdigit():
            num_digit += 1

    # If password is missing one type of character, generate a new password
    if num_upper == 0 or num_digit == 0:
        return generate_password(min_length)

    return password

