function calculateDistance(startLat, startLong, endLat, endLong){
 let R = 6371000; // Earth's radius in meters
 let φ1 = deg2rad(startLat);
 let φ2 = deg2rad(endLat);
 let Δφ = deg2rad(endLat-startLat);
 let Δλ = deg2rad(endLong-startLong);

 let a = Math.sin(Δφ/2) * Math.sin(Δφ/2) + 
         Math.cos(φ1) * Math.cos(φ2) * 
         Math.sin(Δλ/2) * Math.sin(Δλ/2);
 let c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a)); 

 let distance = R * c; // distance in meters

 return distance;
}

