    left_index = 0
    right_index = len(arr)-1

    while left_index < right_index:
        curr_sum = arr[left_index] + arr[right_index]
        if curr_sum == sum:
            return true
        elif curr_sum < sum:
            left_index += 1
        else:
            right_index -= 1
