public static void BubbleSort(int[] array)
{
    // Set the initial pass count
    int passCount = 0;

    // Iterate through the array until no more elements need to be swapped
    while (true)
    {
        // Reset the swapped flag
        bool swapped = false;

        // Iterate through the array
        // For each iteration, compare the current element with the following element
        for (int i = 0; i < array.Length - 1 - passCount; i++)
        {
            if (array[i] > array[i + 1])
            {
                // Swap the elements
                int temp = array[i];
                array[i] = array[i + 1];
                array[i + 1] = temp;

                // Set the swapped flag to true
                swapped = true;
            }
        }

        // If nothing was swapped, the array is sorted
        // Then we can break out of the loop
        if (!swapped)
        {
            break;
        }

        // Increase the pass count
        passCount++;
