def most_frequent_word(text):
    words = text.split()
    counts = {}
    for word in words:
        if word in counts:
            counts[word] += 1
        else:
            counts[word] = 1

    max_count = 0
    result_word = ""
    for (word, count) in counts.items():
        if count > max_count:
            max_count = count
            result_word = word

