vector<int> sieve(int n) {
   vector<bool> prime(n + 1, true);
   vector<int> primes;

   for (int i = 2; i <= n; i++) {
      if (prime[i]) {
         primes.push_back(i);
         for (int j = i + i; j <= n; j += i) {
            prime[j] = false;
         }
      }
   }
   return primes;
}

