public class CycleDetection {

    static int detectCycle(LinkedList list) 
    { 
        Node slow_p = list.head, fast_p = list.head; 
        while (slow_p != null && fast_p != null && fast_p.next != null) { 
            slow_p = slow_p.next; 
            fast_p = fast_p.next.next; 
            if (slow_p == fast_p) { 
                return 1; 
            }
        } 
        return 0; 
    }

}

