// function to convert HTML to LaTeX
function convertToLaTeX(node) {
 if (node.nodeType === 3) {
  // text node
  return node.textContent;
 } else if (node.nodeType === 1) {
  // HTML element node
  switch (node.nodeName) {
   case 'H1':
    return '\\section{' + convertToLaTeX(node.childNodes[0]) + '}\n\n';
   case 'P':
    return '\\begin{ paragraph }\n' + convertToLaTeX(node.childNodes[0]) + '\n\\end{ paragraph }\n\n';
   default:
    return '';
  }
 }
}

