        // Check if we have nested arrays
        if (arr1[i] instanceof Array && arr2[i] instanceof Array) {
            // recurse into the nested arrays
            if (!isEqual(arr1[i], arr2[i]))
                return false;       
        }           
        else if (arr1[i] != arr2[i]) { 
