function addTwoNumbers(num1, num2) {
    let carry = 0;
    let res = 0;

    for (let i = 0; i < 32; i++) {
        const bit1 = num1 & (1 << i);
        const bit2 = num2 & (1 << i);

        // Calculate the Sum without a +
        const currSum = bit1 ^ bit2 ^ carry;
        res |= currSum;
        // Calculate the Carry
        carry = (bit1 & bit2) | (bit2 & carry) | (bit1 & carry);
        carry <<= 1;
    }
    return res;
}

