// doubly linked list node 
struct Node 
{ 
    int data; 
    Node* next; 
    Node* prev; 
}; 

// custom iterator 
class iterator 
{ 
    Node *current; 

public: 
    iterator(Node *p) 
    { current = p; } 

    // overloading dereferencing operator 
    int operator *() 
    { return current->data; } 

    // increment operator overloading 
    void operator ++() 
    { current = current->next; } 
}; 

// Linked list insert Node at the front 
void push(Node** head_ref, int new_data) 
{ 
    // Create a new Node 
    Node* new_node = new Node(); 

    new_node->data = new_data; 

    new_node->next = (*head_ref); 
    new_node->prev = NULL; 

    if ((*head_ref) != NULL) 
        (*head_ref)->prev = new_node; 

    (*head_ref) = new_node; 
} 

// main function 
int main() 
{ 
    // create the linked list 
    Node* head = NULL; 

    // insert nodes into the linked list 
    push(&head, 10); 
    push(&head, 20); 
    push(&head, 30); 

    // create an iterator 
    iterator it(head); 

    // traverse the elements of the linked list 
    cout << *it << endl; 
    ++it; 
    cout << *it << endl; 
    ++it; 
    cout << *it << endl; 

    return 0; 
}

