def parse_tokens(input):
    tokens = []
    i = 0

    while i < len(input):
        if input[i].isdigit():
            tokens.append(int(input[i]))

        elif input[i] in ['+', '-', '*', '/', '<', '>', '=']:
            tokens.append(input[i])

        i += 1
    return tokens

