def lcm(num1, num2):
    # Find the maximum between num1 and num2
    if (num1 > num2):
        max = num1
    else:
        max = num2

    lcm = max 
    while(True):
        if ((lcm % num1 == 0) and (lcm % num2 == 0)):
            break
        lcm += max

    return lcm 

