using namespace std;

class Inventory 
{ 
    private: 
        map<string, int> itemMap;

    public: 
    // function to add items into the inventory 
    void addItemToInventory(string itemName, int quantity) 
    { 
        itemMap[itemName] = quantity; 
    } 

    // function to reduce the item quantity 
    void reduceItemQuantity(string itemName, int quantity) 
    { 
        itemMap[itemName] = itemMap[itemName] - quantity; 
    } 

    // function to update item quantity 
    void updateItemQuantity(string itemName, int quantity) 
    { 
        itemMap[itemName] = quantity; 
    } 

    // function to print all items in inventory 
    void printItems() 
    { 
        for (auto itr = itemMap.begin(); itr != itemMap.end(); itr++) 
        { 
            cout << itr->first << " : " << itr->second << endl; 
        } 
    } 
}; 

int main() 
{ 
    Inventory inv; 

    // adding items to inventory 
    inv.addItemToInventory("Pen", 10); 
    inv.addItemToInventory("Chair", 3); 

    cout << "Item in inventory before reducing quantity\n"; 
    inv.printItems(); 

    // reducing items from inventory 
    inv.reduceItemQuantity("Pen", 2); 

    cout << "\nItem in inventory after reducing quantity\n"; 
    inv.printItems(); 

    // updating item quantity 
    inv.updateItemQuantity("Chair", 5); 

    cout << "\nItem in inventory after updation\n"; 
    inv.printItems(); 

    return 0; 
}

