def print_primes(n):
    # Create a list of prime numbers
    prime_numbers = []

    # Iterate from 2 to n
    for num in range(2, n + 1):
        isPrime = True

        # Check for factors
        for i in range(2, num):
            if num % i == 0:
                isPrime = False
                break

        # If prime, append to list
        if isPrime:
            prime_numbers.append(num)

    # Print out the first 30 prime numbers
    for p in prime_numbers[:30]:
        print(p, end=" ")

