public static String[] getLongestStrings(String[] arr) {

 int maxLength = 0;

 // Find the length of the longest string in the array
 for (String s : arr) {
 maxLength = Math.max(maxLength, s.length());
 }

 // Create a new array to store the longest strings
 // and populate it
 List<String> longestStrings = new ArrayList<>();
 for (String s : arr) {
 if (s.length() == maxLength) {
 longestStrings.add(s);
 }
 }

 // Return the new array
 return longestStrings.toArray(new String[longestStrings.size()]);
}

