#include <vector>

using namespace std;

int main()
{
    // matrices for multiplication
    vector<vector<int>> matrixFirst;
    vector<vector<int>> matrixSecond;

    // matrix for storing result of multiplication
    vector<vector<int>> matrixResult;

    int rowFirst, colFirst, rowSecond, colSecond;

    cout << "Enter rows and columns for first matrix: ";
    cin >> rowFirst >> colFirst;

    cout << "Enter rows and columns for second matrix: ";
    cin >> rowSecond >> colSecond;

    // if column of first matrix in not equal to row of second matrix,
    // ask user to enter the size of matrix again
    while (colFirst != rowSecond)
    {
        cout << "Error! column of first matrix not equal to row of second." << endl;
        cout << "Enter rows and columns for first matrix: ";
        cin >> rowFirst >> colFirst;
        cout << "Enter rows and columns for second matrix: ";
        cin >> rowSecond >> colSecond;
    }

    // Storing elements of first matrix.
    cout << endl << "Enter elements of matrix 1:" << endl;
    for(int i = 0; i < rowFirst; ++i)
    {
        matrixFirst.push_back(vector<int>());

        for(int j = 0; j < colFirst; ++j)
        {
            int element;
            cin >> element;
            matrixFirst[i].push_back(element);
        }
    }

    // Storing elements of second matrix.
    cout << endl << "Enter elements of matrix 2:" << endl;
    for(int i = 0; i < rowSecond; ++i)
    {
        matrixSecond.push_back(vector<int>());

        for(int j = 0; j < colSecond; ++j)
        {
            int element;
            cin >> element;
            matrixSecond[i].push_back(element);
        }
    }

    // Initializing elements of result matrix to 0.
    for(int i = 0; i < rowFirst; ++i)
    {
        matrixResult.push_back(vector<int>());

        for(int j = 0; j < colSecond; ++j)
        {
            matrixResult[i].push_back(0);
        }
    }

    // Multiplying first and second matrix and
    // storing result in results matrix.
    for(int i = 0; i < rowFirst; ++i)
    {
        for(int j = 0; j < colSecond; ++j)
        {
            for(int k = 0; k < rowSecond; ++k)
            {
                matrixResult[i][j] += matrixFirst[i][k] * matrixSecond[k][j];
            }
        }
    }

    // Displaying the result
    cout << endl << "Output Matrix:" << endl;
    for(int i = 0; i < rowFirst; ++i)
    {
        for(int j = 0; j < colSecond; ++j)
        {
            cout << matrixResult[i][j] << " ";
        }
        cout << endl;
    }

    return 0;
}

