def permutate(arr):
    if len(arr) == 0:
        return []
    elif len(arr) == 1:
        return [arr]
    else:
        l = []
        for i in range(len(arr)):
            m = arr[i]
            rem = arr[:i] + arr[i+1:]
            for p in permutate(rem):
                l.append([m] + p)
        return l

