    S = []
    for item in lst:
        s_len = len(S)
        if s_len == 0 or item > S[s_len - 1]:
            S.append(item)
        else:
            start, end = 0, s_len-1
            while start < end:
                mid = (start + end) // 2
                if S[mid] < item:
                    start = mid + 1
                else:
                    end = mid
