use std::str::FromStr;

#[derive(Debug)]
struct TextAnalysis {
    num_words: usize,
    avg_word_len: f64,
    avg_sentence_len: f64,
}

fn analyze_text(input: &str) -> TextAnalysis {
    let words: Vec<&str> = input
    .split(|c: char| c.is_whitespace() || c == '.')
    .filter(|s| !s.is_empty())
    .collect();

    let num_words = words.iter().count();
    let avg_word_len = words
    .iter()
    .map(|word| f64::from_str(word).expect("Could not parse word length"))
    .sum::<f64>() / num_words as f64;

    let sentences: Vec<&str> = input.split('.').filter(|s| !s.is_empty()).collect();
    let num_sentences = sentences.iter().count();
    let avg_sentence_len = words
    .iter()
    .map(|s| f64::from_str(s).expect("Could not parse sentence length"))
    .sum::<f64>() / num_sentences as f64;

    TextAnalysis {
        num_words,
        avg_word_len,
        avg_sentence_len
    }
}

