def sum_recursive(nums):
    """Optimizes the code to find the sum of all numbers in a list using recursion."""
    # base case
    if len(nums) == 1:
        return nums[0]
    elif len(nums) == 0:
        return 0

    # recursive case
    return nums[0] + sum_recursive(nums[1:])

