def longestSubstring(s):
    if not s: 
        return 0
    longest_str = ''
    for i in range(len(s)):
        all_char = set()
        sub_str = ''
        for char in s[i:]:
            if char not in all_char:
                all_char.add(char)
                sub_str += char
            else:
                break
        if len(sub_str) > len(longest_str):
            longest_str = sub_str

    return longest_str

