const blur = (arr) => {
 let output = [...arr];
 let rows = arr.length;
 let cols = arr[0].length;

 // iterate over each row
 for (let row = 0; row < rows; row++) {

   // iterate over each column
   for (let col = 0; col < cols; col++) {

     let sum = 0;
     // get sum of surrounding 8 cells
     for (let k = -1; k < 2; k++) {
       for (let l = -1; l < 2; l++) {
         let curRow = row + k;
         let curCol = col + l;
	     if (curRow >= 0 && curRow < rows && curCol >= 0 && curCol < cols) {
	       sum += arr[curRow][curCol];
	     }
       }
     }
     // get average and set in output
     output[row][col] = sum / 9;
   }
 }
 return output;
}

