 Node *left, *right;
};

struct BinarySearchTree {
 Node *root;

 BinarySearchTree() {
 root = nullptr;
 }

 void insert(Node *node) {
 Node *current = root;

 if (!root) {
 root = node;
 return;
 }

 while (current) {
 if (node->id < current->id) {
 if (!current->left) {
 current->left = node;
 break;
 }

 current = current->left;
 } else {
 if (!current->right) {
 current->right = node;
 break;
 }

 current = current->right;
 }
 }
 }
};

