# Suggest a solution to convert a binary tree to a doubly-linked list

# Perform a modified inorder traversal of the binary tree
# and keep track of the head and the tail of the resulting doubly-linked list
def bintree_to_dlinkedlist(root): 
    if not root: 
        return None
    current = head = None 
    stack = []
    while stack or root: 
        if root: 
            stack.append(root) 
            root = root.left  
        else: 
            temp = stack.pop()
            if current: 
                current.right = temp  
                temp.left = current 
            else:    
                head = temp 
            current = temp  
            root = temp.right
    return head

