import "fmt"

func binarySearch(array []int, target int) int {
    low := 0
    high := len(array) - 1

    for low <= high {
        mid := (low + high) / 2
        guess := array[mid]

        if guess == target {
            return mid
        }

        if guess > target {
            high = mid - 1
        } else {
            low = mid + 1
        }
    }
    return -1
}

