"""
Create a program to encode a given string using the ROT13 algorithm.
"""

def rot13(text):
    """
    Encode a string with the ROT13 algorithm.
    """
    encoded_text = ""
    for c in text:
        if c.isalpha():
            if c.isupper():
                encoded_text += chr((ord(c) - 65 + 13) % 26 + 65)
            else:
                encoded_text += chr((ord(c) - 97 + 13) % 26 + 97)
        else:
            encoded_text += c
    return encoded_text

