"""
Design an algorithm in C++ to transpose a matrix
"""
#include <iostream> 
using namespace std; 

// Size of input matrix
#define N 3 

// Function to transpose a matrix 
void transpose(int A[][N]) 
{ 
    int i, j; 
    for (i = 0; i < N; i++) 
        for (j = i + 1; j < N; j++) 
            swap(A[i][j], A[j][i]); 
} 

// Function to display the matrix 
void displayMatrix(int A[][N]) 
{ 
    for (int i = 0; i < N; i++) 
    { 
        for (int j = 0; j < N; j++) 
            cout << A[i][j] << " "; 
        cout << endl; 
    } 
} 

// Driver Code 
int main() 
{ 
    int A[N][N] = { {1, 2, 3}, {4, 5, 6},{7, 8, 9}}; 

    cout << "Input Matrix:" << endl;
    displayMatrix(A); 

    transpose(A); 

    cout << endl << "Matrix After Transpose:" << endl;
    displayMatrix(A); 
    return 0; 
}

