def longest_increasing_subsequence(arr):
  n = len(arr)

  # LDS[i] stores the minimum value of the subsequence ending at index i
  LDS = [1]*n

  for i in range(1, n):
    for j in range(i):
      if arr[i] > arr[j] and LDS[i] < LDS[j] + 1:
        LDS[i] = LDS[j] + 1

  # Return the maximum of all the LDS values
  return max(LDS)

