function diagonalSum(matrix) {
 let sum = 0;
 for (let i = 0; i < matrix.length; i++) {
 // iterate over each row
 let row = matrix[i];
 sum += row[i]; // add the element at i, i
 // matrix is rectangular so we need to add the element
 // at n - 1 - i, i as well
 sum += row[matrix.length - 1 - i];
 }
 return sum;
}

