def isAnagram(s1, s2):  
    # two strings are anagrams if they have the same frequency of characters  
    # and both strings are of the same length  
    if len(s1) != len(s2):  
        return False  

    # create a frequency map of the characters of the first string  
    s1_freq = {}  
    for char in s1:  
        if char not in s1_freq:  
            s1_freq[char] = 0  
        s1_freq[char] += 1  

    # check if characters of second string have same frequency as in first string  
    for char in s2:  
        if char not in s1_freq or s1_freq[char] == 0:  
            return False  
        s1_freq[char] -= 1  

    # all characters have same frequency, thus it is an anagram  
    return True

