function longestIncreasingSubsequence(arr) { 
  let result = []; 
  let maxLength = 0;

  // loops to build result subarrays 
  for (let i = 0; i < arr.length; i++) { 
    maxLength = Math.max(maxLength, result[i]); 

    result[i] = 1; 

    for (let j = 0; j < i; j++) { 
      if (arr[i] > arr[j] && 
