def find_duplicates(arr):
    # Create a hash table to track elements 
    seen_elements = {}

    duplicates = []

    # Iterate over the array 
    for item in arr:
        # Check if the element is present in the hash table
        if item in seen_elements:
            # If present, add to the list of duplicates
            duplicates.append(item)
        else:
            # If not present, add it to the hash table
            seen_elements[item] = 1

    return duplicates

