def identify_descriptive_words(dataset):
    # Set up a tokenizer to clean up the comments
    tokenizer = RegexpTokenizer(r'\w+')

    # Initialize an empty dictionary to count the word frequencies
    word_frequencies = {}

    # Loop through the dataset
    for comment in dataset:
        # Tokenize the comment and make lowercase
        tokens = tokenizer.tokenize(comment.lower())

        # Count the word frequencies
        for token in tokens:
            if token in word_frequencies:
                word_frequencies[token] += 1
            else:
                word_frequencies[token] = 1
    # Sort the words by their frequency
    sorted_words = sorted(word_frequencies.items(), key=lambda kv: kv[1], reverse=True)

    # Return the most descriptive words
    return sorted_words[:10]

