def caesar_cipher(message, shift): 
    encryption_string = "" 

    # iterate over each character in the message
    for i in range(len(message)): 
        char = message[i] 

        # shift the char according to the shift amount
        if (char.isupper()): 
            encryption_string += chr((ord(char) + shift - 65) % 26 + 65) 
        elif (char.islower()): 
            encryption_string += chr((ord(char) + shift - 97) % 26 + 97) 
        else: 
            encryption_string += char 

    return encryption_string

