int knapsack(int capacity, int weights[], int values[], int n) 
{ 
   int i, j; 
   int K[n+1][capacity+1]; 

   // Build table K[][] from bottom up manner 
   for (i = 0; i <= n; i++) 
   { 
       for (j = 0; j <= capacity; j++) 
       { 
           if (i==0 || j==0) 
               K[i][j] = 0; 
           else if (weights[i-1] <= j) 
                 K[i][j] = max(values[i-1] + K[i-1][j-weights[i-1]], K[i-1][j]); 
           else
                 K[i][j] = K[i-1][j]; 
       } 
   } 
   return K[n][capacity]; 
}

