        this.input = input;
    }

    generate() { 
        let a = 0; 
        let b = 1;
        let series = [a, b];
        if (this.input <= 0) {
            return 'Incorrect input'; 
        } else if (this.input == 1) {
            return [0]; 
        } else if (this.input == 2) {
            return [0, 1];
        } else {
            for (let i = 2 ; i < this.input ; i++) {
                let c = a + b; 
                series.push(c); 
                a = b; 
                b = c;
            } 
        }
        return series; 
    } 
}

