        return False
    return True

def num_students(rows, columns, seats):
  num_students = 0
  for i in range(1, rows+1):
    for j in range(1, columns+1):
      num_students += min(i*j, seats)
      seats -= min(i*j, seats)
      if seats == 0:
        break
    if seats == 0:
      break
  return num_students

